    for (const cell of path) { const mapDoor = labMapDoorAtCell(cell); const door = mapDoor ? state.doors[mapDoor.id] : null; if (door) { door.state = DOOR_STATE_OPEN; door.lockState = DOOR_LOCK_UNLOCKED; } }
