  function updateLawEnforcementRaids(elapsed) {
    ensureLawEnforcementRaids();
    let changes = 0;
    let raid = activeLawEnforcementRaid();
    if (!raid) {
      const due = ensureLawEnforcementRaids().raids.filter((entry) => entry.status === "scheduled" && entry.arrivalAt <= state.clock)
        .sort((left, right) => left.arrivalAt - right.arrivalAt)[0];
      if (!due) return 0;
      const point = raidEntryPoint(due);
      if (!point) return 0;
      const result = LawEnforcementRaids.activate(ensureLawEnforcementRaids(), due.id, { clock: state.clock, entryCell: point.cell, roomId: point.roomId });
      state.lawEnforcementRaids = result.state; raid = result.raid;
      ensureRaidPhysicalEquipment(raid);
      const execution = ensureWarrantExecutions().executions.find((entry) => entry.id === raid.warrantExecutionId);
      if (execution) { execution.status = "active"; execution.startedAt ??= state.clock; }
      addEvent(`${raid.docket}: ${raid.actors.map((actor) => `${actor.name}, ${titleCase(actor.role)}`).join("; ")} entered through ${point.label}.`);
      changes += 1;
    }
    if (!raid) return changes;
    if (scientistIsDead()) {
      externalizeRaidCustody(raid); removeRaidPhysicalEquipment(raid);
      const completed = LawEnforcementRaids.recordScientistDeath(ensureLawEnforcementRaids(), raid.id, { clock: state.clock, summary: "The scientist died during the physical raid. Death ended the run; arrest did not." });
      state.lawEnforcementRaids = completed.state;
      if (completed.changed) finalizeRaidInstitutionalRecords(completed.raid, "scientistKilled", completed.raid.outcome.summary);
      return changes + (completed.changed ? 1 : 0);
    }
    const visibleActor = raid.actors.find(raidScientistVisibleTo);
    if (visibleActor && raid.custody.status === "free") {
      const sighting = LawEnforcementRaids.recordSighting(ensureLawEnforcementRaids(), raid.id, { clock: state.clock, actorId: visibleActor.id, cell: scientistMapCell() });
      state.lawEnforcementRaids = sighting.state; raid = sighting.raid; changes += sighting.changed ? 1 : 0;
    }
    changes += maybeRaidSeizeVisibleEvidence(raid);
    raid = ensureLawEnforcementRaids().raids.find((entry) => entry.id === raid.id) || raid;
    if (["surrendered", "restraining"].includes(raid.custody.status) || actorIsIncapacitated("scientist")) {
      const arrestActor = raidArrestActor(raid);
      const distance = arrestActor ? mapCellDistance(arrestActor.mapCell, scientistMapCell()) : Infinity;
      if (distance > 1) changes += raidMoveTeamToward(raid, scientistMapCell(), scientistRoomId(), elapsed);
      else if (arrestActor) {
        const restrained = LawEnforcementRaids.progressRestraint(ensureLawEnforcementRaids(), raid.id, { clock: state.clock, actorId: arrestActor.id, amount: Math.max(1, elapsed * 20), incapacitated: actorIsIncapacitated("scientist") });
        state.lawEnforcementRaids = restrained.state; raid = restrained.raid; changes += restrained.changed ? 1 : 0;
      }
      return changes;
    }
    if (["restrained", "extracting"].includes(raid.custody.status)) {
      const point = raidEntryPoint(raid);
      const escort = raidArrestActor(raid);
      const distance = escort ? mapCellDistance(escort.mapCell, point?.cell) : Infinity;
      if (distance > 0) {
        changes += raidMoveTeamToward(raid, point.cell, point.roomId, elapsed);
        if (escort?.mapCell) { state.scientist.mapCell = cleanMapCell(escort.mapCell); state.scientist.roomId = escort.roomId; }
      } else {
        let result = LawEnforcementRaids.extract(ensureLawEnforcementRaids(), raid.id, state.clock); state.lawEnforcementRaids = result.state;
        externalizeRaidCustody(result.raid);
        removeRaidPhysicalEquipment(result.raid);
        result = LawEnforcementRaids.book(ensureLawEnforcementRaids(), raid.id, { clock: state.clock, facilityId: "municipal-holding", facilityLabel: "Municipal Holding Facility", cellRoomId: MUNICIPAL_HOLDING_CELL_ROOM_ID });
        state.lawEnforcementRaids = result.state; materializeMunicipalHolding(result.raid);
        finalizeRaidInstitutionalRecords(result.raid, "scientistBooked", "The named arrest target was physically extracted and booked into pretrial detention; the run remained active.");
        changes += 1;
      }
      return changes;
    }
    if (raid.status === "withdrawing") {
      const point = raidEntryPoint(raid);
      changes += raidMoveTeamToward(raid, point?.cell, point?.roomId, elapsed);
      if (raid.actors.filter((actor) => actor.present && actor.health > 0).every((actor) => sameMapCell(actor.mapCell, point?.cell))) {
        externalizeRaidCustody(raid);
        removeRaidPhysicalEquipment(raid);
        const completed = LawEnforcementRaids.completeUnlocated(ensureLawEnforcementRaids(), raid.id, state.clock);
        state.lawEnforcementRaids = completed.state;
        finalizeRaidInstitutionalRecords(completed.raid, "targetNotLocated", completed.raid.outcome.summary);
        addEvent(`${raid.docket}: ${completed.raid.outcome.summary}`);
        changes += 1;
      }
    } else if (raid.communication.lastKnownCell && raid.status === "contact") {
      changes += raidMoveTeamToward(raid, raid.communication.lastKnownCell, scientistRoomId(), elapsed);
    } else {
      const targetRoomId = raidSearchTarget(raid);
      if (targetRoomId) {
        raid.status = "searching"; raid.communication.state = "searching";
        const targetCell = labMapRoomAnchor(targetRoomId);
        changes += raidMoveTeamToward(raid, targetCell, targetRoomId, elapsed);
        if (sameMapCell(raidLeadActor(raid)?.mapCell, targetCell)) { raid.clearedRoomIds.push(targetRoomId); raid.history.push({ at: state.clock, action: "roomCleared", summary: `${roomName(targetRoomId)} was physically searched and cleared.` }); changes += 1; }
      } else raid.status = "withdrawing";
    }
    return changes;
  }

  function companyReportingPeriodState(period) {
    if (!period) return "missing";
    if (period.status === "filed") return "filed";
    if (period.status === "filing") return "filing";
    if (state.clock > period.closesAt + SECONDS_PER_DAY) return "overdue";
    if (state.clock >= period.closesAt) return "ready";
    return "open";
  }

  function companyReconciliationExceptions(company = ensureCompany()) {
    if (!company.enabled) return [];
    const exceptions = company.variances.filter((variance) => variance.status === "open").map((variance) => ({
      id: variance.id,
      kind: variance.kind,
      severity: variance.severity,
      label: variance.label,
      details: variance.details,
      createdAt: variance.createdAt,
      batchId: variance.batchId,
      sourceId: variance.sourceId,
      source: "savedVariance"
    }));
    const inherited = (state.startingLiabilities || []).find((liability) => liability.id === "incomplete-business-records" && liability.status === "active");
    if (inherited) exceptions.push({ id: "incomplete-inherited-records", kind: "incompleteRecords", severity: "material", label: inherited.label, details: inherited.description, createdAt: 0, source: "liability" });
    const period = activeCompanyPeriod(company);
    if (companyReportingPeriodState(period) === "overdue") {
      exceptions.push({ id: `overdue:${period.id}`, kind: "overdueFiling", severity: "material", label: `Reporting period ${period.number} is overdue`, details: `Books were due ${formatClock(period.closesAt)} and remain open.`, createdAt: period.closesAt, source: "derived" });
    }
    const recordedBatchIds = new Set(company.records.map((record) => record.batchId).filter(Boolean));
    for (const stack of ensurePhysicalItemStacks()) {
      const batch = stack.chemicalBatch;
      if (!batch || !SURFACE_ROOM_IDS.includes(stack.roomId) || stack.quantity <= 0) continue;
      const illicit = batch.classification?.actual === "prohibited" || (batch.tags || []).includes("contraband");
      if (illicit && !exceptions.some((entry) => entry.batchId === batch.id)) {
        exceptions.push({
          id: `undeclared-batch:${batch.id}`,
          kind: "undeclaredChemicalInventory",
          severity: "serious",
          label: `${batch.label} is undeclared surface inventory`,
          details: `Batch ${batch.id} is physically held at ${roomName(stack.roomId)} but is outside the company's declared lawful product lines.`,
          createdAt: stack.createdAt,
          batchId: batch.id,
          source: "derived"
        });
      } else if (batch.stage === "finished" && batch.classification?.actual === "controlled" && batch.documentation?.status !== "certified") {
        exceptions.push({
          id: `uncertified-controlled:${batch.id}`,
          kind: "uncertifiedControlledInventory",
          severity: "material",
          label: `${batch.label} is controlled and uncertified`,
          details: `Batch ${batch.id} is held at ${roomName(stack.roomId)} without a truthful certificate tied to its saved assay.`,
          createdAt: stack.createdAt,
          batchId: batch.id,
          source: "derived"
        });
      } else if (!illicit && batch.stage === "finished" && !recordedBatchIds.has(batch.id)) {
        exceptions.push({
          id: `unrecorded-batch:${batch.id}`,
          kind: "unrecordedFinishedBatch",
          severity: "material",
          label: `${batch.label} lacks a company production record`,
          details: `Finished batch ${batch.id} is physically present at ${roomName(stack.roomId)} without a matching production entry in the current retained books.`,
          createdAt: stack.createdAt,
          batchId: batch.id,
          source: "derived"
        });
      }
    }
    const untreatedWaste = ensurePhysicalItemStacks().filter((stack) => {
      const tags = stack.tags || [];
      const chemicalResidue = stack.section === "residue" && tags.includes("chemistry");
      const hazardousWaste = tags.some((tag) => ["waste", "processWaste"].includes(tag))
        && tags.some((tag) => ["hazard", "hazardous", "toxic", "corrosive"].includes(tag));
      return SURFACE_ROOM_IDS.includes(stack.roomId) && stack.quantity > 0
        && (chemicalResidue || hazardousWaste) && stack.key !== "treatedChemicalEffluent";
    });
    if (untreatedWaste.length >= 4) {
      exceptions.push({
        id: "surface-waste-backlog",
        kind: "wasteBacklog",
        severity: untreatedWaste.length >= 8 ? "serious" : "material",
        label: `${untreatedWaste.length} untreated hazardous or process-waste stocks have accumulated`,
        details: "The declared waste-treatment activity is not keeping pace with physical surface waste.",
        createdAt: Math.min(...untreatedWaste.map((stack) => stack.createdAt)),
        source: "derived"
      });
    }
    return exceptions.sort((a, b) => ({ serious: 3, material: 2, minor: 1 }[b.severity] || 0) - ({ serious: 3, material: 2, minor: 1 }[a.severity] || 0) || a.createdAt - b.createdAt || a.id.localeCompare(b.id));
  }

  function companyCredibilityBand(score) {
    return COMPANY_CREDIBILITY_BANDS.find((band) => score >= band.min) || COMPANY_CREDIBILITY_BANDS.at(-1);
  }

  function companyCredibilityDimension(id, label, score, reasons) {
    const value = clamp(Math.round(Number(score) || 0), 0, 100);
    return { id, label, score: value, band: companyCredibilityBand(value).label, reasons: reasons.filter(Boolean) };
  }

  function companyCredibilityAssessment(company = ensureCompany()) {
    if (!company.enabled) return { score: 0, band: { id: "nonviable", label: "No Registered Front", min: 0 }, trend: "stable", dimensions: [], exceptions: [] };
    const exceptions = companyReconciliationExceptions(company);
    const severityPenalty = exceptions.reduce((total, entry) => total + ({ serious: 24, material: 12, minor: 5 }[entry.severity] || 0), 0);
    const filed = company.periods.filter((period) => period.status === "filed");
    const recordsScore = clamp(74 + Math.min(16, filed.length * 6) - severityPenalty, 0, 100);
    const recordsReasons = [
      filed.length ? `${filed.length} reporting period${filed.length === 1 ? "" : "s"} filed.` : "No reporting period has been filed yet.",
      exceptions.length ? `${exceptions.length} unresolved reconciliation exception${exceptions.length === 1 ? "" : "s"}.` : "Current records reconcile without an identified exception."
    ];

    const recentCutoff = Math.max(0, state.clock - SECONDS_PER_DAY * 14);
    const recent = company.records.filter((record) => record.at >= recentCutoff);
    const productionCount = recent.filter((record) => record.kind === "production").length;
    const saleCount = recent.filter((record) => record.kind === "sale").length;
    const receiptCount = recent.filter((record) => record.kind === "received").length;
    const expectation = COMPANY_OPERATING_STATE_DEFS[company.operatingState]?.commercialExpectation || 0;
    const activityUnits = productionCount * 2 + saleCount * 3 + receiptCount;
    const commercialBase = expectation === 0 ? 62 : expectation === 1 ? 38 : 18;
    const commercialScore = clamp(commercialBase + Math.min(expectation === 2 ? 76 : 52, activityUnits * 8), 0, 100);
    const commercialReasons = expectation === 0
      ? ["Renovation status limits current commercial expectations.", activityUnits ? `${activityUnits} weighted lawful activity units recorded recently.` : "Preparatory purchasing or facility work can support the renovation narrative."]
      : [`${productionCount} production, ${saleCount} sale, and ${receiptCount} receipt records in the recent window.`, activityUnits ? "Recorded lawful activity supports the declared operating state." : "The declared operating state has no recent lawful throughput."];

    const chemistryFixtures = (state.fixtures || []).filter((fixture) => chemistryProcessDef(fixture));
    const commissioned = chemistryFixtures.filter((fixture) => fixture.process?.commissioned).length;
    const online = chemistryFixtures.filter((fixture) => fixture.process?.online && fixture.utility?.enabled !== false).length;
    const ready = chemistryFixtures.filter((fixture) => fixture.process?.commissioned && chemistryProcessReadiness(fixture).operational).length;
    const averageCondition = chemistryFixtures.length ? chemistryFixtures.reduce((total, fixture) => total + (Number(fixture.condition) || 0), 0) / chemistryFixtures.length : 0;
    const facilityScore = chemistryFixtures.length ? clamp(averageCondition * 0.42 + commissioned / chemistryFixtures.length * 30 + ready / chemistryFixtures.length * 22 + online / chemistryFixtures.length * 6, 0, 100) : 0;
    const facilityReasons = chemistryFixtures.length
      ? [`${commissioned}/${chemistryFixtures.length} chemistry machines commissioned; ${ready}/${chemistryFixtures.length} have required physical services.`, `Average chemistry-equipment condition is ${formatNumber(averageCondition)}%.`]
      : ["No declared chemistry equipment exists at the site."];

    const surfaceSpills = ensurePhysicalItemStacks().filter((stack) => stack.form === "spill" && SURFACE_ROOM_IDS.includes(stack.roomId) && stack.quantity > 0);
    const hazardousSurfaceWaste = ensurePhysicalItemStacks().filter((stack) => SURFACE_ROOM_IDS.includes(stack.roomId) && stack.quantity > 0 && (stack.tags || []).some((tag) => ["hazard", "hazardous", "toxic", "corrosive", "chemical"].includes(tag)));
    const surfaceContamination = SURFACE_ROOM_IDS.filter((roomId) => roomById(roomId)).map((roomId) => Number(roomEnvironmentAttributes(roomId)?.contamination?.current) || 0);
    const averageContamination = surfaceContamination.length ? surfaceContamination.reduce((total, value) => total + value, 0) / surfaceContamination.length : 100;
    const surfaceFaults = chemistryFixtures.filter((fixture) => normalizeUtilityFault(fixture.utility?.fault)).length;
    const safetyScore = clamp(96 - surfaceSpills.length * 18 - hazardousSurfaceWaste.length * 4 - averageContamination * 1.2 - surfaceFaults * 8, 0, 100);
    const safetyReasons = [
      surfaceSpills.length ? `${surfaceSpills.length} uncontained surface spill${surfaceSpills.length === 1 ? "" : "s"}.` : "No uncontained surface spills.",
      `${hazardousSurfaceWaste.length} hazardous surface stock${hazardousSurfaceWaste.length === 1 ? "" : "s"}; average airborne contamination ${formatDecimal(averageContamination, 1)}.`
    ];

    const reception = roomById(SURFACE_RECEPTION_ROOM_ID);
    const publicEntrance = (state.siteAccessPoints || []).find((point) => point.id === "publicEntrance" && point.lawful);
    const receptionEnvironment = roomEnvironmentAttributes(SURFACE_RECEPTION_ROOM_ID);
    const receptionLight = Number(receptionEnvironment?.light?.current) || 0;
    const receptionContamination = Number(receptionEnvironment?.contamination?.current) || 0;
    const publicScore = reception && publicEntrance ? clamp(78 + Math.min(14, receptionLight / 5) - receptionContamination * 1.5, 0, 100) : 0;
    const publicReasons = reception && publicEntrance
      ? [`Reception is physically connected to the lawful Public Entrance.`, `Reception light ${formatNumber(receptionLight)} and contamination ${formatNumber(receptionContamination)}.`]
      : ["The company lacks a complete lawful public reception route."];

    const publicPoint = (state.siteAccessPoints || []).find((point) => point.id === "publicEntrance" && point.lawful);
    const freightPoint = (state.siteAccessPoints || []).find((point) => point.id === "loadingBay" && point.lawful);
    const covertPoint = (state.siteAccessPoints || []).find((point) => point.id === "concealedExit" && !point.lawful);
    const separated = publicPoint && freightPoint && covertPoint && new Set([publicPoint.roomId, freightPoint.roomId, covertPoint.roomId]).size === 3;
    const basementDoor = state.doors?.["door-surface-basement-staff"] || null;
    const accessScore = clamp((separated ? 82 : 30) + (basementDoor && ["restricted", "staff"].includes(basementDoor.accessRuleId) ? 18 : 0), 0, 100);
    const accessReasons = [separated ? "Public, lawful freight, and covert access remain physically separate." : "Public, freight, and covert routes are not fully separated.", basementDoor ? `The basement boundary uses ${DOOR_ACCESS_RULE_BY_ID[basementDoor.accessRuleId]?.label || "a saved access rule"}.` : "No controlled basement boundary is present."];

    const dimensions = [
      companyCredibilityDimension("commercial", "Commercial Activity", commercialScore, commercialReasons),
      companyCredibilityDimension("records", "Records and Reconciliation", recordsScore, recordsReasons),
      companyCredibilityDimension("facility", "Facility Readiness", facilityScore, facilityReasons),
      companyCredibilityDimension("safety", "Safety and Waste Handling", safetyScore, safetyReasons),
      companyCredibilityDimension("public", "Public Presentation", publicScore, publicReasons),
      companyCredibilityDimension("access", "Access Separation", accessScore, accessReasons)
    ];
    const weights = { commercial: 0.2, records: 0.25, facility: 0.2, safety: 0.15, public: 0.1, access: 0.1 };
    const score = clamp(Math.round(dimensions.reduce((total, dimension) => total + dimension.score * weights[dimension.id], 0)), 0, 100);
    const previous = company.credibilityHistory.at(-1)?.score;
    const trend = previous == null || Math.abs(score - previous) < 3 ? "stable" : score > previous ? "improving" : "declining";
    return { score, band: companyCredibilityBand(score), trend, dimensions, exceptions };
  }

  function updateCompanyState() {
    const company = ensureCompany();
    if (!company.enabled || state.clock < company.lastAssessmentAt + COMPANY_ASSESSMENT_INTERVAL) return 0;
    const assessment = companyCredibilityAssessment(company);
    company.credibilityHistory.push({ at: state.clock, score: assessment.score, bandId: assessment.band.id });
    company.credibilityHistory = company.credibilityHistory.slice(-COMPANY_CREDIBILITY_HISTORY_LIMIT);
    company.lastAssessmentAt = state.clock;
    return 1;
  }

  function setCompanyOperatingState(operatingState) {
    const company = ensureCompany();
    const definition = COMPANY_OPERATING_STATE_DEFS[operatingState];
    if (!company.enabled || !definition || company.operatingState === definition.id) return false;
    if (definition.id === "open" && InstitutionalResponses.activeRestrictions(ensureInstitutionalResponses())
      .some((action) => action.restrictionId === "noFullOperation")) {
      addEvent("An active institutional restriction prohibits Fully Open operation.");
      persist();
      render();
      return false;
    }
    const previous = COMPANY_OPERATING_STATE_DEFS[company.operatingState]?.label || titleCase(company.operatingState);
    company.operatingState = definition.id;
    company.operatingStateChangedAt = state.clock;
    state.siteIdentity.operatingState = definition.id;
    recordCompanyEvent("operatingState", `Operating state changed from ${previous} to ${definition.label}.`, { category: "corporate", roomId: SURFACE_STAFF_ROOM_ID, details: definition.description });
    addEvent(`${company.legalName} is now ${definition.label}.`);
    persist();
    render();
    return true;
  }

  function companyFilingTask() {
    return scientistQueueTasks().find((task) => task.type === "companyFiling") || null;
  }

  function companyFilingBlockReason(period = activeCompanyPeriod()) {
    if (!ensureCompany().enabled) return "No registered front company exists.";
    if (!period || period.status === "filed") return "No open reporting period exists.";
    if (period.status === "filing" || companyFilingTask()) return "Company books are already queued for filing.";
    if (state.clock < period.closesAt) return `Reporting period ${period.number} cannot close until ${formatClock(period.closesAt)}.`;
    if (!roomById(SURFACE_STAFF_ROOM_ID)) return "Staff Operations is unavailable.";
    if (scientistIsDead()) return "The scientist is dead.";
    return staminaBlockReason(adjustedStaminaCost(2, ["analysis"]));
  }

  function startCompanyFiling() {
    const company = ensureCompany();
    const period = activeCompanyPeriod(company);
    const reason = companyFilingBlockReason(period);
    if (reason) {
      addEvent(reason); persist(); render(); return false;
    }
    const targetCell = labMapRoomAnchor(SURFACE_STAFF_ROOM_ID);
    const path = labMapPathBetweenCells(scientistMapCell(), targetCell, { map: ensureLabMap(), ignoreDoors: true, actor: state.scientist });
    if (!path.length) {
      addEvent("No physical route reaches Staff Operations for company filing."); persist(); render(); return false;
    }
    const route = [scientistRoomId(), ...roomsFromMapPath(path)].filter(Boolean).filter((roomId, index, values) => index === 0 || roomId !== values[index - 1]);
    const doorReason = firstDoorSecurityBlockReason(route);
    if (doorReason) { addEvent(doorReason); persist(); render(); return false; }
    const staminaCost = adjustedStaminaCost(2, ["analysis"]);
    if (!spendStamina(staminaCost)) return false;
    const queueTail = scientistQueueTasks().reduce((latest, task) => Math.max(latest, task.dueAt), state.clock);
    const travelSeconds = mapPathTravelDistanceMeters(path, ensureLabMap()) / scientistMoveSpeedMps();
    const workSeconds = adjustedActionDuration(minutesToSeconds(20), "analysis");
    const task = {
      id: `task-${state.nextTaskNumber++}`,
      type: "companyFiling",
      label: `Close company books: period ${period.number}`,
      createdAt: state.clock,
      dueAt: queueTail + travelSeconds + workSeconds,
      data: {
        periodId: period.id,
        toRoomId: SURFACE_STAFF_ROOM_ID,
        toCell: targetCell,
        mapPath: path,
        route,
        doorTransit: doorTransitPlan(route),
        movementStartedAt: queueTail,
        movement: createScientistMovementRecord(path, travelSeconds, queueTail, { intent: "research" }),
        workStartsAt: queueTail + travelSeconds,
        staminaCost,
        skillId: "analysis",
        baseXp: 10
      }
    };
    state.tasks.push(task);
    period.status = "filing";
    period.taskId = task.id;
    addEvent(`Company reporting period ${period.number} queued for filing in Staff Operations.`);
    persist(); render(); return true;
  }

  function completeCompanyFiling(task) {
    const company = ensureCompany();
    const period = company.periods.find((entry) => entry.id === task.data?.periodId);
    if (!period || period.status !== "filing" || period.taskId !== task.id) return false;
    applyDoorTransitPolicy(task.data?.doorTransit, "Company records filing");
    state.scientist.roomId = SURFACE_STAFF_ROOM_ID;
    state.scientist.mapCell = cleanMapCell(task.data?.toCell) || labMapRoomAnchor(SURFACE_STAFF_ROOM_ID);
    const assessment = companyCredibilityAssessment(company);
    period.status = "filed";
    period.taskId = "";
    period.filedAt = state.clock;
    period.recordIds = company.records.filter((record) => record.periodId === period.id).map((record) => record.id);
    period.snapshot = {
      recordCount: period.recordIds.length,
      filedAt: state.clock,
      exceptionCount: assessment.exceptions.length,
      exceptions: assessment.exceptions.map((entry) => ({ id: entry.id, kind: entry.kind, severity: entry.severity, label: entry.label })),
      credibilityBandId: assessment.band.id,
      credibilityScore: assessment.score,
      operatingState: company.operatingState
    };
    const serious = assessment.exceptions.some((entry) => entry.kind !== "incompleteRecords" && ["material", "serious"].includes(entry.severity));
    company.cleanFiledPeriods = serious ? 0 : company.cleanFiledPeriods + 1;
    if (company.cleanFiledPeriods >= 2) {
      const inherited = (state.startingLiabilities || []).find((liability) => liability.id === "incomplete-business-records" && liability.status === "active");
      if (inherited) inherited.status = "resolved";
    }
    const number = company.nextPeriodNumber++;
    const nextPeriod = normalizeCompanyPeriod({ id: `company-period-${number}`, number, openedAt: state.clock, closesAt: state.clock + COMPANY_REPORTING_PERIOD_SECONDS }, company.periods.length);
    company.periods.push(nextPeriod);
    company.periods = company.periods.slice(-COMPANY_PERIOD_LIMIT);
    company.activePeriodId = nextPeriod.id;
    recordCompanyEvent("periodFiled", `Reporting period ${period.number} filed with ${period.snapshot.exceptionCount} exception${period.snapshot.exceptionCount === 1 ? "" : "s"}.`, { category: "records", roomId: SURFACE_STAFF_ROOM_ID, details: `Credibility at filing: ${assessment.band.label}.` });
    recordInvestigativeEvidence("filedCompanyRegistryCopy", {
      category: "documentary", label: `Filed registry copy: period ${period.number}`, significance: "minor",
      subject: { kind: "companyPeriod", id: period.id }, origin: { kind: "filing", id: period.id, label: `${company.legalName} period ${period.number} filing` },
      locus: { kind: "externalRegistry", label: "Commercial Registry copy outside site custody" }, refs: { companyRecordIds: period.recordIds },
      traits: ["filed copy", "external registry", "immutable snapshot"], magnitude: { band: "moderate", amount: period.recordIds.length, unit: "records" },
      discoverability: { level: "ordinary", methods: ["registryReview"] }, persistence: { kind: "permanent" },
      knowledge: { state: "known", source: "recorded", sourceIdentityKnown: true }, coalesceKey: `filed-registry-copy:${period.id}`
    });
    ensureCompanyRecordPackets();
    awardXp("analysis", task.data?.baseXp || 10, "company records filing");
    addEvent(`Company books filed for period ${period.number}: ${period.recordIds.length} records and ${period.snapshot.exceptionCount} reconciliation exception${period.snapshot.exceptionCount === 1 ? "" : "s"}.`);
    return true;
  }

  function institutionalResponseTaskBlockReason(task) {
    const responses = ensureInstitutionalResponses();
    const response = responses.responses.find((entry) => entry.id === task.data?.responseId);
    const demand = responses.demands.find((entry) => entry.id === task.data?.demandId);
    if (!response || response.status !== "preparing") return "The response packet is no longer being prepared.";
    if (!demand || !["pending", "preparing"].includes(demand.status)) return "The institutional demand is no longer open.";
    if (state.clock >= demand.dueAt) return "The response deadline has passed.";
    if (!roomById(SURFACE_STAFF_ROOM_ID) || !recordsCabinet()) return "Staff Operations records storage is unavailable.";
    const available = new Set(institutionalCitationCatalog().map((citation) => citation.id));
    if (response.citations.some((citation) => !available.has(citation.id))) return "A cited physical record is no longer available in Staff Operations.";
    return "";
  }

  function startInstitutionalResponse(demandId, claimId, citationIds = [], playerNote = "", options = {}) {
    updateInstitutionalResponses();
    const demand = ensureInstitutionalResponses().demands.find((entry) => entry.id === demandId);
    if (!demand || !["pending", "preparing"].includes(demand.status)) {
      if (!options.quiet) addEvent("The institutional response demand is no longer open.");
      return null;
    }
    if (state.clock >= demand.dueAt) {
      if (!options.quiet) addEvent("The institutional response deadline has passed.");
      return null;
    }
    if (!ensureCompany().enabled || !roomById(SURFACE_STAFF_ROOM_ID) || !recordsCabinet()) {
      if (!options.quiet) addEvent("Staff Operations and its physical records cabinet are required to prepare a response packet.");
      return null;
    }
    const targetCell = laborTargetAccessCell(recordsCabinet().origin, fixtureRotatedFootprint(fixtureDef(recordsCabinet()), recordsCabinet().rotation), SURFACE_STAFF_ROOM_ID);
    const path = laborPathViaCells([targetCell]);
    if (!path.length) {
      if (!options.quiet) addEvent("No physical route reaches the records cabinet in Staff Operations.");
      return null;
    }
    const route = [scientistRoomId(), ...roomsFromMapPath(path)].filter(Boolean).filter((roomId, index, values) => index === 0 || roomId !== values[index - 1]);
    const doorReason = firstDoorSecurityBlockReason(route);
    if (doorReason) {
      if (!options.quiet) addEvent(doorReason);
      return null;
    }
    const staminaCost = adjustedStaminaCost(3, ["analysis"]);
    const staminaReason = staminaBlockReason(staminaCost);
    if (staminaReason) {
      if (!options.quiet) addEvent(staminaReason);
      return null;
    }
    const catalog = institutionalCitationCatalog();
    const prepared = InstitutionalResponses.prepareResponse(ensureInstitutionalResponses(), {
      demandId, claimId, citationIds, citations: catalog, playerNote, clock: state.clock
    });
    state.institutionalResponses = prepared.state;
    if (!prepared.response || prepared.reason) {
      if (!options.quiet) addEvent(prepared.reason || "The response packet could not be prepared.");
      return null;
    }
    if (!spendStamina(staminaCost)) {
      state.institutionalResponses = InstitutionalResponses.cancelPreparation(state.institutionalResponses, prepared.response.id, state.clock);
      return null;
    }
    const queueTail = scientistQueueTasks().reduce((latest, task) => Math.max(latest, task.dueAt), state.clock);
    const travelSeconds = mapPathTravelDistanceMeters(path, ensureLabMap()) / scientistMoveSpeedMps();
    const workSeconds = adjustedActionDuration(minutesToSeconds(15 + prepared.response.citations.length * 2), "analysis");
    const task = {
      id: `task-${state.nextTaskNumber++}`, type: "institutionalResponse",
      label: `Prepare response: ${demand.docket}`,
      createdAt: state.clock, dueAt: queueTail + travelSeconds + workSeconds,
      data: {
        responseId: prepared.response.id, demandId: demand.id, toRoomId: SURFACE_STAFF_ROOM_ID,
        toCell: targetCell, mapPath: path, route, doorTransit: doorTransitPlan(route),
        movementStartedAt: queueTail,
        movement: createScientistMovementRecord(path, travelSeconds, queueTail, { intent: "research" }),
        workStartsAt: queueTail + travelSeconds, staminaCost, skillId: "analysis", baseXp: 8
      }
    };
    state.tasks.push(task);
    state.institutionalResponses = InstitutionalResponses.setResponseTask(state.institutionalResponses, prepared.response.id, task.id);
    addEvent(`${demand.docket} response packet queued in Staff Operations${task.dueAt > demand.dueAt ? "; the current queue projects completion after its deadline" : ""}.`);
    persist();
    render();
    return task;
  }

  function completeInstitutionalResponse(task) {
    const responses = ensureInstitutionalResponses();
    const response = responses.responses.find((entry) => entry.id === task.data?.responseId);
    const demand = responses.demands.find((entry) => entry.id === task.data?.demandId);
    if (!response || !demand || response.status !== "preparing") return false;
    applyDoorTransitPolicy(task.data?.doorTransit, "Institutional response preparation");
    state.scientist.roomId = SURFACE_STAFF_ROOM_ID;
    state.scientist.mapCell = cleanMapCell(task.data?.toCell) || labMapRoomAnchor(SURFACE_STAFF_ROOM_ID);
    const submitted = InstitutionalResponses.submitResponse(responses, response.id, {
      clock: state.clock, cases: ensureInvestigations().cases
    });
    state.institutionalResponses = submitted.state;
    if (!submitted.response) return false;
    const claim = InstitutionalResponses.CLAIM_DEFS[submitted.response.claimId];
    recordCompanyEvent("institutionalResponse", `${demand.docket} response submitted: ${claim?.label || titleCase(submitted.response.claimId)}.`, {
      category: "records", roomId: SURFACE_STAFF_ROOM_ID,
      details: `${submitted.response.id}; ${submitted.response.citations.length} cited record${submitted.response.citations.length === 1 ? "" : "s"}; immutable submission.`
    });
    awardXp("analysis", task.data?.baseXp || 8, "institutional response preparation");
    addEvent(`${demand.docket} response submitted: ${titleCase(submitted.response.evaluation?.outcome || "reviewed")}.`);
    if (submitted.action) addEvent(`${externalInstitutionLabel(submitted.action.institutionId)} issued ${submitted.action.label.toLowerCase()}: ${submitted.action.publicReason}`);
    enforceInstitutionalActions();
    refreshSuspicionFromExternalDetection();
    return true;
  }

  function payInstitutionalFine(actionId, options = {}) {
    const action = ensureInstitutionalResponses().actions.find((entry) => entry.id === actionId && entry.kind === "fine" && entry.status === "active");
    if (!action) return false;
    if (ensureEconomy().money < action.amount) {
      if (!options.quiet) addEvent(`${action.label} requires ${formatMoney(action.amount)}; available funds are insufficient.`);
      persist(); render(); return false;
    }
    addMoney(-action.amount, `${externalInstitutionLabel(action.institutionId)} administrative fine`);
    const resolved = InstitutionalResponses.resolveAction(ensureInstitutionalResponses(), action.id, state.clock, "paid");
    state.institutionalResponses = resolved.state;
    recordCompanyEvent("institutionalFine", `${action.label} paid.`, {
      category: "corporate", amount: -action.amount, roomId: SURFACE_STAFF_ROOM_ID,
      details: `${action.id}; ${action.publicReason}`
    });
    addEvent(`${action.label} paid: ${formatMoney(action.amount)}.`);
    refreshSuspicionFromExternalDetection();
    persist(); render(); return true;
  }

  function createDefaultCommodityMarket(seed = "seed") {
    const listings = {};
    for (const def of COMMODITY_MARKET_LISTING_DEFS) {
      const rng = seedRng(`${seed}:commodity:${def.id}`);
      const supply = Math.max(1, Math.round(def.supply * (0.82 + rng() * 0.36)));
      const demand = roundOutputValue(0.88 + rng() * 0.24);
      const mid = commodityMidPrice(def, supply, demand);
      listings[def.id] = {
        id: def.id,
        supply,
        demand,
        lastTickAt: 0,
        history: [{ at: 0, mid, bid: commodityQuoteValues(def, mid, 0).bid, ask: commodityQuoteValues(def, mid, 0).ask, supply }]
      };
    }
    return { listings, lastTickAt: 0 };
  }

  function commodityMidPrice(def, supply, demand = 1) {
    const scarcity = Math.pow(Math.max(0.2, def.supply) / Math.max(1, Number(supply) || 1), 0.42);
    return Math.max(1, roundOutputValue(def.basePrice * clamp(Number(demand) || 1, 0.55, 1.8) * scarcity));
  }

  function commodityFeeRate(reputation = ensureEconomy()?.businessReputation || 0) {
    return clamp(0.04 - Math.max(0, Number(reputation) || 0) / 20000, 0.015, 0.04);
  }

  function commoditySpreadRate(reputation = ensureEconomy()?.businessReputation || 0) {
    return clamp(0.08 - Math.max(0, Number(reputation) || 0) / 10000, 0.03, 0.08);
  }

  function commodityQuoteValues(def, mid, reputation = ensureEconomy()?.businessReputation || 0) {
    const spread = commoditySpreadRate(reputation);
    const fee = commodityFeeRate(reputation);
    return {
      mid: Math.max(1, roundOutputValue(mid)),
      bid: Math.max(1, roundOutputValue(mid * (1 - spread / 2) * (1 - fee))),
      ask: Math.max(1, roundOutputValue(mid * (1 + spread / 2) * (1 + fee))),
      fee,
      spread
    };
  }

  function commodityListingState(listingId) {
    const economy = ensureEconomy();
    return economy.commodityMarket?.listings?.[listingId] || null;
  }

  function commodityQuote(listingId) {
    const def = COMMODITY_MARKET_LISTING_BY_ID[listingId];
    const listing = commodityListingState(listingId);
    if (!def || !listing) return null;
    return { ...commodityQuoteValues(def, commodityMidPrice(def, listing.supply, listing.demand)), supply: listing.supply };
  }

  function commodityBusinessReputationLabel(value = ensureEconomy().businessReputation) {
    if (value >= 500) return "Preferred Counterparty";
    if (value >= 150) return "Established Business";
    if (value >= 40) return "Known Customer";
    if (value > 0) return "New Account";
    return "Unrated Business";
  }

  function recordLegalLedger(kind, label, options = {}) {
    const economy = ensureEconomy();
    const entry = {
      id: `legal-ledger-${economy.nextLegalLedgerNumber++}`,
      kind,
      label,
      listingId: String(options.listingId || ""),
      orderId: String(options.orderId || ""),
      consignmentId: String(options.consignmentId || ""),
      amount: Math.round(Number(options.amount) || 0),
      at: state.clock
    };
    economy.legalLedger.unshift(entry);
    economy.legalLedger = economy.legalLedger.slice(0, COMMODITY_MARKET_LEDGER_LIMIT);
    recordCompanyEvent(kind, label, {
      ...options,
      category: "legalExchange",
      lawful: true,
      roomId: options.roomId || (kind === "received" || kind === "sale" ? SURFACE_LOADING_ROOM_ID : SURFACE_STAFF_ROOM_ID)
    });
    return entry;
  }

  function commodityInboundAmount(listingId) {
    return roundOutputValue(ensureEconomy().commodityConsignments
      .filter((consignment) => consignment.listingId === listingId && ["inTransit", "arrived", "unloading"].includes(consignment.status))
      .reduce((total, consignment) => total + consignment.quantity, 0));
  }

  function commodityOwnedAmount(listingId) {
    const def = COMMODITY_MARKET_LISTING_BY_ID[listingId];
    if (!def) return 0;
    return physicalKnownAmount(def.section, def.key);
  }

  function commodityOutstandingCount() {
    return ensureEconomy().commodityConsignments.filter((consignment) => ["inTransit", "arrived", "unloading", "dispatching"].includes(consignment.status)).length;
  }

  function executeCommodityBuy(listingId, requestedQuantity, options = {}) {
    const economy = ensureEconomy();
    const def = COMMODITY_MARKET_LISTING_BY_ID[listingId];
    const listing = commodityListingState(listingId);
    const quote = commodityQuote(listingId);
    if (!def?.buyable || !listing || !quote) return { filled: 0, reason: "This good is not offered for public purchase." };
    if (commodityOutstandingCount() >= COMMODITY_MARKET_MAX_OUTSTANDING) return { filled: 0, reason: "The Loading Bay already has the maximum outstanding freight." };
    const wholeUnits = def.section !== "chemicalBatches";
    let quantity = Math.max(0, Number(requestedQuantity) || 0);
    if (wholeUnits) quantity = Math.floor(quantity);
    quantity = Math.min(quantity, wholeUnits ? Math.floor(listing.supply) : listing.supply);
    const protectedCash = Math.max(0, Math.round(Number(options.protectedCash) || 0));
    const affordable = Math.floor(Math.max(0, economy.money - protectedCash) / quote.ask);
    quantity = Math.min(quantity, affordable);
    if (quantity <= 0) return { filled: 0, reason: economy.money <= protectedCash ? "Protected cash floor prevents this purchase." : "No affordable public supply is available." };
    const total = Math.round(quantity * quote.ask);
    economy.money = Math.max(0, economy.money - total);
    listing.supply = roundOutputValue(Math.max(0, listing.supply - quantity));
    listing.demand = roundOutputValue(clamp(listing.demand + quantity / Math.max(20, def.liquidity * 5), 0.55, 1.8));
    const number = economy.nextCommodityConsignmentNumber++;
    const consignment = {
      id: `legal-consignment-${number}`,
      direction: "inbound",
      listingId,
      quantity,
      unitPrice: quote.ask,
      total,
      orderId: String(options.orderId || ""),
      stackId: "",
      status: "inTransit",
      createdAt: state.clock,
      eta: state.clock + COMMODITY_MARKET_FREIGHT_SECONDS + (number % 4) * minutesToSeconds(5),
      completedAt: null,
      taskId: ""
    };
    economy.commodityConsignments.push(consignment);
    recordLegalLedger("purchase", `Purchased ${formatNumber(quantity)} ${def.label} at ${formatMoney(quote.ask)} per unit; inbound freight booked.`, { listingId, orderId: options.orderId, consignmentId: consignment.id, amount: -total, quantity });
    addEvent(`Open market purchase: ${formatNumber(quantity)} ${def.label} for ${formatMoney(total)}; delivery inbound to the Loading Bay.`);
    return { filled: quantity, total, consignment };
  }

  function commoditySaleEligibleStacks(listingId) {
    const def = COMMODITY_MARKET_LISTING_BY_ID[listingId];
    if (!def?.sellable) return [];
    return ensurePhysicalItemStacks().filter((stack) =>
      stack.section === def.section
      && stack.key === def.key
      && stack.quantity > 0
      && !stack.reservedTaskId
      && (!stack.carriedBy)
      && (def.section !== "chemicalBatches" || (
        stack.chemicalBatch?.classification?.known === "ordinary"
        && stack.chemicalBatch?.classification?.actual === "ordinary"
        && stack.chemicalBatch?.packaging?.state === "packaged"
        && stack.chemicalBatch?.documentation?.status === "certified"
      ))
    );
  }

  function commoditySaleEligibleStack(listingId, stackId = "") {
    return commoditySaleEligibleStacks(listingId).find((stack) => !stackId || stack.id === stackId) || null;
  }

  function commoditySaleUnitPrice(listingId, stack) {
    const quote = commodityQuote(listingId);
    if (!quote) return 0;
    if (stack?.section !== "chemicalBatches") return quote.bid;
    const purity = clamp(Number(stack.chemicalBatch?.purity) || 0, 0, 100);
    const craftsmanship = clamp(Number(stack.chemicalBatch?.craftsmanship) || 0, 0, 100);
    const quality = purity * 0.65 + craftsmanship * 0.35;
    return Math.max(1, roundOutputValue(quote.bid * (0.8 + quality * 0.004)));
  }

  function createCommoditySellOrder(listingId, quantity = 1, limitPrice = 0, stackId = "") {
    const economy = ensureEconomy();
    const def = COMMODITY_MARKET_LISTING_BY_ID[listingId];
    const stack = commoditySaleEligibleStack(listingId, stackId);
    if (!def?.sellable || !stack) return { order: null, reason: "No unreserved, legally saleable physical stack is available." };
    const indivisible = def.section === "chemicalBatches";
    const amount = indivisible ? stack.quantity : Math.min(Math.floor(Math.max(1, Number(quantity) || 1)), Math.floor(stack.quantity));
    const order = {
      id: `legal-order-${economy.nextCommodityOrderNumber++}`,
      kind: "limitSell",
      listingId,
      quantity: amount,
      remaining: amount,
      limitPrice: Math.max(0, Number(limitPrice) || 0),
      targetQuantity: 0,
      protectedCash: 0,
      priority: 3,
      maxOutstanding: 1,
      stackId: stack.id,
      status: "open",
      createdAt: state.clock,
      updatedAt: state.clock
    };
    stack.reservedTaskId = order.id;
    economy.commodityOrders.push(order);
    recordLegalLedger("sellOrder", `${limitPrice > 0 ? "Limit" : "Market"} sell staged: ${formatNumber(amount)} ${def.label}${limitPrice > 0 ? ` at ${formatMoney(limitPrice)} net or better` : ""}.`, { listingId, orderId: order.id });
    processCommodityOrders();
    persist();
    render();
    return { order, reason: "" };
  }

  function createCommodityBuyOrder(listingId, options = {}) {
    const economy = ensureEconomy();
    const def = COMMODITY_MARKET_LISTING_BY_ID[listingId];
    const kind = options.kind === "maintainStock" ? "maintainStock" : "limitBuy";
    if (!def?.buyable) return { order: null, reason: "This listing cannot be purchased." };
    const quantity = Math.max(1, Math.floor(Number(options.quantity) || 1));
    const order = {
      id: `legal-order-${economy.nextCommodityOrderNumber++}`,
      kind,
      listingId,
      quantity,
      remaining: quantity,
      limitPrice: Math.max(1, Number(options.limitPrice) || commodityQuote(listingId)?.ask || def.basePrice),
      targetQuantity: kind === "maintainStock" ? Math.max(1, Math.floor(Number(options.targetQuantity) || quantity)) : 0,
      protectedCash: Math.max(0, Math.round(Number(options.protectedCash) || 0)),
      priority: clamp(Math.floor(Number(options.priority) || 3), 1, 5),
      maxOutstanding: clamp(Math.floor(Number(options.maxOutstanding) || 2), 1, COMMODITY_MARKET_MAX_OUTSTANDING),
      stackId: "",
      status: "open",
      createdAt: state.clock,
      updatedAt: state.clock
    };
    economy.commodityOrders.push(order);
    recordLegalLedger("buyOrder", `${kind === "maintainStock" ? "Maintain-stock" : "Limit buy"} order opened for ${def.label} at ${formatMoney(order.limitPrice)} landed or less.`, { listingId, orderId: order.id });
    processCommodityOrders();
    persist();
    render();
    return { order, reason: "" };
  }

  function cancelCommodityOrder(orderId) {
    const order = ensureEconomy().commodityOrders.find((entry) => entry.id === orderId);
    if (!order || order.status !== "open") return false;
    order.status = "canceled";
    order.updatedAt = state.clock;
    const stack = ensurePhysicalItemStacks().find((entry) => entry.id === order.stackId && entry.reservedTaskId === order.id);
    if (stack) stack.reservedTaskId = "";
    recordLegalLedger("orderCanceled", `Canceled ${order.kind === "limitSell" ? "sale" : "purchase"} order ${order.id}.`, { listingId: order.listingId, orderId: order.id });
    persist();
    render();
    return true;
  }

  function queueCommodityFreight(consignment) {
    if (!consignment || consignment.taskId || !["arrived", "dispatching"].includes(consignment.status)) return false;
    const def = COMMODITY_MARKET_LISTING_BY_ID[consignment.listingId];
    const task = {
      id: `task-${state.nextTaskNumber++}`,
      type: "commodityFreight",
      label: consignment.direction === "inbound" ? `Receive ${def?.label || "legal freight"}` : `Dispatch ${def?.label || "legal freight"}`,
      createdAt: state.clock,
      dueAt: state.clock + minutesToSeconds(5),
      data: { consignmentId: consignment.id, targetCell: labMapRoomAnchor(SURFACE_LOADING_ROOM_ID), toRoomId: SURFACE_LOADING_ROOM_ID, staminaCost: 1 }
    };
    consignment.taskId = task.id;
    consignment.status = consignment.direction === "inbound" ? "unloading" : "dispatching";
    const stack = ensurePhysicalItemStacks().find((entry) => entry.id === consignment.stackId);
    if (stack) stack.reservedTaskId = task.id;
    state.tasks.push(task);
    addEvent(`${task.label} queued at the Loading Bay.`);
    return true;
  }

  function processCommodityOrders() {
    const economy = ensureEconomy();
    let changes = 0;
    const orders = economy.commodityOrders.filter((order) => order.status === "open")
      .sort((a, b) => a.priority - b.priority || a.createdAt - b.createdAt || a.id.localeCompare(b.id));
    for (const order of orders) {
      const quote = commodityQuote(order.listingId);
      if (!quote) continue;
      if (order.kind === "limitSell") {
        const stack = ensurePhysicalItemStacks().find((entry) => entry.id === order.stackId && (entry.reservedTaskId === order.id || !entry.reservedTaskId));
        if (!stack) { order.status = "failed"; order.updatedAt = state.clock; changes += 1; continue; }
        const saleUnitPrice = commoditySaleUnitPrice(order.listingId, stack);
        if (saleUnitPrice + 1e-6 < order.limitPrice) continue;
        const consignment = {
          id: `legal-consignment-${economy.nextCommodityConsignmentNumber++}`,
          direction: "outbound", listingId: order.listingId, quantity: order.remaining, unitPrice: saleUnitPrice,
          total: Math.round(order.remaining * saleUnitPrice), orderId: order.id, stackId: stack.id,
          status: "dispatching", createdAt: state.clock, eta: state.clock, completedAt: null, taskId: ""
        };
        economy.commodityConsignments.push(consignment);
        order.status = "executing";
        order.updatedAt = state.clock;
        queueCommodityFreight(consignment);
        changes += 1;
        continue;
      }
      if (quote.ask > order.limitPrice || commodityOutstandingCount() >= order.maxOutstanding) continue;
      let wanted = order.remaining;
      if (order.kind === "maintainStock") wanted = Math.max(0, order.targetQuantity - commodityOwnedAmount(order.listingId) - commodityInboundAmount(order.listingId));
      if (wanted <= 0) continue;
      const result = executeCommodityBuy(order.listingId, wanted, { orderId: order.id, protectedCash: order.protectedCash });
      if (result.filled > 0) {
        order.remaining = roundOutputValue(Math.max(0, order.remaining - result.filled));
        order.updatedAt = state.clock;
        if (order.kind === "limitBuy" && order.remaining <= 0) order.status = "filled";
        changes += 1;
      }
    }
    return changes;
  }

  function completeCommodityFreight(task) {
    const economy = ensureEconomy();
    const consignment = economy.commodityConsignments.find((entry) => entry.id === task.data?.consignmentId);
    const def = COMMODITY_MARKET_LISTING_BY_ID[consignment?.listingId];
    if (!consignment || !def) return false;
    state.scientist.roomId = SURFACE_LOADING_ROOM_ID;
    state.scientist.mapCell = labMapRoomAnchor(SURFACE_LOADING_ROOM_ID);
    if (consignment.direction === "inbound") {
      createPhysicalItemStack(def.section, def.key, consignment.quantity, physicalFallbackLocation(SURFACE_LOADING_ROOM_ID), {
        phase: def.section === "chemicalBatches" ? CHEMICAL_PRODUCT_BY_ID[def.key]?.phase : "solid",
        tags: ["legalfreight"]
      });
      consignment.status = "received";
      consignment.completedAt = state.clock;
      economy.businessReputation = Math.min(1000, economy.businessReputation + Math.max(1, Math.ceil(consignment.total / 100)));
      recordLegalLedger("received", `Received ${formatNumber(consignment.quantity)} ${def.label} at the Loading Bay.`, { listingId: def.id, orderId: consignment.orderId, consignmentId: consignment.id, quantity: consignment.quantity });
      addEvent(`${formatNumber(consignment.quantity)} ${def.label} received at the Loading Bay; normal stockpile hauling can move it onward.`);
    } else {
      const stack = ensurePhysicalItemStacks().find((entry) => entry.id === consignment.stackId);
      if (!stack || stack.quantity + 1e-6 < consignment.quantity) {
        consignment.status = "failed";
        recordLegalLedger("dispatchFailed", `${def.label} dispatch failed because the reserved stack was unavailable.`, { listingId: def.id, orderId: consignment.orderId, consignmentId: consignment.id });
        return false;
      }
      stack.quantity = roundOutputValue(stack.quantity - consignment.quantity);
      stack.knownQuantity = Math.min(stack.knownQuantity, stack.quantity);
      stack.reservedTaskId = "";
      if (stack.quantity <= 0) state.physicalItemStacks = ensurePhysicalItemStacks().filter((entry) => entry.id !== stack.id);
      const listing = commodityListingState(def.id);
      listing.supply = roundOutputValue(listing.supply + consignment.quantity);
      listing.demand = roundOutputValue(clamp(listing.demand - consignment.quantity / Math.max(20, def.liquidity * 5), 0.55, 1.8));
      economy.money += consignment.total;
      economy.businessReputation = Math.min(1000, economy.businessReputation + Math.max(1, Math.ceil(consignment.total / 80)));
      consignment.status = "sold";
      consignment.completedAt = state.clock;
      const order = economy.commodityOrders.find((entry) => entry.id === consignment.orderId);
      if (order) { order.status = "filled"; order.remaining = 0; order.updatedAt = state.clock; }
      syncPhysicalReadModels();
      recordLegalLedger("sale", `Sold ${formatNumber(consignment.quantity)} ${def.label} at ${formatMoney(consignment.unitPrice)} net per unit.`, { listingId: def.id, orderId: consignment.orderId, consignmentId: consignment.id, amount: consignment.total, quantity: consignment.quantity, batchId: stack.chemicalBatch?.id || "" });
      addEvent(`Legal shipment sold: ${formatNumber(consignment.quantity)} ${def.label} for ${formatMoney(consignment.total)}.`);
    }
    return true;
  }

  function updateCommodityMarket() {
    const economy = ensureEconomy();
    let changes = 0;
    for (const consignment of economy.commodityConsignments) {
      if (consignment.status === "inTransit" && state.clock >= consignment.eta) {
        consignment.status = "arrived";
        changes += 1;
      }
      if (consignment.status === "arrived" && queueCommodityFreight(consignment)) changes += 1;
    }
    while (economy.commodityMarket.lastTickAt + COMMODITY_MARKET_TICK_SECONDS <= state.clock) {
      const tickAt = economy.commodityMarket.lastTickAt + COMMODITY_MARKET_TICK_SECONDS;
      for (const def of COMMODITY_MARKET_LISTING_DEFS) {
        const listing = economy.commodityMarket.listings[def.id];
        const tickNumber = Math.round(tickAt / COMMODITY_MARKET_TICK_SECONDS);
        const rng = seedRng(`${state.seed}:commodity-tick:${def.id}:${tickNumber}`);
        const supplyReturn = (def.supply - listing.supply) * 0.12;
        listing.supply = roundOutputValue(Math.max(1, listing.supply + supplyReturn + (rng() - 0.48) * def.liquidity * 0.12));
        listing.demand = roundOutputValue(clamp(listing.demand * 0.82 + (0.82 + rng() * 0.36) * 0.18, 0.55, 1.8));
        listing.lastTickAt = tickAt;
        const quote = commodityQuote(def.id);
        listing.history.push({ at: tickAt, mid: quote.mid, bid: quote.bid, ask: quote.ask, supply: listing.supply });
        listing.history = listing.history.slice(-COMMODITY_MARKET_HISTORY_LIMIT);
      }
      economy.commodityMarket.lastTickAt = tickAt;
      changes += 1;
    }
    changes += processCommodityOrders();
    economy.commodityOrders = economy.commodityOrders.slice(-200);
    economy.commodityConsignments = economy.commodityConsignments.slice(-200);
    return changes;
  }

  function nextCommodityMarketEvent() {
    const economy = ensureEconomy();
    const events = [{ time: economy.commodityMarket.lastTickAt + COMMODITY_MARKET_TICK_SECONDS, label: "Commodity exchange update", type: "market" }];
    for (const consignment of economy.commodityConsignments) {
      if (consignment.status === "inTransit" && consignment.eta >= state.clock) events.push({ time: consignment.eta, label: `${COMMODITY_MARKET_LISTING_BY_ID[consignment.listingId]?.label || "Freight"} arrives`, type: "freight" });
    }
    return events.filter((event) => event.time >= state.clock).sort((a, b) => a.time - b.time)[0] || null;
  }

  function createBlackMarketContact(seed, number = 1) {
    const rng = seedRng(`${seed}:black-market-contact:${number}`);
    const archetype = BLACK_MARKET_CONTACT_ARCHETYPES[(number - 1) % BLACK_MARKET_CONTACT_ARCHETYPES.length];
    const first = BLACK_MARKET_FIRST_NAMES[Math.floor(rng() * BLACK_MARKET_FIRST_NAMES.length)] || "Vey";
    const last = BLACK_MARKET_LAST_NAMES[Math.floor(rng() * BLACK_MARKET_LAST_NAMES.length)] || "Vell";
    const riskIds = Object.keys(BLACK_MARKET_RISK_PROFILES);
    const riskProfile = archetype.risk || riskIds[Math.floor(rng() * riskIds.length)] || "steady";
    return {
      id: `contact-${number}`,
      name: `${first} ${last}`,
      archetype: archetype.id,
      archetypeLabel: archetype.label,
      trust: Math.round(6 + rng() * 8),
      reliability: roundOutputValue(0.7 + rng() * 0.25),
      completedContracts: 0,
      paymentFailures: 0,
      contractFailures: 0,
      unavailableUntil: 0,
      nextOfferAt: 0,
      riskProfile,
      preferredTags: [...archetype.tags],
      discoveredAt: 0,
      notes: `${archetype.label}; prefers ${archetype.tags.join(", ")} byproducts.`
    };
  }

  function blackMarketByproductTags(label) {
    const text = String(label || "").toLowerCase();
    const tags = new Set([byproductCollectionType(text)]);
    for (const [element, pool] of Object.entries(BYPRODUCT_POOLS_BY_ELEMENT)) {
      if (pool.includes(text)) {
        tags.add(element);
      }
    }
    if (/acid|corrosive|solvent|dissolved/.test(text)) tags.add("corrosive");
    if (/poison|numbing|contaminated|irritant|bitter/.test(text)) tags.add("toxic");
    if (/mana|ether|glow|opalescent/.test(text)) tags.add("arcane");
    if (/smoke|vapor|mist|fume|ozone/.test(text)) tags.add("vapor");
    if (/water|clean|sterile|pale|cooling/.test(text)) tags.add("clean");
    if (/metal|oxide|charged|static|flake|grease/.test(text)) tags.add("metal");
    if (/silt|grit|crystal|salt|clay|dust|film|residue/.test(text)) tags.add("dry");
    if (/mucus|gel|slime|sludge|paste|tar|resin|wax|foam|pulp/.test(text)) tags.add("sludge");
    if (/corpse|decay|contaminated|bitter|dark|black/.test(text)) tags.add("decay");
    if (/trace|inert|mucus|pulp|silt/.test(text)) tags.add("organic");
    if (/mana|ether|acid|contaminated|opalescent|charged/.test(text)) tags.add("rare");
    if (/numbing|brine|clean|sterile|glow/.test(text)) tags.add("medical");
    return [...tags].filter(Boolean);
  }

  function blackMarketByproductUnitValue(label) {
    const tags = new Set(blackMarketByproductTags(label));
    let value = 8;
    if (tags.has("corrosive")) value += 8;
    if (tags.has("toxic")) value += 7;
    if (tags.has("arcane")) value += 10;
    if (tags.has("rare")) value += 5;
    if (tags.has("clean")) value += 3;
    if (tags.has("vapor")) value += 4;
    if (tags.has("metal")) value += 4;
    if (tags.has("dry")) value += 2;
    return value;
  }

  function blackMarketMaterialPoolForContact(contact) {
    const wanted = new Set(contact?.preferredTags || []);
    const matches = BLACK_MARKET_BYPRODUCT_LABELS.filter((label) =>
      blackMarketByproductTags(label).some((tag) => wanted.has(tag))
    );
    return matches.length ? matches : BLACK_MARKET_BYPRODUCT_LABELS;
  }

  function blackMarketManufacturedPoolForContact(contact) {
    const wanted = new Set(contact?.preferredTags || []);
    const matching = BLACK_MARKET_MANUFACTURED_PRODUCT_IDS.filter((productId) =>
      (CHEMICAL_PRODUCT_BY_ID[productId]?.tags || []).some((tag) => wanted.has(tag))
    );
    return matching.length ? matching : BLACK_MARKET_MANUFACTURED_PRODUCT_IDS;
  }

  function createBlackMarketSpecimenRequirements(rng) {
    const knownCandidates = (state?.slimes || [])
      .filter((slime) => slime.status !== "dead")
      .flatMap((slime) => BLACK_MARKET_SPECIMEN_TRAIT_KEYS
        .filter((traitKey) => slime.revealed?.[traitKey])
        .map((traitKey) => ({ traitKey, label: String(slime.revealed[traitKey]) })));
    const desired = knownCandidates.length ? knownCandidates[Math.floor(rng() * knownCandidates.length)] : null;
    return {
      mature: rng() < 0.72,
      minimumGeneration: rng() < 0.28 ? 1 : 0,
      traitKey: desired?.traitKey || "",
      traitLabel: desired?.label || "",
      maximumStress: rng() < 0.5 ? 70 : 100,
      documentationRequired: Boolean(desired)
    };
  }

  function createBlackMarketDeal(seed, contact, number = 1, slot = 0, reputation = 0, clock = 0) {
    const rng = seedRng(`${seed}:black-market-deal:${contact?.id || "contact"}:${number}:${slot}:${contact?.trust || 0}:${reputation}`);
    const contractCategory = (Math.max(1, numericSuffix(contact?.id)) - 1) % 3;
    const commodityKind = slot % BLACK_MARKET_DEALS_PER_CONTACT === 0
      ? "rawByproduct"
      : contractCategory === 1
        ? "manufactured"
        : contractCategory === 2
          ? "specimen"
          : "rawByproduct";
    const pool = blackMarketMaterialPoolForContact(contact);
    const rawMaterial = pool[Math.floor(rng() * pool.length)] || BLACK_MARKET_BYPRODUCT_LABELS[0] || "trace slime";
    const productPool = blackMarketManufacturedPoolForContact(contact);
    const productId = commodityKind === "manufactured" ? productPool[Math.floor(rng() * productPool.length)] : "";
    const product = CHEMICAL_PRODUCT_BY_ID[productId];
    const specimenRequirements = commodityKind === "specimen" ? createBlackMarketSpecimenRequirements(rng) : null;
    const material = product?.label || (commodityKind === "specimen" ? "Living slime specimen" : rawMaterial);
    const tags = commodityKind === "manufactured" ? [...(product.tags || [])] : commodityKind === "specimen" ? ["specimen", "living", "rare"] : blackMarketByproductTags(material);
    const amount = commodityKind === "rawByproduct" ? roundOutputValue(2 + rng() * 5 + Math.min(3, (Number(reputation) || 0) / 120)) : 1;
    const demand = 0.85 + rng() * 0.6;
    const profile = BLACK_MARKET_RISK_PROFILES[contact?.riskProfile] || BLACK_MARKET_RISK_PROFILES.steady;
    const danger = tags.filter((tag) => ["corrosive", "toxic", "arcane", "rare", "vapor"].includes(tag)).length;
    const baseValue = commodityKind === "manufactured"
      ? 110 + (CHEMICAL_CLASSIFICATION_DEFS[product?.baseClassification]?.rank || 1) * 45
      : commodityKind === "specimen"
        ? 260 + (specimenRequirements?.traitKey ? 90 : 0) + specimenRequirements.minimumGeneration * 55
        : amount * blackMarketByproductUnitValue(material);
    const payout = Math.max(1, Math.round(baseValue * demand * profile.payoutMod * (1 + (Number(contact?.trust) || 0) / 260)));
    const exposureChance = commodityKind === "specimen"
      ? clamp(0.42 + profile.chanceMod - (Number(contact?.trust) || 0) / 900 - (Number(reputation) || 0) / 5000, 0.32, 0.78)
      : commodityKind === "manufactured"
        ? clamp(0.18 + danger * 0.045 + profile.chanceMod - (Number(contact?.trust) || 0) / 850 - (Number(reputation) || 0) / 4500, 0.12, 0.65)
        : clamp(0.04 + danger * 0.035 + amount * 0.006 + profile.chanceMod - (Number(contact?.trust) || 0) / 800 - (Number(reputation) || 0) / 4000, 0.02, 0.55);
    const offerKind = slot % BLACK_MARKET_DEALS_PER_CONTACT === 0 ? "spot" : "contract";
    const offerLife = Math.round(BLACK_MARKET_OFFER_MIN_SECONDS + rng() * (BLACK_MARKET_OFFER_MAX_SECONDS - BLACK_MARKET_OFFER_MIN_SECONDS));
    const deliveryWindow = Math.round(clamp(
      BLACK_MARKET_CONTRACT_MIN_SECONDS + rng() * (BLACK_MARKET_CONTRACT_MAX_SECONDS - BLACK_MARKET_CONTRACT_MIN_SECONDS) - amount * SECONDS_PER_HOUR * 2,
      BLACK_MARKET_CONTRACT_MIN_SECONDS,
      BLACK_MARKET_CONTRACT_MAX_SECONDS
    ));
    const paymentTerm = offerKind === "spot"
      ? "delivery"
      : contact?.riskProfile === "reckless" && rng() < 0.55
        ? "credit"
        : rng() < 0.2
          ? "escrow"
          : "delivery";
    return {
      id: `deal-${number}`,
      offerKind,
      slot: Math.max(0, Math.floor(Number(slot) || 0)),
      contactId: contact?.id || "",
      commodityKind,
      material,
      productId,
      batchRequirements: commodityKind === "manufactured" ? {
        minimumPurity: Math.round(45 + rng() * 30),
        minimumCraftsmanship: Math.round(30 + rng() * 30),
        requireAssay: rng() < 0.72,
        requirePackaging: true,
        allowUnverified: false
      } : null,
      specimenRequirements,
      tags,
      amount,
      payout,
      exposureChance: roundOutputValue(exposureChance),
      suspicionOnObserved: commodityKind === "specimen" ? Math.round(16 + rng() * 10) : commodityKind === "manufactured" ? Math.round(8 + danger * 2 + rng() * 5) : Math.max(1, Math.round(3 + danger * 2 + amount * 0.7)),
      reputationGain: Math.max(1, Math.round(2 + danger + payout / 45)),
      trustGain: Math.max(1, Math.round(1 + payout / 80)),
      paymentTerm,
      deliveryWindow,
      expiresAt: finiteTime(clock, 0) + offerLife,
      negotiationRoll: roundOutputValue(rng()),
      status: "open",
      taskId: "",
      createdAt: finiteTime(clock, 0),
      completedAt: null,
      flavor: blackMarketDealFlavor(contact, material, tags)
    };
  }

  function blackMarketDealFlavor(contact, material, tags = []) {
    const type = contact?.archetypeLabel || "Buyer";
    if (tags.includes("specimen")) {
      return `${type} wants a living specimen in an opaque transfer pod and accepts the severe handoff risk.`;
    }
    if (tags.includes("contraband")) {
      return `${type} wants a traceable manufactured lot kept outside licensed distribution records.`;
    }
    if (tags.includes("toxic")) {
      return `${type} needs carefully stoppered ${material}.`;
    }
    if (tags.includes("arcane")) {
      return `${type} wants ${material} before it loses its charge.`;
    }
    if (tags.includes("corrosive")) {
      return `${type} will pay extra if the ${material} arrives without eating through the wrapping.`;
    }
    if (tags.includes("vapor")) {
      return `${type} requested sealed flasks of ${material}.`;
    }
    return `${type} is quietly buying ${material}.`;
  }

  function blackMarketContractTerms(deal, negotiationId = "standard") {
    const negotiation = BLACK_MARKET_NEGOTIATION_DEFS[negotiationId] || BLACK_MARKET_NEGOTIATION_DEFS.standard;
    const paymentTerm = BLACK_MARKET_PAYMENT_TERMS[negotiation.paymentTerm || deal?.paymentTerm] || BLACK_MARKET_PAYMENT_TERMS.delivery;
    return {
      negotiationId: negotiation.id,
      payout: Math.max(1, Math.round((Number(deal?.payout) || 1) * negotiation.payoutMod * paymentTerm.payoutMod)),
      deliveryWindow: Math.round(clamp((Number(deal?.deliveryWindow) || BLACK_MARKET_CONTRACT_MIN_SECONDS) * negotiation.windowMod, BLACK_MARKET_CONTRACT_MIN_SECONDS, BLACK_MARKET_CONTRACT_MAX_SECONDS * 1.5)),
      exposureChance: clamp(roundOutputValue((Number(deal?.exposureChance) || 0) * negotiation.exposureMod), 0.01, 0.75),
      paymentTerm: paymentTerm.id,
      extraSeconds: Math.max(0, Number(negotiation.extraSeconds) || 0)
    };
  }

  function blackMarketNegotiationAccepted(deal, contact, negotiationId) {
    const negotiation = BLACK_MARKET_NEGOTIATION_DEFS[negotiationId] || BLACK_MARKET_NEGOTIATION_DEFS.standard;
    if (negotiation.id === "standard") return true;
    const profileModifier = contact?.riskProfile === "cautious" && negotiation.id === "discreet"
      ? 0.12
      : contact?.riskProfile === "reckless" && negotiation.id === "higherPayout"
        ? 0.08
        : 0;
    const chance = clamp(negotiation.acceptanceBase + (Number(contact?.trust) || 0) / 250 + profileModifier, 0.15, 0.94);
    return (Number(deal?.negotiationRoll) || 0) < chance;
  }

  function createBlackMarketContract(deal, negotiationId = "standard", number = 1, clock = 0) {
    const contact = blackMarketContactById(deal?.contactId);
    const terms = blackMarketContractTerms(deal, negotiationId);
    const id = `contract-${number}`;
    const reliability = clamp(Number(contact?.reliability) || 0.75, 0.35, 0.99);
    const paymentTerm = BLACK_MARKET_PAYMENT_TERMS[terms.paymentTerm] || BLACK_MARKET_PAYMENT_TERMS.delivery;
    const paymentRisk = paymentTerm.secured ? 0 : clamp((1 - reliability) * (paymentTerm.id === "credit" ? 1.35 : 0.75), 0.02, 0.65);
    const paymentRoll = seedRng(`${state.seed}:black-market-payment:${id}:${deal?.id}:${negotiationId}`)();
    const paymentFraction = paymentTerm.secured || paymentRoll >= paymentRisk
      ? 1
      : paymentRoll < paymentRisk * 0.35
        ? 0
        : 0.5;
    return {
      id,
      offerId: String(deal?.id || ""),
      contactId: String(deal?.contactId || ""),
      commodityKind: ["rawByproduct", "manufactured", "specimen"].includes(deal?.commodityKind) ? deal.commodityKind : "rawByproduct",
      material: deal?.commodityKind === "rawByproduct" || !deal?.commodityKind ? byproductInventoryKey(deal?.material) : String(deal?.material || "Contraband shipment"),
      productId: String(deal?.productId || ""),
      batchRequirements: deal?.batchRequirements ? clonePlainObject(deal.batchRequirements) : null,
      specimenRequirements: deal?.specimenRequirements ? clonePlainObject(deal.specimenRequirements) : null,
      selectedStackId: "",
      selectedSlimeId: "",
      selectedPodStackId: "",
      shipmentValueModifier: 1,
      transportOutcome: "pending",
      transportFailureChance: 0,
      transportRoll: roundOutputValue(seedRng(`${state.seed}:black-market-transport:${id}:${deal?.id}`)()),
      tags: [...(deal?.tags || [])],
      amount: roundOutputValue(Number(deal?.amount) || 0),
      payout: terms.payout,
      paymentTerm: paymentTerm.id,
      paymentFraction,
      paymentDueAt: null,
      exposureChance: terms.exposureChance,
      exposureRoll: roundOutputValue(seedRng(`${state.seed}:black-market-contract-exposure:${id}:${deal?.id}`)()),
      suspicionOnObserved: Math.max(1, Math.round(Number(deal?.suspicionOnObserved) || 1)),
      reputationGain: Math.max(1, Math.round(Number(deal?.reputationGain) || 1)),
      trustGain: Math.max(1, Math.round(Number(deal?.trustGain) || 1)),
      negotiationId: terms.negotiationId,
      extraSeconds: terms.extraSeconds,
      acceptedAt: finiteTime(clock, 0),
      dueAt: finiteTime(clock, 0) + terms.deliveryWindow,
      deliveredAt: null,
      settledAt: null,
      failedAt: null,
      status: "active",
      taskId: "",
      reservations: [],
      warnings: [],
      outcome: "",
      notes: String(deal?.flavor || "")
    };
  }

