  function handleWindowBlur() {
    clearHeldMapPanKeys();
    endMapDrag({ persist: true });
  }

  function handleKeyboardShortcut(event) {
    if (startupOverlayOpen) {
      if (event.key === "Escape" && !isTypingTarget(event.target) && startupView !== "title") {
        event.preventDefault();
        if (startupView === "setup" && setupReturnView === "worlds") prepareWorldLibrary({ forNewRun: true });
        else showStartupView("title");
      }
      return;
    }
    if (event.defaultPrevented || isTypingTarget(event.target) || !state?.started) {
      return;
    }
    if (handleTimeShortcut(event)) {
      return;
    }
    if (handleMapZoomShortcut(event)) {
      return;
    }
    if (handleMapPanKeydown(event)) {
      return;
    }
    if (handleMenuKeyboardShortcut(event)) {
      return;
    }
    handleMapKeyboardShortcut(event);
  }

  function handleKeyboardKeyup(event) {
    if (event.key === "Shift") {
      mapPanShiftHeld = false;
    }
    const panKey = mapPanKeyForEvent(event);
    if (!panKey || !heldMapPanKeys.has(panKey)) {
      return;
    }
    heldMapPanKeys.delete(panKey);
    event.preventDefault();
    if (!heldMapPanKeys.size) {
      stopMapPanLoop();
      settleCanvasMapPanOffset({ persist: false });
      persist();
    }
  }

  function mapPanKeyForEvent(event) {
    const key = String(event.key || "").toLowerCase();
    return ["w", "a", "s", "d"].includes(key) ? key : "";
  }

  function mapPanDeltaForKey(key) {
    const deltas = {
      w: { dx: 0, dy: -1 },
      a: { dx: -1, dy: 0 },
      s: { dx: 0, dy: 1 },
      d: { dx: 1, dy: 0 }
    };
    return deltas[key] || null;
  }

  function handleMapPanKeydown(event) {
    if (event.defaultPrevented || isTypingTarget(event.target) || !state?.started || currentWorkspaceTab() !== "map") {
      return false;
    }
    const panKey = mapPanKeyForEvent(event);
    if ((event.ctrlKey || event.metaKey || event.altKey) && panKey) {
      return false;
    }
    if (!panKey) {
      if (event.key === "Shift") {
        mapPanShiftHeld = true;
      }
      return false;
    }
    event.preventDefault();
    mapPanShiftHeld = Boolean(event.shiftKey);
    const wasHeld = heldMapPanKeys.has(panKey);
    heldMapPanKeys.add(panKey);
    if (!wasHeld) {
      const delta = mapPanDeltaForKey(panKey);
      const step = mapPanShiftHeld ? 3 : 1;
      if (currentMapRendererMode() === MAP_RENDERER_CANVAS) {
        panCanvasMapByPixels(delta.dx * step * mapDragTileSpan(), delta.dy * step * mapDragTileSpan(), { render: true });
      } else {
        panMapCamera(delta.dx * step, delta.dy * step, { persist: false, render: true });
      }
    }
    startMapPanLoop();
    return true;
  }

  function startMapPanLoop() {
    if (mapPanAnimationFrame) {
      return;
    }
    mapPanLastFrameAt = 0;
    mapPanAnimationFrame = window.requestAnimationFrame(stepMapPanLoop);
  }

  function stopMapPanLoop() {
    if (mapPanAnimationFrame) {
      window.cancelAnimationFrame(mapPanAnimationFrame);
    }
    mapPanAnimationFrame = 0;
    mapPanLastFrameAt = 0;
    mapPanCarryX = 0;
    mapPanCarryY = 0;
  }

  function clearHeldMapPanKeys() {
    if (!heldMapPanKeys.size && !mapPanAnimationFrame) {
      return;
    }
    heldMapPanKeys.clear();
    mapPanShiftHeld = false;
    stopMapPanLoop();
    if (state?.started) {
      settleCanvasMapPanOffset({ persist: false });
      persist();
    }
  }

  function mapPanVectorFromHeldKeys() {
    let dx = 0;
    let dy = 0;
    for (const key of heldMapPanKeys) {
      const delta = mapPanDeltaForKey(key);
      if (!delta) {
        continue;
      }
      dx += delta.dx;
      dy += delta.dy;
    }
    if (!dx && !dy) {
      return null;
    }
    const magnitude = Math.hypot(dx, dy) || 1;
    return {
      dx: dx / magnitude,
      dy: dy / magnitude
    };
  }

  function mapPanCellsPerSecond() {
    const viewport = mapViewportForUi(ensureLabMap());
    const pixelsPerSecond = mapPanShiftHeld ? LAB_MAP_FAST_PAN_PIXELS_PER_SECOND : LAB_MAP_PAN_PIXELS_PER_SECOND;
    return pixelsPerSecond / Math.max(1, viewport.tilePx);
  }

  function mapPanIntegerStep(value) {
    return value < 0 ? Math.ceil(value) : Math.floor(value);
  }

  function stepMapPanLoop(now) {
    if (!heldMapPanKeys.size || !state?.started || currentWorkspaceTab() !== "map") {
      clearHeldMapPanKeys();
      return;
    }
    if (!mapPanLastFrameAt) {
      mapPanLastFrameAt = now;
    }
    const elapsedSeconds = clamp((now - mapPanLastFrameAt) / 1000, 0, 0.12);
    mapPanLastFrameAt = now;
    const vector = mapPanVectorFromHeldKeys();
    if (vector) {
      if (currentMapRendererMode() === MAP_RENDERER_CANVAS) {
        const pixelsPerSecond = mapPanShiftHeld ? LAB_MAP_FAST_PAN_PIXELS_PER_SECOND : LAB_MAP_PAN_PIXELS_PER_SECOND;
        panCanvasMapByPixels(
          vector.dx * pixelsPerSecond * elapsedSeconds,
          vector.dy * pixelsPerSecond * elapsedSeconds,
          { render: true }
        );
      } else {
        const cells = mapPanCellsPerSecond() * elapsedSeconds;
        mapPanCarryX += vector.dx * cells;
        mapPanCarryY += vector.dy * cells;
        const stepX = mapPanIntegerStep(mapPanCarryX);
        const stepY = mapPanIntegerStep(mapPanCarryY);
        if (stepX || stepY) {
          if (panMapCamera(stepX, stepY, { persist: false, render: true })) {
            mapPanCarryX -= stepX;
            mapPanCarryY -= stepY;
          } else {
            mapPanCarryX = 0;
            mapPanCarryY = 0;
          }
        }
      }
    }
    mapPanAnimationFrame = window.requestAnimationFrame(stepMapPanLoop);
  }

  function panMapCamera(dx, dy, options = {}) {
    const map = ensureLabMap();
    const ui = ensureUiState();
    const viewport = mapViewportForUi(map, ui);
    const next = normalizeMapCamera({
      x: viewport.x + dx,
      y: viewport.y + dy
    }, map, viewport.zoomIndex);
    if (next.x === viewport.x && next.y === viewport.y) {
      return false;
    }
    ui.mapCamera = next;
    setActiveWorkspaceTab("map", { scroll: false });
    if (options.persist !== false) {
      persist();
    }
    if (options.render !== false) {
      renderMapNavigationInteraction();
    }
    return true;
  }

  function canvasMapPresentation(mapView = null) {
    const view = mapView || activeCanvasMapSurface?.mapView || buildLabMapView();
    const accessibility = mapAccessibilityPresentation();
    return {
      tilePx: Number(view?.zoom?.tilePx) || mapViewportForUi(ensureLabMap()).tilePx,
      origin: {
        x: CANVAS_MAP_ORIGIN_PX - canvasMapPanOffset.x,
        y: CANVAS_MAP_ORIGIN_PX - canvasMapPanOffset.y
      },
      includeOverscan: true,
      glyphMode: accessibility.visualMode === "glyphs",
      reducedMotion: accessibility.reducedMotion,
      highContrast: accessibility.highContrast,
      effectIntensity: accessibility.effectIntensity,
      markerScale: accessibility.markerScale
    };
  }

  function canvasMapPixelStep(value, tileSpan) {
    if (value >= tileSpan) return Math.floor(value / tileSpan);
    if (value <= -tileSpan) return Math.ceil(value / tileSpan);
    return 0;
  }

  function panCanvasMapByPixels(dx, dy, options = {}) {
    if (currentMapRendererMode() !== MAP_RENDERER_CANVAS || !activeCanvasMapRenderer) {
      return panMapCamera(
        mapPanIntegerStep((Number(dx) || 0) / mapDragTileSpan()),
        mapPanIntegerStep((Number(dy) || 0) / mapDragTileSpan()),
        options
      );
    }
    const tileSpan = mapDragTileSpan(activeCanvasMapSurface?.mapView);
    canvasMapPanOffset.x += Number(dx) || 0;
    canvasMapPanOffset.y += Number(dy) || 0;
    const stepX = canvasMapPixelStep(canvasMapPanOffset.x, tileSpan);
    const stepY = canvasMapPixelStep(canvasMapPanOffset.y, tileSpan);
    let cameraChanged = false;
    if (stepX || stepY) {
      const before = mapViewportForUi(ensureLabMap());
      cameraChanged = panMapCamera(stepX, stepY, { persist: false, render: false });
      const after = mapViewportForUi(ensureLabMap());
      const movedX = after.x - before.x;
      const movedY = after.y - before.y;
      canvasMapPanOffset.x -= movedX * tileSpan;
      canvasMapPanOffset.y -= movedY * tileSpan;
      if (movedX !== stepX) canvasMapPanOffset.x = 0;
      if (movedY !== stepY) canvasMapPanOffset.y = 0;
    }
    if (options.render !== false) {
      if (cameraChanged) refreshActiveCanvasMapSurface();
      else activeCanvasMapRenderer.setPresentation(canvasMapPresentation(activeCanvasMapSurface?.mapView));
    }
    return cameraChanged || Boolean(dx) || Boolean(dy);
  }

  function settleCanvasMapPanOffset(options = {}) {
    if (currentMapRendererMode() !== MAP_RENDERER_CANVAS || (!canvasMapPanOffset.x && !canvasMapPanOffset.y)) {
      return false;
    }
    const tileSpan = mapDragTileSpan(activeCanvasMapSurface?.mapView);
    const stepX = Math.abs(canvasMapPanOffset.x) >= tileSpan / 2 ? Math.sign(canvasMapPanOffset.x) : 0;
    const stepY = Math.abs(canvasMapPanOffset.y) >= tileSpan / 2 ? Math.sign(canvasMapPanOffset.y) : 0;
    const cameraChanged = stepX || stepY
      ? panMapCamera(stepX, stepY, { persist: false, render: false })
      : false;
    canvasMapPanOffset = { x: 0, y: 0 };
    if (options.render !== false) refreshActiveCanvasMapSurface();
    if (options.persist !== false && state?.started) persist();
    return cameraChanged;
  }

  function mapDragTileSpan(mapView = null) {
    const tilePx = Number(mapView?.zoom?.tilePx) || mapViewportForUi(ensureLabMap()).tilePx;
    return Math.max(1, tilePx + LAB_MAP_GRID_GAP_PX);
  }

  function setMapDragCursor(active) {
    document.body?.classList.toggle("map-dragging", Boolean(active));
  }

  function suppressMapMiddleButtonDefault(event) {
    if (event.button !== 1) {
      return;
    }
    event.preventDefault();
  }

  function handleMapDragPointerDown(event, mapView) {
    if (event.button !== 1 || !state?.started || currentWorkspaceTab() !== "map") {
      return;
    }
    event.preventDefault();
    clearCanvasMapHover();
    endMapDrag({ persist: false });
    mapDragState = {
      pointerId: event.pointerId,
      startX: event.clientX,
      startY: event.clientY,
      lastX: event.clientX,
      lastY: event.clientY,
      carryX: 0,
      carryY: 0,
      active: false,
      tileSpan: mapDragTileSpan(mapView),
      renderer: currentMapRendererMode()
    };
    document.addEventListener("pointermove", handleMapDragPointerMove, { passive: false });
    document.addEventListener("pointerup", handleMapDragPointerEnd, { passive: false });
    document.addEventListener("pointercancel", handleMapDragPointerEnd, { passive: false });
  }

  function handleMapDragPointerMove(event) {
    if (!mapDragState || event.pointerId !== mapDragState.pointerId) {
      return;
    }
    event.preventDefault();
    const totalX = event.clientX - mapDragState.startX;
    const totalY = event.clientY - mapDragState.startY;
    if (!mapDragState.active) {
      if (Math.hypot(totalX, totalY) < LAB_MAP_DRAG_THRESHOLD_PX) {
        return;
      }
      mapDragState.active = true;
      setMapDragCursor(true);
    }
    const deltaX = event.clientX - mapDragState.lastX;
    const deltaY = event.clientY - mapDragState.lastY;
    mapDragState.lastX = event.clientX;
    mapDragState.lastY = event.clientY;
    if (mapDragState.renderer === MAP_RENDERER_CANVAS) {
      panCanvasMapByPixels(-deltaX, -deltaY, { render: true });
      return;
    }
    mapDragState.carryX += -deltaX / mapDragState.tileSpan;
    mapDragState.carryY += -deltaY / mapDragState.tileSpan;
    const stepX = mapPanIntegerStep(mapDragState.carryX);
    const stepY = mapPanIntegerStep(mapDragState.carryY);
    if (!stepX && !stepY) {
      return;
    }
    if (panMapCamera(stepX, stepY, { persist: false, render: true })) {
      mapDragState.carryX -= stepX;
      mapDragState.carryY -= stepY;
    } else {
      mapDragState.carryX = 0;
      mapDragState.carryY = 0;
    }
  }

  function handleMapDragPointerEnd(event) {
    if (!mapDragState || event.pointerId !== mapDragState.pointerId) {
      return;
    }
    event.preventDefault();
    endMapDrag({ persist: true });
  }

  function endMapDrag(options = {}) {
    if (!mapDragState) {
      setMapDragCursor(false);
      return;
    }
    document.removeEventListener("pointermove", handleMapDragPointerMove);
    document.removeEventListener("pointerup", handleMapDragPointerEnd);
    document.removeEventListener("pointercancel", handleMapDragPointerEnd);
    mapDragState = null;
    setMapDragCursor(false);
    settleCanvasMapPanOffset({ persist: false });
    if (options.persist !== false && state?.started) {
      persist();
    }
  }

  function canvasMapCellFromPointer(event, surface = activeCanvasMapSurface) {
    return surface?.renderer?.clientPointToCell?.(event.clientX, event.clientY) || null;
  }

  function canvasMapEntityFromPointer(event, surface = activeCanvasMapSurface) {
    return surface?.renderer?.clientPointTarget?.(event.clientX, event.clientY) || null;
  }

  function canvasMapSurfaceIndexes(mapView) {
    return {
      cellIndex: new Map((mapView?.scene?.cells || []).map((entry) => [entry.key, entry])),
      interactionIndex: new Map((mapView?.scene?.interactionIndex || []).map((entry) => [entry.key, entry]))
    };
  }

  function canvasMapSceneCell(cell, surface = activeCanvasMapSurface) {
    const clean = cleanMapCell(cell);
    if (!clean || !MapVisualState.cellInBounds(clean, surface?.mapView?.scene?.viewport)) return null;
    return surface?.cellIndex?.get(mapCellKey(clean)) || null;
  }

  function canvasMapInteraction(cell, surface = activeCanvasMapSurface) {
    const clean = cleanMapCell(cell);
    if (!clean || !MapVisualState.cellInBounds(clean, surface?.mapView?.scene?.viewport)) return null;
    return surface?.interactionIndex?.get(mapCellKey(clean)) || null;
  }

  function clearCanvasMapHover(options = {}) {
    if (canvasMapHoverTimer) {
      window.clearTimeout(canvasMapHoverTimer);
      canvasMapHoverTimer = 0;
    }
    const surface = activeCanvasMapSurface;
    if (!surface) return;
    if (surface.tooltip) surface.tooltip.hidden = true;
    if (options.keepCell !== true) surface.hoverCellKey = "";
  }

  function positionCanvasMapTooltip(surface, clientX, clientY) {
    if (!surface?.tooltip || surface.tooltip.hidden) return;
    const rect = surface.host.getBoundingClientRect();
    const gap = 12;
    surface.tooltip.style.left = `${clientX - rect.left + gap}px`;
    surface.tooltip.style.top = `${clientY - rect.top + gap}px`;
    window.requestAnimationFrame(() => {
      if (surface !== activeCanvasMapSurface || surface.tooltip.hidden) return;
      const maxLeft = Math.max(6, rect.width - surface.tooltip.offsetWidth - 6);
      const maxTop = Math.max(6, rect.height - surface.tooltip.offsetHeight - 6);
      surface.tooltip.style.left = `${clamp(clientX - rect.left + gap, 6, maxLeft)}px`;
      surface.tooltip.style.top = `${clamp(clientY - rect.top + gap, 6, maxTop)}px`;
    });
  }

  function scheduleCanvasMapHover(event, surface = activeCanvasMapSurface) {
    if (!surface || canvasMapPointerState || mapDragState?.active) {
      clearCanvasMapHover();
      return;
    }
    const cell = canvasMapCellFromPointer(event, surface);
    const cellView = canvasMapSceneCell(cell, surface);
    if (!cellView) {
      clearCanvasMapHover();
      return;
    }
    const key = cellView.key;
    if (surface.hoverCellKey === key && !surface.tooltip.hidden) {
      positionCanvasMapTooltip(surface, event.clientX, event.clientY);
      return;
    }
    clearCanvasMapHover();
    surface.hoverCellKey = key;
    const clientX = event.clientX;
    const clientY = event.clientY;
    canvasMapHoverTimer = window.setTimeout(() => {
      canvasMapHoverTimer = 0;
      if (surface !== activeCanvasMapSurface || surface.hoverCellKey !== key || canvasMapPointerState || mapDragState?.active) return;
      const latestCell = canvasMapSceneCell(cell, surface);
      if (!latestCell) return;
      surface.tooltip.textContent = latestCell.tooltip?.text || `Tile ${cell.x}, ${cell.y}, Z ${cell.z}`;
      surface.tooltip.hidden = false;
      positionCanvasMapTooltip(surface, clientX, clientY);
    }, CANVAS_MAP_HOVER_DELAY_MS);
  }

  function canvasMapEditingMode() {
    if (accessAreaEditing()) return "access";
    if (roomDesignationModeActive()) return "room";
    if (constructionWorkModeActive()) return "construction";
    return "selection";
  }

  function applyCanvasMapPaintCell(cell, mode) {
    const cellView = canvasMapSceneCell(cell);
    if (!cellView?.known) return false;
    if (mode === "access") {
      if (accessAreaCellBlockReason(cell)) return false;
      return applyAccessAreaBrush(cell, { persist: false, render: false });
    }
    if (mode === "room") {
      if (roomDesignationCellBlockReason(cell)) return false;
      return applyRoomDesignationBrush(cell, { persist: false, render: false });
    }
    return false;
  }

  function selectCanvasMapCell(cell) {
    const interaction = canvasMapInteraction(cell);
    const targets = interaction?.targets || [];
    const cellKey = mapCellKey(cell);
    let target = targets[0] || interaction?.primaryTarget || null;
    const current = currentSelection();
    if (targets.length > 1
      && current?.source === "map"
      && mapCellKey(canvasMapLastSelectionCell) === cellKey) {
      const selectedKey = selectionKey(current);
      const selectedIndex = targets.findIndex((candidate) => selectionKey(candidate) === selectedKey);
      if (selectedIndex >= 0) target = targets[(selectedIndex + 1) % targets.length];
    }
    if (!target) return false;
    canvasMapLastSelectionCell = { ...cell };
    ensureUiState().mapCursor = { ...cell };
    return focusMapTarget(target, {
      keepWorkspace: true,
      source: "map",
      resetInspectorTab: true,
      resetInspectorExpanded: true,
      resetCommandMenu: true
    });
  }

  function selectCanvasMapEntityHit(hit) {
    if (!hit?.target) return false;
    const anchorCell = cleanMapCell(hit.anchorCell);
    if (anchorCell) {
      canvasMapLastSelectionCell = { ...anchorCell };
      ensureUiState().mapCursor = { ...anchorCell };
    }
    return focusMapTarget(hit.target, {
      keepWorkspace: true,
      source: "map",
      resetInspectorTab: true,
      resetInspectorExpanded: true,
      resetCommandMenu: true
    });
  }

  function handleCanvasMapConstructionClick(cell) {
    if (!constructionWorkModeActive()) return false;
    const cellView = canvasMapSceneCell(cell);
    if (!cellView?.known) return false;
    if (constructionActiveMode() !== "cancel" && constructionDraftCellAddBlockReason(cell)) return false;
    const changed = toggleConstructionDraftCell(cell, { persist: false, render: false });
    if (changed) {
      persist();
      refreshActiveCanvasMapSurface();
    }
    return true;
  }

  function handleCanvasMapPointerDown(event, surface = activeCanvasMapSurface) {
    if (event.button !== 0 || !surface || !state?.started || currentWorkspaceTab() !== "map") return;
    const cell = canvasMapCellFromPointer(event, surface);
    const cellView = canvasMapSceneCell(cell, surface);
    if (!cellView) return;
    clearCanvasMapHover();
    const editingMode = canvasMapEditingMode();
    const entityHit = editingMode === "selection"
      ? canvasMapEntityFromPointer(event, surface)
      : null;
    const paintMode = ["access", "room"].includes(editingMode)
      && cellView.known
      && !(editingMode === "access" ? accessAreaCellBlockReason(cell) : roomDesignationCellBlockReason(cell))
      ? editingMode
      : "";
    canvasMapPointerState = {
      pointerId: event.pointerId,
      startX: event.clientX,
      startY: event.clientY,
      startCellKey: cellView.key,
      startEntityId: entityHit?.entityId || "",
      mode: paintMode || (editingMode === "construction" ? "construction" : "selection"),
      changed: false,
      moved: false,
      visited: new Set()
    };
    surface.host.setPointerCapture?.(event.pointerId);
    if (paintMode) {
      event.preventDefault();
      canvasMapPointerState.visited.add(cellView.key);
      canvasMapPointerState.changed = applyCanvasMapPaintCell(cell, paintMode);
      if (canvasMapPointerState.changed) refreshActiveCanvasMapSurface();
    }
  }

  function handleCanvasMapPointerMove(event, surface = activeCanvasMapSurface) {
    const pointer = canvasMapPointerState;
    if (!pointer || event.pointerId !== pointer.pointerId) {
      scheduleCanvasMapHover(event, surface);
      return;
    }
    if (Math.hypot(event.clientX - pointer.startX, event.clientY - pointer.startY) >= LAB_MAP_DRAG_THRESHOLD_PX) {
      pointer.moved = true;
    }
    if (!["access", "room"].includes(pointer.mode) || !(event.buttons & 1)) return;
    event.preventDefault();
    const cell = canvasMapCellFromPointer(event, surface);
    const cellView = canvasMapSceneCell(cell, surface);
    if (!cellView || pointer.visited.has(cellView.key)) return;
    pointer.visited.add(cellView.key);
    const changed = applyCanvasMapPaintCell(cell, pointer.mode);
    pointer.changed = changed || pointer.changed;
    if (changed) refreshActiveCanvasMapSurface();
  }

  function endCanvasMapPointer(event, options = {}) {
    const pointer = canvasMapPointerState;
    if (!pointer || event.pointerId !== pointer.pointerId) return false;
    const surface = activeCanvasMapSurface;
    const cell = canvasMapCellFromPointer(event, surface);
    const cellView = canvasMapSceneCell(cell, surface);
    const entityHit = canvasMapEntityFromPointer(event, surface);
    canvasMapPointerState = null;
    if (surface?.host?.hasPointerCapture?.(event.pointerId)) {
      surface.host.releasePointerCapture(event.pointerId);
    }
    if (["access", "room"].includes(pointer.mode)) {
      if (pointer.changed) {
        persist();
        refreshActiveCanvasMapSurface();
      }
      return true;
    }
    if (options.cancelled || pointer.moved) return false;
    if (pointer.mode === "selection"
      && pointer.startEntityId
      && entityHit?.entityId === pointer.startEntityId) {
      return selectCanvasMapEntityHit(entityHit);
    }
    if (!cellView || cellView.key !== pointer.startCellKey) return false;
    if (pointer.mode === "construction" && handleCanvasMapConstructionClick(cell)) return true;
    return selectCanvasMapCell(cell);
  }

  function handleRoomPaintPointerDown(event) {
    if (event.button !== 0 || !roomDesignationModeActive()) return;
    const tile = event.target instanceof Element ? event.target.closest(".lab-map-cell") : null;
    const cell = mapCellFromDomTile(tile);
    if (!cell || roomDesignationCellBlockReason(cell)) return;
    event.preventDefault();
    roomPaintState = { pointerId: event.pointerId, changed: false, visited: new Set() };
    const key = mapCellKey(cell);
    roomPaintState.visited.add(key);
    roomPaintState.changed = applyRoomDesignationBrush(cell, { persist: false, render: false });
    document.addEventListener("pointerup", handleRoomPaintPointerEnd, { once: true });
    document.addEventListener("pointercancel", handleRoomPaintPointerEnd, { once: true });
  }

  function handleRoomPaintPointerOver(event) {
    if (!roomPaintState || event.pointerId !== roomPaintState.pointerId || !(event.buttons & 1)) return;
    const tile = event.target instanceof Element ? event.target.closest(".lab-map-cell") : null;
    const cell = mapCellFromDomTile(tile);
    if (!cell || roomDesignationCellBlockReason(cell)) return;
    const key = mapCellKey(cell);
    if (roomPaintState.visited.has(key)) return;
    roomPaintState.visited.add(key);
    roomPaintState.changed = applyRoomDesignationBrush(cell, { persist: false, render: false }) || roomPaintState.changed;
  }

  function handleRoomPaintPointerEnd(event) {
    if (!roomPaintState || event.pointerId !== roomPaintState.pointerId) return;
    const changed = roomPaintState.changed;
    roomPaintState = null;
    suppressNextMapClick = changed;
    if (changed) {
      persist();
      renderMapInteraction();
    }
  }

  function handleAccessPaintPointerDown(event) {
    if (event.button !== 0 || !accessAreaEditing()) return;
    const tile = event.target instanceof Element ? event.target.closest(".lab-map-cell") : null;
    const cell = mapCellFromDomTile(tile);
    if (!cell || tile?.classList.contains("unknown-darkness-cell") || accessAreaCellBlockReason(cell)) return;
    event.preventDefault();
    accessPaintState = { pointerId: event.pointerId, changed: false, visited: new Set([mapCellKey(cell)]) };
    accessPaintState.changed = applyAccessAreaBrush(cell, { persist: false, render: false });
    document.addEventListener("pointerup", handleAccessPaintPointerEnd, { once: true });
    document.addEventListener("pointercancel", handleAccessPaintPointerEnd, { once: true });
  }

  function handleAccessPaintPointerOver(event) {
    if (!accessPaintState || event.pointerId !== accessPaintState.pointerId || !(event.buttons & 1)) return;
    const tile = event.target instanceof Element ? event.target.closest(".lab-map-cell") : null;
    const cell = mapCellFromDomTile(tile);
    if (!cell || tile?.classList.contains("unknown-darkness-cell") || accessAreaCellBlockReason(cell)) return;
    const key = mapCellKey(cell);
    if (accessPaintState.visited.has(key)) return;
    accessPaintState.visited.add(key);
    accessPaintState.changed = applyAccessAreaBrush(cell, { persist: false, render: false }) || accessPaintState.changed;
  }

  function handleAccessPaintPointerEnd(event) {
    if (!accessPaintState || event.pointerId !== accessPaintState.pointerId) return;
    const changed = accessPaintState.changed;
    accessPaintState = null;
    suppressNextMapClick = changed;
    if (changed) {
      persist();
      render();
    }
  }

  function cleanKeyboardKey(event) {
    if (event.ctrlKey || event.metaKey || event.altKey) {
      return "";
    }
    const key = String(event.key || "").trim();
    return /^[a-z]$/i.test(key) ? key.toLowerCase() : "";
  }

  function keyboardMenuDef(pathId) {
    const id = String(pathId || "").trim();
    const def = KEYBOARD_MENU_DEFS[id] || null;
    if (def?.debugOnly && !debugToolsEnabled()) {
      return null;
    }
    return def;
  }

  function normalizeKeyboardMenuPath(pathId) {
    const id = String(pathId || "").trim();
    return KEYBOARD_MENU_DEFS[id] ? id : "";
  }

  function keyboardMenuOptionsText(pathId) {
    const def = keyboardMenuDef(pathId);
    if (!def) {
      return "";
    }
    return def.items
      .filter((item) => workspaceTabVisible(item.workspaceTab))
      .map((item) => `${item.key} ${item.label}`)
      .join("; ");
  }

  function keyboardMenuPathForWorkspace(tabId = currentWorkspaceTab()) {
    const tab = cleanWorkspaceTab(tabId);
    if (tab === "tasks") {
      return "tasks";
    }
    if (tab === "specimens" || tab === "containers") {
      return "creatures";
    }
    if (tab === "resources") {
      return "stores";
    }
    if (tab === "economy") {
      return "economy";
    }
    if (tab === "policies") {
      return "policies";
    }
    if (tab === "journal" || tab === "log") {
      return "records";
    }
    if (tab === "cheats") {
      return "debug";
    }
    return "";
  }

  function workspaceHotkeyDefForKey(key) {
    const def = WORKSPACE_KEY_BY_KEY[String(key || "").toLowerCase()] || null;
    if (!def || (def.debugOnly && !debugToolsEnabled())) {
      return null;
    }
    return workspaceTabVisible(def.workspaceTab) ? def : null;
  }

  function openWorkspaceByHotkey(def) {
    setUiMode(UI_MODE_NAVIGATION);
    const ui = ensureUiState();
    ui.commandMenuOpen = false;
    ui.overlayMenuOpen = false;
    setActiveWorkspaceTab(def.workspaceTab, { scroll: true, animate: false });
    ui.keyboardMenuPath = def.menuPath && keyboardMenuDef(def.menuPath) ? String(def.menuPath) : "";
    persist();
    render();
    return true;
  }

  function applyKeyboardMenuItem(item) {
    setUiMode(UI_MODE_NAVIGATION);
    const ui = ensureUiState();
    ui.commandMenuOpen = false;
    ui.overlayMenuOpen = false;
    setActiveWorkspaceTab(item.workspaceTab, { scroll: true, animate: false });
    if (item.tabKind === "tasks") {
      ui.taskMenuTab = normalizeTaskMenuTab(item.tabId);
    } else if (item.tabKind === "creatures") {
      ui.creatureRecordTab = normalizeCreatureRecordTab(item.tabId);
    } else if (item.tabKind === "production") {
      ui.productionMenuTab = normalizeProductionMenuTab(item.tabId);
    } else if (item.tabKind === "stores") {
      ui.storeMenuTab = normalizeStoreMenuTab(item.tabId);
    } else if (item.tabKind === "economy") {
      ui.economyMenuTab = normalizeEconomyMenuTab(item.tabId);
    } else if (item.tabKind === "policies") {
      ui.policyMenuTab = normalizePolicyMenuTab(item.tabId);
    } else if (item.tabKind === "debug") {
      ui.debugMenuTab = normalizeDebugMenuTab(item.tabId);
    }
    ui.keyboardMenuPath = item.nextPath && keyboardMenuDef(item.nextPath) ? String(item.nextPath) : "";
    persist();
    render();
    return true;
  }

  function handleMenuKeyboardShortcut(event) {
    const key = cleanKeyboardKey(event);
    if (!key) {
      return false;
    }
    const ui = ensureUiState();
    if (ui.mode === UI_MODE_COMMAND || ui.commandMenuOpen) {
      return false;
    }
    const explicitMenu = keyboardMenuDef(ui.keyboardMenuPath);
    if (explicitMenu) {
      const item = explicitMenu.items.find((candidate) =>
        candidate.key.toLowerCase() === key && workspaceTabVisible(candidate.workspaceTab)
      );
      if (item) {
        event.preventDefault();
        applyKeyboardMenuItem(item);
        return true;
      }
      const topLevel = workspaceHotkeyDefForKey(key);
      if (topLevel) {
        event.preventDefault();
        openWorkspaceByHotkey(topLevel);
        return true;
      }
      event.preventDefault();
      ui.keyboardMenuPath = "";
      addEvent(`No ${explicitMenu.label} shortcut for ${key.toUpperCase()}.`);
      persist();
      render();
      return true;
    }
    const workspaceDef = workspaceHotkeyDefForKey(key);
    if (workspaceDef) {
      event.preventDefault();
      openWorkspaceByHotkey(workspaceDef);
      return true;
    }
    const localMenu = keyboardMenuDef(keyboardMenuPathForWorkspace());
    if (localMenu) {
      const item = localMenu.items.find((candidate) =>
        candidate.key.toLowerCase() === key && workspaceTabVisible(candidate.workspaceTab)
      );
      if (item) {
        event.preventDefault();
        applyKeyboardMenuItem(item);
        return true;
      }
    }
    return false;
  }

  function handleMapKeyboardShortcut(event) {
    const key = event.key;
    const ui = ensureUiState();
    if (key === "?" || (event.shiftKey && event.code === "Slash")) {
      event.preventDefault();
      toggleKeyboardHelp();
      return true;
    }
    if (key === "Escape") {
      return handleBackNavigation(event);
    }
    if (ui.mode === UI_MODE_COMMAND) {
      if (/^[1-9]$/.test(key)) {
        event.preventDefault();
        runContextCommandByShortcut(Number(key));
        return true;
      }
      if (mapCursorMovementForKey(event)) {
        event.preventDefault();
        return true;
      }
      return false;
    }
    if (currentWorkspaceTab() !== "map") {
      return false;
    }
    if ((event.code === "BracketLeft" || key === "[") && !event.ctrlKey && !event.metaKey && !event.altKey) {
      event.preventDefault();
      setMapLayer(-1);
      return true;
    }
    if ((event.code === "BracketRight" || key === "]") && !event.ctrlKey && !event.metaKey && !event.altKey) {
      event.preventDefault();
      setMapLayer(1);
      return true;
    }
    const movement = mapCursorMovementForKey(event);
    if (movement) {
      event.preventDefault();
      moveMapCursor(movement.dx, movement.dy);
      return true;
    }
    if (key.toLowerCase() === "o" && !event.ctrlKey && !event.metaKey && !event.altKey) {
      event.preventDefault();
      cycleMapOverlay(event.shiftKey ? -1 : 1);
      return true;
    }
    if (key === "Enter") {
      event.preventDefault();
      selectMapCursorTarget();
      return true;
    }
    return false;
  }

  function handleBackNavigation(event) {
    const ui = ensureUiState();
    if (ui.keyboardHelpOpen) {
      event.preventDefault();
      ui.keyboardHelpOpen = false;
      persist();
      render();
      return true;
    }
    if (ui.commandMenuOpen || ui.mode === UI_MODE_COMMAND) {
      event.preventDefault();
      ui.commandMenuOpen = false;
      ui.keyboardMenuPath = "";
      setUiMode(UI_MODE_NAVIGATION);
      persist();
      render();
      return true;
    }
    if (ui.overlayMenuOpen) {
      event.preventDefault();
      ui.overlayMenuOpen = false;
      persist();
      render();
      return true;
    }
    if (ui.selectionInspectorExpanded) {
      event.preventDefault();
      ui.selectionInspectorExpanded = false;
      persist();
      render();
      return true;
    }
    if (currentWorkspaceTab() !== "map") {
      event.preventDefault();
      ui.keyboardMenuPath = "";
      setActiveWorkspaceTab("map");
      persist();
      render();
      return true;
    }
    const selection = currentSelection();
    if (selection) {
      event.preventDefault();
      ui.keyboardMenuPath = "";
      setSelection(null);
      persist();
      render();
      return true;
    }
    return false;
  }

  function handleTimeShortcut(event) {
    if (event.defaultPrevented || isTypingTarget(event.target) || !state?.started) {
      return false;
    }
    if (event.code === "Space") {
      event.preventDefault();
      togglePause();
      return true;
    }
    if ((event.key === "<" || (event.code === "Comma" && event.shiftKey)) && !event.ctrlKey && !event.metaKey && !event.altKey) {
      event.preventDefault();
      changeTimeSpeed(-1);
      return true;
    }
    if ((event.key === ">" || (event.code === "Period" && event.shiftKey)) && !event.ctrlKey && !event.metaKey && !event.altKey) {
      event.preventDefault();
      changeTimeSpeed(1);
      return true;
    }
    if (event.code === "Period") {
      event.preventDefault();
      if (event.ctrlKey || event.metaKey) {
        skipToNextQueueCompletion();
      } else {
        skipToNextEvent();
      }
      return true;
    }
    return false;
  }

  function handleMapZoomShortcut(event) {
    if (event.defaultPrevented || isTypingTarget(event.target) || !state?.started || currentWorkspaceTab() !== "map") {
      return false;
    }
    if (event.ctrlKey || event.metaKey || event.altKey) {
      return false;
    }
    if (event.key === "+" || event.code === "Equal" || event.code === "NumpadAdd") {
      event.preventDefault();
      setMapZoom(1);
      return true;
    }
    if (event.key === "-" || event.code === "Minus" || event.code === "NumpadSubtract") {
      event.preventDefault();
      setMapZoom(-1);
      return true;
    }
    return false;
  }

