  const SLIME_RESPONSE_STATE_LABELS = {
    calm: "Calm",
    wary: "Wary",
    agitated: "Agitated",
    pained: "Pained",
    panicked: "Panicked",
    desperate: "Desperate"
  };
  const SLIME_RESPONSE_STATES = Object.keys(SLIME_RESPONSE_STATE_LABELS);
