  function containerInteriorMapTargets(container) {
    if (!container?.id) {
      return [];
    }
    const occupants = containerOccupants(container.id)
      .sort((a, b) => containedSlimeInterestScore(b) - containedSlimeInterestScore(a) || a.name.localeCompare(b.name))
      .map((slime) => ({
        kind: "slime",
        id: slime.id,
        label: `${slime.name} contained in ${container.name || "container"}`
      }));
    const corpses = containerCorpses(container.id)
      .sort((a, b) => corpseStateInterestScore(b) - corpseStateInterestScore(a) || a.name.localeCompare(b.name))
      .map((corpse) => ({
        kind: "corpse",
        id: corpse.id,
        label: `${corpse.name} remains in ${container.name || "container"}`
      }));
    return [...occupants, ...corpses];
  }

  function containedSlimeInterestScore(slime) {
    if (!slime) {
      return 0;
    }
    let score = 10;
    if (slime.status === "released") score += 20;
    if (!slime.mature) score += 2;
    score += Math.round(clamp(slimeStat(slime, "stress").current, 0, 100) / 10);
    score += Math.round(clamp(100 - slimeStat(slime, "bodyIntegrity").current, 0, 100) / 10);
    if (slimeRoleId(slime) !== "idle") score += 5;
    if (slime.containmentTest?.active) score += 8;
    return score;
  }

  function corpseStateInterestScore(corpse) {
    const freshness = corpseFreshness(corpse);
    return { fresh: 8, decaying: 6, spoiled: 4, ruined: 2 }[freshness] || 1;
  }

  function taskRouteList(task) {
    if (!task) {
      return [];
    }
    if (Array.isArray(task.data?.routes)) {
      return task.data.routes.filter((route) => Array.isArray(route) && route.length);
    }
    return Array.isArray(task.data?.route) && task.data.route.length ? [task.data.route] : [];
  }

  function taskPathList(task) {
    if (!task) {
      return [];
    }
    if (Array.isArray(task.data?.mapPaths)) {
      return task.data.mapPaths.filter((path) => Array.isArray(path) && path.length);
    }
    if (Array.isArray(task.data?.mapPath) && task.data.mapPath.length) {
      return [task.data.mapPath];
    }
    return [];
  }

  function taskPathCells(task) {
    return taskPathList(task).flat();
  }

  function scientistTaskDisplayPaths(task, options = {}) {
    if (!task) return [];
    if (options.remaining && task.data?.movement) {
      const movement = normalizeScientistMovementRecord(task.data.movement, task);
      if (movement?.steps?.length) {
        const remaining = movement.steps
          .slice(movement.stepIndex)
          .map((step) => cleanMapCell(step.cell))
          .filter(Boolean);
        if (remaining.length) return [remaining];
      }
    }
    return taskPathList(task)
      .map((path) => path.map(cleanMapCell).filter(Boolean))
      .filter((path) => path.length);
  }

  function scientistRouteMarkers(paths) {
    const markers = new Map();
    const connection = (from, to) => {
      if (!from || !to) return null;
      if (from.z !== to.z) return to.z > from.z ? "up" : "down";
      if (to.x === from.x && to.y === from.y - 1) return "north";
      if (to.x === from.x + 1 && to.y === from.y) return "east";
      if (to.x === from.x && to.y === from.y + 1) return "south";
      if (to.x === from.x - 1 && to.y === from.y) return "west";
      return null;
    };
    for (const path of paths) {
      for (let index = 0; index < path.length; index += 1) {
        const cell = path[index];
        const key = mapCellKey(cell);
        if (!key) continue;
        const marker = markers.get(key) || {
          connections: new Set(),
          start: false,
          end: false,
          vertical: new Set()
        };
        marker.start ||= index === 0;
        marker.end ||= index === path.length - 1;
        for (const neighbor of [path[index - 1], path[index + 1]]) {
          const direction = connection(cell, neighbor);
          if (["up", "down"].includes(direction)) marker.vertical.add(direction);
          else if (direction) marker.connections.add(direction);
        }
        markers.set(key, marker);
      }
    }
    return new Map([...markers.entries()].map(([key, marker]) => [key, {
      connections: [...marker.connections],
      start: marker.start,
      end: marker.end,
      vertical: [...marker.vertical]
    }]));
  }

  function taskPathSummary(task) {
    const paths = taskPathList(task);
    if (!paths.length) {
      return "No map path recorded";
    }
    return paths.map((path) => mapPathSummary(path, ensureLabMap())).join("; ");
  }

  function taskMovementRoute(task, map = ensureLabMap(), options = {}) {
    if (!task) {
      return { task: null, keys: new Set(), markers: new Map(), label: "" };
    }
    const paths = scientistTaskDisplayPaths(task, { remaining: options.remaining });
    const markers = scientistRouteMarkers(paths);
    return {
      task,
      keys: new Set(markers.keys()),
      markers,
      label: task.label || "queued movement",
      selected: Boolean(options.selected)
    };
  }

  function selectedOrNextScientistTaskRoute(map = ensureLabMap()) {
    const selected = currentSelection();
    const selectedTask = selected?.kind === "task" ? findTask(selected.id) : null;
    if (selectedTask && isScientistQueueTask(selectedTask) && taskPathCells(selectedTask).length) {
      return taskMovementRoute(selectedTask, map, {
        selected: true,
        remaining: selectedTask.id === firstScientistQueueTask()?.id
      });
    }
    const task = scientistQueueTasks().find((candidate) => taskPathCells(candidate).length) || null;
    return taskMovementRoute(task, map, { remaining: task?.id === firstScientistQueueTask()?.id });
  }

  function taskTargetRoomId(task) {
    if (!task) {
      return "";
    }
    return roomById(task.data?.toRoomId)?.id
      || roomById(task.data?.resourceRoomId)?.id
      || roomById(task.data?.roomId)?.id
      || roomById(task.data?.fromRoomId)?.id
      || "";
  }

  function taskTargetCell(task) {
    if (!task) {
      return null;
    }
    return cleanMapCell(task.data?.toCell)
      || cleanMapCell(task.data?.targetCell)
      || cleanMapCell(task.data?.fromCell)
      || (Array.isArray(task.data?.cells) ? cleanMapCell(task.data.cells[0]) : null)
      || taskPathCells(task).at(-1)
      || null;
  }

  function taskDoorBlockReason(task) {
    for (const path of taskPathList(task)) {
      const reason = firstMapPathDoorSecurityBlockReason(path);
      if (reason) return reason;
    }
    for (const route of taskRouteList(task)) {
      const reason = firstDoorSecurityBlockReason(route);
      if (reason) {
        return reason;
      }
    }
    return "";
  }

  function taskCarriedLoad(task) {
    if (task?.data?.carriedLoad) return task.data.carriedLoad;
    if (task?.type === "resourceHaul" && task.data?.transfers?.length) {
      return resourceHaulCarriedLoad(task.data.transfers[0]);
    }
    return null;
  }

  function synthesisTaskBlockReason() {
    const tube = synthesisTube();
    if (!tube) {
      return "No synthesis tube exists.";
    }
    const occupants = synthesisTubeOccupants();
    if (occupants.length) {
      return `Synthesis tube occupied by ${occupants.map((slime) => slime.name).join(", ")}.`;
    }
    const corpses = containerCorpses(tube.id);
    if (corpses.length) {
      return `Synthesis tube blocked by ${corpses.map((corpse) => `${corpse.name} remains`).join(", ")}.`;
    }
    return "";
  }

  function collectionBayTransferTaskBlockReason(task) {
    if (scientistRoomId() !== COLLECTION_BAY_ROOM_ID) {
      return "Scientist must be in the Collection Bay.";
    }
    const container = containerById(task.data?.containerId);
    const info = collectionBayStationInfo(container);
    if (!container || !info?.station || !info.station.material) {
      return "No collection receptacle is assigned.";
    }
    if ((Number(info.station.receptacle?.amount) || 0) <= 0) {
      return "Receptacle is empty.";
    }
    const replacementItemKey = task.data?.replacementItemKey || info.station.receptacle.itemKey;
    if (!replacementItemKey || physicalEmptyReceptacleStacks(replacementItemKey).reduce((total, stack) => total + stack.quantity, 0) <= 0) {
      return `No empty ${inventoryItemLabel(replacementItemKey || "receptacle")} remains for the replacement.`;
    }
    return "";
  }

  function resourceHaulTaskBlockReason(task) {
    const transfers = Array.isArray(task.data?.transfers) ? task.data.transfers : [];
    if (!transfers.length) {
      return "No material transfer is recorded.";
    }
    const haulLegs = resourceHaulLegs(task);
    for (const [transferIndex, transfer] of transfers.entries()) {
      const required = haulLegs.length
        ? haulLegs.filter((leg) => leg.transferIndex === transferIndex && leg.status === "pending").reduce((total, leg) => total + Math.max(0, Number(leg.amount) || 0), 0)
        : transfer.amount;
      if (resourceAmountInRoom(transfer.key, transfer.fromRoomId) < required) {
        return `${roomName(transfer.fromRoomId)} no longer has ${formatNumber(required)} ${resourceLabel(transfer.key)}.`;
      }
    }
    return "";
  }

  function taskBlackMarketSpecimenReservationReason(task) {
    const data = task?.data || {};
    const referencedSlimeIds = new Set([
      data.slimeId,
      data.parentAId,
      data.parentBId,
      ...(Array.isArray(data.parentIds) ? data.parentIds : [])
    ].filter(Boolean));
    for (const slimeId of referencedSlimeIds) {
      const slime = findSlime(slimeId);
      if (slime?.blackMarketContractId && slime.blackMarketContractId !== data.contractId) {
        return `${slime.name} is reserved for ${slime.blackMarketContractId} and cannot be used for other work.`;
      }
    }
    const referencedContainerIds = new Set([
      data.containerId,
      data.sourceContainerId,
      data.destinationContainerId,
      ...(Array.isArray(data.destinationContainerIds) ? data.destinationContainerIds : [])
    ].filter(Boolean));
    for (const containerId of referencedContainerIds) {
      const reserved = containerOccupants(containerId).find((slime) => slime?.blackMarketContractId && slime.blackMarketContractId !== data.contractId);
      if (reserved) return `${reserved.name} is reserved for ${reserved.blackMarketContractId}; its container cannot be moved or serviced by conflicting work.`;
    }
    return "";
  }

  function taskBlockReason(task) {
    if (!task || !isScientistQueueTask(task)) {
      return "";
    }
    if (scientistIsDead()) {
      return "The scientist is dead.";
    }
    const custodyStatus = scientistRaidCustodyStatus();
    if (["surrendered", "restraining", "restrained", "extracting"].includes(custodyStatus)) {
      return "The scientist is under active physical arrest and cannot perform ordinary work.";
    }
    if (custodyStatus === "booked" && !["detentionSecurityStudy", "jailCommunication", "pretrialHearing", "pretrialReleaseTransport", "pretrialLegalWork", "trialCourtAppearance", "trialRemandTransport", "jailEscapeAction", "rest"].includes(task.type)
      && !(task.type === "scientistMove" && [MUNICIPAL_HOLDING_CELL_ROOM_ID, MUNICIPAL_HOLDING_CORRIDOR_ROOM_ID].includes(task.data?.toRoomId))) {
      return "The scientist is in pretrial detention and cannot reach the laboratory.";
    }
    if (currentPrisonStay() && !["prisonInteraction", "prisonCommunication", "prisonReleaseReview", "prisonDischarge", "prisonBreakAction", "rest"].includes(task.type)) return "The scientist is serving a finite prison sentence and cannot reach or directly supervise the laboratory.";
    if (currentDeathRowStay() && !["capitalAppealTransfer", "executiveCommutationTransfer", "deathRowEscapeAction", "publicExecutionAction", "rest"].includes(task.type)) return "The scientist is held in the State Capital Custody Unit and cannot reach or directly supervise the laboratory.";
    if (scientistInFugitiveStaging() && !["jailEscapeAction", "prisonBreakAction", "deathRowEscapeAction", "rest"].includes(task.type)) {
      return "The scientist is at an off-site fugitive staging location and cannot perform or directly supervise laboratory work.";
    }
    if (actorIsIncapacitated("scientist") && task.type !== "rest" && !(task.type === "injuryTreatment" && task.data?.targetActorId === "scientist")) {
      return "The scientist is incapacitated and must be stabilized before resuming work.";
    }
    const activeTrade = activeBlackMarketTradeTask();
    if (activeTrade && activeTrade.id !== task.id) {
      return "The scientist is outside the lab for a black market trade.";
    }
    const specimenReservationReason = taskBlackMarketSpecimenReservationReason(task);
    if (specimenReservationReason) return specimenReservationReason;
    const laborAdapter = laborTaskAdapterInfo(task);
    if (laborAdapter && !scientistLaborCategoryEnabled(laborAdapter.category)) {
      return `${laborCategoryLabel(laborAdapter.category)} is disabled for the scientist.`;
    }
    const doorReason = taskDoorBlockReason(task);
    if (doorReason) {
      return doorReason;
    }
    const carriedLoad = taskCarriedLoad(task);
    if (carriedLoad) {
      for (const path of taskPathList(task)) {
        const payloadReason = mapPathPayloadBlockReason(path, carriedLoad);
        if (payloadReason) return payloadReason;
      }
    }
    if (!task.data?.accessOverrideAll) {
      const allowedOverrideKeys = new Set(Array.isArray(task.data?.accessOverrideKeys) ? task.data.accessOverrideKeys : []);
      for (const path of taskPathList(task)) {
        const accessViolation = pathAccessViolations(state.scientist, path).find((violation) => !allowedOverrideKeys.has(violation.key));
        if (accessViolation) return accessViolation.reason;
      }
    }
    if (task.type === "blackMarketTrade") {
      return blackMarketTradeTaskBlockReason(task);
    }
    if (task.type === "commodityFreight") {
      return ensureEconomy().commodityConsignments.some((entry) => entry.id === task.data?.consignmentId)
        ? ""
        : "The legal consignment no longer exists.";
    }
    if (task.type === "companyFiling") {
      const period = ensureCompany().periods.find((entry) => entry.id === task.data?.periodId);
      return period && period.status === "filing" && period.taskId === task.id
        ? ""
        : "The company reporting period is no longer assigned to this filing task.";
    }
    if (task.type === "evidenceHandling") {
      const order = ensureEvidenceHandling().orders.find((entry) => entry.id === task.data?.orderId);
      if (!order || !["queued", "active"].includes(order.status)) return "The evidence-handling order is no longer active.";
      if (task.data?.action === "amend") {
        return ensureCompany().variances.some((variance) => variance.id === task.data?.varianceId && variance.status === "open")
          ? "" : "The selected records variance is no longer open.";
      }
      const stack = ensurePhysicalItemStacks().find((entry) => entry.id === task.data?.stackId);
      if (!stack || stack.quantity <= 0) return "The physical evidence subject no longer exists.";
      if (stack.reservedTaskId && stack.reservedTaskId !== task.id) return "The subject is reserved for different work.";
      if (task.data?.action === "dispose" && ensureEconomy().money < Number(task.data?.fee || 0)) return "Licensed disposal funds are no longer available.";
      return "";
    }
    if (task.type === "synthesize") {
      return synthesisTaskBlockReason(task);
    }
    if (task.type === "test") {
      return findSlime(task.data?.slimeId) ? "" : "The test specimen is no longer available.";
    }
    if (task.type === "breed") {
      return reproductionProcedureTaskBlockReason(task);
    }
    if (task.type === "necropsy" || task.type === "harvestCorpse") {
      return findCorpse(task.data?.corpseId) ? "" : "The corpse is no longer available.";
    }
    if (task.type === "harvestSlime") {
      const slime = findSlime(task.data?.slimeId);
      return slime && slime.status !== "dead" ? "" : "The living specimen is no longer available.";
    }
    if (task.type === "containerHaul" || task.type === "containerInteraction" || task.type === "collectionBayTransfer") {
      if (!containerById(task.data?.containerId)) {
        return "The target container no longer exists.";
      }
    }
    if (task.type === "recaptureSlime") {
      return recaptureSlimeBlockReason(findSlime(task.data?.slimeId), containerById(task.data?.destinationContainerId), {
        taskId: task.id,
        targetCell: task.data?.targetCell,
        methodId: task.data?.methodId,
        secured: task.data?.secured
      });
    }
    if (task.type === "placeBait") {
      return placeBaitBlockReason(task.data?.targetCell, task.data?.feedstockKey, {
        taskId: task.id,
        sourceStackId: task.data?.sourceStackId
      });
    }
    if (task.type === "containerHaul" && !roomById(task.data?.toRoomId)) {
      return "The destination room no longer exists.";
    }
    if (task.type === "resourceHaul") {
      return resourceHaulTaskBlockReason(task);
    }
    if (task.type === "stockpileHaul") {
      return stockpileHaulTaskBlockReason(task);
    }
    if (task.type === "collectionBayTransfer") {
      return collectionBayTransferTaskBlockReason(task);
    }
    if (task.type === "spillCleanup") {
      return spillCleanupTaskBlockReason(task);
    }
    if (task.type === "scientistMove" && !roomById(task.data?.toRoomId)) {
      return "The destination room no longer exists.";
    }
    if (task.type === "scientistMove" && !canActorOccupyTile(state.scientist, task.data?.toCell)) {
      return "The destination tile no longer has enough clear space for the scientist.";
    }
    if (task.type === "doorOperation") {
      return doorOperationTaskBlockReason(task);
    }
    if (task.type === "visitFixtureAccess") {
      const fixture = fixtureById(task.data?.fixtureId);
      const visit = siteVisitById(task.data?.visitId);
      if (!fixture) return "The requested storage fixture no longer exists.";
      if (!visit?.actor.present) return "The visitor is no longer on site.";
      if (!visit.grantedFixtureIds.includes(fixture.id)) return "The visit no longer has permission for this fixture.";
    }
    if (task.type === "forcedEntryCompliance") {
      const visit = siteVisitById(task.data?.visitId);
      const execution = warrantExecutionForVisit(visit);
      const barrier = execution?.forcedEntry?.barriers.find((entry) => entry.id === task.data?.barrierId);
      if (!visit?.actor.present) return "The enforcement team is no longer on site.";
      if (!barrier || barrier.status !== "complied") return "This forced-entry barrier no longer awaits late compliance.";
      const targetCell = cleanMapCell(task.data?.toCell);
      if (!targetCell || !labMapPathBetweenCells(scientistMapCell(), targetCell, {
        map: ensureLabMap(), actor: state.scientist, ignoreDoors: true, ignoreAccessPolicy: true
      }).length) return "No physical route currently reaches the barrier operating position.";
    }
    if (task.type === "institutionalResponse") {
      return institutionalResponseTaskBlockReason(task);
    }
    if (task.type === "constructionWork") {
      const order = constructionOrderById(task.data?.constructionOrderId);
      const tile = constructionOrderTile(order, task.data?.constructionTileKey || task.data?.targetCell);
      if (!order || !tile || tile.status !== "queued" || tile.taskId !== task.id) return "The construction designation no longer exists.";
      const staticReason = constructionTileStaticBlockReason(order.mode, tile.cell, { exceptOrderId: order.id, order });
      if (staticReason) return staticReason;
      const occupancyReason = constructionTargetOccupancyBlockReason(order, tile);
      if (occupancyReason) return occupancyReason;
      for (const selection of task.data?.toolSelections || []) {
        const tool = toolInstanceById(selection.instanceId)?.instance;
        if (!tool) return `${inventoryItemLabel(selection.itemKey)} is no longer available.`;
        if (tool.current <= 0) return `${inventoryItemLabel(selection.itemKey)} is broken.`;
        if (tool.reservedTaskId && tool.reservedTaskId !== task.id) return `${inventoryItemLabel(selection.itemKey)} is reserved for other work.`;
      }
      const map = ensureLabMap();
      const accessCell = cleanMapCell(task.data?.toCell);
      if (!accessCell || !labMapCellIsWalkable(accessCell, map)) return "The designated work position is no longer walkable floor.";
      if (mapCellKey(accessCell) !== mapCellKey(scientistMapCell()) && labMapCellIsPathBlocked(accessCell, { map })) return "The designated work position is occupied.";
      return labMapPathBetweenCells(scientistMapCell(), accessCell, { map, ignoreDoors: true }).length
        ? ""
        : "No physical route currently reaches the designated work position.";
    }
    if (task.type === "productionWork") {
      return productionWorkTaskBlockReason(task);
    }
    if (task.type === "toolMaintenance") {
      const tool = toolInstanceById(task.data?.toolInstanceId)?.instance;
      if (!tool) return "The tool is no longer available.";
      if (tool.reservedTaskId && tool.reservedTaskId !== task.id) return "The tool is reserved for other work.";
    }
    if (task.type === "equipmentChange") {
      return equipmentChangeBlockReason(task.data?.itemKey, task.data?.toolInstanceId, task.data?.action, task.id);
    }
    if (task.type === "physicalDiagnostic") {
      return physicalDiagnosticTaskBlockReason(task);
    }
    if (task.type === "experimentConclusion") {
      return experimentConclusionTaskBlockReason(task);
    }
    if (task.type === "researchWork") {
      return researchWorkTaskBlockReason(task);
    if (task.type === "injuryTreatment") {
      const injury = (state.injuries || []).find((entry) => entry.id === task.data?.injuryId);
      if (!injury || injury.status === "healed") return "The selected injury no longer needs care.";
      const stackId = task.data?.supplyStackId;
      if (stackId) {
        const stack = ensurePhysicalItemStacks().find((entry) => entry.id === stackId);
        if (!stack || stack.reservedTaskId !== task.id || stack.quantity <= 0) return "The reserved medical supply is no longer available.";
      }
    }
    }
    if (task.type === "laborWork") {
      return laborWorkTaskBlockReason(task);
    }
    return "";
  }

  function taskStatusInfo(task) {
    const blockedReason = taskBlockReason(task) || task.data?.blockedReason || "";
    if (blockedReason) {
      return { id: "blocked", label: "Blocked", reason: blockedReason };
    }
    if (task.dueAt <= state.clock) {
      return { id: "ready", label: "Ready", reason: "" };
    }
    if (firstScientistQueueTask()?.id === task.id) {
      return { id: "active", label: "Active", reason: "" };
    }
    return { id: "queued", label: "Queued", reason: "" };
  }

  function cleanTaskHistoryStatus(value) {
    const status = String(value || "completed").trim();
    return ["completed", "canceled"].includes(status) ? status : "completed";
  }

  function taskHistoryEntry(task, status = "completed") {
    const cleanStatus = cleanTaskHistoryStatus(status);
    return {
      id: `task-history-${task?.id || state.nextTaskNumber}-${cleanStatus}-${Math.round(state.clock)}`,
      taskId: String(task?.id || ""),
      type: String(task?.type || "task"),
      label: String(task?.label || "Task"),
      category: task ? taskCategory(task) : "Task",
      status: cleanStatus,
      createdAt: finiteTime(task?.createdAt, state.clock),
      dueAt: finiteTime(task?.dueAt, state.clock),
      completedAt: state.clock,
      targetRoomId: taskTargetRoomId(task),
      pathSummary: taskPathSummary(task),
      details: cleanStatus === "canceled" ? "Canceled by player." : "Finished."
    };
  }

  function normalizeTaskHistory(candidate = []) {
    return (Array.isArray(candidate) ? candidate : [])
      .map((entry, index) => ({
        id: String(entry?.id || `task-history-${index}`),
        taskId: String(entry?.taskId || ""),
        type: String(entry?.type || "task"),
        label: String(entry?.label || "Task"),
        category: String(entry?.category || "Task"),
        status: cleanTaskHistoryStatus(entry?.status),
        createdAt: finiteTime(entry?.createdAt, 0),
        dueAt: finiteTime(entry?.dueAt, finiteTime(entry?.completedAt, 0)),
        completedAt: finiteTime(entry?.completedAt, 0),
        targetRoomId: cleanRoomId(entry?.targetRoomId),
        pathSummary: String(entry?.pathSummary || "No map path recorded"),
        details: String(entry?.details || "")
      }))
      .sort((a, b) => b.completedAt - a.completedAt || String(b.id).localeCompare(String(a.id)))
      .slice(0, TASK_HISTORY_LIMIT);
  }

  function recordTaskHistory(task, status = "completed") {
    if (!task || !isScientistQueueTask(task)) {
      return;
    }
    state.taskHistory = normalizeTaskHistory([
      taskHistoryEntry(task, status),
      ...(state.taskHistory || [])
    ]);
  }

  function cancelTaskBlockReason(task) {
    if (!task) {
      return "Task no longer exists.";
    }
    if (!isScientistQueueTask(task)) {
      return "Only scientist queue tasks can be canceled here.";
    }
    if (["jailEscapeAction", "prisonBreakAction"].includes(task.type)) {
      return "An active escape stage or fugitive journey cannot be canceled after its physical opportunity begins.";
    }
    if (["pretrialHearing", "pretrialReleaseTransport", "pretrialLegalWork", "trialCourtAppearance", "trialRemandTransport"].includes(task.type)) {
      return "A court appearance or court-ordered custody transfer cannot be canceled from the ordinary work queue.";
    }
    return "";
  }

  function cleanupCancelledTask(task) {
    if (!task) {
      return;
    }
    if (task.type !== "laborWork" && task.data?.resourceCosts && Object.keys(task.data.resourceCosts).length) {
      addResources(task.data.resourceCosts, task.data.resourceRoomId || task.data.roomId || STORAGE_ROOM_ID);
    }
    if (task.type === "blackMarketTrade") {
      const contract = blackMarketContractById(task.data?.contractId);
      if (contract && contract.taskId === task.id) {
        contract.status = "active";
        contract.taskId = "";
      } else {
        const deal = blackMarketDealById(task.data?.dealId);
        if (deal && deal.taskId === task.id) {
          deal.status = "open";
          deal.taskId = "";
        }
      }
    }
    if (task.type === "resourceHaul") {
      releaseResourceHaulCarriedLoads(task);
    }
    if (task.type === "constructionWork") {
      const order = constructionOrderById(task.data?.constructionOrderId);
      const tile = constructionOrderTile(order, task.data?.constructionTileKey || task.data?.targetCell);
      if (tile) {
        tile.status = "canceled";
        tile.taskId = "";
        tile.blockedReason = "";
      }
      releaseConstructionTaskTools(task, { retain: false });
      cancelLinkedFixtureProduction(order);
    }
    if (task.type === "productionWork") {
      cleanupCanceledProductionTask(task);
    }
    if (task.type === "toolMaintenance") {
      const tool = toolInstanceById(task.data?.toolInstanceId)?.instance;
      if (tool?.reservedTaskId === task.id) tool.reservedTaskId = "";
    }
    if (task.type === "equipmentChange") {
      const tool = toolInstanceById(task.data?.toolInstanceId)?.instance;
      const stack = ensurePhysicalItemStacks().find((entry) => entry.id === task.data?.stackId);
      if (tool?.reservedTaskId === task.id) tool.reservedTaskId = "";
      if (stack?.reservedTaskId === task.id) stack.reservedTaskId = "";
    }
    if (task.type === "institutionalResponse") {
      state.institutionalResponses = InstitutionalResponses.cancelPreparation(
        ensureInstitutionalResponses(), task.data?.responseId, state.clock
      );
    }
    if (task.type === "physicalDiagnostic") {
      releaseConstructionTaskTools(task, { retain: false });
      releaseProductionMaterialReservations(task);
    }
    if (task.type === "experimentConclusion") {
      cleanupCanceledExperimentConclusion(task);
    if (task.type === "injuryTreatment") {
      const stack = ensurePhysicalItemStacks().find((entry) => entry.id === task.data?.supplyStackId);
      if (stack?.reservedTaskId === task.id) stack.reservedTaskId = "";
    }
    }
    if (task.type === "researchWork") {
      cleanupCanceledResearchTask(task);
    }
    if (task.type === "stockpileHaul") {
      const stack = ensurePhysicalItemStacks().find((entry) => entry.id === task.data?.stackId);
      if (stack?.reservedTaskId === task.id) stack.reservedTaskId = "";
    }
    if (task.type === "spillCleanup") {
      const stack = physicalSpillStackById(task.data?.spillId);
      if (stack?.reservedTaskId === task.id) stack.reservedTaskId = "";
      const scraper = task.data?.toolInstanceId ? toolInstanceById(task.data.toolInstanceId)?.instance : null;
      if (scraper?.reservedTaskId === task.id) scraper.reservedTaskId = "";
      const wash = ensurePhysicalItemStacks().find((entry) => entry.id === task.data?.washStackId);
      if (wash?.reservedTaskId === task.id) wash.reservedTaskId = "";
      const order = ensureEvidenceHandling().orders.find((entry) => entry.id === task.data?.orderId);
      if (order) {
        order.status = "canceled";
        order.interruption = "Cleanup canceled before collection completed.";
        order.completedAt = state.clock;
      }
    }
    if (task.type === "evidenceHandling") {
      const order = ensureEvidenceHandling().orders.find((entry) => entry.id === task.data?.orderId);
      const stack = ensurePhysicalItemStacks().find((entry) => entry.id === task.data?.stackId);
      if (order) {
        order.status = "canceled";
        order.interruption = "Canceled by player before physical completion.";
        order.completedAt = state.clock;
      }
      if (stack?.reservedTaskId === task.id) stack.reservedTaskId = "";
    }
    if (task.type === "placeBait") {
      const stack = ensurePhysicalItemStacks().find((entry) => entry.id === task.data?.sourceStackId);
      if (stack?.reservedTaskId === task.id) stack.reservedTaskId = "";
    }
    if (task.type === "recaptureSlime" && task.data?.secured) {
      const slime = findSlime(task.data?.slimeId);
      if (slime && slime.status !== "dead" && slimeIsUncontained(slime)) {
        slime.mapCell = cleanMapCell(state.scientist.mapCell) || slime.mapCell;
        slime.roomId = scientistRoomId();
        slime.roomActivity = { type: "emerging", label: "recovering from interrupted handling", roomId: slime.roomId, updatedAt: state.clock };
        slime.nextAutonomousDecisionAt = state.clock;
      }
    }
    const incidentId = String(task.data?.incidentId || "").trim();
    if (incidentId) {
      const incident = incidentById(incidentId);
      if (incident && incident.responseTaskId === task.id) {
        incident.responseTaskId = "";
        incident.updatedAt = state.clock;
      }
    }
    for (const incident of state.incidents || []) {
      if (incident.responseTaskId === task.id) {
        incident.responseTaskId = "";
        incident.updatedAt = state.clock;
      }
    }
  }

  function cancelTask(taskId, options = {}) {
    const task = findTask(taskId);
    const reason = cancelTaskBlockReason(task);
    if (reason) {
      addEvent(reason);
      persist();
      render();
      return false;
    }
    cleanupCancelledTask(task);
    finishWorkOrderForTask(task, "canceled");
    if (task.type === "scientistMove") movementReservations.releaseActor("scientist");
    state.tasks = (state.tasks || []).filter((candidate) => candidate.id !== task.id);
    if (task.id === state.combat?.routineSuspension?.taskId) resumeScientistRoutineWork();
    if (currentSelection()?.kind === "task" && currentSelection().id === task.id) {
      setSelection(null);
    }
    recordTaskHistory(task, "canceled");
    refreshConstructionOrderBlocks();
    claimNextConstructionWork();
    if (!options.noProductionClaim) claimNextProductionWork();
    if (!options.noLaborClaim) claimNextLaborWork();
    if (!options.quiet) addEvent(`Canceled task: ${task.label}.`);
    if (!options.quiet) {
      persist();
      render();
    }
    return true;
  }

  function selectedMapTarget() {
    const selection = currentSelection();
    state.selectedMapTarget = selectionToMapTarget(selection);
    return state.selectedMapTarget;
  }

  function currentSelection() {
    const normalized = normalizeSelection(state.selection)
      || normalizeSelection(state.selectedMapTarget)
      || normalizeSelection(state.selectedSlimeId ? { kind: "slime", id: state.selectedSlimeId, source: "legacy" } : null);
    state.selection = normalized;
    syncLegacySelectionFields(normalized);
    return normalized;
  }

  function setSelection(target, options = {}) {
    const previousKey = selectionKey(state.selection);
    const normalized = normalizeSelection({
      ...(target || {}),
      source: options.source || target?.source,
      pinned: options.pinned ?? target?.pinned
    });
    const custodyCell = normalized ? selectionMapCell(normalized) : null;
    if (currentJailStay() && custodyCell && custodyCell.z !== MUNICIPAL_HOLDING_Z) return state.selection;
    if (currentPrisonStay() && custodyCell && custodyCell.z !== STATE_PRISON_Z) return state.selection;
    if (currentDeathRowStay() && custodyCell && custodyCell.z !== CAPITAL_CUSTODY_Z) return state.selection;
    if (scientistInFugitiveStaging() && custodyCell && custodyCell.z !== FUGITIVE_STAGING_Z) return state.selection;
    state.selection = normalized;
    if (normalized && options.centerMap !== false) {
      const cell = selectionMapCell(normalized);
      if (cell) {
        ensureMapCameraIncludesCell(cell);
      }
    }
    if (state.ui) {
      const nextKey = selectionKey(normalized);
      if (!normalized) {
        state.ui.selectionInspectorExpanded = false;
      }
      if (!normalized || previousKey !== nextKey) {
        state.ui.commandMenuOpen = false;
        if (state.ui.mode === UI_MODE_COMMAND) {
          state.ui.mode = UI_MODE_NAVIGATION;
        }
      }
    }
    syncLegacySelectionFields(normalized);
    return normalized;
  }

  function syncSelectionState() {
    currentSelection();
  }

  function syncLegacySelectionFields(selection) {
    state.selectedMapTarget = selectionToMapTarget(selection);
    state.selectedSlimeId = selection?.kind === "slime" ? selection.id : null;
  }

  function selectionSource(source) {
    const clean = String(source || "panel");
    return ["map", "panel", "log", "queue", "auto", "legacy", "inspector", "keyboard"].includes(clean) ? clean : "panel";
  }

  function normalizeSelection(candidate) {
    const target = normalizeMapTarget(candidate);
    if (!target) {
      return null;
    }
    return {
      ...target,
      source: selectionSource(candidate?.source),
      pinned: Boolean(candidate?.pinned)
    };
  }

  function normalizeMapTarget(candidate) {
    if (!candidate || typeof candidate !== "object") {
      return null;
    }
    const kind = String(candidate.kind || "");
    if (kind === "scientist") {
      return { kind, id: "scientist" };
    }
    if (kind === "visitor") {
      const id = String(candidate.id || "");
      const found = siteVisitActorById(id);
      return found?.actor.present ? { kind, id: found.actor.id } : null;
    }
    if (kind === "raidOfficer") {
      const id = String(candidate.id || "");
      const found = raidActorById(id);
      return found?.actor.present ? { kind, id: found.actor.id } : null;
    }
    if (kind === "jailOfficer") {
      const id = String(candidate.id || "");
      const found = jailActorById(id);
      return found?.actor.present ? { kind, id: found.actor.id } : null;
    }
    if (kind === "prisonActor") { const id = String(candidate.id || ""); const found = prisonActorById(id); return found?.actor.present ? { kind, id: found.actor.id } : null; }
    if (kind === "capitalCustodyActor") { const id = String(candidate.id || ""); const found = capitalCustodyActorById(id); return found?.actor.present ? { kind, id: found.actor.id } : null; }
    if (kind === "tile") {
      const map = ensureLabMap();
      const cell = cleanMapCell(candidate.tile || candidate.cell || candidate);
      if (!mapCellInBounds(cell, map)) {
        return null;
      }
      return { kind, tile: cell, roomId: labMapCellRoomId(cell, map) || "" };
    }
    if (kind === "room") {
      const roomId = roomById(candidate.roomId || candidate.id)?.id || "";
      return roomId ? { kind, roomId } : null;
    }
    if (kind === "door") {
      const key = doorKey(candidate.roomIds?.[0], candidate.roomIds?.[1]) || String(candidate.key || "");
      const door = key ? labMapDoor(key) : null;
      return door ? { kind, key: door.key, roomIds: [...door.roomIds] } : null;
    }
    if (kind === "container") {
      const id = cleanContainerId(candidate.id);
      return id && containerById(id) ? { kind, id } : null;
    }
    if (kind === "fixture") {
      const id = String(candidate.id || "");
      return id && fixtureById(id) ? { kind, id } : null;
    }
    if (kind === "itemStack") {
      const id = String(candidate.id || "");
      return id && ensurePhysicalItemStacks().some((stack) => stack.id === id) ? { kind, id } : null;
    }
    if (kind === "slime") {
      const id = String(candidate.id || "");
      return id && findSlime(id) ? { kind, id } : null;
    }
    if (kind === "corpse") {
      const id = String(candidate.id || "");
      return id && findCorpse(id) ? { kind, id } : null;
    }
    if (kind === "incident") {
      const id = String(candidate.id || "");
      const incident = id ? incidentById(id) : null;
      return incident ? { kind, id: incident.id, roomId: incident.roomId, tile: cleanMapCell(incident.cell) } : null;
    }
    if (kind === "task") {
      const id = String(candidate.id || "");
      const task = id ? findTask(id) : null;
      return task ? { kind, id: task.id } : null;
    }
    if (kind === "collectionStation") {
      const id = cleanContainerId(candidate.id || candidate.containerId);
      const container = id ? containerById(id) : null;
      return container && collectionBayStationSelectable(container) ? { kind, id: container.id, roomId: container.roomId } : null;
    }
    if (kind === "stockpile") {
      const roomId = roomById(candidate.roomId)?.id || roomById(candidate.id)?.id || "";
      const focusId = normalizeResourceOverlayFocusId(candidate.focusId || candidate.resourceFocusId || candidate.key);
      return roomId ? { kind, id: `${roomId}:${focusId}`, roomId, focusId } : null;
    }
    if (kind === "tool" || kind === "resource") {
      const id = String(candidate.id || candidate.key || "");
      return id ? { kind, id } : null;
    }
    return null;
  }

  function selectionToMapTarget(selection) {
    if (!selection) {
      return null;
    }
    if (selection.kind === "tile") {
      return { kind: "tile", tile: { ...selection.tile }, roomId: selection.roomId || "" };
    }
    if (selection.kind === "scientist") {
      return { kind: "scientist", id: "scientist" };
    }
    if (selection.kind === "room") {
      return { kind: "room", roomId: selection.roomId };
    }
    if (selection.kind === "door") {
      return { kind: "door", key: selection.key, roomIds: [...(selection.roomIds || [])] };
    }
    if (selection.kind === "collectionStation") {
      return { kind: "collectionStation", id: selection.id, roomId: selection.roomId || "" };
    }
    if (selection.kind === "stockpile") {
      return { kind: "stockpile", id: selection.id, roomId: selection.roomId || "", focusId: selection.focusId || DEFAULT_RESOURCE_OVERLAY_FOCUS_ID };
    }
    if (["visitor", "raidOfficer", "jailOfficer", "prisonActor", "capitalCustodyActor", "container", "fixture", "itemStack", "slime", "corpse", "incident", "task", "tool", "resource"].includes(selection.kind)) {
      return { kind: selection.kind, id: selection.id, roomId: selection.roomId || "", tile: selection.tile || null };
    }
    return null;
  }

  function setSelectedMapTarget(target) {
    setSelection(target, { source: target?.source || "map" });
  }

  function selectedTargetMatchesTile(target, { cell, roomId, door, objectEntry, incidentEntry, overlayEntry, scientistHere }) {
    if (!target) {
      return false;
    }
    if (target.kind === "scientist") {
      return Boolean(scientistHere);
    }
    if (target.kind === "room") {
      return roomId === target.roomId;
    }
    if (target.kind === "door") {
      return door?.key === target.key;
    }
    if (target.kind === "tile") {
      return Boolean(cell && target.tile && mapCellKey(cell) === mapCellKey(target.tile));
    }
    if (target.kind === "incident") {
      return incidentEntry?.alerts?.some((incident) => incident.id === target.id) || false;
    }
    if (target.kind === "collectionStation") {
      return objectEntry?.targets?.some((candidate) => candidate.kind === "collectionStation" && candidate.id === target.id) || false;
    }
    if (target.kind === "stockpile") {
      return Boolean(
        overlayEntry?.target?.kind === "stockpile"
        && overlayEntry.target.roomId === target.roomId
        && normalizeResourceOverlayFocusId(overlayEntry.target.focusId) === normalizeResourceOverlayFocusId(target.focusId)
      ) || roomId === target.roomId;
    }
    if (target.kind === "slime") {
      const slime = findSlime(target.id);
      if (slime?.containerId) {
        return objectEntry?.targets?.some((candidate) => candidate.kind === "container" && candidate.id === slime.containerId) || false;
      }
    }
    if (target.kind === "corpse") {
      const corpse = findCorpse(target.id);
      if (corpse?.containerId) {
        return objectEntry?.targets?.some((candidate) => candidate.kind === "container" && candidate.id === corpse.containerId) || false;
      }
    }
    return objectEntry?.targets?.some((candidate) => candidate.kind === target.kind && candidate.id === target.id) || false;
  }

  function selectedTargetMatchesCard(kind, idOrKey) {
    const target = currentSelection();
    if (!target || target.kind !== kind) {
      return false;
    }
    if (kind === "room") {
      return target.roomId === idOrKey;
    }
    if (kind === "door") {
      return target.key === idOrKey;
    }
    if (kind === "scientist") {
      return true;
    }
    return target.id === idOrKey;
  }

  function selectionKey(selection) {
    if (!selection) {
      return "";
    }
    if (selection.kind === "room") {
      return `room:${selection.roomId}`;
    }
    if (selection.kind === "door") {
      return `door:${selection.key}`;
    }
    if (selection.kind === "tile") {
      return `tile:${mapCellKey(selection.tile)}`;
    }
    if (selection.kind === "stockpile") {
      return `stockpile:${selection.roomId || ""}:${normalizeResourceOverlayFocusId(selection.focusId)}`;
    }
    return `${selection.kind}:${selection.id || ""}`;
  }

  function selectionLabel(selection) {
    if (!selection) {
      return "Nothing selected";
    }
    if (selection.kind === "scientist") {
      return "Scientist";
    }
    if (selection.kind === "visitor") {
      const found = siteVisitActorById(selection.id);
      return found?.actor.label || found?.visit.visitorLabel || "Visitor";
    }
    if (selection.kind === "raidOfficer") return raidActorById(selection.id)?.actor.name || "Raid Officer";
    if (selection.kind === "jailOfficer") return jailActorById(selection.id)?.actor.name || "Custody Officer";
    if (selection.kind === "prisonActor") return prisonActorById(selection.id)?.actor.name || "Prison Actor";
    if (selection.kind === "capitalCustodyActor") return capitalCustodyActorById(selection.id)?.actor.name || "Capital Custody Actor";
    if (selection.kind === "tile") {
      return `Tile ${selection.tile.x},${selection.tile.y}, Z ${selection.tile.z}`;
    }
    if (selection.kind === "room") {
      return roomById(selection.roomId)?.name || roomName(selection.roomId);
    }
    if (selection.kind === "door") {
      const door = labMapDoor(selection.key);
      return door ? `${door.roomIds.map(roomName).join(" / ")} door` : "Door";
    }
    if (selection.kind === "container") {
      return containerById(selection.id)?.name || "Container";
    }
    if (selection.kind === "fixture") {
      return fixtureById(selection.id)?.name || "Fixture";
    }
    if (selection.kind === "itemStack") {
      const stack = ensurePhysicalItemStacks().find((entry) => entry.id === selection.id);
      return stack ? `${physicalStackLabel(stack)}${stack.form === "spill" ? " spill" : ""}` : "Item Stack";
    }
    if (selection.kind === "slime") {
      return findSlime(selection.id)?.name || "Slime";
    }
    if (selection.kind === "corpse") {
      const corpse = findCorpse(selection.id);
      return corpse ? `${corpse.name} remains` : "Corpse";
    }
    if (selection.kind === "incident") {
      return incidentById(selection.id)?.label || "Incident";
    }
    if (selection.kind === "task") {
      return findTask(selection.id)?.label || "Task";
    }
    if (selection.kind === "collectionStation") {
      const container = containerById(selection.id);
      return container ? `${container.name} collection station` : "Collection Station";
    }
    if (selection.kind === "stockpile") {
      const focus = stockpileSelectionFocusDef(selection);
      return `${roomName(selection.roomId)} ${focus.label}`;
    }
    if (selection.kind === "resource") {
      return resourceLabel(selection.id);
    }
    if (selection.kind === "tool") {
      return inventoryItemLabel(selection.id);
    }
    return titleCase(selection.kind || "selection");
  }

  function selectionKindLabel(selection) {
    const labels = {
      scientist: "Scientist",
      visitor: "Site Visitor",
      raidOfficer: "Law-Enforcement Officer",
      jailOfficer: "Jail Custody Officer",
      prisonActor: "Prisoner or Prison Staff",
      capitalCustodyActor: "Capital Custody Staff",
      tile: "Map Tile",
      room: "Room",
      door: "Door",
      container: "Container",
      fixture: "Fixture",
      itemStack: "Physical Contents",
      slime: "Living Specimen",
      corpse: "Deceased Specimen",
      incident: "Incident",
      task: "Task",
      collectionStation: "Collection Station",
      stockpile: "Known Stockpile",
      resource: "Resource",
      tool: "Tool"
    };
    return labels[selection?.kind] || "Selection";
  }

  function selectionRoomId(selection) {
    if (!selection) {
      return "";
    }
    if (selection.kind === "scientist") {
      return scientistRoomId();
    }
    if (selection.kind === "visitor") {
      return siteVisitActorById(selection.id)?.actor.roomId || "";
    }
    if (selection.kind === "raidOfficer") return raidActorById(selection.id)?.actor.roomId || "";
    if (selection.kind === "jailOfficer") return jailActorById(selection.id)?.actor.roomId || "";
    if (selection.kind === "prisonActor") return prisonActorById(selection.id)?.actor.roomId || "";
    if (selection.kind === "capitalCustodyActor") return capitalCustodyActorById(selection.id)?.actor.roomId || "";
    if (selection.kind === "tile") {
      return selection.roomId || labMapCellRoomId(selection.tile);
    }
    if (selection.kind === "room") {
      return selection.roomId;
    }
    if (selection.kind === "door") {
      return labMapDoor(selection.key)?.roomIds?.[0] || "";
    }
    if (selection.kind === "container") {
      return containerById(selection.id)?.roomId || "";
    }
    if (selection.kind === "fixture") {
      return labMapCellRoomId(fixtureById(selection.id)?.origin) || "";
    }
    if (selection.kind === "itemStack") {
      return ensurePhysicalItemStacks().find((stack) => stack.id === selection.id)?.roomId || "";
    }
    if (selection.kind === "slime") {
      const slime = findSlime(selection.id);
      if (slimeIsUncontained(slime) && !mapShowsRoomOccupants(slime.roomId || MAIN_ROOM_ID, { cell: objectMapCell(slime) })) {
        return creatureRecordForSlime(slime)?.lastKnownRoomId || "";
      }
      return slimeEffectiveRoomId(slime);
    }
    if (selection.kind === "corpse") {
      return findCorpse(selection.id)?.roomId || "";
    }
    if (selection.kind === "incident") {
      return incidentById(selection.id)?.roomId || "";
    }
    if (selection.kind === "task") {
      return taskTargetRoomId(findTask(selection.id));
    }
    if (selection.kind === "collectionStation") {
      return containerById(selection.id)?.roomId || selection.roomId || "";
    }
    if (selection.kind === "stockpile") {
      return selection.roomId || "";
    }
    return "";
  }

  function selectionMapCell(selection) {
    if (!selection) {
      return null;
    }
    if (selection.kind === "scientist") {
      return scientistMapCell();
    }
    if (selection.kind === "visitor") {
      return cleanMapCell(siteVisitActorById(selection.id)?.actor.mapCell);
    }
    if (selection.kind === "raidOfficer") return cleanMapCell(raidActorById(selection.id)?.actor.mapCell);
    if (selection.kind === "jailOfficer") return cleanMapCell(jailActorById(selection.id)?.actor.mapCell);
    if (selection.kind === "prisonActor") return cleanMapCell(prisonActorById(selection.id)?.actor.mapCell);
    if (selection.kind === "capitalCustodyActor") return cleanMapCell(capitalCustodyActorById(selection.id)?.actor.mapCell);
    if (selection.kind === "tile") {
      return selection.tile;
    }
    if (selection.kind === "room") {
      return labMapRoomAnchor(selection.roomId);
    }
    if (selection.kind === "door") {
      const door = labMapDoor(selection.key);
      return door?.cell || null;
    }
    if (selection.kind === "container") {
      return objectMapCell(containerById(selection.id));
    }
    if (selection.kind === "fixture") {
      return objectMapCell(fixtureById(selection.id));
    }
    if (selection.kind === "itemStack") {
      return cleanMapCell(ensurePhysicalItemStacks().find((stack) => stack.id === selection.id)?.cell);
    }
    if (selection.kind === "slime") {
      const slime = findSlime(selection.id);
      if (slimeIsUncontained(slime) && !mapShowsRoomOccupants(slime.roomId || MAIN_ROOM_ID, { cell: objectMapCell(slime) })) {
        return cleanMapCell(creatureRecordForSlime(slime)?.lastKnownMapCell);
      }
      return slime?.containerId ? objectMapCell(containerById(slime.containerId)) : objectMapCell(slime);
    }
    if (selection.kind === "corpse") {
      const corpse = findCorpse(selection.id);
      return corpse?.containerId ? objectMapCell(containerById(corpse.containerId)) : objectMapCell(corpse);
    }
    if (selection.kind === "incident") {
      return cleanMapCell(incidentById(selection.id)?.cell);
    }
    if (selection.kind === "task") {
      return taskTargetCell(findTask(selection.id));
    }
    if (selection.kind === "collectionStation") {
      return objectMapCell(containerById(selection.id));
    }
    if (selection.kind === "stockpile") {
      return labMapRoomAnchor(selection.roomId);
    }
    return null;
  }

  function selectionLocationLabel(selection) {
    const roomId = selectionRoomId(selection);
    const cell = selectionMapCell(selection);
    const roomText = roomId ? roomName(roomId) : "unknown room";
    return cell ? `${roomText}; cell ${cell.x},${cell.y}` : roomText;
  }

  function selectionStatusChips(selection) {
    if (!selection) {
      return [];
    }
    if (selection.kind === "slime") {
      const slime = findSlime(selection.id);
      if (!slime) return [];
      if (slimeIsUncontained(slime) && !mapShowsRoomOccupants(slime.roomId || MAIN_ROOM_ID, { cell: objectMapCell(slime) })) {
        const record = creatureRecordForSlime(slime);
        return [
          "Status uncertain",
          `Last known: ${roomName(record?.lastKnownRoomId || MAIN_ROOM_ID)}`,
          record?.lastKnownActivity || "activity unknown"
        ].map(chip);
      }
      return [slimeStateLabel(slime), slimeLocationLabel(slime), slimeActivityLabel(slime)].map(chip);
    }
    if (selection.kind === "corpse") {
      const corpse = findCorpse(selection.id);
      return corpse ? [corpseStateLabel(corpse), corpseLocationLabel(corpse), corpseDecayText(corpse)].map(chip) : [];
    }
    if (selection.kind === "container") {
      const container = containerById(selection.id);
      return container ? [containerTypeLabel(container.typeId), `condition ${containerConditionLabel(container)}`, roomName(container.roomId)].map(chip) : [];
    }
    if (selection.kind === "fixture") {
      const fixture = fixtureById(selection.id);
      return fixture ? [fixtureDef(fixture)?.label || "Fixture", titleCase(fixture.operationalState), `condition ${formatNumber(fixture.condition)}%`].map(chip) : [];
    }
    if (selection.kind === "itemStack") {
      const stack = ensurePhysicalItemStacks().find((entry) => entry.id === selection.id);
      return stack ? [physicalStackQuantityText(stack), titleCase(stack.form || "stack"), stack.fixtureId ? "stored" : stack.containerId ? "contained" : "on floor", physicalStackKnowledgeLabel(stack)].map(chip) : [];
    }
    if (selection.kind === "room") {
      const room = roomById(selection.roomId);
      const evaluation = room ? roomPurposeEvaluation(room) : null;
      return room ? [
        evaluation.purpose.label,
        evaluation.status.label,
        room.designationDisconnected ? "Disconnected designation" : `${titleCase(room.designationSource || "manual")} designation`,
        roomOccupancySummary(room.id)
      ].map(chip) : [];
    }
    if (selection.kind === "door") {
      const door = labMapDoor(selection.key);
      return door ? [titleCase(doorStateLabel(door.roomIds[0], door.roomIds[1])), `condition ${doorConditionLabel(door)}`].map(chip) : [];
    }
    if (selection.kind === "incident") {
      const incident = incidentById(selection.id);
      return incident ? [incidentSeverityLabel(incident.severity), roomName(incident.roomId), incidentStatusLabel(incident.status)].map(chip) : [];
    }
    if (selection.kind === "task") {
      const task = findTask(selection.id);
      if (!task) {
        return [];
      }
      const status = taskStatusInfo(task);
      return [taskCategory(task), status.label, status.reason || `${formatDuration(Math.max(0, task.dueAt - state.clock))} remaining`].map(chip);
    }
    if (selection.kind === "collectionStation") {
      const info = collectionStationSelectionInfo(selection);
      return info ? [info.status, info.material || "no output assigned", roomName(info.container?.roomId)].map(chip) : [];
    }
    if (selection.kind === "stockpile") {
      const focus = stockpileSelectionFocusDef(selection);
      return [roomName(selection.roomId), focus.label, "last inventoried"].map(chip);
    }
    if (selection.kind === "tile") {
      return [chip(selectionLocationLabel(selection))];
    }
    return [];
  }

  function selectableTargetsAtCell(
    cell,
    map = ensureLabMap(),
    scene = activeCanvasMapSurface?.mapView?.scene || null
  ) {
    const clean = cleanMapCell(cell);
    if (!mapCellInBounds(clean, map)) {
      return [];
    }
    const key = mapCellKey(clean);
    const knownCellKeys = labMapKnownCellKeys(map, { fullReveal: mapFullRevealActive() });
    if (!labMapCellKnown(clean, map, knownCellKeys, labMapExcavatedCellKeys(map))) {
      return [];
    }
    const showIncidentTargets = currentMapOverlayDef().id === "incidents" || trackedMapSelection()?.kind === "incident";
    const incidentEntry = showIncidentTargets ? labMapIncidentAssignments(map).get(key) : null;
    const scientistCell = scientistMapCell();
    const scientistHere = Boolean(scientistCell && mapCellKey(scientistCell) === key);
    const objectEntry = labMapObjectAssignments(map).get(key);
    const roomId = labMapCellRoomId(clean, map);
    let overlayEntry = null;
    if (currentMapOverlayDef().id === "resources" && roomId && resourceOverlayReadingForRoom(roomId, currentResourceOverlayFocusDef())) {
      const focus = currentResourceOverlayFocusDef();
      overlayEntry = { target: { kind: "stockpile", id: `${roomId}:${focus.id}`, roomId, focusId: focus.id } };
    }
    const targets = mapTileInteractionTargets({
      roomId,
      door: labMapDoorAtCell(clean, map),
      objectEntry,
      incidentEntry,
      overlayEntry,
      plannedEntry: plannedExcavationAssignments().get(key) || null,
      scientistHere,
      cell: clean
    });
    const sceneTargets = scene ? MapRenderOrder.targetsAtCell(scene, clean) : [];
    const orderedTargets = sceneTargets.length
      ? sceneTargets
      : MapRenderOrder.orderInteractionTargets(scene, targets);
    const seen = new Set();
    return orderedTargets
      .map((target) => normalizeSelection({ ...target, source: "inspector" }))
      .filter(Boolean)
      .filter((target) => {
        const keyName = selectionKey(target);
        if (seen.has(keyName)) {
          return false;
        }
        seen.add(keyName);
        return true;
      });
  }

  function selectionRelatedTargets(selection) {
    if (!selection) {
      return [];
    }
    if (selection.kind === "container") {
      const container = containerById(selection.id);
      if (!container) {
        return [];
      }
      const rows = [
        ...containerOccupants(container.id).map((slime) => ({ kind: "slime", id: slime.id })),
        ...containerCorpses(container.id).map((corpse) => ({ kind: "corpse", id: corpse.id })),
        { kind: "room", roomId: container.roomId }
      ];
      return rows;
    }
    if (selection.kind === "fixture") {
      const fixture = fixtureById(selection.id);
      const roomId = fixture ? labMapCellRoomId(fixture.origin) : "";
      return fixture && roomId ? [
        ...physicalStacksInFixture(fixture.id).filter((stack) => stack.knownQuantity > 0).map((stack) => ({ kind: "itemStack", id: stack.id })),
        { kind: "room", roomId }
      ] : [];
    }
    if (selection.kind === "itemStack") {
      const stack = ensurePhysicalItemStacks().find((entry) => entry.id === selection.id);
      return stack ? [
        stack.fixtureId ? { kind: "fixture", id: stack.fixtureId } : null,
        stack.roomId ? { kind: "room", roomId: stack.roomId } : null
      ].filter(Boolean) : [];
    }
    if (selection.kind === "slime") {
      const slime = findSlime(selection.id);
      return [
        slime?.containerId ? { kind: "container", id: slime.containerId } : null,
        slime?.roomId ? { kind: "room", roomId: slime.roomId } : null
      ].filter(Boolean);
    }
    if (selection.kind === "corpse") {
      const corpse = findCorpse(selection.id);
      return [
        corpse?.containerId ? { kind: "container", id: corpse.containerId } : null,
        corpse?.roomId ? { kind: "room", roomId: corpse.roomId } : null
      ].filter(Boolean);
    }
    if (selection.kind === "incident") {
      const incident = incidentById(selection.id);
      const target = incident ? incidentFocusTarget(incident) : null;
      return target ? [target] : [];
    }
    if (selection.kind === "room") {
      return unresolvedIncidentAlerts()
        .filter((incident) => incident.roomId === selection.roomId)
        .map((incident) => ({ kind: "incident", id: incident.id }));
    }
    if (selection.kind === "door") {
      const door = labMapDoor(selection.key);
      return (door?.roomIds || []).map((roomId) => ({ kind: "room", roomId }));
    }
    if (selection.kind === "task") {
      const task = findTask(selection.id);
      if (!task) {
        return [];
      }
      const targets = [];
      if (task.data?.slimeId) {
        targets.push({ kind: "slime", id: task.data.slimeId });
      }
      if (task.data?.corpseId) {
        targets.push({ kind: "corpse", id: task.data.corpseId });
      }
      if (task.data?.containerId) {
        targets.push({ kind: "container", id: task.data.containerId });
      }
      if (task.data?.incidentId) {
        targets.push({ kind: "incident", id: task.data.incidentId });
      }
      const roomId = taskTargetRoomId(task);
      if (roomId) {
        targets.push({ kind: "room", roomId });
      }
      const cell = taskTargetCell(task);
      if (cell) {
        targets.push({ kind: "tile", tile: cell });
      }
      return targets;
    }
    if (selection.kind === "collectionStation") {
      const container = containerById(selection.id);
      if (!container) {
        return [];
      }
      return [
        { kind: "container", id: container.id },
        ...containerOccupants(container.id).map((slime) => ({ kind: "slime", id: slime.id })),
        { kind: "room", roomId: container.roomId }
      ];
    }
    if (selection.kind === "stockpile") {
      return selection.roomId ? [{ kind: "room", roomId: selection.roomId }] : [];
    }
    return [];
  }

  function selectionLink(target) {
    const normalized = normalizeSelection({ ...target, source: "inspector" });
    if (!normalized) {
      return null;
    }
    return entityLink(selectionLabel(normalized), `Select ${selectionLabel(normalized)}`, "entity-link-chip", () => {
      focusMapTarget(normalized, { animate: false, keepWorkspace: true, resetInspectorTab: true });
    });
  }

  function selectionLinkRow(label, targets) {
    const links = targets
      .map(selectionLink)
      .filter(Boolean);
    if (!links.length) {
      return null;
    }
    const row = document.createElement("div");
    row.className = "selection-inspector-row";
    row.append(textEl("span", label));
    const body = document.createElement("div");
    body.className = "selection-link-list";
    links.forEach((link, index) => {
      if (index > 0) {
        body.append(document.createTextNode(" "));
      }
      body.append(link);
    });
    row.append(body);
    return row;
  }

  function commandDef(options) {
    return {
      id: String(options.id || ""),
      label: String(options.label || "Command"),
      group: String(options.group || "Actions"),
      description: String(options.description || ""),
      disabledReason: String(options.disabledReason || ""),
      danger: Boolean(options.danger),
      run: typeof options.run === "function" ? options.run : () => false
    };
  }

  function openWorkspaceContext(options = {}) {
    const workspaceTab = visibleWorkspaceTabOrMap(options.workspaceTab || "map");
    setUiMode(UI_MODE_NAVIGATION);
    const ui = ensureUiState();
    ui.commandMenuOpen = false;
    ui.overlayMenuOpen = false;
    if (options.tabKind === "tasks") {
      ui.taskMenuTab = normalizeTaskMenuTab(options.tabId);
    } else if (options.tabKind === "creatures") {
      ui.creatureRecordTab = normalizeCreatureRecordTab(options.tabId);
    } else if (options.tabKind === "stores") {
      ui.storeMenuTab = normalizeStoreMenuTab(options.tabId);
    } else if (options.tabKind === "economy") {
      ui.economyMenuTab = normalizeEconomyMenuTab(options.tabId);
    } else if (options.tabKind === "policies") {
      ui.policyMenuTab = normalizePolicyMenuTab(options.tabId);
    } else if (options.tabKind === "debug") {
      ui.debugMenuTab = normalizeDebugMenuTab(options.tabId);
    }
    if (options.overlayId) {
      ui.mapOverlay = normalizeMapOverlayId(options.overlayId);
    }
    if (options.resourceFocusId) {
      ui.resourceOverlayFocus = normalizeResourceOverlayFocusId(options.resourceFocusId);
      ui.mapOverlay = "resources";
    }
    ui.keyboardMenuPath = options.keyboardMenuPath || keyboardMenuPathForWorkspace(workspaceTab);
    setActiveWorkspaceTab(workspaceTab, { scroll: true, animate: false });
    return true;
  }

  function openWorkspaceCommand(options = {}) {
    return commandDef({
      id: options.id,
      label: options.label,
      group: options.group || "Open Menu",
      disabledReason: options.workspaceTab && !workspaceTabVisible(options.workspaceTab) ? `${options.label || "Menu"} is not currently visible.` : "",
      description: options.description || `Open ${options.label || "the relevant management screen"}.`,
      run: () => openWorkspaceContext(options)
    });
  }

  function contextualCommandsForSelection(selection) {
    if (!selection) {
      return [];
    }
    if (selection.kind === "room") {
      return roomContextCommands(roomById(selection.roomId));
    }
    if (selection.kind === "scientist") {
      return scientistContextCommands();
    }
    if (selection.kind === "tile") {
      return tileContextCommands(selection);
    }
    if (selection.kind === "door") {
      return doorContextCommands(labMapDoor(selection.key), selection);
    }
    if (selection.kind === "incident") {
      return incidentContextCommands(incidentById(selection.id));
    }
    if (selection.kind === "corpse") {
      return corpseContextCommands(findCorpse(selection.id));
    }
    if (selection.kind === "slime") {
      return slimeContextCommands(findSlime(selection.id));
    }
    if (selection.kind === "container") {
      return containerContextCommands(containerById(selection.id));
    }
    if (selection.kind === "fixture") {
      return fixtureContextCommands(fixtureById(selection.id));
    }
    if (selection.kind === "itemStack") {
      return physicalItemStackContextCommands(selection);
    }
    if (selection.kind === "collectionStation") {
      return collectionStationContextCommands(selection);
    }
    if (selection.kind === "stockpile") {
      return stockpileContextCommands(selection);
    }
    if (selection.kind === "task") {
      return taskContextCommands(findTask(selection.id));
    }
    return [];
  }

  function taskContextCommands(task) {
    if (!task) {
      return [];
    }
    return [
      commandDef({
        id: `task.cancel.${task.id}`,
        label: "Cancel Task",
        group: "Task",
        disabledReason: cancelTaskBlockReason(task),
        description: "Remove this scientist order from the queue. Spent time and stamina are not recovered; recorded unused materials are returned.",
        danger: true,
        run: () => cancelTask(task.id)
      }),
      openWorkspaceCommand({
        id: `task.openQueue.${task.id}`,
        label: "Open Tasks",
        group: "Open Menu",
        workspaceTab: "tasks",
        tabKind: "tasks",
        tabId: taskStatusInfo(task).id === "blocked" ? "blocked" : "queue",
        description: "Open the Tasks management screen."
      })
    ];
  }

  function fieldDiagnosticContextCommands(kind, id = "", cell = null, options = {}) {
    const commands = [];
    if (options.environment !== false) {
      commands.push(commandDef({
        id: `diagnostic.environment.${kind}.${id || mapCellKey(cell)}`,
        label: "Environmental Survey",
        group: "Diagnostics",
        disabledReason: fieldDiagnosticBlockReason("environmentalSurveyKit", kind, id, cell),
        description: "Use the worn field kit to measure local temperature, humidity, light, and electrical conditions. Poor calibration produces wider ranges.",
        run: () => startFieldDiagnostic("environmentalSurveyKit", kind, id, cell)
      }));
      commands.push(commandDef({
        id: `diagnostic.mana.${kind}.${id || mapCellKey(cell)}`,
        label: "Thaumic Survey",
        group: "Diagnostics",
        disabledReason: fieldDiagnosticBlockReason("thaumometer", kind, id, cell),
        description: "Use the thaumometer to measure local ambient mana. Calibration and instrument condition determine precision.",
        run: () => startFieldDiagnostic("thaumometer", kind, id, cell)
      }));
    }
    for (const methodId of options.sampleMethods || []) {
      const method = Diagnostics.SAMPLE_METHOD_BY_ID[methodId];
      commands.push(commandDef({
        id: `diagnostic.sample.${methodId}.${kind}.${id || mapCellKey(cell)}`,
        label: method.label === "Air Vial" ? "Take Air Sample" : method.label,
        group: "Diagnostics",
        disabledReason: sampleCollectionBlockReason(methodId, kind, id, cell),
        description: methodId === "fluidSample"
          ? "Collect a high-quality invasive fluid sample. This causes stress and minor body damage."
          : methodId === "surfaceSwab"
            ? "Collect a lower-quality non-invasive surface sample. This causes minor stress."
            : "Seal a physical air vial for later bench analysis. The captured environment will not change after collection.",
        danger: methodId === "fluidSample",
        run: () => startSampleCollection(methodId, kind, id, cell)
      }));
    }
    return commands;
  }

  function injuryContextCommands(actorOrId) {
    const injuries = actorInjuries(actorOrId);
    const commands = [];
    for (const injury of injuries) {
      const known = INJURY_TYPE_DEFS[injury.typeId].visible || injury.diagnosedAt != null || injury.actorId === "scientist";
      const label = known ? `${INJURY_SEVERITY_DEFS[injury.severityId].label} ${INJURY_TYPE_DEFS[injury.typeId].label} — ${injury.location}` : "Suspected internal injury";
      commands.push(commandDef({
        id: `injury.examine.${injury.id}`,
        label: `Examine: ${label}`,
        group: "Medical Care",
        disabledReason: injuryTreatmentBlockReason(injury, "examine"),
        description: known ? "Confirm the wound and its treatment needs using Medicine." : "Examine symptoms without revealing an unobserved internal injury in advance.",
        run: () => startInjuryTreatment(injury.id, "examine")
      }));
      if (!known) continue;
      commands.push(commandDef({
        id: `injury.stabilize.${injury.id}`,
        label: `Stabilize: ${label}`,
        group: "Medical Care",
        disabledReason: injuryTreatmentBlockReason(injury, "stabilize"),
        description: `Use ${inventoryItemLabel(INJURY_TYPE_DEFS[injury.typeId].supplyKey)} to stop bleeding, leakage, corrosion, or other progressive harm.`,
        run: () => startInjuryTreatment(injury.id, "stabilize")
      }));
      commands.push(commandDef({
        id: `injury.treat.${injury.id}`,
        label: `Treat: ${label}`,
        group: "Medical Care",
        disabledReason: injuryTreatmentBlockReason(injury, "treat"),
        description: `Use ${inventoryItemLabel(INJURY_TYPE_DEFS[injury.typeId].supplyKey)} and Medicine to begin recovery.`,
        run: () => startInjuryTreatment(injury.id, "treat")
      }));
    }
    return commands;
  }

  function equipmentContextCommands() {
    const commands = [];
    for (const [itemKey, def] of Object.entries(TOOL_DURABILITY_DEFS)) {
      if (!def.equipment) continue;
      const instances = toolInstancesForItem(itemKey);
      if (!instances.length) continue;
      const equipped = equippedEquipmentEntries("scientist").find((entry) => entry.itemKey === itemKey);
      if (equipped) {
        commands.push(commandDef({
          id: `equipment.unequip.${equipped.instance.id}`,
          label: `Unequip ${inventoryItemLabel(itemKey)}`,
          group: "Equipment",
          disabledReason: equipmentChangeBlockReason(itemKey, equipped.instance.id, "unequip"),
          description: `Remove it from ${equipped.slots.map((slotId) => EQUIPMENT_SLOT_BY_ID[slotId].label).join(" + ")} while retaining the physical item in inventory.`,
          run: () => queueEquipmentChange(itemKey, equipped.instance.id, "unequip")
        }));
        if (Number(equipped.instance.contaminationLoad) > 0) {
          commands.push(commandDef({
            id: `equipment.clean.${equipped.instance.id}`,
            label: `Clean ${inventoryItemLabel(itemKey)}`,
            group: "Equipment Care",
            disabledReason: inventoryAmount("neutralizingWash") > 0 ? "" : "Neutralizing Wash is required.",
            description: `Remove ${formatNumber(equipped.instance.contaminationLoad)} contamination load with one Neutralizing Wash.`,
            run: () => cleanEquipmentInstance(equipped.instance.id)
          }));
        }
      } else {
        const instance = instances.find((candidate) => candidate.current > 0 && !candidate.reservedTaskId) || instances[0];
        commands.push(commandDef({
          id: `equipment.equip.${instance.id}`,
          label: `Equip ${inventoryItemLabel(itemKey)}`,
          group: "Equipment",
          disabledReason: equipmentChangeBlockReason(itemKey, instance.id, "equip"),
          description: `Retrieve this physical item and equip it in ${equipmentSlotIds(itemKey).map((slotId) => EQUIPMENT_SLOT_BY_ID[slotId].label).join(" + ")}.`,
          run: () => queueEquipmentChange(itemKey, instance.id, "equip")
        }));
      }
    }
    commands.push(commandDef({
      id: "equipment.saveLoadout",
      label: "Save Current Loadout",
      group: "Loadouts",
      disabledReason: (state.equipmentLoadouts || []).length >= EQUIPMENT_LOADOUT_LIMIT ? `Maximum of ${EQUIPMENT_LOADOUT_LIMIT} loadouts reached.` : "",
      description: "Name and save the currently equipped item types. An empty vat-start loadout is valid.",
      run: () => {
        const name = window.prompt("Loadout name:", `Loadout ${state.nextEquipmentLoadoutNumber || 1}`);
        return name == null ? false : saveCurrentEquipmentLoadout(name);
      }
    }));
    for (const loadout of normalizeEquipmentLoadouts(state.equipmentLoadouts)) {
      commands.push(commandDef({
        id: `equipment.loadout.${loadout.id}`,
        label: `Equip Loadout: ${loadout.name}`,
        group: "Loadouts",
        description: "Queue the required removals and routed equipment retrieval tasks.",
        run: () => queueEquipmentLoadout(loadout.id)
      }));
      commands.push(commandDef({
        id: `equipment.deleteLoadout.${loadout.id}`,
        label: `Delete Loadout: ${loadout.name}`,
        group: "Loadouts",
        description: "Delete this saved equipment plan without changing currently worn items.",
        danger: true,
        run: () => {
          state.equipmentLoadouts = normalizeEquipmentLoadouts(state.equipmentLoadouts).filter((entry) => entry.id !== loadout.id);
          addEvent(`Deleted equipment loadout: ${loadout.name}.`);
          persist();
          render();
          return true;
        }
      }));
    }
    return commands;
  }

  function scientistContextCommands() {
    const pending = state.combat?.pendingActions?.scientist;
    return [
      ...equipmentContextCommands(),
      ...injuryContextCommands("scientist"),
      ...fieldDiagnosticContextCommands("scientist", "scientist", scientistMapCell(), { environment: false, sampleMethods: ["surfaceSwab", "fluidSample"] }),
      commandDef({
        id: "scientist.guard",
        label: scientistGuarding() ? "Stop Guarding" : "Guard",
        group: "Combat",
        disabledReason: scientistIsDead() ? "The scientist is dead." : "",
        description: scientistGuarding()
          ? "Lower the guard and resume suspended routine work."
          : "Adopt a defensive stance, reduce incoming attack damage, and suspend routine work until canceled or replaced by another direct command.",
        run: () => scientistGuarding() ? stopScientistGuardAndRender() : startScientistGuard()
      }),
      commandDef({
        id: "scientist.cancelCombatAction",
        label: "Cancel Current Action",
        group: "Combat",
        disabledReason: pending ? "" : "The scientist is not charging or channeling an ability.",
        description: pending ? `Interrupt ${combatActionDef(pending.actionId)?.label || "the current ability"} and resume routine work.` : "No interruptible combat action is active.",
        run: () => {
          const changed = cancelPendingScientistCombatAction();
          persist();
          render();
          return changed;
        }
      })
    ];
  }

  function roomMenuContextCommands(room) {
    if (!room) {
      return [];
    }
    const commands = [
      openWorkspaceCommand({
        id: `room.openStockpiles.${room.id}`,
        label: "Open Room Stockpiles",
        group: "Open Menu",
        workspaceTab: "resources",
        tabKind: "stores",
        tabId: "rooms",
        description: "Open known room stockpiles and local material inventories."
      }),
      commandDef({
        id: `room.showResources.${room.id}`,
        label: "Show Resource Overlay",
        group: "Map",
        description: "Switch the map to the resource overlay for this room.",
        run: () => openWorkspaceContext({ workspaceTab: "map", overlayId: "resources", keyboardMenuPath: "" })
      })
    ];
    if (room.role === "byproductCollection" || room.id === COLLECTION_BAY_ROOM_ID) {
      commands.push(openWorkspaceCommand({
        id: `room.openCollectionStations.${room.id}`,
        label: "Open Collection Stations",
        group: "Open Menu",
        workspaceTab: "resources",
        tabKind: "stores",
        tabId: "stations",
        description: "Open Collection Bay station readouts and receptacle status."
      }));
    }
    if (room.role === "labExit" || room.id === CONCEALED_EXIT_ROOM_ID) {
      commands.push(openWorkspaceCommand({
        id: `room.openBlackMarket.${room.id}`,
        label: "Open Black Market",
        group: "Open Menu",
        workspaceTab: "economy",
        tabKind: "economy",
        tabId: "deals",
        description: "Open illicit contacts and queued outside-lab trade options."
      }));
    }
    if (roomPurposeId(room) === "unassigned") {
      commands.push(commandDef({
        id: `room.showConstruction.${room.id}`,
        label: "Show Construction Overlay",
        group: "Map",
        description: "Switch the map to construction designations and rough rooms.",
        run: () => openWorkspaceContext({ workspaceTab: "map", overlayId: "construction", keyboardMenuPath: "" })
      }));
    }
    return commands;
  }

  function roomContextCommands(room) {
    if (!room) {
      return [];
    }
    const reason = scientistMoveBlockReason(room.id, { allowMultiRoom: true });
    const routeSummary = roomPathSummary(scientistRoomId(), room.id, {
      ignoreDoors: true,
      fromCell: scientistMapCell(),
      toCell: nearestOpenMapCellInRoom(room.id, labMapRoomAnchor(room.id), { preferredCell: scientistMapCell() })
    });
    const commands = [
      commandDef({
        id: `room.move.${room.id}`,
        label: "Move Scientist Here",
        group: "Movement",
        disabledReason: reason,
        description: `Queue movement to ${room.name}. Route: ${routeSummary}.`,
        run: () => startScientistMove(room.id, { allowMultiRoom: true })
      })
    ];
    if (roomCanAssignPurpose(room)) {
      for (const purpose of ROOM_PURPOSE_DEFS) {
        commands.push(commandDef({
          id: `room.assignPurpose.${room.id}.${purpose.id}`,
          label: purpose.id === "unassigned" ? "Clear Primary Purpose" : `Set Purpose: ${purpose.label}`,
          group: "Room Purpose",
          disabledReason: roomPurposeId(room) === purpose.id ? `This room is already ${purpose.label}.` : "",
          description: purpose.description,
          run: () => assignRoomPurpose(room.id, purpose.id)
        }));
      }
      const suggestion = roomPurposeInference(room);
      if (suggestion && ["unassigned", "automatic"].includes(room.purposeSource) && suggestion.purposeId !== roomPurposeId(room)) {
        const suggestedPurpose = ROOM_PURPOSE_BY_ID[suggestion.purposeId];
        commands.unshift(commandDef({
          id: `room.acceptPurposeSuggestion.${room.id}.${suggestion.purposeId}`,
          label: `Accept Suggested ${suggestedPurpose.label}`,
          group: "Room Purpose",
          description: `Suggested because ${suggestion.reasons.join(" and ")}.`,
          run: () => assignRoomPurpose(room.id, suggestion.purposeId)
        }));
      }
      commands.push(...roomZoneContextCommands(room, labMapRoomCells(room.id), "room"));
    }
    for (const designation of stockpileDesignationsInRoom(room.id)) {
      commands.push(commandDef({
        id: `room.stockpile.rename.${designation.id}`,
        label: `Rename ${designation.name}`,
        group: "Stockpile",
        description: "Stockpile names and identities remain independent of the room and its generic zone layer.",
        run: () => renameStockpileDesignation(designation.id)
      }));
      for (const preset of STOCKPILE_FILTER_PRESETS) {
        commands.push(commandDef({
          id: `room.stockpile.filter.${designation.id}.${preset.id}`,
          label: `${designation.name}: Accept ${preset.label}`,
          group: "Stockpile Filters",
          disabledReason: designation.filterPresetId === preset.id ? `${designation.name} already uses this filter.` : "",
          description: preset.description,
          run: () => setStockpileFilterPreset(designation.id, preset.id)
        }));
      }
      commands.push(commandDef({
        id: `room.stockpile.floor.${designation.id}`,
        label: `${designation.allowFloorStorage ? "Forbid" : "Allow"} Floor Storage in ${designation.name}`,
        group: "Stockpile",
        description: "Furniture improves capacity and protection, but designated floor tiles may store accepted items by default.",
        run: () => toggleStockpileFloorStorage(designation.id)
      }));
    }
    commands.push(...roomDesignationContextCommands(labMapRoomAnchor(room.id), room));
    commands.push(...roomMenuContextCommands(room));
    return commands;
  }

  function roomZoneContextCommands(room, cells, scopeLabel = "tile") {
    const cleanCells = normalizeDigCells(cells);
    if (!room || !cleanCells.length) return [];
    return ROOM_ZONE_DEFS.map((zoneDef) => {
      const zone = roomZoneForType(room, zoneDef.id);
      const zoneKeys = new Set((zone?.cells || []).map(mapCellKey));
      const allIncluded = cleanCells.every((cell) => zoneKeys.has(mapCellKey(cell)));
      return commandDef({
        id: `room.zone.${room.id}.${zoneDef.id}.${scopeLabel}`,
        label: `${allIncluded ? "Remove" : "Add"} ${zoneDef.label}${scopeLabel === "room" ? " Across Room" : ""}`,
        group: "Zones",
        description: `${zoneDef.description} Zones express player intent and do not create equipment or physical capability.`,
        run: () => setRoomZoneCells(room.id, zoneDef.id, cleanCells, !allIncluded)
      });
    });
  }

  function roomDesignationContextCommands(cell, room = null) {
    const clean = cleanMapCell(cell);
    const manualStartCell = room ? null : clean;
    const editRoomId = state.construction.roomEditId;
    const draft = roomDesignationDraftCells();
    const draftReason = draft.length ? roomDesignationBlockReason(draft) : "No room draft has been selected.";
    const compartment = clean ? inferredCompartmentAtCell(clean) : null;
    const unassignedCount = compartment
      ? compartment.cells.filter((candidate) => !labMapCellRoomId(candidate)).length
      : 0;
    const commands = [
      commandDef({
        id: `roomDesignation.begin.${clean?.x ?? "none"}.${clean?.y ?? "none"}`,
        label: room ? "Edit Room Tiles" : roomDesignationModeActive() ? "Restart Room Draft" : "Draw Room Designation",
        group: "Room Designation",
        disabledReason: room ? "" : clean ? roomDesignationCellBlockReason(clean) : "No excavated tile selected.",
        description: "Enter manual room designation mode. Click excavated tiles to define one persistent room area.",
        run: () => room ? beginRoomDesignationEdit(room.id) : beginRoomDesignationAtCell(manualStartCell)
      }),
      commandDef({
        id: "roomDesignation.confirm",
        label: editRoomId ? "Apply Room Tile Changes" : "Confirm Room Designation",
        group: "Room Designation",
        disabledReason: draftReason,
        description: "Create a new room from the manual tile draft. Existing room tiles are reassigned without deleting disconnected remnants.",
        run: () => confirmRoomDesignationDraft()
      }),
      commandDef({
        id: "roomDesignation.paint",
        label: "Paint Tiles",
        group: "Room Designation",
        disabledReason: roomDesignationModeActive() && roomDesignationBrush() !== "paint" ? "" : "Paint is already selected.",
        description: "Left-click or drag across excavated floor to add it to the draft.",
        run: () => setRoomDesignationBrush("paint")
      }),
      commandDef({
        id: "roomDesignation.erase",
        label: "Erase Tiles",
        group: "Room Designation",
        disabledReason: roomDesignationModeActive() && roomDesignationBrush() !== "erase" ? "" : "Erase is already selected.",
        description: "Left-click or drag across excavated floor to remove it from the draft.",
        run: () => setRoomDesignationBrush("erase")
      }),
      commandDef({
        id: "roomDesignation.clear",
        label: "Clear Room Draft",
        group: "Room Designation",
        disabledReason: draft.length ? "" : "No room draft has been selected.",
        description: "Clear the current manual room tile selection.",
        run: () => clearRoomDesignationDraft()
      }),
      commandDef({
        id: `roomDesignation.accept.${compartment?.id || "none"}`,
        label: "Accept Inferred Compartment",
        group: "Room Designation",
        disabledReason: !compartment
          ? "No inferred compartment exists at this tile."
          : unassignedCount
            ? ""
            : "This inferred compartment is already fully designated.",
        description: "Accept the automatically inferred architectural area as a room, or expand its one existing room designation into unassigned tiles.",
        run: () => {
          const result = designateInferredCompartmentAtCell(clean, { source: "manual" });
          applyAutomaticRoomPurposes();
          persist();
          render();
          return Boolean(result);
        }
      }),
      commandDef({
        id: `roomDesignation.overlay.${clean?.x ?? "none"}.${clean?.y ?? "none"}`,
        label: "Show Rooms Overlay",
        group: "Map",
        description: "Show inferred compartments, thresholds, room ownership, and the current manual draft.",
        run: () => openWorkspaceContext({ workspaceTab: "map", overlayId: "rooms", keyboardMenuPath: "" })
      })
    ];
    if (room?.designationDisconnected) {
      commands.unshift(commandDef({
        id: `roomDesignation.disconnected.${room.id}`,
        label: "Room Designation Is Disconnected",
        group: "Room Designation",
        disabledReason: "Redraw this room when convenient; its existing tile ownership has been preserved.",
        description: "Construction split this room into disconnected tile groups. The game has preserved them instead of deleting either side."
      }));
    }
    if (room) {
      commands.push(commandDef({
        id: `roomDesignation.split.${room.id}`,
        label: "Draw Room Designation",
        group: "Room Designation",
        description: "Start an empty draft that can claim part of this room as a separate room identity.",
        run: () => beginRoomDesignationAtCell(null)
      }));
      commands.push(commandDef({
        id: `roomDesignation.rename.${room.id}`,
        label: "Rename Room",
        group: "Room Designation",
        description: "Change the persistent room name without changing its tiles or purpose.",
        run: () => renameRoomDesignation(room.id)
      }));
      commands.push(commandDef({
        id: `roomDesignation.delete.${room.id}`,
        label: "Delete Room Designation",
        group: "Room Designation",
        disabledReason: roomDesignationHasTiles(room.id) ? "" : "This room currently has no designated tiles.",
        description: "Remove room ownership from its tiles. Fixtures and loose stock remain physically where they are.",
        run: () => deleteRoomDesignation(room.id)
      }));
      for (const otherId of room.connections || []) {
        const other = state.rooms.find((entry) => entry.id === otherId);
        if (!other || !roomDesignationHasTiles(other.id)) continue;
        commands.push(commandDef({
          id: `roomDesignation.merge.${room.id}.${other.id}`,
          label: `Merge ${other.name} Into This Room`,
          group: "Room Designation",
          description: `${room.name} survives with its name, purpose, and identity; ${other.name}'s tiles and stockpile ownership are absorbed.`,
          run: () => mergeRoomDesignation(room.id, other.id)
        }));
      }
    }
    return commands;
  }

  function activeLaborOrderForDedupeKey(key) {
    return workOrderByDedupeKey(key);
  }

  function repairTargetDescriptor(target) {
    if (!target) return null;
    if (target.kind === "door") return { kind: "door", id: target.value?.id || target.mapDoor?.id, cell: target.cell, label: doorTypeLabel(target.value?.typeId) };
    if (target.kind === "container") return { kind: "container", id: target.value?.id, cell: target.cell, label: target.value?.name || "container" };
    if (target.kind === "fixture") return { kind: "fixture", id: target.value?.id, cell: target.cell, label: target.value?.name || "fixture" };
    if (["constructedWall", "constructedFloor"].includes(target.kind)) return { kind: "structure", cell: target.cell, label: target.kind === "constructedWall" ? "constructed wall" : "constructed floor" };
    return null;
  }

  function repairLaborCommands(target) {
    const descriptor = repairTargetDescriptor(target);
    if (!descriptor) return [];
    const condition = laborRepairCondition(target);
    const breached = target.kind === "door" ? doorIsBreached(target.value) : target.kind === "container" ? containerBreachState(target.value) !== "intact" : false;
    const commands = [];
    const repairKey = `repair:${descriptor.kind}:${descriptor.id || mapCellKey(descriptor.cell)}`;
    const existingRepair = activeLaborOrderForDedupeKey(repairKey);
    commands.push(commandDef({
      id: `labor.repair.${descriptor.kind}.${descriptor.id || mapCellKey(descriptor.cell)}`,
      label: `Repair ${descriptor.label}`,
      group: "Maintenance",
      disabledReason: existingRepair ? "Repair is already designated." : condition >= 100 ? "This object is already at full condition." : "",
      description: `Create a priority 4 repair order using compatible physical material. Current condition ${formatNumber(condition)}%. Materials elsewhere will be hauled first.`,
      run: () => startLaborWorkOrder({
        kind: "repair",
        category: "repair",
        label: `Repair ${descriptor.label}`,
        priority: 4,
        source: "manual",
        target: descriptor,
        dedupeKey: repairKey
      })
    }));
    if (["door", "container"].includes(descriptor.kind)) {
      const sealKey = `seal-repair:${descriptor.kind}:${descriptor.id}`;
      const existingSeal = activeLaborOrderForDedupeKey(sealKey);
      commands.push(commandDef({
        id: `labor.sealRepair.${descriptor.kind}.${descriptor.id}`,
        label: `Restore ${descriptor.label} Seal`,
        group: "Maintenance",
        disabledReason: existingSeal ? "Seal restoration is already designated." : breached ? "" : "The seal structure is not breached or compromised.",
        description: "Repair the physical seal, gasket, and fittings with Rubber and Metal Parts. This restores seal integrity but does not automatically engage or lock it.",
        run: () => startLaborWorkOrder({
          kind: "sealRepair",
          category: "repair",
          label: `Restore ${descriptor.label} seal`,
          priority: 3,
          source: "manual",
          target: descriptor,
          dedupeKey: sealKey
        })
      }));
    }
    return commands;
  }

  function rubbleLaborCommands(cell) {
    return rubbleAtCell(cell).map((pile) => {
      const key = `rubble:${pile.id}`;
      const existing = activeLaborOrderForDedupeKey(key);
      const destination = defaultRubbleDestination(pile);
      const metrics = rubblePileMetrics(pile);
      const trips = Math.max(1, Math.ceil(metrics.massKg / SCIENTIST_CARRY_MASS_KG), Math.ceil(metrics.volumeL / SCIENTIST_CARRY_VOLUME_L));
      return commandDef({
        id: `labor.rubble.${pile.id}`,
        label: "Haul Rubble",
        group: "Labor",
        disabledReason: existing ? "This rubble already has a work order." : destination ? "" : "No compatible material stockpile exists.",
        description: `Move this physical rubble to the highest-priority compatible stockpile. Estimated ${formatDecimal(metrics.massKg, 1)} kg in ${formatNumber(trips)} trip${trips === 1 ? "" : "s"}; it remains unprocessed rubble.`,
        run: () => startLaborWorkOrder({
          kind: "rubbleHaul",
          category: "hauling",
          label: `Haul rubble from ${cell.x},${cell.y}`,
          priority: 4,
          source: "manual",
          target: { kind: "rubble", id: pile.id, cell },
          destination,
          dedupeKey: key
        })
      });
    });
  }

  function tileLaborContextCommands(cell) {
    const target = structuralTargetAtCell(cell);
    return [...rubbleLaborCommands(cell), ...repairLaborCommands(target)];
  }

  function tileContextCommands(selection) {
    const roomId = selection?.roomId || labMapCellRoomId(selection?.tile);
    if (!roomId) {
      const cell = cleanMapCell(selection?.tile);
      if (!cell) {
        return [];
      }
      if (labMapCellIsExcavated(cell)) {
        const movementRoomId = nearestDesignatedRoomIdForCell(cell);
        const movementReason = scientistMoveBlockReason(movementRoomId, {
          toCell: cell,
          allowMultiRoom: true,
          allowUnassignedCell: true
        });
        return [
          commandDef({
            id: `tile.moveUnassigned.${cell.x}.${cell.y}`,
            label: "Move Scientist Here",
            group: "Movement",
            disabledReason: movementReason,
            description: `Queue movement to unassigned rough floor at ${cell.x},${cell.y}.`,
            run: () => startScientistMove(movementRoomId, {
              toCell: cell,
              allowMultiRoom: true,
              allowUnassignedCell: true,
              label: `Move scientist to unassigned tile ${cell.x},${cell.y}`
            })
          }),
          ...baitPlacementContextCommands(cell),
          ...fieldDiagnosticContextCommands("tile", "", cell, { sampleMethods: ["airVial"] }),
          ...tileLaborContextCommands(cell),
          ...roomDesignationContextCommands(cell),
          ...constructionContextCommands(cell)
        ];
      }
      return [
        ...constructionContextCommands(cell),
        commandDef({
          id: `tile.showConstruction.${cell.x}.${cell.y}`,
          label: "Show Construction Overlay",
          group: "Map",
          description: "Switch the map to construction designations and rough rooms.",
          run: () => openWorkspaceContext({ workspaceTab: "map", overlayId: "construction", keyboardMenuPath: "" })
        })
      ];
    }
    const reason = scientistMoveBlockReason(roomId, { toCell: selection.tile, allowMultiRoom: true });
    const routeSummary = roomPathSummary(scientistRoomId(), roomId, {
      ignoreDoors: true,
      fromCell: scientistMapCell(),
      toCell: selection.tile
    });
    return [
      commandDef({
        id: `tile.move.${selection.tile.x}.${selection.tile.y}`,
        label: "Move Scientist Here",
        group: "Movement",
        disabledReason: reason,
        description: `Queue movement to tile ${selection.tile.x},${selection.tile.y}. Route: ${routeSummary}.`,
        run: () => startScientistMove(roomId, {
          toCell: selection.tile,
          allowMultiRoom: true,
          label: `Move scientist to tile ${selection.tile.x},${selection.tile.y}`
        })
      }),
      ...baitPlacementContextCommands(selection.tile),
      ...fieldDiagnosticContextCommands("tile", "", selection.tile, { sampleMethods: ["airVial"] }),
      ...tileLaborContextCommands(selection.tile),
      openWorkspaceCommand({
        id: `tile.openStockpiles.${selection.tile.x}.${selection.tile.y}`,
        label: "Open Room Stockpiles",
        group: "Open Menu",
        workspaceTab: "resources",
        tabKind: "stores",
        tabId: "rooms",
        description: "Open known room stockpiles for this area."
      }),
      commandDef({
        id: `tile.showResources.${selection.tile.x}.${selection.tile.y}`,
        label: "Show Resource Overlay",
        group: "Map",
        description: "Switch the map to the resource overlay.",
        run: () => openWorkspaceContext({ workspaceTab: "map", overlayId: "resources", keyboardMenuPath: "" })
      }),
      ...roomZoneContextCommands(roomById(roomId), [selection.tile], "tile"),
      ...roomDesignationContextCommands(selection.tile),
      ...constructionContextCommands(selection.tile)
    ];
  }

  function constructionContextCommands(cell) {
    const clean = cleanMapCell(cell);
    if (!clean) return [];
    const mode = constructionWorkModeActive()
      ? constructionActiveMode()
      : labMapCellIsExcavated(clean)
        ? "smoothFloor"
        : "mine";
    const inDraft = constructionDraftCellKeys().has(mapCellKey(clean));
    const draftCells = constructionDraftCells();
    const draftReason = draftCells.length ? constructionDraftBlockReason() : "No construction draft has been selected.";
    const toggleLabel = mode === "mine"
      ? inDraft ? "Remove Dig Tile" : "Add Dig Tile"
      : mode === "cancel" ? `${inDraft ? "Remove" : "Add"} Order Cancellation Tile`
      : mode === "build" ? `${inDraft ? "Remove" : "Add"} ${constructionBuildDef().label} Tile`
      : `${inDraft ? "Remove" : "Add"} ${constructionModeLabel(mode)} Tile`;
    const commands = [
      commandDef({
        id: `construction.toggle.${mode}.${clean.x}.${clean.y}`,
        label: toggleLabel,
        group: "Construction Draft",
        disabledReason: inDraft ? "" : mode === "cancel"
          ? constructionOrderAtCell(clean) ? "" : "No active construction order exists on this tile."
          : constructionTileStaticBlockReason(mode, clean, { buildType: state.construction.buildType }),
        description: `${inDraft ? "Remove this tile from" : "Add this tile to"} the ${constructionModeLabel(mode).toLowerCase()} draft.`,
        run: () => {
          if (!constructionWorkModeActive()) {
            state.construction.mode = mode;
            ensureUiState().mapOverlay = "construction";
          }
          return toggleConstructionDraftCell(clean);
        }
      }),
      commandDef({
        id: "construction.confirmDraft",
        label: mode === "mine" ? "Confirm Dig Designation" : mode === "cancel" ? "Confirm Order Cancellation" : mode === "build" ? `Confirm ${constructionBuildDef().label} Designation` : `Confirm ${constructionModeLabel(mode)} Designation`,
        group: "Construction Draft",
        disabledReason: draftReason,
        description: `Confirm ${draftCells.length} tile${draftCells.length === 1 ? "" : "s"} at priority ${state.construction.priority}. Work completes one tile at a time.`,
        run: () => startExcavationDraftDesignation()
      }),
      commandDef({
        id: "construction.clearDraft",
        label: "Clear Construction Draft",
        group: "Construction Draft",
        disabledReason: draftCells.length ? "" : "No construction draft has been selected.",
        description: "Clear the temporary painted draft without changing confirmed orders.",
        run: () => clearConstructionDraft()
      })
    ];
    for (const def of CONSTRUCTION_MODE_DEFS) {
      commands.push(commandDef({
        id: `construction.mode.${def.id}`,
        label: `${def.label} Mode`,
        group: "Construction Mode",
        disabledReason: !def.implemented ? `${def.label} is not implemented yet.` : constructionActiveMode() === def.id ? `${def.label} Mode is already active.` : "",
        description: def.description,
        run: () => setConstructionMode(def.id)
      }));
    }
    for (const def of CONSTRUCTION_BUILD_DEFS) {
      const fixture = def.kind === "fixture" ? fixtureDef(def.fixtureTypeId) : null;
      const material = fixture ? fixtureMaterialOption(fixture, state.construction.fixtureMaterialPolicy) : null;
      commands.push(commandDef({
        id: `construction.buildType.${def.id}`,
        label: `Build: ${def.label}`,
        group: "Build Type",
        disabledReason: constructionActiveMode() === "build" && state.construction.buildType === def.id ? `${def.label} is already selected.` : "",
        description: fixture
          ? `${def.description} ${titleCase(fixture.assemblyClass.replace(/([A-Z])/g, " $1"))}; ${fixtureRotatedFootprint(fixture, state.construction.fixtureRotation).width}x${fixtureRotatedFootprint(fixture, state.construction.fixtureRotation).height} footprint. ${fixture.assemblyClass === "siteBuilt" ? `On-site materials: ${formatResourceBundle(material?.costs || {})}.` : "Missing items or components create an automatic linked production bill."}`
          : `${def.description} Cost per tile: ${formatResourceBundle(def.resourceCosts)}.`,
        run: () => setConstructionBuildType(def.id)
      }));
    }
    const selectedFixture = constructionBuildDef()?.kind === "fixture" ? fixtureDef(constructionBuildDef().fixtureTypeId) : null;
    if (selectedFixture) {
      commands.push(commandDef({
        id: "construction.fixture.rotate",
        label: `Rotate Fixture (${state.construction.fixtureRotation} degrees)`,
        group: "Fixture Placement",
        description: "Rotate the footprint and every named interaction point clockwise by 90 degrees.",
        run: () => rotateConstructionFixture(1)
      }));
      for (const policy of FIXTURE_MATERIAL_POLICY_DEFS.filter((policy) => ["closest", "best"].includes(policy.id) || selectedFixture.materialOptions[policy.id])) {
        commands.push(commandDef({
          id: `construction.fixture.material.${policy.id}`,
          label: `Material: ${policy.label}`,
          group: "Fixture Material",
          disabledReason: state.construction.fixtureMaterialPolicy === policy.id ? `${policy.label} is already selected.` : "",
          description: policy.description,
          run: () => setConstructionFixtureMaterialPolicy(policy.id)
        }));
      }
    }
    if (constructionActiveMode() === "ramp") {
      const ramp = rampPlacementRecord(clean, state.construction);
      commands.push(commandDef({
        id: "construction.ramp.customGeometry",
        label: `Ramp Size: ${state.construction.rampLength} m x ${state.construction.rampWidth} m`,
        group: "Ramp Geometry",
        description: `${ramp.grade} ramp; ${formatDecimal(ramp.angleDegrees, 1)} degrees in geometric Debug terms. Short ramps remain deliberately playable abstractions.`,
        run: () => promptConstructionRampGeometry()
      }));
      for (const length of [1, 2, 4, 8]) {
        commands.push(commandDef({
          id: `construction.ramp.length.${length}`,
          label: `Length ${length} m (${Vertical.rampGradeLabel(length)})`,
          group: "Ramp Geometry",
          disabledReason: state.construction.rampLength === length ? `Ramp length is already ${length} m.` : "",
          description: `Set a ${length}-tile horizontal run for one 4 m layer of rise.`,
          run: () => setConstructionRampGeometry({ length })
        }));
      }
      for (const direction of Object.keys(Vertical.DIRECTIONS)) {
        commands.push(commandDef({
          id: `construction.ramp.direction.${direction}`,
          label: `Direction: ${titleCase(direction)}`,
          group: "Ramp Direction",
          disabledReason: state.construction.rampDirection === direction ? `Ramp direction is already ${direction}.` : "",
          description: `The ramp rises toward the ${direction}.`,
          run: () => setConstructionRampGeometry({ direction })
        }));
      }
    }
    for (let priority = CONSTRUCTION_PRIORITY_MIN; priority <= CONSTRUCTION_PRIORITY_MAX; priority += 1) {
      commands.push(commandDef({
        id: `construction.priority.${priority}`,
        label: `Priority ${priority}${priority === CONSTRUCTION_PRIORITY_MIN ? " (Highest)" : priority === CONSTRUCTION_PRIORITY_MAX ? " (Lowest)" : ""}`,
        group: "Construction Priority",
        disabledReason: state.construction.priority === priority ? `Priority ${priority} is already selected.` : "",
        description: "Lower numbers are claimed first, following Dwarf Fortress priority ordering.",
        run: () => setConstructionPriority(priority)
      }));
    }
    const selectedOrder = constructionOrderAtCell(clean);
    const linkedBill = productionBillForOrder(selectedOrder);
    if (debugToolsEnabled() && linkedBill && linkedBill.status !== "completed") {
      commands.push(commandDef({
        id: `construction.debugFulfillBill.${linkedBill.id}`,
        label: `Debug: Fabricate ${fixtureDef(linkedBill.fixtureTypeId)?.label || "Fixture"}`,
        group: "Debug Construction",
        description: "Complete this linked prototype production bill so placement and assembly can be tested before the full crafting pass.",
        run: () => fulfillFixtureProductionBill(linkedBill)
      }));
    }
    commands.push(...structuralDamageContextCommands(clean));
    return commands;
  }

  function structuralDamageContextCommands(cell) {
    const clean = cleanMapCell(cell);
    const target = clean ? structuralTargetAtCell(clean) : null;
    if (!target) return [];
    const scientistCell = scientistMapCell();
    const adjacent = scientistCell.z === clean.z && Math.max(Math.abs(scientistCell.x - clean.x), Math.abs(scientistCell.y - clean.y)) <= 1;
    const commands = [commandDef({
      id: `structure.strike.${clean.x}.${clean.y}`,
      label: "Strike Structure",
      group: "Combat",
      disabledReason: adjacent ? staminaBlockReason(adjustedStaminaCost(COMBAT_STRIKE_STAMINA, ["striking"])) : "The scientist must be on or adjacent to the structure.",
      description: `Strike this ${target.kind} with physical force. Material resistance determines actual condition damage.`,
      run: () => strikeStructure(clean)
    })];
    if (debugToolsEnabled()) {
      for (const damageTypeId of ["physical", "corrosive", "heat", "electrical", "arcane", "force"]) {
        const def = damageTypeDef(damageTypeId);
        commands.push(commandDef({
          id: `structure.debugDamage.${damageTypeId}.${clean.x}.${clean.y}`,
          label: `Debug: ${def.label} Damage`,
          group: "Debug Structure",
          description: `Apply 40 raw ${def.label.toLowerCase()} damage to test material resistance and failure states.`,
          run: () => debugDamageStructure(clean, damageTypeId, 40)
        }));
      }
    }
    return commands;
  }

  function doorContextCommands(door, selection = {}) {
    if (!door) {
      return [];
    }
    const roomIds = Array.isArray(door.roomIds) && door.roomIds.length
      ? door.roomIds
      : Array.isArray(selection.roomIds) && selection.roomIds.length
        ? selection.roomIds
        : doorRoomIdsFromKey(selection.key || door.key);
    const [roomAId, roomBId] = roomIds;
    const key = selection.key || door.key || doorKey(roomAId, roomBId);
    const liveDoor = state.doors?.[key] || doorForConnection(roomAId, roomBId) || door;
    const connectionLabel = roomIds.length ? roomIds.map(roomName).join(" to ") : `tile ${door.cell?.x},${door.cell?.y}`;
    const description = `${doorTypeLabel(liveDoor.typeId)} at ${connectionLabel}; condition ${doorConditionLabel(liveDoor)}; ${contaminationDiffusionDoorLabel(liveDoor)}.`;
    const breachedReason = doorIsBreached(liveDoor) ? `${roomIds.map(roomName).join(" to ")} door is breached.` : "";
    const openAction = liveDoor.state === DOOR_STATE_OPEN ? DOOR_STATE_CLOSED : DOOR_STATE_OPEN;
    const lockAction = liveDoor.lockState === DOOR_LOCK_LOCKED ? DOOR_LOCK_UNLOCKED : DOOR_LOCK_LOCKED;
    const sealAction = liveDoor.sealState === DOOR_SEAL_SEALED ? DOOR_SEAL_UNSEALED : DOOR_SEAL_SEALED;
    return [
      commandDef({
        id: `door.position.${key}`,
        label: openAction === DOOR_STATE_OPEN ? "Open Door" : "Close Door",
        group: "Door",
        disabledReason: breachedReason || (openAction === DOOR_STATE_OPEN && liveDoor.sealState === DOOR_SEAL_SEALED
          ? "This door is sealed."
          : openAction === DOOR_STATE_OPEN && liveDoor.lockState === DOOR_LOCK_LOCKED ? "This door is locked." : ""),
        description,
        run: () => queueDoorOperation(key, "position", openAction)
      }),
      commandDef({
        id: `door.lock.${key}`,
        label: lockAction === DOOR_LOCK_LOCKED ? "Lock Door" : "Unlock Door",
        group: "Door",
        disabledReason: breachedReason || (lockAction === DOOR_LOCK_LOCKED && liveDoor.sealState === DOOR_SEAL_SEALED ? "Sealed doors are already secured." : ""),
        description,
        run: () => queueDoorOperation(key, "lock", lockAction)
      }),
      commandDef({
        id: `door.seal.${key}`,
        label: sealAction === DOOR_SEAL_SEALED ? "Seal Door" : "Unseal Door",
        group: "Door",
        disabledReason: breachedReason,
        description,
        run: () => queueDoorOperation(key, "seal", sealAction)
      }),
      openWorkspaceCommand({
        id: `door.openPolicies.${key}`,
        label: "Door Policies",
        group: "Open Menu",
        workspaceTab: "policies",
        tabKind: "policies",
        tabId: "doors",
        description: "Open laboratory door automation and security policy settings."
      }),
      ...repairLaborCommands({ kind: "door", value: liveDoor, cell: door.cell, mapDoor: door }),
      ...structuralDamageContextCommands(door.cell)
    ];
  }

  function incidentContextCommands(incident) {
    if (!incident) {
      return [];
    }
    const target = incidentFocusTarget(incident);
    const commands = [
      commandDef({
        id: `incident.focus.${incident.id}`,
        label: "Focus Source",
        group: "Incident",
        disabledReason: target ? "" : "This incident has no focus target.",
        description: "Select the map object or room connected to this alert.",
        run: () => focusMapTarget(target)
      }),
      commandDef({
        id: `incident.respond.${incident.id}`,
        label: "Respond",
        group: "Incident",
        disabledReason: incidentResponseMoveBlockReason(incident),
        description: "Queue scientist movement to the alert site.",
        run: () => startIncidentResponseMove(incident.id)
      }),
      commandDef({
        id: `incident.ack.${incident.id}`,
        label: incident.acknowledgedAt !== null ? "Acknowledged" : "Acknowledge",
        group: "Incident",
        disabledReason: incident.status === "resolved"
          ? "This incident is already resolved."
          : incident.acknowledgedAt !== null
            ? "This incident has already been acknowledged."
            : "",
        description: "Mark this alert as seen.",
        run: () => acknowledgeIncident(incident.id)
      }),
      commandDef({
        id: `incident.resolve.${incident.id}`,
        label: "Mark Resolved",
        group: "Incident",
        disabledReason: incident.status === "resolved" ? "This incident is already resolved." : containmentEmergencyResolutionBlockReason(incident),
        description: "Clear this known alert. The same observation stays dismissed until it changes.",
        run: () => resolveIncident(incident.id)
      }),
      openWorkspaceCommand({
        id: `incident.openMessages.${incident.id}`,
        label: "Open Message History",
        group: "Open Menu",
        workspaceTab: "log",
        description: "Open the full message history for incident context."
      }),
      openWorkspaceCommand({
        id: `incident.openTasks.${incident.id}`,
        label: "Open Tasks",
        group: "Open Menu",
        workspaceTab: "tasks",
        tabKind: "tasks",
        tabId: incident.responseTaskId ? "queue" : "blocked",
        description: "Open the scientist task management screen."
      })
    ];
    if (incident.sourceKind === "slime" && incident.type !== "containmentEmergency") {
      commands.splice(2, 0, ...recaptureContextCommands(findSlime(incident.sourceId)));
    }
    if (incident.type === "containmentEmergency" && ["exact", "exact-source"].includes(incident.perceptionPrecision)) {
      commands.splice(2, 0, ...incident.emergencyCreatureIds
        .map(findSlime)
        .filter((slime) => slime && slime.status !== "dead" && slimeIsUncontained(slime))
        .flatMap(recaptureContextCommands));
      const emergency = containmentEmergencyById(incident.emergencyId);
      commands.splice(2, 0, ...baitPlacementContextCommands(incident.cell));
      const currentRoom = roomById(scientistRoomId());
      const safeRoom = currentRoom?.connections
        ?.map(roomById)
        .find((room) => room && room.id !== incident.roomId
          && !(state.containmentEmergencies || []).some((entry) => entry.stage !== "resolved" && entry.roomId === room.id));
      commands.splice(2, 0, commandDef({
        id: `incident.retreat.${incident.id}`,
        label: safeRoom ? `Retreat to ${safeRoom.name}` : "Emergency Retreat",
        group: "Containment Response",
        disabledReason: scientistRoomId() !== incident.roomId
          ? "The scientist is already outside the emergency room."
          : safeRoom
            ? scientistMoveBlockReason(safeRoom.id, { allowMultiRoom: true })
            : "No connected room is currently clear of known containment emergencies.",
        description: "Queue ordinary physical movement out of the emergency room. Doors, routes, access, and stamina still apply.",
        run: () => startScientistMove(safeRoom.id, { allowMultiRoom: true, label: `Retreat to ${safeRoom.name}` })
      }));
      const container = emergency?.sourceKind === "container" ? containerById(emergency.sourceId) : null;
      if (container) commands.splice(2, 0, ...repairLaborCommands({ kind: "container", value: container, cell: objectMapCell(container) }));
      for (const spill of emergency ? containmentEmergencyHazardousSpills(emergency) : []) {
        commands.splice(2, 0, commandDef({
          id: `incident.cleanup.${incident.id}.${spill.id}`,
          label: `Clean ${physicalStackLabel(spill)}`,
          group: "Containment Recovery",
          disabledReason: spillCleanupTask(spill.id) ? "Cleanup is already queued for this spill." : "",
          description: "Queue physical travel, collection, and receptacle use for this hazardous spill.",
          run: () => {
            const task = startSpillCleanup(spill.id, { emergencyId: emergency.id });
            persist();
            render();
            return Boolean(task);
          }
        }));
      }
    }
    commands.splice(2, 0, commandDef({
      id: `incident.lockdown.${incident.id}`,
      label: ensureAccessControl().lockdownActive ? "Lift Emergency Lockdown" : "Initiate Emergency Lockdown",
      group: "Containment Response",
      disabledReason: incident.status === "resolved" ? "This incident is already resolved." : "",
      description: ensureAccessControl().lockdownActive
        ? "Lift access restrictions. Doors remain in their current physical states."
        : "Activate access restrictions and queue the configured physical door operations. Ordinary doors do not move remotely.",
      danger: !ensureAccessControl().lockdownActive,
      run: () => setAccessLockdown(!ensureAccessControl().lockdownActive)
    }));
    return commands;
  }

  function corpseContextCommands(corpse) {
    if (!corpse) {
      return [];
    }
    const commands = [];
    const necropsyCost = adjustedStaminaCost(BASE_ACTION_STAMINA, ["medicine", "creatureHandling"]);
    commands.push(commandDef({
      id: `corpse.necropsy.${corpse.id}`,
      label: "Necropsy",
      group: "Corpse",
      disabledReason: necropsyBlockReason(corpse, necropsyCost),
      description: `Scientific examination; ${formatDuration(adjustedActionDuration(necropsyDuration(corpse), "medicine"))}.`,
      run: () => startNecropsy(corpse)
    }));
    commands.push(commandDef({
      id: `corpse.forensic.${corpse.id}`,
      label: `Forensic Analyze (${FORENSIC_ANALYZE_MANA_COST} MANA)`,
      group: "Corpse",
      disabledReason: forensicAnalyzeCorpseBlockReason(corpse),
      description: "Instant magical read of cause, tissue, and evidence state.",
      run: () => startForensicAnalyzeCorpse(corpse.id)
    }));
    for (const procedure of SPECIMEN_HARVEST_PROCEDURE_DEFS) {
      const cost = adjustedStaminaCost(procedure.staminaCost, ["medicine", "creatureHandling"]);
      commands.push(commandDef({
        id: `corpse.harvest.${corpse.id}.${procedure.id}`,
        label: procedure.corpseLabel,
        group: "Harvest",
        disabledReason: corpseHarvestBlockReason(corpse, procedure, cost),
        description: corpseHarvestProcedureTitle(corpse, procedure),
        danger: Boolean(procedure.corpseConsumes || procedure.corpseRuins),
        run: () => startCorpseHarvest(corpse, procedure.id)
      }));
    }
    for (const pit of state.containers.filter(isPitHoleContainer)) {
      const key = `corpse-haul:${corpse.id}:pit:${pit.id}`;
      const existing = activeLaborOrderForDedupeKey(key);
      commands.push(commandDef({
        id: `corpse.haul.${corpse.id}.${pit.id}`,
        label: `Haul to ${pit.name}`,
        group: "Hauling",
        disabledReason: existing
          ? "This hauling order already exists."
          : corpse.storage === "container" && corpse.containerId === pit.id
            ? `The corpse is already in ${pit.name}.`
            : pitHoleCorpseCount(pit) >= pitHoleCorpseCapacity(pit)
              ? `${pit.name} is full.`
              : corpseCarryMassKg(corpse) > SCIENTIST_CARRY_MASS_KG
                ? `These remains require hauling equipment; ${formatDecimal(corpseCarryMassKg(corpse), 1)} kg exceeds hand-carry capacity.`
                : "",
        description: "Create a physical hauling order. Relocation does not process, harvest, or dispose of the corpse.",
        run: () => startLaborWorkOrder({
          kind: "corpseHaul",
          category: "hauling",
          label: `Haul ${corpse.name} remains to ${pit.name}`,
          priority: 4,
          source: "manual",
          target: { kind: "corpse", id: corpse.id, roomId: corpse.roomId },
          destination: { containerId: pit.id, roomId: pit.roomId },
          dedupeKey: key
        })
      }));
    }
    {
      const key = `corpse-haul:${corpse.id}:drums`;
      const existing = activeLaborOrderForDedupeKey(key);
      commands.push(commandDef({
        id: `corpse.haul.${corpse.id}.drums`,
        label: "Haul to Waste Drums",
        group: "Hauling",
        disabledReason: existing
          ? "This hauling order already exists."
          : corpse.storage === "drum"
            ? "The corpse is already in the Waste Drums."
            : drummedCorpseCount() >= WASTE_DRUM_CAPACITY
              ? "The Waste Drums are full."
              : corpseCarryMassKg(corpse) > SCIENTIST_CARRY_MASS_KG
                ? `These remains require hauling equipment; ${formatDecimal(corpseCarryMassKg(corpse), 1)} kg exceeds hand-carry capacity.`
                : "",
        description: "Create a physical hauling order to the current Waste Drum storage. The corpse remains intact and still requires processing or disposal.",
        run: () => startLaborWorkOrder({
          kind: "corpseHaul",
          category: "hauling",
          label: `Haul ${corpse.name} remains to Waste Drums`,
          priority: 4,
          source: "manual",
          target: { kind: "corpse", id: corpse.id, roomId: corpse.roomId },
          destination: { storage: "drum", roomId: PITS_ROOM_ID, cell: labMapRoomAnchor(PITS_ROOM_ID) },
          dedupeKey: key
        })
      }));
    }
    commands.push(commandDef({
      id: `corpse.dump.${corpse.id}`,
      label: "Dump Outside",
      group: "Disposal",
      disabledReason: dumpCorpseBlockReason(corpse),
      description: "Remove the corpse from lab storage and increase Suspicion.",
      danger: true,
      run: () => dumpCorpseOutside(corpse.id)
    }));
    commands.push(openWorkspaceCommand({
      id: `corpse.openRecord.${corpse.id}`,
      label: "Open Deceased Records",
      group: "Open Menu",
      workspaceTab: "specimens",
      tabKind: "creatures",
      tabId: "deceased",
      description: "Open deceased specimen records."
    }));
    commands.push(openWorkspaceCommand({
      id: `corpse.openStockpiles.${corpse.id}`,
      label: "Open Room Stockpiles",
      group: "Open Menu",
      workspaceTab: "resources",
      tabKind: "stores",
      tabId: "rooms",
      description: "Open local storage and pit contents for this corpse location."
    }));
    return commands;
  }

  function slimeContextCommands(slime) {
    if (!slime) {
      return [];
    }
    const organicFeedstock = FEEDSTOCK_BY_KEY.organicFeedstock;
    const bestFeedstockKey = slime.revealed?.sustenance ? bestAvailableFeedstockKey(slime) : "";
    const bestFeedstock = bestFeedstockKey ? FEEDSTOCK_BY_KEY[bestFeedstockKey] : null;
    const commands = [
      ...fieldDiagnosticContextCommands("slime", slime.id, objectMapCell(slime), { environment: false, sampleMethods: ["surfaceSwab", "fluidSample"] }),
      commandDef({
        id: `slime.analyze.${slime.id}`,
        label: `Analyze (${ANALYZE_MANA_COST} MANA)`,
        group: "Analyze",
        disabledReason: analyzeSlimeBlockReason(slime),
        description: "Read practiced skills and broad learned behavior.",
        run: () => startAnalyzeSlime(slime.id)
      }),
      commandDef({
        id: `slime.advancedAnalyze.${slime.id}`,
        label: `Advanced Analyze (${ADVANCED_ANALYZE_MANA_COST} MANA)`,
        group: "Analyze",
        disabledReason: advancedAnalyzeSlimeBlockReason(slime),
        description: "Read exact levels for skills already found by Analyze.",
        run: () => startAdvancedAnalyzeSlime(slime.id)
      }),
      commandDef({
        id: `slime.combatAnalyze.${slime.id}`,
        label: `Combat Analyze (${COMBAT_ANALYZE_MANA_COST} MANA)`,
        group: "Analyze",
        disabledReason: combatAnalyzeSlimeBlockReason(slime),
        description: "Read combat intent, threat band, and observed damage tags.",
        run: () => startCombatAnalyzeSlime(slime.id)
      }),
      commandDef({
        id: `slime.feed.${slime.id}.organicFeedstock`,
        label: `Feed ${organicFeedstock.label}`,
        group: "Feeding",
        disabledReason: manualFeedBlockReason(slime, organicFeedstock.key),
        description: resourceLogisticsHint({ [organicFeedstock.key]: 1 }, slimeEffectiveRoomId(slime), `feeding ${slime.name}`)
          || `Feed one unit of ${organicFeedstock.label}.`,
        run: () => {
          const result = feedSlimeOrQueueDelivery(slime, organicFeedstock.key, { source: "manual" });
          persist();
          render();
          return result;
        }
      }),
      commandDef({
        id: `slime.feedBest.${slime.id}`,
        label: bestFeedstock ? `Feed Best Match (${bestFeedstock.label})` : "Feed Best Match",
        group: "Feeding",
        disabledReason: bestFeedBlockReason(slime),
        description: bestFeedstock
          ? resourceLogisticsHint({ [bestFeedstock.key]: 1 }, slimeEffectiveRoomId(slime), `feeding ${slime.name}`) || `Feed the best known available match: ${bestFeedstock.label}.`
          : "Feed the best known available match once Sustenance is discovered.",
        run: () => {
          const feedstockKey = bestAvailableFeedstockKey(slime);
          const result = feedstockKey ? feedSlimeOrQueueDelivery(slime, feedstockKey, { source: "manual" }) : false;
          persist();
          render();
          return result;
        }
      }),
      commandDef({
        id: `slime.containment.${slime.id}`,
        label: slimeContainmentToggleLabel(slime),
        group: "Handling",
        disabledReason: slime.status === "released" ? "Choose a specific Recapture command and destination container." : slimeContainmentToggleBlockReason(slime),
        description: slime.status === "released" ? "Loose creatures require a physical recapture task with a selected destination." : releaseSuitabilityTooltipText(slime),
        danger: slime.status !== "released",
        run: () => toggleSlimeContainment(slime.id)
      }),
      commandDef({
        id: `slime.strike.${slime.id}`,
        label: "Strike",
        group: "Combat",
        disabledReason: scientistStrikeBlockReason(slime),
        description: `Attempt a Physical attack using Striking. ${combatActionTimingText(combatActionDef("strike"))}; ${COMBAT_STRIKE_STAMINA} base Stamina.`,
        danger: true,
        run: () => startScientistStrike(slime.id)
      }),
      commandDef({
        id: `slime.shove.${slime.id}`,
        label: "Shove",
        group: "Combat",
        disabledReason: scientistCombatActionBlockReason("shove", slime),
        description: `Use Grappling to force the target one tile away. ${combatActionTimingText(combatActionDef("shove"))}; 8 base Stamina.`,
        danger: true,
        run: () => startScientistShove(slime.id)
      }),
      commandDef({
        id: `slime.intercept.${slime.id}`,
        label: "Intercept",
        group: "Combat",
        disabledReason: scientistCombatActionBlockReason("intercept", slime),
        description: "Prepare a Guarding reaction that strikes this creature when it attacks the scientist.",
        run: () => startScientistIntercept(slime.id)
      }),
      commandDef({
        id: `slime.retreat.${slime.id}`,
        label: "Retreat",
        group: "Combat",
        disabledReason: scientistIsDead() ? "The scientist is dead." : actorIsIncapacitated("scientist") ? "The scientist is incapacitated." : "",
        description: "Cancel the current stance or prepared action and urgently move one open tile away from this creature.",
        run: () => retreatScientistFrom(slime.id)
      }),
      commandDef({
        id: `slime.soulLash.${slime.id}`,
        label: `Soul Lash (${COMBAT_SOUL_LASH_MANA} MANA)`,
        group: "Combat",
        disabledReason: scientistCombatActionBlockReason("soulLash", slime),
        description: `Instant Animancy attack against a living, souled target within ${COMBAT_SOUL_LASH_RANGE_M} m. Deals Arcane damage; ${combatActionTimingText(combatActionDef("soulLash"))}.`,
        danger: true,
        run: () => startScientistSoulLash(slime.id)
      }),
      openWorkspaceCommand({
        id: `slime.openRecord.${slime.id}`,
        label: "Open Creature Record",
        group: "Open Menu",
        workspaceTab: "specimens",
        tabKind: "creatures",
        tabId: isUnknownCreatureRecord(slime) ? "unknown" : "living",
        description: "Open creature records for this specimen."
      }),
      openWorkspaceCommand({
        id: `slime.openJobs.${slime.id}`,
        label: "Open Roles",
        group: "Open Menu",
        workspaceTab: "specimens",
        tabKind: "creatures",
        tabId: "jobs",
        description: "Open creature roles, actual activity, worksites, and observed performance."
      }),
      openWorkspaceCommand({
        id: `slime.openTesting.${slime.id}`,
        label: "Open Testing",
        group: "Open Menu",
        workspaceTab: "specimens",
        tabKind: "creatures",
        tabId: "testing",
        description: "Open testing and research actions."
      })
    ];
    commands.push(...injuryContextCommands(slime));
    if (slimeIsUncontained(slime) && slime.status !== "dead") {
      commands.splice(5, 0, ...recaptureContextCommands(slime));
    }
    const container = slime?.containerId ? containerById(slime.containerId) : null;
    if (container && container.type !== "synthesis" && !isPitHoleContainer(container)) {
      commands.push(commandDef({
        id: `slime.stageCollection.${slime.id}`,
        label: "Stage Container in Collection Bay",
        group: "Movement",
        disabledReason: containerHaulBlockReason(container, COLLECTION_BAY_ROOM_ID),
        description: `Queue ${container.name} for Collection Bay staging. The contained specimen and interior contents move with it.`,
        run: () => moveContainerToRoom(container.id, COLLECTION_BAY_ROOM_ID)
      }));
    }
    commands.push(commandDef({
      id: `slime.role.${slime.id}.automatic`,
      label: "Use Site Default",
      group: "Role",
      disabledReason: slimeRoleContextBlockReason(slime, "automatic"),
      description: "Remove the manual override and derive this creature's role from its current physical site.",
      run: () => assignCreatureRole(slime.id, "automatic")
    }));
    for (const role of CREATURE_ROLES) {
      commands.push(commandDef({
        id: `slime.role.${slime.id}.${role.id}`,
        label: role.id === "idle" ? "Set Role: Idle" : `Set Role: ${role.label}`,
        group: "Role",
        disabledReason: slimeRoleContextBlockReason(slime, role.id),
        description: `Record ${role.label} as the player's intended use. The creature still acts according to its biology and situation.`,
        run: () => assignCreatureRole(slime.id, role.id)
      }));
    }
    if (isInSynthesisTube(slime)) {
      commands.push(commandDef({
        id: `slime.moveFromTube.${slime.id}`,
        label: "Move to Open Container",
        group: "Handling",
        disabledReason: synthesisTubeMoveBlockReason(slime),
        description: "Move the specimen from the synthesis tube to an open permanent container.",
        run: () => moveTubeOccupantToOpenContainer(slime.id)
      }));
    }
    for (const procedure of SPECIMEN_HARVEST_PROCEDURE_DEFS) {
      const cost = adjustedStaminaCost(procedure.staminaCost, ["medicine", "creatureHandling"]);
      commands.push(commandDef({
        id: `slime.harvest.${slime.id}.${procedure.id}`,
        label: procedure.livingLabel,
        group: "Harvest",
        disabledReason: livingHarvestBlockReason(slime, procedure, cost),
        description: livingHarvestProcedureTitle(slime, procedure),
        danger: Boolean(procedure.terminal),
        run: () => startLivingHarvest(slime, procedure.id)
      }));
    }
    return commands;
  }

  function recaptureContextCommands(slime) {
    if (!slime || slime.status === "dead" || !slimeIsUncontained(slime)) return [];
    const destinations = recaptureDestinationCandidates(slime);
    if (!destinations.length) {
      return [commandDef({
        id: `slime.recapture.${slime.id}.none`,
        label: "Recapture",
        group: "Containment Response",
        disabledReason: "No empty usable destination container is available.",
        description: "Recapture requires an explicit physical destination."
      })];
    }
    return destinations.map((container) => commandDef({
      id: `slime.recapture.${slime.id}.${container.id}`,
      label: `${isPitHoleContainer(container) ? "Herd" : "Recapture"} into ${container.name}`,
      group: "Containment Response",
      disabledReason: recaptureSlimeBlockReason(slime, container),
      description: `${recaptureRiskDescription(slime, container)} The scientist must reach the observed creature, control it, and ${isPitHoleContainer(container) ? "guide it into this pit" : "carry it to this container"}.`,
      danger: recaptureRiskAssessment(slime, container, { knownOnly: true }).band === "Extremely Dangerous",
      run: () => startSlimeRecapture(slime.id, container.id)
    }));
  }

  function slimeRoleContextBlockReason(slime, roleId) {
    if (!slime || slime.status === "dead") {
      return "No living slime available.";
    }
    normalizeSlimeRole(slime);
    if (roleId === "automatic") {
      return slime.roleSource === "automatic" ? `${slime.name} already uses its site default.` : roleAssignmentBlockReason(slime);
    }
    const normalizedRoleId = cleanCreatureRoleId(roleId);
    if (slime.roleSource === "manual" && slime.roleId === normalizedRoleId) {
      return `${slime.name} already has the ${creatureRoleLabel(normalizedRoleId)} role.`;
    }
    return roleAssignmentBlockReason(slime);
  }

  function synthesisTubeMoveBlockReason(slime) {
    if (!slime || !isInSynthesisTube(slime)) {
      return "Specimen is not in the synthesis tube.";
    }
    if (!firstOpenPermanentContainer()) {
      return "No open permanent container is available.";
    }
    const cost = adjustedStaminaCost(HANDLING_STAMINA, ["creatureHandling"]);
    return physicalStateRiskBlockReason(`moving ${slime.name} from the synthesis tube`)
      || handlingMethodMissingToolReason(currentHandlingMethodId())
      || staminaBlockReason(cost);
  }

  function containerContextCommands(container) {
    if (!container) {
      return [];
    }
    const commands = [];
    commands.push(...fieldDiagnosticContextCommands("container", container.id, objectMapCell(container), { sampleMethods: ["airVial"] }));
    if (isPitHoleContainer(container)) {
      for (const role of CREATURE_ROLES.filter((candidate) => ["idle", "corpse", "disposal"].includes(candidate.id))) {
        commands.push(commandDef({
          id: `container.defaultRole.${container.id}.${role.id}`,
          label: `Default Role: ${role.label}`,
          group: "Role Default",
          disabledReason: containerDefaultRoleId(container) === role.id ? `${container.name} already defaults to ${role.label}.` : "",
          description: "Creatures placed here inherit this role unless they have a manual role override.",
          run: () => setContainerDefaultRole(container.id, role.id)
        }));
      }
    }
    if (container.type !== "synthesis") {
      const action = containerAccessOpen(container) ? "close" : "open";
      const baseCost = action === "close" ? CONTAINER_INTERACTION_CLOSE_STAMINA : CONTAINER_INTERACTION_OPEN_STAMINA;
      const actionLabel = action === "close" ? "Close Container" : "Open Container";
      const physicalRiskLabel = `${action === "close" ? "closing" : "opening"} ${container.name}`;
      commands.push(commandDef({
        id: `container.access.${container.id}`,
        label: actionLabel,
        group: "Container",
        disabledReason: containerInteractionBlockReason(container, action)
          || physicalStateRiskBlockReason(physicalRiskLabel)
          || handlingMethodMissingToolReason(currentHandlingMethodId())
          || staminaBlockReason(adjustedStaminaCost(baseCost, ["creatureHandling"])),
        description: handlingRiskTitle(container, action, currentHandlingMethodId()),
        run: () => startContainerInteraction(container.id, action)
      }));

      const currentRoomId = scientistRoomId();
      commands.push(commandDef({
        id: `container.haulCurrent.${container.id}`,
        label: `Haul to ${roomName(currentRoomId)}`,
        group: "Movement",
        disabledReason: containerHaulBlockReason(container, currentRoomId),
        description: "Queue a container hauling task to the scientist's current room.",
        run: () => moveContainerToRoom(container.id, currentRoomId)
      }));
      commands.push(commandDef({
        id: `container.stageCollection.${container.id}`,
        label: "Stage in Collection Bay",
        group: "Movement",
        disabledReason: containerHaulBlockReason(container, COLLECTION_BAY_ROOM_ID),
        description: "Queue this container for Collection Bay staging. Contents and contained remains move with the container.",
        run: () => moveContainerToRoom(container.id, COLLECTION_BAY_ROOM_ID)
      }));

      if (container.roomId === COLLECTION_BAY_ROOM_ID) {
        const stationInfo = collectionBayStationInfo(container);
        if (stationInfo?.station) {
          commands.push(commandDef({
            id: `container.collectionTransfer.${container.id}`,
            label: "Transfer Receptacle",
            group: "Collection",
            disabledReason: collectionBayTransferDisabledReason(stationInfo)
              || physicalStateRiskBlockReason(`transferring ${container.name} receptacle`)
              || staminaBlockReason(adjustedStaminaCost(RESOURCE_HAUL_STAMINA, ["materialsScience", "creatureHandling"])),
            description: "Queue a scientist task to remove the filled physical receptacle and install an empty replacement. Overflow remains in the apparatus and refills the replacement before hauling begins.",
            run: () => transferCollectionBayReceptacle(container.id)
          }));
        }
      }

      if (!isPitHoleContainer(container) && containerCorpses(container.id).length) {
        for (const remainsAction of ["dumpRemains", "scrapeRemains"]) {
          const base = remainsAction === "scrapeRemains" ? REMAINS_SCRAPE_STAMINA : REMAINS_DUMP_STAMINA;
          const riskLabel = `${remainsHandlingActionLabel(remainsAction).toLowerCase()} from ${container.name}`;
          commands.push(commandDef({
            id: `container.remains.${container.id}.${remainsAction}`,
            label: remainsHandlingActionLabel(remainsAction),
            group: "Remains",
            disabledReason: remainsHandlingBlockReason(container, remainsAction)
              || physicalStateRiskBlockReason(riskLabel)
              || handlingMethodMissingToolReason(currentHandlingMethodId())
              || staminaBlockReason(adjustedStaminaCost(base, ["creatureHandling"])),
            description: handlingRiskTitle(container, remainsAction, currentHandlingMethodId()),
            danger: true,
            run: () => startRemainsHandling(container.id, remainsAction)
          }));
        }
      }

      if (containerOccupants(container.id).length) {
        const destination = liveTransferDestinationCandidates(container)[0] || null;
        const riskLabel = "transferring a living slime";
        commands.push(commandDef({
          id: `container.transfer.${container.id}`,
          label: destination ? `Transfer to ${destination.name}` : "Transfer Living Slime",
          group: "Handling",
          disabledReason: liveTransferBlockReason(container, destination?.id || "")
            || physicalStateRiskBlockReason(riskLabel)
            || handlingMethodMissingToolReason(currentHandlingMethodId())
            || staminaBlockReason(adjustedStaminaCost(LIVE_TRANSFER_STAMINA, ["creatureHandling"])),
          description: destination ? `Transfer one living occupant into ${destination.name}.` : "Move one living occupant to an open same-room container.",
          run: () => startLiveSlimeTransfer(container.id, destination?.id || "")
        }));
      }
    } else {
      const occupant = containerOccupants(container.id)[0] || null;
      commands.push(commandDef({
        id: `container.openFoundry.${container.id}`,
        label: "Open Foundry",
        group: "Synthesis",
        description: "Open the Genome Foundry for editing the current genome and reviewing predictions.",
        run: openFoundryWorkspace
      }));
      commands.push(commandDef({
        id: `container.synthesize.${container.id}`,
        label: "Synthesize Slime",
        group: "Synthesis",
        disabledReason: synthesisActionBlockReason(),
        description: synthesisContextDescription(),
        run: startSynthesisFromCurrentGenome
      }));
      commands.push(commandDef({
        id: `container.knownOutcome.${container.id}`,
        label: "Open Known Outcome Editor",
        group: "Synthesis",
        disabledReason: knownOutcomeEditorBlockReason(),
        description: "Open the Foundry editor that applies discovered trait outcomes to the current genome.",
        run: openKnownOutcomeEditorFromContext
      }));
      if (occupant) {
        commands.push(commandDef({
          id: `container.focusOccupant.${container.id}`,
          label: `Focus ${occupant.name}`,
          group: "Handling",
          description: "Select the stabilized specimen currently inside the synthesis tube.",
          run: () => focusMapTarget({ kind: "slime", id: occupant.id }, { keepWorkspace: true, source: "map", resetInspectorTab: true, resetCommandMenu: true })
        }));
        commands.push(commandDef({
          id: `container.tubeMove.${container.id}`,
          label: "Move Occupant to Open Container",
          group: "Handling",
          disabledReason: synthesisTubeMoveBlockReason(occupant),
          description: "Move the synthesis tube occupant to an open permanent container.",
          run: () => moveTubeOccupantToOpenContainer(occupant.id)
        }));
      }
    }
    commands.push(openWorkspaceCommand({
      id: `container.openRecords.${container.id}`,
      label: isPitHoleContainer(container) ? "Open Creature Roles" : "Open Containers",
      group: "Open Menu",
      workspaceTab: isPitHoleContainer(container) ? "specimens" : "containers",
      tabKind: isPitHoleContainer(container) ? "creatures" : "",
      tabId: isPitHoleContainer(container) ? "jobs" : "",
      description: isPitHoleContainer(container)
        ? "Open creature roles, worksites, activity, and observed performance."
        : "Open the container management screen."
    }));
    commands.push(openWorkspaceCommand({
      id: `container.openStockpiles.${container.id}`,
      label: "Open Room Stockpiles",
      group: "Open Menu",
      workspaceTab: "resources",
      tabKind: "stores",
      tabId: "rooms",
      description: "Open known stockpiles for this container's room."
    }));
    if (collectionBayStationSelectable(container)) {
      commands.push(openWorkspaceCommand({
        id: `container.openCollectionStations.${container.id}`,
        label: "Open Collection Stations",
        group: "Open Menu",
        workspaceTab: "resources",
        tabKind: "stores",
        tabId: "stations",
        description: "Open Collection Bay station readouts and receptacle status."
      }));
      commands.push(openWorkspaceCommand({
        id: `container.openByproducts.${container.id}`,
        label: "Open Collected Byproducts",
        group: "Open Menu",
        workspaceTab: "resources",
        tabKind: "stores",
        tabId: "byproducts",
        description: "Open raw collected byproduct inventory."
      }));
    }
    commands.push(...repairLaborCommands({ kind: "container", value: container, cell: objectMapCell(container) }));
    if (debugToolsEnabled()) {
      for (const damageTypeId of ["physical", "corrosive", "heat", "electrical", "arcane", "force"]) {
        const def = damageTypeDef(damageTypeId);
        commands.push(commandDef({
          id: `container.debugDamage.${container.id}.${damageTypeId}`,
          label: `Debug: ${def.label} Damage`,
          group: "Debug Structure",
          description: `Apply 40 raw ${def.label.toLowerCase()} damage using the shared material model.`,
          run: () => debugDamageContainer(container.id, damageTypeId, 40)
        }));
      }
    }
    return commands;
  }

  function setContainerDefaultRole(containerId, roleId) {
    const container = containerById(containerId);
    if (!container || !isPitHoleContainer(container)) return false;
    container.defaultRoleId = cleanCreatureRoleId(roleId);
    for (const slime of containerOccupants(container.id)) {
      if (slime.roleSource !== "manual") {
        slime.roleSource = "automatic";
        normalizeSlimeRole(slime);
      }
    }
    addEvent(`${container.name}'s default role set to ${creatureRoleLabel(container.defaultRoleId)}.`);
    persist();
    render();
    return true;
  }

  function updateFixtureUtility(fixtureId, changes, eventText = "") {
    const fixture = fixtureById(fixtureId);
    if (!fixture || !fixtureInfrastructureDef(fixture)) return false;
    fixture.utility = normalizeFixtureUtility({ ...fixture.utility, ...changes }, fixtureDef(fixture));
    if (eventText) addEvent(eventText);
    persist();
    render();
    return true;
  }

  function loadFixtureUtilityResource(fixtureId, resourceKey, field, capacity) {
    const fixture = fixtureById(fixtureId);
    if (!fixture) return false;
    const roomId = labMapCellRoomId(fixture.origin);
    if (!roomId || resourceAmountInRoom(resourceKey, roomId) < 1) return false;
    if ((Number(fixture.utility[field]) || 0) >= capacity) return false;
    if (removePhysicalItemQuantity("resources", resourceKey, 1, roomId) < 1) return false;
    fixture.utility[field] = Math.min(capacity, (Number(fixture.utility[field]) || 0) + 1);
    addEvent(`${fixture.name} loaded with 1 ${resourceLabel(resourceKey)}.`);
    persist();
    render();
    return true;
  }

  function emptyFixtureUtilityWaste(fixtureId, field, label, options = {}) {
    const fixture = fixtureById(fixtureId);
    if (!fixture) return false;
    const contents = field === "capturedAirborne" ? fixture.utility.capturedAirborne : fixture.utility.contents;
    const amount = field === "capturedAirborne" ? airborneLoadTotal(contents) : utilityContentsTotal(contents);
    if (amount <= TILE_ENVIRONMENT_EPSILON) return false;
    const roomId = labMapCellRoomId(fixture.origin) || PITS_ROOM_ID;
    createPhysicalWasteBatch(Math.max(1, Math.ceil(amount)), ["utility", field === "capturedAirborne" ? "filter" : "drainage", ...Object.keys(contents)], {
      roomId,
      cell: fixture.origin
    }, { phase: field === "capturedAirborne" ? "solid" : "sludge", sourceLabels: [fixture.name] });
    fixture.utility[field] = {};
    addEvent(`${fixture.name} emptied into physical ${label}; the material now requires storage or disposal.`);
    if (!options.quiet) {
      persist();
      render();
    }
    return true;
  }

  function setFixtureExactTemperature(fixtureId) {
    const fixture = fixtureById(fixtureId);
    if (!fixture || !utilityThermostatAvailable(fixture)) return false;
    const current = Number.isFinite(Number(fixture.utility.exactTargetC)) ? fixture.utility.exactTargetC : utilityClimateTargetC(fixture);
    const proposed = window.prompt("Exact target temperature (°C)", String(current));
    if (proposed === null) return false;
    const value = Number(proposed);
    if (!Number.isFinite(value)) return false;
    return updateFixtureUtility(fixture.id, { exactTargetC: clamp(value, -50, 100) }, `${fixture.name} thermostat set to ${formatDecimal(clamp(value, -50, 100), 1)} °C.`);
  }

  function fixtureUtilityNetworkSummary(fixture) {
    const networks = fixtureUtilityNetworks(fixture);
    if (!networks.length) return "Local device";
    const context = utilityNetworkContext();
    return networks.map((medium) => {
      const component = utilityComponentForFixture(fixture, medium, context);
      const metrics = component?.metrics;
      const capacity = metrics ? `${formatDecimal(metrics.demand, 1)} / ${formatDecimal(metrics.capacity, 1)} per hour` : "no capacity reading";
      const redundancy = metrics?.redundant ? `${metrics.sourceCount} sources; redundant` : `${metrics?.sourceCount || 0} source${metrics?.sourceCount === 1 ? "" : "s"}`;
      return `${titleCase(medium)}: ${component?.fixtures?.length || 1} connected; ${capacity}; ${redundancy}`;
    }).join("; ");
  }

  function fixtureUtilityFaultSummary(fixture) {
    const fault = normalizeUtilityFault(fixture?.utility?.fault);
    if (!fault) return fixture?.utility?.knownFaultId === "none" ? "No fault found at last inspection" : "No active symptoms";
    return fixture.utility.knownFaultId === fault.id
      ? `${UTILITY_FAULT_DEFS[fault.id].label}; ${titleCase(fault.severity)}; identified ${formatClock(fixture.utility.lastInspectedAt)}`
      : `Unidentified ${fault.severity} fault; inspection required`;
  }

  function fixtureUtilityMaintenanceSummary(fixture) {
    const hours = Number(fixture?.utility?.maintenanceIntervalHours) || 0;
    if (!hours) return `Manual only; ${formatDecimal(fixture.utility.serviceHours, 1)} service hours; wear index ${formatNumber(fixture.utility.wear)}`;
    const remaining = Math.max(0, hours - fixture.utility.serviceHours);
    return `${formatDecimal(fixture.utility.serviceHours, 1)} / ${hours} service hours; ${utilityMaintenanceDue(fixture) ? "due now" : `${formatDecimal(remaining, 1)} hours until due`}; wear index ${formatNumber(fixture.utility.wear)}`;
  }

  function fixtureContextCommands(fixture) {
    if (!fixture) return [];
    const def = fixtureDef(fixture);
    const access = fixtureAccessCells(fixture);
    const commands = [commandDef({
      id: `fixture.deconstruct.${fixture.id}`,
      label: "Dismantle Fixture",
      group: "Construction",
      disabledReason: fixture.typeId === "concealedExit"
        ? "The laboratory's only surface route cannot be dismantled in this pass."
        : constructionOrderAtCell(fixture.origin) ? "Construction is already designated across this fixture." : "",
      description: `${def?.assemblyClass === "siteBuilt" ? "Dismantle this site-built equipment" : "Dismantle this fixture"} into physical rubble. Heavy equipment must be reconstructed to move it.`,
      run: () => createConstructionOrder("deconstruct", [fixture.origin], { targetFixtureId: fixture.id })
    })];
    if (def?.capabilities?.includes("workbench")) {
      commands.push(commandDef({
        id: `fixture.openBills.${fixture.id}`,
        label: "Add Workstation Bill",
        group: "Production",
        description: `Open Production with a bill scoped to ${fixture.name}. Bills created here remain pinned to this workstation.`,
        run: () => {
          ensureUiState().productionMenuTab = "bills";
          setActiveWorkspaceTab("production", { scroll: true, animate: false });
          persist();
          render();
          requestAnimationFrame(() => {
            const compatibleRecipe = PRODUCTION_RECIPE_DEFS.find((recipe) => (recipe.workstationCapabilities || []).every((capability) => def.capabilities.includes(capability)));
            if (compatibleRecipe) dom.productionRecipeSelect.value = compatibleRecipe.id;
            dom.productionScopeSelect.value = "workstation";
            renderProductionBillEditor();
            dom.productionWorkstationSelect.value = fixture.id;
          });
          return true;
        }
      }));
    }
    if (isStorageFixture(fixture)) {
      const designation = stockpileForFixture(fixture);
      const canClose = !def.capabilities.includes("openStorage");
      const canLock = def.capabilities.includes("secureStorage");
      if (fixture.accessState === "open") {
        commands.push(commandDef({
          id: `fixture.storage.close.${fixture.id}`,
          label: "Close Storage",
          group: "Storage Access",
          disabledReason: canClose ? "" : "Open shelves cannot be closed.",
          description: "Close this storage fixture. Its contents remain available to authorized workers but are protected from loose creatures.",
          run: () => setStorageFixtureAccessState(fixture.id, "closed")
        }));
      } else if (fixture.accessState === "closed") {
        commands.push(commandDef({
          id: `fixture.storage.open.${fixture.id}`,
          label: "Open Storage",
          group: "Storage Access",
          description: "Open this fixture, exposing its contents to anything able to reach the interaction point.",
          run: () => setStorageFixtureAccessState(fixture.id, "open")
        }));
        commands.push(commandDef({
          id: `fixture.storage.lock.${fixture.id}`,
          label: "Lock Storage",
          group: "Storage Access",
          disabledReason: canLock ? "" : "This storage fixture has no lock.",
          description: "Lock this fixture against unauthorized actors. The scientist remains authorized.",
          run: () => setStorageFixtureAccessState(fixture.id, "locked")
        }));
      } else {
        commands.push(commandDef({
          id: `fixture.storage.unlock.${fixture.id}`,
          label: "Unlock Storage",
          group: "Storage Access",
          description: "Unlock this fixture while leaving it closed.",
          run: () => setStorageFixtureAccessState(fixture.id, "closed")
        }));
      }
      commands.push(commandDef({
        id: `fixture.storage.rename.${fixture.id}`,
        label: "Rename Stockpile",
        group: "Stockpile",
        disabledReason: designation ? "" : "This fixture is not inside a stockpile designation.",
        description: designation ? `Rename ${designation.name}, independently of its room and zone labels.` : "Place this fixture inside a stockpile designation first.",
        run: () => renameStockpileDesignation(designation?.id)
      }));
      for (const preset of STOCKPILE_FILTER_PRESETS) {
        commands.push(commandDef({
          id: `fixture.storage.filter.${fixture.id}.${preset.id}`,
          label: `Accept ${preset.label}`,
          group: "Stockpile Filters",
          disabledReason: !designation
            ? "This fixture is not inside a stockpile designation."
            : designation.filterPresetId === preset.id ? `${designation.name} already uses this filter.` : "",
          description: preset.description,
          run: () => setStockpileFilterPreset(designation?.id, preset.id)
        }));
      }
      commands.push(commandDef({
        id: `fixture.storage.priorityUp.${fixture.id}`,
        label: "Raise Stockpile Priority",
        group: "Stockpile",
        disabledReason: !designation ? "This fixture is not inside a stockpile designation." : designation.priority <= STOCKPILE_PRIORITY_MIN ? "This stockpile is already priority 1." : "",
        description: "Move this designation one step closer to priority 1. Haulers prefer lower numbers.",
        run: () => setStockpilePriority(designation?.id, designation.priority - 1)
      }));
      commands.push(commandDef({
        id: `fixture.storage.priorityDown.${fixture.id}`,
        label: "Lower Stockpile Priority",
        group: "Stockpile",
        disabledReason: !designation ? "This fixture is not inside a stockpile designation." : designation.priority >= STOCKPILE_PRIORITY_MAX ? "This stockpile is already priority 7." : "",
        description: "Move this designation one step closer to priority 7.",
        run: () => setStockpilePriority(designation?.id, designation.priority + 1)
      }));
      commands.push(commandDef({
        id: `fixture.storage.floor.${fixture.id}`,
        label: designation?.allowFloorStorage ? "Forbid Floor Storage" : "Allow Floor Storage",
        group: "Stockpile",
        disabledReason: designation ? "" : "This fixture is not inside a stockpile designation.",
        description: "Choose whether accepted items may be left directly on designated floor tiles when furniture is full or unsuitable.",
        run: () => toggleStockpileFloorStorage(designation?.id)
      }));
    }
    const infrastructure = fixtureInfrastructureDef(fixture);
    if (infrastructure) {
      if (!chemistryProcessDef(fixture)) {
        commands.push(commandDef({
          id: `fixture.utility.toggle.${fixture.id}`,
          label: fixture.utility.enabled ? "Switch Off" : "Switch On",
          group: "Infrastructure",
          description: fixture.utility.enabled ? "Disable this utility device without dismantling its physical network." : "Enable this utility device. It will operate only when its physical inputs and connections are available.",
          run: () => updateFixtureUtility(fixture.id, { enabled: !fixture.utility.enabled }, `${fixture.name} switched ${fixture.utility.enabled ? "off" : "on"}.`)
        }));
      }
      if (chemistryProcessDef(fixture)) {
        const readiness = chemistryProcessReadiness(fixture);
        const activeKind = (kind) => Boolean(activeLaborOrderForDedupeKey(`chemistry:${kind}:${fixture.id}`));
        commands.push(commandDef({
          id: `fixture.chemistry.commission.${fixture.id}`,
          label: "Commission Equipment",
          group: "Chemistry Operations",
          disabledReason: fixture.process.commissioned ? "This equipment is already commissioned." : activeKind("commissionEquipment") ? "Commissioning is already designated." : readiness.blockers.join(" "),
          description: `Run a routed inherited-equipment commissioning procedure.${readiness.warnings.length ? ` Warnings: ${readiness.warnings.join(" ")}` : ""}`,
          run: () => startChemistryProcessWork(fixture, "commissionEquipment")
        }));
        commands.push(commandDef({
          id: `fixture.chemistry.${fixture.process.online ? "shutdown" : "start"}.${fixture.id}`,
          label: fixture.process.online ? "Shut Down Equipment" : "Start Equipment",
          group: "Chemistry Operations",
          disabledReason: activeKind(fixture.process.online ? "shutdownEquipment" : "startEquipment") ? "An operating-state procedure is already designated." : !fixture.process.online && !fixture.process.commissioned ? "Commission the equipment first." : !fixture.process.online ? readiness.blockers.join(" ") : "",
          description: "Startup and shutdown are physical operator procedures; they are not instantaneous UI toggles.",
          run: () => startChemistryProcessWork(fixture, fixture.process.online ? "shutdownEquipment" : "startEquipment")
        }));
        commands.push(commandDef({
          id: `fixture.chemistry.test.${fixture.id}`,
          label: "Run Diagnostic Test Cycle",
          group: "Chemistry Operations",
          disabledReason: activeKind("testEquipment") ? "A test is already designated." : !fixture.process.online ? "Start the equipment first." : readiness.blockers.join(" "),
          description: `Produce diagnostic waste only; no saleable recipe output is implemented.${readiness.warnings.length ? ` Proceeding accepts: ${readiness.warnings.join(" ")}` : ""}`,
          run: () => startChemistryProcessWork(fixture, "testEquipment")
        }));
        commands.push(commandDef({
          id: `fixture.chemistry.calibrate.${fixture.id}`,
          label: "Calibrate Equipment",
          group: "Chemistry Care",
          disabledReason: activeKind("calibrateEquipment") ? "Calibration is already designated." : "",
          description: "Route the scientist to restore instrument calibration. Calibration drifts during test cycles.",
          run: () => startChemistryProcessWork(fixture, "calibrateEquipment")
        }));
        commands.push(commandDef({
          id: `fixture.chemistry.clean.${fixture.id}`,
          label: "Clean Equipment",
          group: "Chemistry Care",
          disabledReason: activeKind("cleanEquipment") ? "Cleaning is already designated." : "",
          description: "Clean internal surfaces and leave removed contamination as physical tagged residue for disposal.",
          run: () => startChemistryProcessWork(fixture, "cleanEquipment")
        }));
      }
      for (const priority of [2, 4, 6]) {
        const label = priority === 2 ? "High" : priority === 4 ? "Normal" : "Low";
        commands.push(commandDef({
          id: `fixture.utility.priority.${fixture.id}.${priority}`,
          label: `${label} Utility Priority`,
          group: "Infrastructure",
          disabledReason: fixture.utility.priority === priority ? `${fixture.name} already uses ${label.toLowerCase()} utility priority.` : "",
          description: "When a connected network lacks capacity, lower priority numbers receive service first. Equal-priority devices use stable fixture-ID order.",
          run: () => updateFixtureUtility(fixture.id, { priority }, `${fixture.name} utility priority set to ${label.toLowerCase()}.`)
        }));
      }
      const inspectionKey = `utility:inspectUtility:${fixture.id}`;
      const maintenanceKey = `utility:maintainUtility:${fixture.id}`;
      const repairKey = `utility:repairUtility:${fixture.id}`;
      const fault = normalizeUtilityFault(fixture.utility.fault);
      commands.push(commandDef({
        id: `fixture.utility.inspect.${fixture.id}`,
        label: "Inspect Utility Fixture",
        group: "Maintenance",
        disabledReason: activeLaborOrderForDedupeKey(inspectionKey) ? "Inspection is already designated." : "",
        description: "Create a routed inspection order. Symptoms remain visible, but the exact fault and repair procedure stay unknown until inspection completes.",
        run: () => startUtilityWorkOrder(fixture, "inspectUtility")
      }));
      commands.push(commandDef({
        id: `fixture.utility.maintain.${fixture.id}`,
        label: "Perform Preventive Maintenance",
        group: "Maintenance",
        disabledReason: activeLaborOrderForDedupeKey(maintenanceKey) ? "Maintenance is already designated." : fault ? "Repair the active fault before preventive maintenance." : "",
        description: "Create a routed maintenance order that resets the service clock, reduces wear, and modestly restores condition.",
        run: () => startUtilityWorkOrder(fixture, "maintainUtility")
      }));
      commands.push(commandDef({
        id: `fixture.utility.repairFault.${fixture.id}`,
        label: "Repair Utility Fault",
        group: "Maintenance",
        disabledReason: activeLaborOrderForDedupeKey(repairKey) ? "Fault repair is already designated." : !fault ? "No active fault is present." : fixture.utility.knownFaultId !== fault.id ? "Inspect the fixture to identify its fault first." : "",
        description: "Create a routed repair order using physical Metal Parts and seals where the network medium requires them.",
        run: () => startUtilityWorkOrder(fixture, "repairUtility")
      }));
      for (const hours of [0, ...UTILITY_MAINTENANCE_INTERVALS]) {
        const label = hours ? `${hours} Hour Service Schedule` : "Disable Service Schedule";
        commands.push(commandDef({
          id: `fixture.utility.schedule.${fixture.id}.${hours}`,
          label,
          group: "Maintenance Schedule",
          disabledReason: fixture.utility.maintenanceIntervalHours === hours ? `${fixture.name} already uses this schedule.` : "",
          description: hours ? `Automatically create an inspection, repair, or preventive-maintenance order when this fixture reaches ${hours} service hours.` : "Stop automatic utility work orders for this fixture; manual inspection and repair remain available.",
          run: () => updateFixtureUtility(fixture.id, { maintenanceIntervalHours: hours }, `${fixture.name} service schedule ${hours ? `set to ${hours} hours` : "disabled"}.`)
        }));
      }
      for (const mode of infrastructure.powerModes || []) {
        commands.push(commandDef({
          id: `fixture.utility.power.${fixture.id}.${mode}`,
          label: `Use ${UTILITY_POWER_MODE_BY_ID[mode]?.label || titleCase(mode)}`,
          group: "Power Source",
          disabledReason: fixture.utility.powerMode === mode ? `${fixture.name} already uses this power source.` : "",
          description: mode === "fuel" ? "Burn fuel stored inside this device." : mode === "electric" ? "Draw power from a physically connected electrical conduit and generator." : "Draw stored mana through a physically connected mana conduit.",
          run: () => updateFixtureUtility(fixture.id, { powerMode: mode }, `${fixture.name} switched to ${UTILITY_POWER_MODE_BY_ID[mode]?.label || titleCase(mode)}.`)
        }));
      }
      if (Number(infrastructure.fuelCapacity) > 0 || infrastructure.powerModes?.includes("fuel")) {
        const capacity = Number(infrastructure.fuelCapacity) || UTILITY_FUEL_CAPACITY;
        const roomId = labMapCellRoomId(fixture.origin);
        commands.push(commandDef({
          id: `fixture.utility.fuel.${fixture.id}`,
          label: "Load Fuel Reagent",
          group: "Power Source",
          disabledReason: fixture.utility.fuel >= capacity ? "The internal fuel store is full." : resourceAmountInRoom("fuelReagent", roomId) < 1 ? `No Fuel Reagent is physically stored in ${roomName(roomId)}.` : "",
          description: `Move one local Fuel Reagent into this device. Internal capacity ${formatDecimal(fixture.utility.fuel, 1)} / ${formatDecimal(capacity, 1)}.`,
          run: () => loadFixtureUtilityResource(fixture.id, "fuelReagent", "fuel", capacity)
        }));
      }
      if (infrastructure.role === "airTerminal") {
        for (const mode of ["exhaust", "supply", "closed"]) {
          commands.push(commandDef({
            id: `fixture.utility.air.${fixture.id}.${mode}`,
            label: `${titleCase(mode)} Airflow`,
            group: "Ventilation",
            disabledReason: fixture.utility.mode === mode ? `The terminal is already set to ${mode}.` : "",
            description: mode === "exhaust" ? "Move this tile's exact air mixture toward filters and an exterior terminal." : mode === "supply" ? "Draw exterior air into this exact tile." : "Close this terminal without dismantling its duct connection.",
            run: () => updateFixtureUtility(fixture.id, { mode }, `${fixture.name} set to ${mode} airflow.`)
          }));
        }
      }
      if (infrastructure.role === "heater") {
        for (const setting of UTILITY_CLIMATE_SETTING_DEFS) {
          commands.push(commandDef({
            id: `fixture.utility.climate.${fixture.id}.${setting.id}`,
            label: `${setting.label} Setting`,
            group: "Temperature",
            disabledReason: fixture.utility.climateSetting === setting.id && fixture.utility.exactTargetC === null ? `${fixture.name} already uses this broad setting.` : "",
            description: `Use the broad ${setting.label.toLowerCase()} target, approximately ${setting.targetC} °C.`,
            run: () => updateFixtureUtility(fixture.id, { climateSetting: setting.id, exactTargetC: null }, `${fixture.name} set to ${setting.label}.`)
          }));
        }
        commands.push(commandDef({
          id: `fixture.utility.climateExact.${fixture.id}`,
          label: "Set Exact Temperature",
          group: "Temperature",
          disabledReason: utilityThermostatAvailable(fixture) ? "" : "Install an operational thermostat in this room to set an exact Celsius target.",
          description: "Set a precise Celsius target through the room's thermostat.",
          run: () => setFixtureExactTemperature(fixture.id)
        }));
      }
      if (infrastructure.role === "manaSource") {
        for (const mode of ["rock", "feedstock"]) {
          commands.push(commandDef({
            id: `fixture.utility.manaSource.${fixture.id}.${mode}`,
            label: mode === "rock" ? "Collect from Rock" : "Consume Arcane Feedstock",
            group: "Mana",
            disabledReason: fixture.utility.mode === mode ? `The collector already uses ${mode}.` : "",
            description: mode === "rock" ? "Slowly extract mana from the exact surrounding rock reservoir." : "Convert Arcane Feedstock loaded into this collector.",
            run: () => updateFixtureUtility(fixture.id, { mode }, `${fixture.name} source changed to ${mode}.`)
          }));
        }
        const capacity = Number(infrastructure.feedstockCapacity) || UTILITY_FUEL_CAPACITY;
        const roomId = labMapCellRoomId(fixture.origin);
        commands.push(commandDef({
          id: `fixture.utility.arcaneFeedstock.${fixture.id}`,
          label: "Load Arcane Feedstock",
          group: "Mana",
          disabledReason: fixture.utility.feedstock >= capacity ? "The feedstock hopper is full." : resourceAmountInRoom("arcaneFeedstock", roomId) < 1 ? `No Arcane Feedstock is physically stored in ${roomName(roomId)}.` : "",
          description: `Load one local Arcane Feedstock. Hopper ${formatDecimal(fixture.utility.feedstock, 1)} / ${formatDecimal(capacity, 1)}.`,
          run: () => loadFixtureUtilityResource(fixture.id, "arcaneFeedstock", "feedstock", capacity)
        }));
      }
      if (infrastructure.role === "airFilter") {
        const key = `service:${fixture.id}:capturedAirborne`;
        commands.push(commandDef({
          id: `fixture.utility.emptyFilter.${fixture.id}`,
          label: "Remove Spent Filter Medium",
          group: "Maintenance",
          disabledReason: activeLaborOrderForDedupeKey(key) ? "Filter service is already designated." : airborneLoadTotal(fixture.utility.capturedAirborne) > 0 ? "" : "The filter contains no captured material.",
          description: "Create a physical service order that turns captured airborne substances into tagged waste on this tile.",
          run: () => startLaborWorkOrder({ kind: "serviceFixture", category: "servicing", label: `Service ${fixture.name}`, priority: 4, source: "manual", target: { kind: "fixture", id: fixture.id }, data: { field: "capturedAirborne", label: "spent filter waste" }, dedupeKey: key })
        }));
      }
      if (infrastructure.role === "drainSump") {
        const key = `service:${fixture.id}:contents`;
        commands.push(commandDef({
          id: `fixture.utility.emptySump.${fixture.id}`,
          label: "Pump Out Sump",
          group: "Maintenance",
          disabledReason: activeLaborOrderForDedupeKey(key) ? "Sump service is already designated." : utilityContentsTotal(fixture.utility.contents) > 0 ? "" : "The sump is empty.",
          description: "Create a physical service order that pumps the sump's exact contents into tagged sludge for later handling.",
          run: () => startLaborWorkOrder({ kind: "serviceFixture", category: "servicing", label: `Service ${fixture.name}`, priority: 4, source: "manual", target: { kind: "fixture", id: fixture.id }, data: { field: "contents", label: "sump waste" }, dedupeKey: key })
        }));
      }
    }
    commands.push(...repairLaborCommands({ kind: "fixture", value: fixture, cell: objectMapCell(fixture) }));
    commands.push(commandDef({
      id: `fixture.access.${fixture.id}`,
      label: "Show Interaction Points",
      group: "Fixture",
      disabledReason: access.length ? "" : "All interaction points are physically blocked.",
      description: access.length ? access.map((port) => `${port.label} at ${port.cell.x},${port.cell.y}`).join("; ") : "No usable interaction point remains.",
      run: () => {
        addEvent(`${fixture.name} interaction points: ${access.map((port) => `${port.label} ${port.cell.x},${port.cell.y}`).join("; ")}.`);
        persist();
        render();
        return true;
      }
    }));
    return commands;
  }

  function physicalItemStackContextCommands(selection) {
    const stack = ensurePhysicalItemStacks().find((entry) => entry.id === selection?.id);
    if (!stack) return [];
    const commands = [];
    if (stack.section === "chemicalBatches" && stack.chemicalBatch) {
      const batch = stack.chemicalBatch;
      const action = !(batch.assays || []).length && batch.stage === "finished"
        ? { recipeId: "chemistry:assayBatch", label: "Assay This Batch", description: "Reserve this exact batch for a confidence-bounded bench assay." }
        : batch.stage === "finished" && batch.packaging.state !== "packaged"
          ? { recipeId: "chemistry:packageFinished", label: "Package This Batch", description: "Reserve this exact assayed batch and one empty reagent bottle for packaging." }
          : batch.packaging.state === "packaged" && batch.documentation.status !== "certified"
            ? { recipeId: "chemistry:certifyBatch", label: "Issue Certificate of Analysis", description: "Issue an immutable truthful certificate from this exact batch's recorded assay." }
            : null;
      if (action) commands.push(commandDef({
        id: `itemStack.chemistry.${action.recipeId}.${stack.id}`,
        label: action.label,
        group: "Chemistry",
        disabledReason: stack.reservedTaskId ? "This physical batch is already reserved." : "",
        description: action.description,
        run: () => createProductionBill({ recipeId: action.recipeId, inputStackId: stack.id, scope: "global", mode: "once", createdBy: "batch command" })
      }));
    }
    if (stack.section === "inventory" && stack.key === "diagnosticSample") {
      commands.push(commandDef({
        id: `itemStack.assay.${stack.id}`,
        label: "Analyze Sample at Workbench",
        group: "Diagnostics",
        disabledReason: diagnosticSampleAssayBlockReason(stack.id),
        description: "Carry this sealed sample and one Assay Reagent to an operational research workbench. Cancellation preserves both physical inputs.",
        run: () => startDiagnosticSampleAssay(stack.id)
      }));
    }
    if (stack.form === "spill") {
      const itemKey = spillCleanupReceptacleItemKey(stack);
      const cleanupReason = spillCleanupTask(stack.id)
        ? "Cleanup is already queued for this spill."
        : stack.containerId
          ? "Interior residue requires a container-cleaning procedure."
          : availableEmptyReceptacleCount(itemKey) <= 0
            ? `No empty ${inventoryItemLabel(itemKey)} is available.`
            : staminaBlockReason(SPILL_CLEANUP_STAMINA);
      commands.push(commandDef({
        id: `itemStack.clean.${stack.id}`,
        label: "Clean Spill",
        group: "Cleanup",
        disabledReason: cleanupReason,
        description: `Queue cleanup into an empty ${inventoryItemLabel(itemKey)}. Physical residue will be contained as tagged waste; environmental contamination remains.`,
        run: () => {
          const task = startSpillCleanup(stack.id);
          persist();
          render();
          return task;
        }
      }));
    }
    const knownEvidence = evidenceHandlingRecordsForSubject("physicalStack", stack.id).some((record) => record.knowledge.state !== "unknown");
    if (knownEvidence && stack.form !== "spill") {
      for (const action of ["secure", "conceal", ...(stack.section === "chemicalBatches" ? ["relabel"] : []), "treat", "dispose", ...(stack.key === "companyRecordsPacket" ? ["destroy"] : [])]) {
        const labels = { secure: "Secure in Locked Storage", conceal: "Conceal in Opaque Locked Storage", relabel: "Apply Misleading Package Label", treat: "Treat at Waste Station", dispose: "Order Licensed Disposal", destroy: "Shred Local Records" };
        commands.push(commandDef({
          id: `itemStack.evidence.${action}.${stack.id}`,
          label: labels[action],
          group: "Evidence Handling",
          disabledReason: evidenceHandlingBlockReason(stack, action),
          description: action === "dispose"
            ? `Route this exact contained subject to the Loading Bay, pay ${formatMoney(evidenceDisposalFee(stack))}, and retain a permanent custody manifest.`
            : action === "destroy"
              ? "Route this local packet through the Packaging Station. Paper fragments and permanent missing-record evidence will remain; filed copies are unaffected."
              : "Queue physical work using the exact subject, route, equipment, custody state, and a saved qualitative risk outcome.",
          run: () => {
            const task = startEvidenceHandling(stack.id, action);
            persist(); render();
            return task;
          }
        }));
      }
    }
    if (stack.roomId !== scientistRoomId()) {
      commands.push(commandDef({
        id: `itemStack.move.${stack.id}`,
        label: "Move Scientist Here",
        group: "Movement",
        disabledReason: scientistMoveBlockReason(stack.roomId, { allowMultiRoom: true }),
        description: `Queue movement to ${roomName(stack.roomId)} to inspect these supplies.`,
        run: () => startScientistMove(stack.roomId, { allowMultiRoom: true })
      }));
    }
    if (stack.fixtureId) {
      commands.push(commandDef({
        id: `itemStack.fixture.${stack.id}`,
        label: "Focus Storage Fixture",
        group: "Storage",
        disabledReason: fixtureById(stack.fixtureId) ? "" : "The recorded storage fixture no longer exists.",
        description: "Select the shelf, crate, or cabinet holding this stack.",
        run: () => focusMapTarget({ kind: "fixture", id: stack.fixtureId }, { keepWorkspace: true, source: "map", resetInspectorTab: true, resetCommandMenu: true })
      }));
    }
    commands.push(openWorkspaceCommand({
      id: `itemStack.openStores.${stack.id}`,
      label: "Open Stores",
      group: "Open Menu",
      workspaceTab: "resources",
      tabKind: "stores",
      tabId: ["collectedByproducts", "chemicalBatches"].includes(stack.section) ? "byproducts" : stack.section === "specimenMaterials" ? "specimens" : "materials",
      description: "Open the relevant inventory ledger for this physical stack."
    }));
    return commands;
  }

  function collectionStationContextCommands(selection) {
    const info = collectionStationSelectionInfo(selection);
    if (!info?.container) {
      return [];
    }
    return [
      commandDef({
        id: `station.focusContainer.${info.container.id}`,
        label: "Focus Source Container",
        group: "Collection",
        description: "Select the container feeding this collection station.",
        run: () => focusMapTarget({ kind: "container", id: info.container.id }, { keepWorkspace: true, source: "map", resetInspectorTab: true, resetCommandMenu: true })
      }),
      commandDef({
        id: `station.transfer.${info.container.id}`,
        label: "Transfer Receptacle",
        group: "Collection",
        disabledReason: collectionBayTransferDisabledReason(info)
          || physicalStateRiskBlockReason(`transferring ${info.container.name} receptacle`)
          || staminaBlockReason(adjustedStaminaCost(RESOURCE_HAUL_STAMINA, ["materialsScience", "creatureHandling"])),
        description: "Queue a scientist task to remove the filled physical receptacle, install an empty replacement, and haul the filled vessel to an appropriate stockpile.",
        run: () => transferCollectionBayReceptacle(info.container.id)
      }),
      openWorkspaceCommand({
        id: `station.openStations.${info.container.id}`,
        label: "Open Collection Stations",
        group: "Open Menu",
        workspaceTab: "resources",
        tabKind: "stores",
        tabId: "stations",
        description: "Open Collection Bay station readouts and receptacle status."
      }),
      openWorkspaceCommand({
        id: `station.openByproducts.${info.container.id}`,
        label: "Open Collected Byproducts",
        group: "Open Menu",
        workspaceTab: "resources",
        tabKind: "stores",
        tabId: "byproducts",
        description: "Open raw collected byproduct inventory."
      })
    ];
  }

  function stockpileContextCommands(selection) {
    const focus = stockpileSelectionFocusDef(selection);
    const roomId = selection?.roomId || "";
    const storeTab = focus.type === "collectedByproducts"
      ? "byproducts"
      : focus.type === "specimenMaterials"
        ? "specimens"
        : focus.type === "inventoryCategory" && focus.key === "tools"
          ? "tools"
          : "materials";
    const commands = [
      openWorkspaceCommand({
        id: `stockpile.openRooms.${selection.id}`,
        label: "Open Room Stockpiles",
        group: "Open Menu",
        workspaceTab: "resources",
        tabKind: "stores",
        tabId: "rooms",
        description: "Open all known room-local stockpiles."
      }),
      openWorkspaceCommand({
        id: `stockpile.openFocusedStore.${selection.id}`,
        label: `Open ${focus.label}`,
        group: "Open Menu",
        workspaceTab: "resources",
        tabKind: "stores",
        tabId: storeTab,
        description: `Open the store tab for ${focus.label}.`
      }),
      commandDef({
        id: `stockpile.showOverlay.${selection.id}`,
        label: "Show This Resource Overlay",
        group: "Map",
        description: `Keep the map on the ${focus.label} resource overlay.`,
        run: () => openWorkspaceContext({ workspaceTab: "map", resourceFocusId: focus.id, keyboardMenuPath: "" })
      })
    ];
    if (roomId && roomId !== scientistRoomId()) {
      commands.unshift(commandDef({
        id: `stockpile.move.${selection.id}`,
        label: "Move Scientist Here",
        group: "Movement",
        disabledReason: scientistMoveBlockReason(roomId, { allowMultiRoom: true }),
        description: `Queue movement to ${roomName(roomId)} before working with these supplies.`,
        run: () => startScientistMove(roomId, { allowMultiRoom: true })
      }));
    }
    return commands;
  }

  function renderContextualCommands(selection) {
    const groups = orderedContextualCommandGroupsForSelection(selection);
    const commandMode = ensureUiState().mode === UI_MODE_COMMAND;
    const panel = document.createElement("div");
    panel.className = "selection-command-panel";
    panel.dataset.contextCommandPanel = "true";
    panel.dataset.commandMode = commandMode ? "true" : "false";
    const title = document.createElement("div");
    title.className = "subpanel-title";
    title.textContent = "Commands";
    panel.append(title);
    if (!groups.length) {
      panel.append(emptyText("No contextual commands for this selection yet."));
      return panel;
    }
    let commandIndex = 0;
    for (const [group, groupCommands] of groups) {
      const groupEl = document.createElement("div");
      groupEl.className = "selection-command-group";
      groupEl.append(textEl("strong", group));
      const list = document.createElement("div");
      list.className = "selection-command-list";
      for (const command of groupCommands) {
        commandIndex += 1;
        const wrap = document.createElement("div");
        wrap.className = "selection-command-entry";
        wrap.classList.toggle("command-disabled", Boolean(command.disabledReason));
        const button = document.createElement("button");
        button.type = "button";
        button.className = `context-command${command.danger ? " danger-action" : ""}`;
        button.dataset.contextCommand = command.id;
        button.dataset.contextCommandIndex = String(commandIndex);
        button.dataset.contextCommandDisabled = command.disabledReason ? "true" : "false";
        if (commandMode && commandIndex <= 9) {
          button.dataset.contextCommandShortcut = String(commandIndex);
          button.textContent = `${commandIndex}. ${command.label}`;
        } else {
          button.textContent = command.label;
        }
        setActionButtonState(button, Boolean(command.disabledReason), command.disabledReason);
        if (!command.disabledReason && command.description) {
          button.title = command.description;
        }
        button.addEventListener("click", (event) => {
          event.stopPropagation();
          runContextCommand(command);
        });
        wrap.append(button);
        if (command.disabledReason) {
          wrap.append(textEl("em", command.disabledReason));
        } else if (command.description) {
          wrap.append(textEl("em", command.description));
        }
        list.append(wrap);
      }
      groupEl.append(list);
      panel.append(groupEl);
    }
    return panel;
  }

  function orderedContextualCommandGroupsForSelection(selection) {
    const groups = new Map();
    for (const command of contextualCommandsForSelection(selection)) {
      if (!groups.has(command.group)) {
        groups.set(command.group, []);
      }
      groups.get(command.group).push(command);
    }
    return [...groups.entries()].map(([group, commands]) => [
      group,
      [
        ...commands.filter((command) => !command.disabledReason),
        ...commands.filter((command) => command.disabledReason)
      ]
    ]);
  }

  function orderedContextualCommandsForSelection(selection) {
    return orderedContextualCommandGroupsForSelection(selection)
      .flatMap(([_group, commands]) => commands);
  }

  function contextCommandMenuEl() {
    const selection = currentSelection();
    if (!selection || !contextCommandMenuOpen() || currentWorkspaceTab() !== "map") {
      return null;
    }
    const menu = document.createElement("div");
    menu.className = "context-command-menu";
    menu.dataset.contextCommandMenu = "true";
    menu.dataset.selectionKind = selection.kind;
    if (selection.id) {
      menu.dataset.selectionId = selection.id;
    }

    const header = document.createElement("div");
    header.className = "context-command-menu-header";
    const title = document.createElement("div");
    title.className = "context-command-menu-title";
    title.append(textEl("strong", `Commands: ${selectionLabel(selection)}`), chip(selectionKindLabel(selection)));
    if (ensureUiState().mode === UI_MODE_COMMAND) {
      title.append(chip("1-9 shortcuts active"));
    }
    const close = document.createElement("button");
    close.type = "button";
    close.textContent = "Close";
    close.title = "Close contextual commands.";
    close.addEventListener("click", () => closeContextCommandMenu());
    header.append(title, close);
    menu.append(header, renderContextualCommands(selection));
    return menu;
  }

  function renderContextCommandMenu() {
    document.querySelectorAll("[data-context-command-menu]").forEach((menu) => menu.remove());
    const menu = contextCommandMenuEl();
    if (menu) {
      document.querySelector(".app-shell")?.append(menu);
    }
  }

  function runContextCommand(command) {
    if (command.disabledReason) {
      addEvent(command.disabledReason);
      persist();
      render();
      return false;
    }
    const result = command.run();
    if (result !== false) {
      closeContextCommandMenu({ render: false });
      persist();
      render();
    }
    return result;
  }

  function selectionInspectorTabsEl(activeTab) {
    const tabs = document.createElement("div");
    tabs.className = "selection-inspector-tabs";
    tabs.setAttribute("role", "tablist");
    tabs.dataset.selectionInspectorTabs = "true";
    for (const tab of SELECTION_INSPECTOR_TABS) {
      const button = document.createElement("button");
      button.type = "button";
      button.className = "selection-inspector-tab";
      button.dataset.selectionInspectorTab = tab.id;
      button.setAttribute("role", "tab");
      button.setAttribute("aria-selected", tab.id === activeTab.id ? "true" : "false");
      button.classList.toggle("active-selection-inspector-tab", tab.id === activeTab.id);
      button.textContent = tab.label;
      button.addEventListener("click", () => setSelectionInspectorTab(tab.id));
      tabs.append(button);
    }
    return tabs;
  }

  function inspectorRow(label, content) {
    const row = document.createElement("div");
    row.className = "selection-inspector-row";
    row.append(textEl("span", label));
    const body = document.createElement("div");
    body.className = "selection-inspector-row-body";
    if (content instanceof Node) {
      body.append(content);
    } else if (Array.isArray(content)) {
      for (const [index, item] of content.filter(Boolean).entries()) {
        if (index > 0) {
          body.append(document.createTextNode(" "));
        }
        body.append(item instanceof Node ? item : document.createTextNode(String(item)));
      }
    } else {
      body.append(textEl("strong", String(content || "Unknown")));
    }
    row.append(body);
    return row;
  }

  function inspectorRowsEl(rows, emptyMessage = "No details available yet.") {
    const list = document.createElement("div");
    list.className = "selection-inspector-section";
    const cleanRows = rows.filter((row) => row && row[1] !== null && row[1] !== undefined && row[1] !== "");
    if (!cleanRows.length) {
      list.append(emptyText(emptyMessage));
      return list;
    }
    for (const [label, content] of cleanRows) {
      list.append(inspectorRow(label, content));
    }
    return list;
  }

  function knownTraitLabel(key) {
    return REGION_BY_KEY[key]?.label || VIRTUAL_TRAIT_DEFS[key]?.label || titleCase(key);
  }

  function slimeKnownTraitSummary(slime) {
    const known = Object.entries(slime?.revealed || {})
      .filter(([_key, value]) => Boolean(value))
      .map(([key]) => knownTraitLabel(key));
    return known.length ? known.join(", ") : "No discovered traits";
  }

  function roomObservationInspectorSummary(room) {
    if (!room) {
      return "Unknown";
    }
    if (scientistObservesRoom(room.id)) {
      const observation = makeRoomObservation(room);
      return `Current observation: ${observation.exposureBand}; contamination ${observation.contaminationBand}; reliability High`;
    }
    const observation = normalizeRoomObservation(room.observation || state.roomObservations?.[room.id]);
    if (!observation) {
      return "No observation; current conditions unknown";
    }
    const reliability = roomObservationReliabilityLabel(roomObservationReliabilityScore(room, observation));
    return `Previous observation at ${formatClock(observation.observedAt)}: ${observation.exposureBand}; contamination ${observation.contaminationBand}; reliability ${reliability}`;
  }

  function stockpileSelectionEntries(selection) {
    const roomId = selection?.roomId || "";
    if (!roomId) {
      return [];
    }
    const focus = stockpileSelectionFocusDef(selection);
    const entries = knownSupplyEntriesForRoom(roomId);
    if (focus.type === "resource") {
      return entries.filter((entry) =>
        (entry.type === "resource" && entry.key === focus.key)
        || (focus.key === "waste" && entry.type === "pitContents")
      );
    }
    if (focus.type === "inventoryCategory") {
      const wantedType = focus.key === "tools" ? "tool" : "inventory";
      return entries.filter((entry) => entry.type === wantedType);
    }
    if (focus.type === "collectedByproducts") {
      return entries.filter((entry) => entry.type === "byproduct");
    }
    if (focus.type === "specimenMaterials") {
      return entries.filter((entry) => entry.type === "specimen");
    }
    return entries;
  }

  function stockpileSelectionAmountText(selection) {
    const entries = stockpileSelectionEntries(selection);
    if (!entries.length) {
      return "None known";
    }
    return entries
      .map((entry) => `${entry.label}: ${entry.amountText}`)
      .join("; ");
  }

  function selectionSummaryRows(selection) {
    if (selection.kind === "capitalCustodyActor") { const found = capitalCustodyActorById(selection.id); if (!found) return []; return [["Capital custody staff", found.actor.name], ["Role", titleCase(found.actor.role)], ["Affiliation", found.actor.affiliation], ["Shift", titleCase(found.actor.shift)], ["Room", roomName(found.actor.roomId)], ["Current routine", found.stay.routine.currentLabel], ["Facility", found.stay.facility.label]]; }
    if (selection.kind === "prisonActor") { const found = prisonActorById(selection.id); if (!found) return []; const relationship = found.stay.relationships.find((entry) => entry.actorId === found.actor.id); return [[found.actor.role === "prisoner" ? "Prisoner" : "Staff", found.actor.name], ["Role", titleCase(found.actor.role)], ["Affiliation", found.actor.affiliation], ["Room", roomName(found.actor.roomId)], ["Routine", found.stay.routine.currentLabel], ["Relationship", relationship ? `${titleCase(relationship.band)} (${formatNumber(relationship.score)})` : "Institutional"]]; }
    if (selection.kind === "jailOfficer") {
      const found = jailActorById(selection.id);
      if (!found) return [];
      return [["Officer", found.actor.name], ["Role", titleCase(found.actor.role)], ["Shift", titleCase(found.actor.shift)], ["Room", roomName(found.actor.roomId)], ["Current routine", found.stay.routine.currentLabel], ["Facility", found.stay.facility.label]];
    }
    if (selection.kind === "raidOfficer") {
      const found = raidActorById(selection.id);
      if (!found) return [];
      return [
        ["Officer", found.actor.name], ["Role", titleCase(found.actor.role)], ["Raid", `${found.raid.docket} · ${titleCase(found.raid.status)}`],
        ["Room", roomName(found.actor.roomId)], ["Health", `${formatNumber(found.actor.health)} / 100`],
        ["Equipment", found.actor.equipment.map((entry) => titleCase(entry.label || entry.id)).join(", ")],
        ["Force posture", titleCase(found.raid.force.posture)], ["Last-known target", found.raid.communication.lastKnownCell ? `${found.raid.communication.lastKnownCell.x},${found.raid.communication.lastKnownCell.y}, Z ${found.raid.communication.lastKnownCell.z}` : "None"]
      ];
    }
    if (selection.kind === "visitor") {
      const found = siteVisitActorById(selection.id);
      const visit = found?.visit;
      const actor = found?.actor;
      if (!visit) return [];
      const warrantExecution = warrantExecutionForVisit(visit);
      const rows = [
        ["Visitor", actor?.label || visit.visitorLabel], ["Role", titleCase(actor?.role || "lead")], ["Institution", externalInstitutionLabel(visit.institutionId)],
        ["Mandate", visit.mandate], ["Phase", titleCase(visit.phase)],
        ["Current activity", siteVisitCurrentAgenda(visit)?.label || "Departing"], ["Room", roomName(actor?.roomId)],
        ["Access", `${visit.grantedRoomIds.length} rooms and ${visit.grantedFixtureIds.length} fixtures granted`],
        ["Carrying", actorInventoryContentsLabel(actor?.id)]
      ];
      if (warrantExecution) rows.push(
        ["Warrant", `${warrantExecution.docket} · ${warrantExecution.scope.label}`],
        ["Authorized rooms", warrantExecution.scope.authorizedRoomIds.map(roomName).join(", ")],
        ["Authorized subjects", warrantExecution.scope.subjectCategories.map(titleCase).join(", ")],
        ["Seizures", warrantExecution.seizures.map((seizure) => `${seizure.label} (${titleCase(seizure.status)})`).join("; ") || "None"]
      );
      if (warrantExecution?.forcedEntry) rows.push(
        ["Forced entry", titleCase(warrantExecution.forcedEntry.status)],
        ["Team", siteVisitActors(visit).map((entry) => `${entry.label} (${titleCase(entry.role)})`).join("; ")],
        ["Barriers", warrantExecution.forcedEntry.barriers.map((entry) => `${entry.label}: ${titleCase(entry.status)}, ${formatNumber(entry.damageApplied)} damage`).join("; ") || "None encountered"],
        ["Expanded scope", warrantExecution.forcedEntry.expansions.map((entry) => entry.label).join("; ") || "None"]
      );
      return rows;
    }
    const rows = [
      ["Type", selectionKindLabel(selection)],
      ["Location", selectionLocationLabel(selection)]
    ];
    if (selection?.source) {
      rows.push(["Selected by", titleCase(selection.source)]);
    }
    if (selection.kind === "scientist") {
      rows.push(["Inventory", actorInventoryContentsLabel("scientist")]);
      rows.push(["Equipment", equipmentSummary("scientist")]);
      rows.push(["Burden", `${actorEncumbranceInfo("scientist").label} (${Math.round(actorEncumbranceInfo("scientist").ratio * 100)}%)`]);
      rows.push(["Equipment contamination", equipmentContaminationSummary("scientist")]);
      rows.push(["Condition", actorIsIncapacitated("scientist") ? "Incapacitated" : actorInjuries("scientist").length ? "Injured" : "Able-bodied"]);
      rows.push(["Injuries", injurySummary("scientist", { internal: true })]);
    } else if (selection.kind === "room") {
      const room = roomById(selection.roomId);
      const evaluation = roomPurposeEvaluation(room);
      const readiness = roomExpansionReadiness(room);
      rows.push(["Purpose", evaluation.purpose.label]);
      rows.push(["Function", evaluation.status.label]);
      rows.push(["Expansion", readiness.status]);
      rows.push(["Readiness", readiness.stages.map((stage) => `${stage.met ? "✓" : "○"} ${stage.label}`).join(" · ")]);
      rows.push(["Occupancy", roomOccupancySummary(room.id)]);
      rows.push(["Observation", roomObservationInspectorSummary(room)]);
    } else if (selection.kind === "door") {
      const door = labMapDoor(selection.key);
      const stateDoor = door ? doorForConnection(door.roomIds[0], door.roomIds[1]) || door : null;
      if (door) {
        rows.push(["Connects", door.roomIds.map(roomName).join(" / ")]);
        rows.push(["State", doorStateLabel(door.roomIds[0], door.roomIds[1])]);
        rows.push(["Condition", doorConditionLabel(stateDoor)]);
      }
    } else if (selection.kind === "container") {
      const container = containerById(selection.id);
      if (container) {
        if (isSynthesisTubeContainer(container)) {
          rows.push(["Tube state", synthesisTubeStatusText()]);
          rows.push(["Current task", synthesisTubeTaskSummary()]);
        } else {
          rows.push(["Access", containerAccessLabel(container)]);
          rows.push(["Contents", `${containerOccupants(container.id).length} living; ${containerCorpses(container.id).length} corpse${containerCorpses(container.id).length === 1 ? "" : "s"}`]);
        }
      }
    } else if (selection.kind === "fixture") {
      const fixture = fixtureById(selection.id);
      const def = fixtureDef(fixture);
      if (fixture && def) {
        rows.push(["State", titleCase(fixture.operationalState)]);
        rows.push(["Assembly", titleCase(def.assemblyClass.replace(/([A-Z])/g, " $1"))]);
        rows.push(["Access", `${fixtureAccessCells(fixture).length} / ${fixturePortCells(fixture).length} interaction points usable`]);
        if (fixtureInfrastructureDef(fixture)) {
          rows.push(["Utility", `${titleCase(fixture.utility.status || "idle")}${fixture.utility.statusReason ? `: ${fixture.utility.statusReason}` : ""}`]);
          rows.push(["Reliability", fixtureUtilityFaultSummary(fixture)]);
        }
        if (chemistryProcessDef(fixture) && fixture.process) {
          const readiness = chemistryProcessReadiness(fixture);
          rows.push(["Chemistry state", `${fixture.process.commissioned ? "Commissioned" : "Uncommissioned"}; ${fixture.process.online ? "online" : "shut down"}`]);
          rows.push(["Calibration", `${formatNumber(fixture.process.calibrated)}%`]);
          rows.push(["Cleanliness", `${formatNumber(fixture.process.cleanliness)}%`]);
          rows.push(["Service readiness", readiness.operational ? readiness.warnings.length ? `Degraded: ${readiness.warnings.join(" ")}` : "All hard services available" : `Blocked: ${readiness.blockers.join(" ")}`]);
          rows.push(["Test history", `${fixture.process.cycleCount} cycle${fixture.process.cycleCount === 1 ? "" : "s"}; ${fixture.process.lastResult}`]);
        }
        if (isStorageFixture(fixture)) {
          rows.push(["Storage", titleCase(fixture.accessState)]);
          rows.push(["Known contents", storageFixtureContentsLabel(fixture)]);
          rows.push(["Capacity", storageFixtureCapacityLabel(fixture)]);
        }
      }
    } else if (selection.kind === "itemStack") {
      const stack = ensurePhysicalItemStacks().find((entry) => entry.id === selection.id);
      if (stack) {
        rows.push(["Known amount", `${physicalStackQuantityText(stack)} ${physicalStackLabel(stack)}`]);
        rows.push(["Form", titleCase(stack.form || "stack")]);
        if (stack.contents?.length) rows.push(["Contents", physicalStackContentsLabel(stack)]);
        if (stack.chemicalBatch) {
          const batch = stack.chemicalBatch;
          const assay = batch.assays.at(-1);
          rows.push(["Batch ID", batch.id]);
          rows.push(["Recipe", `${productionRecipe(batch.recipeId)?.label || batch.recipeId || "Unknown"} revision ${batch.recipeVersion}`]);
          rows.push(["Quality", `${assay?.purityBand || "Purity not assayed"}; ${craftsmanshipBand(batch.craftsmanship).label} craftsmanship`]);
          rows.push(["Hazards", batch.hazards.join(", ") || "None recorded"]);
          rows.push(["Contaminants", Object.keys(batch.contaminants).join(", ") || "None recorded"]);
          rows.push(["Provenance", `${batch.lineage.length} direct input${batch.lineage.length === 1 ? "" : "s"}; ${batch.ancestorBatchIds.length} ancestor batch${batch.ancestorBatchIds.length === 1 ? "" : "es"}; ${batch.sourceSlimeIds.length} source specimen${batch.sourceSlimeIds.length === 1 ? "" : "s"}`]);
          rows.push(["Packaging", batch.packaging.state === "packaged" ? `Sealed in ${inventoryItemLabel(batch.packaging.containerKey)}` : "Bulk"]);
          rows.push(["Documentation", batch.documentation.status === "certified" ? `Certificate ${batch.documentation.certificateId}` : "No certificate"]);
          rows.push(["Classification", batch.classification.known === "unclassified"
            ? "Unclassified; actual handling category awaits a completed assay"
            : CHEMICAL_CLASSIFICATION_DEFS[batch.classification.known].label]);
        }
        rows.push(["Knowledge", physicalStackKnowledgeLabel(stack)]);
        rows.push(["Storage", physicalStackStorageLabel(stack)]);
      }
    } else if (selection.kind === "slime") {
      const slime = findSlime(selection.id);
      if (slime) {
        rows.push(["State", slimeStateLabel(slime)]);
        rows.push(["Activity", slimeActivityLabel(slime).replace(/^Activity:\s*/i, "")]);
        rows.push(["Inventory", actorInventoryContentsLabel(slime.id)]);
        rows.push(["Condition", actorIsIncapacitated(slime) ? "Incapacitated" : injurySummary(slime)]);
      }
    } else if (selection.kind === "corpse") {
      const corpse = findCorpse(selection.id);
      if (corpse) {
        rows.push(["State", corpseStateLabel(corpse)]);
        rows.push(["Decay", corpseDecayText(corpse)]);
      }
    } else if (selection.kind === "incident") {
      const incident = incidentById(selection.id);
      if (incident) {
        if (incident.type === "containmentEmergency") rows.push(["Stage", incident.emergencyStage ? containmentEmergencyStageLabel(incident.emergencyStage) : "Unconfirmed"]);
        rows.push(["Severity", incidentSeverityLabel(incident.severity)]);
        rows.push(["Status", incidentStatusLabel(incident.status)]);
        rows.push(["Summary", incident.summary || incident.label]);
      }
    } else if (selection.kind === "task") {
      const task = findTask(selection.id);
      if (task) {
        const status = taskStatusInfo(task);
        rows.push(["Task", taskCategory(task)]);
        rows.push(["Status", status.reason ? `${status.label}: ${status.reason}` : status.label]);
        rows.push(["Due", formatClock(task.dueAt)]);
        rows.push(["Route", taskPathSummary(task)]);
      }
    } else if (selection.kind === "collectionStation") {
      const info = collectionStationSelectionInfo(selection);
      if (info) {
        rows.push(["Status", info.status]);
        rows.push(["Output", info.material || "Unresolved"]);
        rows.push(["Receptacle", info.station ? `${formatCollectionAmount(info.station.receptacle.amount)} / ${formatCollectionAmount(info.station.receptacle.capacity)} ${info.station.receptacle.label}` : "No receptacle configured"]);
      }
    } else if (selection.kind === "stockpile") {
      const focus = stockpileSelectionFocusDef(selection);
      rows.push(["Focus", focus.label]);
      rows.push(["Known supplies", stockpileSelectionAmountText(selection)]);
    }
    return rows;
  }

  function selectionDetailsRows(selection) {
    if (selection.kind === "scientist") {
      const vitals = state.scientist?.vitals || {};
      const pending = state.combat?.pendingActions?.scientist;
      const carriedLight = normalizeScientistCarriedLight(state.scientist?.carriedLight);
      return [
        ["Room", roomName(scientistRoomId())],
        ["Health", `${formatNumber(vitals.health?.current || 0)} / ${formatNumber(vitals.health?.max || DEFAULT_VITAL_MAX)}`],
        ["Stamina", `${formatNumber(vitals.stamina?.current || 0)} / ${formatNumber(vitals.stamina?.max || DEFAULT_VITAL_MAX)}`],
        ["Mana", `${formatNumber(vitals.mana?.current || 0)} / ${formatNumber(vitals.mana?.max || DEFAULT_VITAL_MAX)}`],
        ["Inventory", actorInventoryContentsLabel("scientist")],
        ["Equipment", equipmentSummary("scientist")],
        ["Encumbrance", `${actorEncumbranceInfo("scientist").label}; movement ×${formatDecimal(actorEncumbranceInfo("scientist").speedMultiplier, 2)}; +${actorEncumbranceInfo("scientist").staminaModifier} STA when burdened`],
        ["Equipment contamination", equipmentContaminationSummary("scientist")],
        ["Injuries", injurySummary("scientist", { internal: true })],
        ["Carried light", `${carriedLight.label}; ${carriedLight.enabled && carriedLight.condition > 0 ? `on, warm, ${carriedLight.radius} m nominal radius` : "off or damaged"}`],
        ["Combat action", pending ? `${combatActionDef(pending.actionId)?.label || pending.actionId}; releases ${formatClock(pending.releaseAt)}` : scientistGuarding() ? "Guarding" : "None"],
        ["Routine work", state.combat?.routineSuspension ? `Suspended: ${state.combat.routineSuspension.reason}` : "Available"]
      ];
    }
    if (selection.kind === "tile") {
      const roomId = selection.roomId || labMapCellRoomId(selection.tile);
      const door = labMapDoorAtCell(selection.tile);
      const excavated = labMapCellIsExcavated(selection.tile);
      const surfaceGround = surfaceGroundAtCell(selection.tile);
      const envelope = surfaceEnvelopeAtCell(selection.tile);
      const constructedWall = constructedWallAtCell(selection.tile);
      const constructedFloor = constructedFloorAtCell(selection.tile);
      const structuralTarget = structuralTargetAtCell(selection.tile);
      const structuralComposition = structuralTarget ? structuralTargetComposition(structuralTarget) : null;
      const structuralCondition = structuralTarget ? structuralTargetCondition(structuralTarget) : null;
      const compartment = inferredCompartmentAtCell(selection.tile);
      const order = constructionOrderAtCell(selection.tile);
      const orderTile = constructionOrderTile(order, selection.tile);
      const productionBill = productionBillForOrder(order);
      const key = mapCellKey(selection.tile);
      const surfaceDescription = constructedWall
        ? `${resourceLabel(constructedWall.materialId)} constructed wall; ${formatNumber(constructedWall.condition)}% condition`
        : constructedFloor
          ? `${resourceLabel(constructedFloor.materialId)} constructed floor; ${formatNumber(constructedFloor.condition)}% condition`
          : (ensureLabMap().terrain?.smoothedFloors || []).some((cell) => mapCellKey(cell) === key)
        ? "Smoothed floor"
        : (ensureLabMap().terrain?.smoothedWalls || []).some((cell) => mapCellKey(cell) === key)
          ? "Smoothed natural wall"
          : surfaceGround ? `${titleCase(surfaceGround.terrainId)} ground; ${titleCase(envelope.kind)}` : excavated ? "Rough floor" : "Natural rock";
      const geologyFace = !excavated && !surfaceGround && !constructedFloor ? Geology.faceKnowledge(Geology.profileForCell(state.seed, selection.tile)) : null;
      const rows = [
        ["Coordinates", `${selection.tile.x},${selection.tile.y}`],
        ["Room", roomId ? roomName(roomId) : surfaceGround ? "Outdoor site" : excavated ? "Unassigned floor" : "Solid earth"],
        ["Inferred compartment", compartment ? `${compartment.kind}; ${compartment.status}; ${compartment.cells.length} tiles` : "None"],
        ["Door", door ? `${door.roomIds.map(roomName).join(" / ")} door` : "None"],
        ["Surface", surfaceDescription],
        ["Envelope", titleCase(envelope.kind)],
        ["Material", structuralComposition ? materialCompositionLabel(structuralComposition) : surfaceGround ? titleCase(surfaceGround.terrainId) : excavated ? "Excavated ground" : geologyFace?.label || MATERIAL_BY_ID[naturalWallMaterialId(selection.tile)]?.label || "Common Stone"],
        ["Material properties", structuralComposition ? materialPropertySummary(structuralComposition) : geologyFace ? `Hardness: ${geologyFace.hardnessBand}; Stability: ${geologyFace.stabilityBand}; Permeability: ${geologyFace.permeabilityBand}; Mana response: ${geologyFace.manaResponseBand}` : "No constructed material profile"],
        ["Damage resistance", structuralComposition ? damageResistanceSummary(damageResistanceEntriesForComposition(structuralComposition, structuralCondition), "none") : "None"],
        ["Structural state", structuralTarget ? structureConditionBand(structuralCondition) : "Not a damageable structure"],
        ["Attack channel", wallAllowsAttackTransmission(selection.tile) ? "Attacks and directed abilities may pass; movement remains blocked" : "Blocked"],
        ["Construction order", order ? `${constructionModeLabel(order.mode)}; priority ${order.priority}; ${titleCase(orderTile.status)}${orderTile.blockedReason ? `; ${orderTile.blockedReason}` : ""}` : "None"],
        ["Production dependency", productionBill ? `${fixtureDef(productionBill.fixtureTypeId)?.label || "Fixture"}; ${titleCase(productionBill.status)}${productionBill.blockedReason ? `; ${productionBill.blockedReason}` : ""}` : "None"],
        ["Work progress", orderTile?.workRequiredSeconds ? `${formatDuration(orderTile.workCompletedSeconds)} / ${formatDuration(orderTile.workRequiredSeconds)}` : order ? "Not started" : "None"],
        ["Last interruption", orderTile?.lastInterruptionReason || "None"],
        ["Loose rubble", rubbleAtCell(selection.tile).length ? rubbleAtCell(selection.tile).flatMap((pile) => pile.materials).map((material) => `${formatNumber(material.amount)} ${material.label}`).join(", ") : "None"],
        ["Walkability", labMapCellIsWalkable(selection.tile) ? "Walkable if not blocked" : labMapCellHasFloor(selection.tile) ? "Blocked by structure" : "Solid"]
      ];
      const environment = tileEnvironmentAtCell(selection.tile);
      const environmentKnown = Boolean(environment && (mapDebugOverlayActive() || (roomId && scientistObservesRoom(roomId))));
      if (environmentKnown) {
        const debug = mapDebugOverlayActive();
        const attributes = tileEnvironmentAttributes(environment, roomById(roomId)?.attributes);
        for (const attributeKey of ["temperature", "light", "humidity", "ambientMana", "contamination"]) {
          const value = attributes[attributeKey].current;
          const band = roomAttributeBand(attributeKey, value);
          rows.push([ROOM_ATTRIBUTE_BY_KEY[attributeKey].label, debug ? `${roomAttributeMeasurementText(attributeKey, value, { debug: true })}; ${band.label}` : band.label]);
        }
        if (debug) {
          rows.push(["Airborne substances", Object.entries(environment.airborne || {}).length
            ? Object.entries(environment.airborne).map(([id, concentration]) => `${airborneSubstanceLabel(id)}: ${formatDecimal(concentration, 2)}`).join("; ")
            : "None"]);
        }
      } else if (environment) {
        rows.push(["Environment", "Not currently observed"]);
      }
      return rows;
    }
    if (selection.kind === "room") {
      const room = roomById(selection.roomId);
      const geometry = roomGeometry(room);
      const evaluation = roomPurposeEvaluation(room);
      const suggestion = roomPurposeInference(room);
      const rows = [
        ["Name", room.name],
        ["Primary purpose", evaluation.purpose.label],
        ["Functional state", evaluation.status.label],
        ["Requirements", roomFunctionalIssueSummary(evaluation)],
        ["Zones", roomZonesSummary(room)],
        ["Designation", `${titleCase(room.designationSource || "manual")}${room.designationDisconnected ? "; disconnected" : ""}`],
        ["Purpose source", titleCase(room.purposeSource || "manual")],
        ["Purpose rationale", room.purposeReason || (roomPurposeId(room) === "unassigned" ? "No primary purpose selected" : "Assigned directly")],
        ["Suggested purpose", suggestion && suggestion.purposeId !== roomPurposeId(room) ? `${ROOM_PURPOSE_BY_ID[suggestion.purposeId].label}: ${suggestion.reasons.join(" and ")}` : "None"],
        ["Shape", titleCase(geometry.shape)],
        ["Size", `${formatDecimal(geometry.lengthM, 1)}m x ${formatDecimal(geometry.widthM, 1)}m x ${formatDecimal(geometry.heightM, 1)}m`],
        ["Spatial feel", roomSpatialFeel(room)],
        ["Crowding", roomCrowdingLabel(room)],
        ["Connections", roomConnectionsLabel(room).replace(/^Connected to:\s*/i, "")],
        ["Observation", roomObservationInspectorSummary(room)]
      ];
      const observed = scientistObservesRoom(room.id);
      if (observed || mapDebugOverlayActive()) {
        for (const attributeKey of ["temperature", "light", "humidity", "ambientMana", "contamination"]) {
          const value = room.attributes[attributeKey].current;
          const band = roomAttributeBand(attributeKey, value);
          rows.push([ROOM_ATTRIBUTE_BY_KEY[attributeKey].label, mapDebugOverlayActive() ? `${roomAttributeMeasurementText(attributeKey, value, { debug: true })}; ${band.label}` : band.label]);
        }
      }
      return rows;
    }
    if (selection.kind === "door") {
      const door = labMapDoor(selection.key);
      const stateDoor = door ? doorFixtureState(door) || door : null;
      if (!door || !stateDoor) {
        return [];
      }
      return [
        ["Type", doorTypeLabel(stateDoor.typeId)],
        ["Connects", door.roomIds.map(roomName).join(" / ")],
        ["State", doorStateLabelByFixture(door)],
        ["Materials", materialCompositionLabel(doorMaterialComposition(stateDoor))],
        ["Material properties", materialPropertySummary(doorMaterialComposition(stateDoor))],
        ["Damage resistance", damageResistanceSummary(damageResistanceEntriesForComposition(doorMaterialComposition(stateDoor), doorCondition(stateDoor)), "none")],
        ["Lock", titleCase(stateDoor.lockState || "unlocked")],
        ["Seal", titleCase(stateDoor.sealState || "unsealed")],
        ["Condition", doorConditionLabel(stateDoor)],
        ["Wards", doorWardLabels(stateDoor.wardIds).join(", ") || "None"]
      ];
    }
    if (selection.kind === "container") {
      const container = containerById(selection.id);
      if (!container) {
        return [];
      }
      const footprint = containerFootprintDimensions(container);
      if (isSynthesisTubeContainer(container)) {
        const resourceCosts = synthesisResourceCosts();
        const resourceRoomId = synthesisResourceRoomId();
        const occupants = containerOccupants(container.id);
        const corpses = containerCorpses(container.id);
        return [
          ["Type", "Synthesis Tube"],
          ["Room", roomName(container.roomId)],
          ["State", synthesisTubeStatusText()],
          ["Occupant", occupants.map((slime) => slime.name).join(", ") || "None"],
          ["Blocked remains", corpses.map((corpse) => `${corpse.name} remains`).join(", ") || "None"],
          ["Current task", synthesisTubeTaskSummary()],
          ["Requirements", `${formatResourceBundle(resourceCosts)}, ${formatNumber(synthesisStaminaCost())} STA, ${formatDuration(synthesisDurationSeconds())}`],
          ["Biomass locality", resourceLocalitySummary(resourceCosts, resourceRoomId)],
          ["Condition", containerConditionLabel(container)],
          ["Footprint", `${footprint.width} x ${footprint.height} tile${footprint.width * footprint.height === 1 ? "" : "s"}`]
        ];
      }
      return [
        ["Type", containerTypeLabel(container.typeId)],
        ["Materials", materialCompositionLabel(containerMaterialComposition(container))],
        ["Material properties", materialPropertySummary(containerMaterialComposition(container))],
        ["Damage resistance", damageResistanceSummary(damageResistanceEntriesForContainer(container), "none")],
        ["Room", roomName(container.roomId)],
        ["Access", containerAccessLabel(container)],
        ["Breach", containerBreachStateLabel(container)],
        ["Condition", containerConditionLabel(container)],
        ["Footprint", `${footprint.width} x ${footprint.height} tile${footprint.width * footprint.height === 1 ? "" : "s"}`],
        ["Wards", containerWardLabels(container.wardIds).join(", ") || "None"],
        ...(isPitHoleContainer(container) ? [["Default role", creatureRoleLabel(containerDefaultRoleId(container))]] : []),
        ["Contents", `${containerOccupants(container.id).length} living; ${containerCorpses(container.id).length} corpse${containerCorpses(container.id).length === 1 ? "" : "s"}`]
      ];
    }
    if (selection.kind === "fixture") {
      const fixture = fixtureById(selection.id);
      const def = fixtureDef(fixture);
      if (!fixture || !def) return [];
      const footprint = fixtureRotatedFootprint(def, fixture.rotation);
      const ports = fixturePortCells(fixture);
      const usablePorts = fixtureAccessCells(fixture);
      const roomId = labMapCellRoomId(fixture.origin);
      const rows = [
        ["Type", def.label],
        ["Room", roomId ? roomName(roomId) : "Unassigned floor"],
        ["State", titleCase(fixture.operationalState)],
        ["Assembly", titleCase(def.assemblyClass.replace(/([A-Z])/g, " $1"))],
        ["Footprint", `${footprint.width} x ${footprint.height} tiles; ${fixture.rotation} degrees`],
        ["Materials", materialCompositionLabel(fixture.materialComposition)],
        ["Condition", `${formatNumber(fixture.condition)}%`],
        ["Capabilities", def.capabilities.map(titleCase).join(", ") || "None"],
        ["Interaction points", ports.map((port) => `${port.label} ${port.cell.x},${port.cell.y}`).join("; ") || "None"],
        ["Accessible points", `${usablePorts.length} / ${ports.length}`],
        ["Wards", containerWardLabels(fixture.wardIds).join(", ") || "None"]
      ];
      const infrastructure = fixtureInfrastructureDef(fixture);
      if (infrastructure) {
        rows.push(
          ["Utility state", `${fixture.utility.enabled ? "Enabled" : "Disabled"}; ${titleCase(fixture.utility.status || "idle")}${fixture.utility.statusReason ? `; ${fixture.utility.statusReason}` : ""}`],
          ["Physical networks", fixtureUtilityNetworkSummary(fixture)],
          ["Utility priority", `${fixture.utility.priority} (1 is highest)`],
          ["Inspection", fixtureUtilityFaultSummary(fixture)],
          ["Maintenance", fixtureUtilityMaintenanceSummary(fixture)]
        );
        if (infrastructure.powerModes?.length) rows.push(["Power source", UTILITY_POWER_MODE_BY_ID[fixture.utility.powerMode]?.label || "Unavailable"]);
        if (Number(infrastructure.fuelCapacity) > 0 || infrastructure.powerModes?.includes("fuel")) rows.push(["Internal fuel", `${formatDecimal(fixture.utility.fuel, 1)} / ${formatDecimal(Number(infrastructure.fuelCapacity) || UTILITY_FUEL_CAPACITY, 1)} Fuel Reagent`]);
        if (infrastructure.role === "heater") rows.push(["Temperature target", utilityThermostatAvailable(fixture) && fixture.utility.exactTargetC !== null ? `${formatDecimal(fixture.utility.exactTargetC, 1)} °C (thermostat)` : `${titleCase(fixture.utility.climateSetting)} broad setting`]);
        if (infrastructure.role === "airTerminal") rows.push(["Airflow mode", titleCase(fixture.utility.mode)]);
        if (infrastructure.role === "airFilter") rows.push(["Filter load", `${formatDecimal(airborneLoadTotal(fixture.utility.capturedAirborne), 1)} / ${formatDecimal(Number(infrastructure.capacity) || UTILITY_FILTER_CAPACITY, 1)}; ${Object.keys(fixture.utility.capturedAirborne).map(airborneSubstanceLabel).join(", ") || "empty"}`]);
        if (infrastructure.role === "drainSump") rows.push(["Sump contents", `${formatDecimal(utilityContentsTotal(fixture.utility.contents), 1)} / ${formatDecimal(Number(infrastructure.capacity) || UTILITY_SUMP_CAPACITY, 1)}; ${Object.keys(fixture.utility.contents).map(airborneSubstanceLabel).join(", ") || "empty"}`]);
        if (infrastructure.role === "manaSource") rows.push(["Mana storage", `${formatDecimal(fixture.utility.storedMana, 1)} / ${formatDecimal(Number(infrastructure.capacity) || UTILITY_MANA_CAPACITY, 1)} thaums; source ${titleCase(fixture.utility.mode)}`]);
        if (infrastructure.role === "manaEmitter") rows.push(["Mana target", `${formatDecimal(fixture.utility.manaTarget, 1)} thaums/m³`]);
        if (["airExterior", "drainExterior"].includes(infrastructure.role)) rows.push(["Exterior discharge", `${formatDecimal(fixture.utility.dischargedLoad, 1)} total load; ${fixture.utility.exposureChecks} exposure checks`]);
      }
      if (isStorageFixture(fixture)) {
        const storageDef = storageFixtureDef(fixture).storage;
        const designation = stockpileForFixture(fixture);
        rows.push(
          ["Storage access", titleCase(fixture.accessState)],
          ["Security", storageDef.security ? `Rating ${storageDef.security}; ${physicalStacksInFixture(fixture.id).some(physicalStackExposed) ? "contents exposed" : "contents protected"}` : "Open storage; contents exposed"],
          ["Capacity used", storageFixtureCapacityLabel(fixture)],
          ["Known contents", storageFixtureContentsLabel(fixture)],
          ["Stockpile", designation?.name || "No designation"],
          ["Accepted category", designation ? STOCKPILE_FILTER_PRESET_BY_ID[designation.filterPresetId].label : "None"],
          ["Stockpile priority", designation ? `${designation.priority} (1 is highest)` : "None"],
          ["Floor storage", designation ? designation.allowFloorStorage ? "Allowed" : "Forbidden" : "No designation"]
        );
      }
      return rows;
    }
    if (selection.kind === "itemStack") {
      const stack = ensurePhysicalItemStacks().find((entry) => entry.id === selection.id);
      if (!stack) return [];
      const fixture = stack.fixtureId ? fixtureById(stack.fixtureId) : null;
      const designation = stack.stockpileId ? ensureStockpileDesignations().find((entry) => entry.id === stack.stockpileId) : stockpileDesignationAtCell(stack.cell);
      return [
        ["Item", physicalStackLabel(stack)],
        ["Form", titleCase(stack.form || "stack")],
        ["Known amount", physicalStackQuantityText(stack)],
        ["Contents", physicalStackContentsLabel(stack)],
        ["Tags", normalizeResidueTags(stack.tags).join(", ") || "None"],
        ["Knowledge", physicalStackKnowledgeLabel(stack)],
        ["Physical volume", `${formatDecimal(stack.knownQuantity * stack.unitVolumeL, 1)} L`],
        ["Physical mass", `${formatDecimal(stack.knownQuantity * stack.unitMassKg, 1)} kg`],
        ["Storage fixture", physicalStackStorageLabel(stack)],
        ["Access", stack.carriedBy ? "Controlled by carrier" : fixture ? titleCase(fixture.accessState) : "Exposed"],
        ["Protection", stack.carriedBy ? "Carried inventory" : physicalStackExposed(stack) ? "Exposed to loose creatures" : "Protected by closed storage"],
        ["Stockpile", designation?.name || "Not in a valid stockpile"],
        ["Stored correctly", physicalStackStoredCorrectly(stack) ? "Yes" : "No; automatic hauling will seek a valid destination"]
      ];
    }
    if (selection.kind === "slime") {
      const slime = findSlime(selection.id);
      if (!slime) {
        return [];
      }
      return [
        ["State", slimeStateLabel(slime)],
        ["Location", slimeLocationLabel(slime)],
        ["Role", creatureRoleLabel(slimeRoleId(slime))],
        ["Role source", roleSourceLabel(slime)],
        ["Activity", slimeActivityLabel(slime).replace(/^Activity:\s*/i, "")],
        ["Inventory", actorInventoryContentsLabel(slime.id)],
        ["Known injuries", injurySummary(slime)],
        ["Known traits", slimeKnownTraitSummary(slime)],
        ["Automation", slime.automationExcluded ? "Excluded from global automation" : "Follows global automation"]
      ];
    }
    if (selection.kind === "corpse") {
      const corpse = findCorpse(selection.id);
      if (!corpse) {
        return [];
      }
      return [
        ["State", corpseStateLabel(corpse)],
        ["Location", corpseLocationLabel(corpse)],
        ["Decay", corpseDecayText(corpse)],
        ["Harvesting", corpse.harvestBlocked || corpse.ruined ? "Ruined or blocked" : "Potentially harvestable"],
        ["Necropsy", corpse.necropsied || corpse.forensicReport ? "Performed" : "Not performed"]
      ];
    }
    if (selection.kind === "incident") {
      const incident = incidentById(selection.id);
      if (!incident) {
        return [];
      }
      const response = incidentResponseTask(incident);
      const rows = [
        ["Type", incidentTypeLabel(incident.type)],
        ["Severity", incidentSeverityLabel(incident.severity)],
        ["Status", incidentStatusLabel(incident.status)],
        ["Room", roomName(incident.roomId)],
        ["Summary", incident.summary || incident.label],
        ["Response", response ? `${response.label}; due ${formatClock(response.dueAt)}` : "No response queued"]
      ];
      if (incident.type === "containmentEmergency") {
        const exactEmergency = ["exact", "exact-source"].includes(incident.perceptionPrecision);
        const emergency = exactEmergency ? containmentEmergencyById(incident.emergencyId) : null;
        rows.splice(1, 0,
          ["Stage", incident.emergencyStage ? containmentEmergencyStageLabel(incident.emergencyStage) : "Unconfirmed"],
          ["Detection", `${titleCase(incident.perceptionChannel)}; ${titleCase(incident.perceptionPrecision)}`],
          ["Known creatures", incident.emergencyCreatureIds.map(findSlime).filter(Boolean).map((slime) => slime.name).join(", ") || "No exact identities confirmed"],
          ["Affected rooms", emergency ? containmentEmergencyAffectedRoomIds(emergency).map(roomName).join(", ") : "Unconfirmed"],
          ["Recovery requirements", incident.emergencyRequirements.join("; ") || "None remaining"],
          ["Response policy", CONTAINMENT_EMERGENCY_POLICY_BY_ID[containmentEmergencyPolicyMode()].label],
          ["Lockdown", ensureAccessControl().lockdownActive ? "Emergency restrictions active; configured door work is physical" : "Inactive"],
          ["Active response orders", emergency ? formatNumber(containmentEmergencyActiveOrders(emergency).length) : "Unknown"]
        );
      }
      return rows;
    }
    if (selection.kind === "task") {
      const task = findTask(selection.id);
      if (!task) {
        return [];
      }
      const status = taskStatusInfo(task);
      const rows = [
        ["Type", task.type],
        ["Category", taskCategory(task)],
        ["Status", status.label],
        ["Blocked reason", status.reason || "None"],
        ["Worker", "Scientist"],
        ["Route", taskPathSummary(task)],
        ["Target", selectionLocationLabel(selection)],
        ["Stamina spent", task.data?.staminaCost ? formatNumber(task.data.staminaCost) : "None recorded"],
        ["Created", formatClock(task.createdAt || state.clock)],
        ["Due", formatClock(task.dueAt)],
        ["Remaining", formatDuration(Math.max(0, task.dueAt - state.clock))]
      ];
      if (task.type === "constructionWork") {
        const order = constructionOrderById(task.data?.constructionOrderId);
        const tile = constructionOrderTile(order, task.data?.constructionTileKey || task.data?.targetCell);
        const geology = constructionGeologyProfiles(order, tile).map(Geology.faceKnowledge).filter(Boolean);
        rows.push(
          ["Tools", (task.data?.toolSelections || []).map((selection) => `${inventoryItemLabel(selection.itemKey)} (${damageResistanceBand(selection.score)})`).join(", ") || "None"],
          ["Geology", geology.length ? [...new Set(geology.map((entry) => `${entry.label}; ${entry.hardnessBand}; ${entry.stabilityBand}`))].join(" / ") : "Not natural-rock excavation"],
          ["Work progress", tile ? `${formatDuration(tile.workCompletedSeconds)} / ${formatDuration(tile.workRequiredSeconds)}` : "Unknown"],
          ["Work rate", `${formatDecimal((Number(task.data?.workRate) || 1) * 100, 0)}%`]
        );
      }
      return rows;
    }
    if (selection.kind === "collectionStation") {
      const info = collectionStationSelectionInfo(selection);
      if (!info) {
        return [];
      }
      return [
        ["Container", info.container?.name || "Unknown container"],
        ["Room", roomName(info.container?.roomId)],
        ["Status", info.status],
        ["Output", info.material || "Unresolved"],
        ["Rate", info.outputLabel],
        ["Method", info.method?.label || "Unclear"],
        ["Support", info.support?.label || "Unclear"],
        ["Receptacle", info.station ? `${formatCollectionAmount(info.station.receptacle.amount)} / ${formatCollectionAmount(info.station.receptacle.capacity)} ${info.station.receptacle.label}` : "No receptacle configured"],
        ["Overflow", info.station ? `${formatCollectionAmount(info.station.overflow.amount)} / ${formatCollectionAmount(info.station.overflow.capacity)} apparatus buffer` : "No overflow buffer configured"],
        ["Sources", info.sourceMaterials?.length ? info.sourceMaterials.join(", ") : "None"],
        ["Specimens", info.occupants?.length ? info.occupants.map((slime) => slime.name).join(", ") : "No active specimen"]
      ];
    }
    if (selection.kind === "stockpile") {
      const focus = stockpileSelectionFocusDef(selection);
      const entries = stockpileSelectionEntries(selection);
      return [
        ["Room", roomName(selection.roomId)],
        ["Focus", focus.label],
        ["Known supplies", entries.length ? entries.map((entry) => `${entry.label}: ${entry.amountText}`).join("; ") : "None known"],
        ["Source", entries.length ? [...new Set(entries.map((entry) => entry.source || "Known inventory"))].join("; ") : "Last inventoried stockpile"],
        ["Inventory state", "Prototype values update exactly; future interference may make this stale"]
      ];
    }
    return [];
  }

  function selectionHistoryRows(selection) {
    if (selection.kind === "raidOfficer") {
      const raid = raidActorById(selection.id)?.raid;
      return raid ? raid.history.slice(-10).reverse().map((entry) => [formatClock(entry.at), entry.summary]) : [];
    }
    if (selection.kind === "visitor") {
      const visit = siteVisitActorById(selection.id)?.visit;
      const warrantExecution = warrantExecutionForVisit(visit);
      const rows = visit ? [
        ["Arrived", formatClock(visit.startedAt)], ["Route observations", String(visit.routeHistory.length)],
        ["Confirmed findings", String(visit.findings.length)], ["Obstructions", String(visit.obstructionIds.length)]
      ] : [];
      if (warrantExecution) rows.push(
        ["Custody events", String(warrantExecution.seizures.reduce((total, seizure) => total + seizure.custody.length, 0))],
        ["Warrant return", warrantExecution.warrantReturn?.summary || "Not yet filed"]
      );
      if (warrantExecution?.forcedEntry) rows.push(
        ["Barrier work", `${warrantExecution.forcedEntry.barriers.length} specifically authorized barrier record(s)`],
        ["Supplemental return", warrantExecution.forcedEntry.supplementalReturn?.summary || "Not yet filed"]
      );
      return rows;
    }
    if (selection.kind === "room") {
      const room = roomById(selection.roomId);
      const observation = normalizeRoomObservation(room?.observation || state.roomObservations?.[room?.id]);
      return observation ? [
        ["Last observation", formatClock(observation.observedAt)],
        ["Exposure then", observation.exposureBand],
        ["Known factors", observation.knownFactors?.join(", ") || "None recorded"],
        ["Uncertain factors", observation.unknownFactors?.join(", ") || "Current conditions may have changed"]
      ] : [["Observation", "No observation recorded"]];
    }
    if (selection.kind === "container") {
      const container = containerById(selection.id);
      const summary = containerBreachSummary(container);
      return summary ? [["Last breach", summary]] : [["History", "No notable container history recorded"]];
    }
    if (selection.kind === "slime") {
      const slime = findSlime(selection.id);
      if (!slime) return [];
      return [
        ["Created", formatClock(slime.createdAt || 0)],
        ["Maturity", slime.mature ? "Mature" : `Matures in ${formatDuration(slime.matureAt - state.clock)}`],
        ["Expected death", formatClock(slime.deathAt || state.clock)],
        ["Tests run", `${(slime.testsRun || []).length}`]
      ];
    }
    if (selection.kind === "corpse") {
      const corpse = findCorpse(selection.id);
      if (!corpse) return [];
      return [
        ["Died", formatClock(corpse.diedAt || state.clock)],
        ["Fresh until", formatClock(corpse.freshUntil || state.clock)],
        ["Spoiled at", formatClock(corpse.spoiledAt || state.clock)],
        ["Evidence", corpse.forensicReport ? "Forensic report recorded" : "No forensic report"]
      ];
    }
    if (selection.kind === "incident") {
      const incident = incidentById(selection.id);
      if (!incident) return [];
      const rows = [
        ["Created", formatClock(incident.createdAt || state.clock)],
        ["Updated", formatClock(incident.updatedAt || incident.createdAt || state.clock)],
        ["Stale since", incident.staleAt !== null && incident.staleAt !== undefined ? formatClock(incident.staleAt) : "No"],
        ["Acknowledged", incident.acknowledgedAt !== null && incident.acknowledgedAt !== undefined ? formatClock(incident.acknowledgedAt) : "No"],
        ["Response reached", incident.responseArrivedAt !== null && incident.responseArrivedAt !== undefined ? formatClock(incident.responseArrivedAt) : "No"],
        ["Resolved", incident.resolvedAt !== null && incident.resolvedAt !== undefined ? formatClock(incident.resolvedAt) : "No"],
        ["Manual clear", incident.manualResolvedAt !== null && incident.manualResolvedAt !== undefined ? formatClock(incident.manualResolvedAt) : "No"],
        ["Urgency handled", incident.urgencyHandledAt !== null && incident.urgencyHandledAt !== undefined ? formatClock(incident.urgencyHandledAt) : "No"]
      ];
      const emergency = incident.type === "containmentEmergency" && ["exact", "exact-source"].includes(incident.perceptionPrecision)
        ? containmentEmergencyById(incident.emergencyId)
        : null;
      if (emergency) rows.push(["Stage history", emergency.history.map((entry) => `${containmentEmergencyStageLabel(entry.stage)} ${formatClock(entry.at)}`).join(" · ")]);
      return rows;
    }
    if (selection.kind === "task") {
      const task = findTask(selection.id);
      return task ? [
        ["Created", formatClock(task.createdAt || state.clock)],
        ["Due", formatClock(task.dueAt)],
        ["Remaining", formatDuration(Math.max(0, task.dueAt - state.clock))]
      ] : [];
    }
    return [["History", "No notable history recorded"]];
  }

  function selectionRelatedPanelEl(selection) {
    const panel = document.createElement("div");
    panel.className = "selection-inspector-section";
    const relatedTargets = selectionRelatedTargets(selection);
    const relatedKeys = new Set(
      relatedTargets
        .map((target) => normalizeSelection({ ...target, source: "inspector" }))
        .filter(Boolean)
        .map(selectionKey)
    );
    const related = selectionLinkRow("Related", relatedTargets);
    if (related) {
      panel.append(related);
    }
    const cell = selectionMapCell(selection);
    const stack = cell
      ? selectableTargetsAtCell(cell).filter((target) => selectionKey(target) !== selectionKey(selection) && !relatedKeys.has(selectionKey(target)))
      : [];
    const alsoHere = selectionLinkRow("Also here", stack);
    if (alsoHere) {
      panel.append(alsoHere);
    }
    if (!panel.childElementCount) {
      panel.append(emptyText("No related selections visible from here."));
    }
    return panel;
  }

  function selectionKnownSuppliesPanelEl(selection) {
    const roomId = selectionRoomId(selection);
    if (!roomId || !["room", "tile", "stockpile"].includes(selection?.kind)) {
      return null;
    }
    const entries = selection?.kind === "stockpile"
      ? stockpileSelectionEntries(selection)
      : knownSupplyEntriesForRoom(roomId);
    const panel = document.createElement("div");
    panel.className = "selection-inspector-section selection-known-supplies";
    panel.dataset.selectionKnownSupplies = roomId;
    const title = document.createElement("div");
    title.className = "subpanel-title";
    title.textContent = "Known Supplies";
    title.title = "Last inventoried physical supplies known in this room. Prototype values update exactly for now; future interference can make this stale.";
    panel.append(title);
    panel.append(emptyText(`Last inventoried: ${formatClock(state.clock)}. Storage capacity is unlimited for now.`));
    if (!entries.length) {
      panel.append(emptyText("No known supplies or pit contents in this room."));
      return panel;
    }
    const list = document.createElement("div");
    list.className = "inventory-list compact-inventory-list";
    for (const entry of entries.slice(0, 10)) {
      const row = document.createElement("div");
      row.className = "inventory-row";
      row.dataset.stockpileType = entry.type;
      row.title = `${entry.source || "Known supply"} - ${entry.label}`;
      row.append(textEl("span", entry.label), textEl("strong", entry.amountText));
      list.append(row);
    }
    if (entries.length > 10) {
      const note = document.createElement("p");
      note.className = "journal-meta inventory-note";
      note.textContent = `${entries.length - 10} additional known supplies hidden.`;
      list.append(note);
    }
    panel.append(list);
    return panel;
  }

  function containerResidueSummary(container) {
    const entries = feedingResiduesForLocation({ type: "container", containerId: container?.id });
    if (!entries.length) {
      return "None";
    }
    return entries
      .map((residue) => `${feedingResidueLabel(residue.typeKey)} ${feedingResidueUnitText(residue.amount)}`)
      .join("; ");
  }

  function collectionStationInspectorSummary(container) {
    if (!container || container.type === "synthesis") {
      return "";
    }
    const info = collectionBayStationInfo(container);
    if (!info.station && container.roomId !== COLLECTION_BAY_ROOM_ID) {
      return "";
    }
    const station = info.station;
    const material = info.material || station?.material || "no assigned material";
    if (!station) {
      return `${info.status}; ${material}`;
    }
    return [
      `${info.status}; ${material}`,
      `receptacle ${formatCollectionAmount(station.receptacle?.amount || 0)} / ${formatCollectionAmount(station.receptacle?.capacity || 0)}`,
      `overflow ${formatCollectionAmount(station.overflow?.amount || 0)} / ${formatCollectionAmount(station.overflow?.capacity || 0)}`
    ].join("; ");
  }

  function containerOccupantRiskSummary(container) {
    const occupants = containerOccupants(container?.id);
    if (!occupants.length) {
      return "No living specimens";
    }
    return occupants.map((slime) => {
      const physicalFit = physicalContainerFitPrediction(slime, container);
      const compatibility = containerCompatibilityAssessment(slime, container, { knownOnly: true });
      const risk = activeContainmentRisk(slime, container);
      const riskPrediction = activeContainmentRiskPrediction(risk, slime, container);
      return `${slime.name}: physical ${predictionRangeText(physicalFit.range)}, compatibility ${predictionRangeText(compatibility.range)}, active risk ${predictionRangeText(riskPrediction.range)}`;
    }).join("; ");
  }

  function selectionContainerContextPanelEl(selection) {
    if (!selection || !["container", "slime", "corpse"].includes(selection.kind)) {
      return null;
    }
    let container = null;
    let titleText = "Container Context";
    const rows = [];
    if (selection.kind === "container") {
      container = containerById(selection.id);
      titleText = "Interior";
    } else if (selection.kind === "slime") {
      const slime = findSlime(selection.id);
      container = slime?.containerId ? containerById(slime.containerId) : null;
      if (!container) {
        return null;
      }
      rows.push(["Container", selectionLink({ kind: "container", id: container.id })]);
      rows.push(["Container state", `${containerAccessLabel(container)}; ${containerBreachStateLabel(container)}; condition ${containerConditionLabel(container)}`]);
      rows.push(["Physical fit", predictionRangeText(physicalContainerFitPrediction(slime, container).range)]);
      rows.push(["Compatibility", predictionRangeText(containerCompatibilityAssessment(slime, container, { knownOnly: true }).range)]);
      rows.push(["Active risk", predictionRangeText(activeContainmentRiskPrediction(activeContainmentRisk(slime, container), slime, container).range)]);
    } else if (selection.kind === "corpse") {
      const corpse = findCorpse(selection.id);
      container = corpse?.containerId ? containerById(corpse.containerId) : null;
      if (!container) {
        return null;
      }
      rows.push(["Container", selectionLink({ kind: "container", id: container.id })]);
      rows.push(["Container state", `${containerAccessLabel(container)}; ${containerBreachStateLabel(container)}; condition ${containerConditionLabel(container)}`]);
    }
    if (!container) {
      return null;
    }
    const occupants = containerOccupants(container.id);
    const corpses = containerCorpses(container.id);
    if (selection.kind === "container") {
      rows.push(["Living", occupants.length ? occupants.map((slime) => selectionLink({ kind: "slime", id: slime.id })) : "None"]);
      rows.push(["Remains", corpses.length ? corpses.map((corpse) => selectionLink({ kind: "corpse", id: corpse.id })) : "None"]);
      rows.push(["Containment", containerOccupantRiskSummary(container)]);
    } else {
      const otherOccupants = occupants.filter((slime) => selection.kind !== "slime" || slime.id !== selection.id);
      const otherCorpses = corpses.filter((corpse) => selection.kind !== "corpse" || corpse.id !== selection.id);
      if (otherOccupants.length || otherCorpses.length) {
        rows.push(["Also inside", [
          ...otherOccupants.map((slime) => selectionLink({ kind: "slime", id: slime.id })),
          ...otherCorpses.map((corpse) => selectionLink({ kind: "corpse", id: corpse.id }))
        ]]);
      }
    }
    rows.push(["Interior residue", containerResidueSummary(container)]);
    if (isPitHoleContainer(container)) {
      rows.push(["Pit contents", `${formatNumber(containerWasteAmount(container))} Waste; ${pitHoleCorpseCount(container)}/${pitHoleCorpseCapacity(container)} corpse capacity used`]);
    }
    const stationSummary = collectionStationInspectorSummary(container);
    if (stationSummary) {
      rows.push(["Collection station", stationSummary]);
    }
    const panel = inspectorRowsEl(rows);
    panel.classList.add("selection-container-context");
    panel.dataset.selectionContainerContext = container.id;
    const title = document.createElement("div");
    title.className = "subpanel-title";
    title.textContent = titleText;
    panel.prepend(title);
    return panel;
  }

  function combatIncidentContextPanelEl(selection) {
    if (!selection || selection.kind !== "incident") {
      return null;
    }
    const incident = incidentById(selection.id);
    if (!incident || incident.type !== "combat") {
      return null;
    }
    const record = combatRecordForIncident(incident);
    const participants = combatRecordParticipantTargets(record);
    const responseTask = incidentResponseTask(incident);
    const rows = [
      ["State", `${incidentStatusLabel(incident.status)}; ${incidentSeverityLabel(incident.severity)}`],
      ["Awareness", record
        ? (scientistAwareOfCombat(record) ? "Currently known to the scientist" : "Known record; not currently observed")
        : (incident.status === "stale" ? "Last-known combat; current state unknown" : "Combat incident record; active combat no longer confirmed")],
      ["Last known tile", `${roomName(incident.roomId)}; cell ${incident.cell?.x ?? "?"},${incident.cell?.y ?? "?"}`],
      ["Detected by", `${titleCase(incident.perceptionChannel || "vision")}; ${incident.perceptionPrecision || "exact"}${incident.uncertaintyRadius ? `; about ${incident.uncertaintyRadius} m uncertainty` : ""}`],
      ["Summary", incident.summary || incident.label],
      ["Participants", participants.length
        ? participants.map((target) => selectionLink(target))
        : (record ? "No known participants" : (incident.sourceLabel || "Unknown combatants"))],
      ["Combat type", record ? `${titleCase(record.type)}${record.combatIntent && record.combatIntent !== "none" ? `; ${SLIME_COMBAT_INTENT_LABELS[record.combatIntent] || titleCase(record.combatIntent)}` : ""}` : "Last-known only"],
      ["Contact", record?.cell ? `${record.cell.x},${record.cell.y}` : "No current contact record"],
      ["Response", responseTask ? `${responseTask.label}; due ${formatClock(responseTask.dueAt)}` : "No response queued"]
    ];
    const panel = inspectorRowsEl(rows);
    panel.classList.add("selection-combat-context");
    panel.dataset.selectionCombatContext = incident.id;
    const title = document.createElement("div");
    title.className = "subpanel-title";
    title.textContent = "Combat Situation";
    panel.prepend(title);
    return panel;
  }

  function selectionInspectorTabPanelEl(selection, activeTab) {
    const panel = document.createElement("div");
    panel.className = "selection-inspector-panel";
    panel.dataset.selectionInspectorPanel = activeTab.id;
    panel.setAttribute("role", "tabpanel");
    if (activeTab.id === "summary") {
      panel.append(inspectorRowsEl(selectionSummaryRows(selection)));
      const combat = combatIncidentContextPanelEl(selection);
      if (combat) panel.append(combat);
      const context = selectionContainerContextPanelEl(selection);
      if (context) panel.append(context);
      const supplies = selectionKnownSuppliesPanelEl(selection);
      if (supplies) panel.append(supplies);
    } else if (activeTab.id === "details") {
      panel.append(inspectorRowsEl(selectionDetailsRows(selection), "No detailed readout for this selection yet."));
      const combat = combatIncidentContextPanelEl(selection);
      if (combat) panel.append(combat);
      const context = selectionContainerContextPanelEl(selection);
      if (context) panel.append(context);
      const supplies = selectionKnownSuppliesPanelEl(selection);
      if (supplies) panel.append(supplies);
    } else if (activeTab.id === "related") {
      panel.append(selectionRelatedPanelEl(selection));
    } else if (activeTab.id === "history") {
      panel.append(inspectorRowsEl(selectionHistoryRows(selection), "No history recorded for this selection yet."));
    }
    return panel;
  }

  function selectionCompactRows(selection) {
    return selectionSummaryRows(selection)
      .filter(([label]) => !["Type", "Selected by"].includes(label))
      .slice(0, 4);
  }

  function selectionInspectorMapCell(selection) {
    const clickedCell = cleanMapCell(canvasMapLastSelectionCell);
    const scene = activeCanvasMapSurface?.mapView?.scene;
    const selectedKey = selectionKey(selection);
    if (currentMapRendererMode() === MAP_RENDERER_CANVAS
      && selection?.source === "map"
      && clickedCell
      && MapRenderOrder.targetsAtCell(scene, clickedCell)
        .some((target) => selectionKey(target) === selectedKey)) {
      return clickedCell;
    }
    return selectionMapCell(selection);
  }

  function selectionCompactAlsoHereEl(selection) {
    const cell = selectionInspectorMapCell(selection);
    if (!cell) {
      return null;
    }
    const currentKey = selectionKey(selection);
    const seen = new Set([currentKey]);
    const targets = [
      ...selectableTargetsAtCell(cell),
      ...selectionRelatedTargets(selection)
    ]
      .map((target) => normalizeSelection({ ...target, source: "inspector" }))
      .filter(Boolean)
      .filter((target) => {
        const key = selectionKey(target);
        if (!key || seen.has(key)) {
          return false;
        }
        seen.add(key);
        return true;
      });
    if (!targets.length) {
      return null;
    }
    const row = document.createElement("div");
    row.className = "selection-compact-related";
    row.dataset.selectionCompactRelated = "true";
    row.append(textEl("span", "Also here"));
    const links = document.createElement("div");
    links.className = "selection-link-list";
    for (const [index, target] of targets.entries()) {
      const link = selectionLink(target);
      if (link) {
        link.dataset.selectionAlsoHereKey = selectionKey(target);
        link.dataset.selectionAlsoHereOrder = String(index);
        links.append(link);
      }
    }
    if (!links.childElementCount) {
      return null;
    }
    row.append(links);
    return row;
  }

  function selectionInspectorCompactControlsEl(selection, expanded) {
    const controls = document.createElement("div");
    controls.className = "selection-inspector-controls";
    if (expanded || !selection) {
      return controls;
    }
    const detailTabs = [
      ["details", "Details"],
      ["actions", "Actions"],
      ["related", "Related"],
      ["history", "History"]
    ];
    for (const [tabId, label] of detailTabs) {
      const button = document.createElement("button");
      button.type = "button";
      button.dataset.selectionInspectorTab = tabId;
      button.textContent = label;
      if (tabId === "actions") {
        button.dataset.commandMenuTrigger = "true";
        button.addEventListener("click", () => openContextCommandMenu({ commandMode: false, selectCursor: false }));
      } else {
        button.addEventListener("click", () => openSelectionInspectorTab(tabId));
      }
      controls.append(button);
    }
    return controls;
  }

  function selectionInspectorExpandedEl(selection) {
    const activeTab = currentSelectionInspectorTab();
    const expanded = document.createElement("div");
    expanded.className = "selection-inspector-expanded";
    expanded.dataset.selectionInspectorExpandedPanel = "true";
    expanded.append(selectionInspectorExpandedHeaderEl(selection));
    expanded.append(selectionInspectorTabsEl(activeTab));
    expanded.append(selectionInspectorTabPanelEl(selection, activeTab));
    return expanded;
  }

  function selectionInspectorExpandedHeaderEl(selection) {
    const header = document.createElement("div");
    header.className = "selection-inspector-expanded-header";
    const title = document.createElement("div");
    title.className = "selection-inspector-expanded-title";
    title.append(textEl("strong", selectionLabel(selection)), chip(selectionKindLabel(selection)));
    const controls = document.createElement("div");
    controls.className = "selection-inspector-window-controls";
    const actions = document.createElement("button");
    actions.type = "button";
    actions.dataset.selectionInspectorTab = "actions";
    actions.dataset.commandMenuTrigger = "true";
    actions.textContent = "Actions";
    actions.title = "Open contextual commands for this selection.";
    actions.addEventListener("click", () => openContextCommandMenu({ commandMode: false, selectCursor: false }));
    const collapse = document.createElement("button");
    collapse.type = "button";
    collapse.textContent = "Collapse";
    collapse.title = "Return to the compact map inspector.";
    collapse.addEventListener("click", () => setSelectionInspectorExpanded(false));
    const close = document.createElement("button");
    close.type = "button";
    close.textContent = "Close";
    close.title = "Clear the current map selection.";
    close.addEventListener("click", () => {
      setSelection(null);
      persist();
      render();
    });
    controls.append(actions, collapse, close);
    header.append(title, controls);
    return header;
  }

  function selectionInspectorEl() {
    const panel = document.createElement("div");
    panel.className = "selection-inspector selection-inspector-compact";
    panel.dataset.selectionInspector = "true";

    const selection = currentSelection();
    const expanded = selectionInspectorExpanded();
    panel.dataset.selectionInspectorExpanded = String(expanded && Boolean(selection));
    if (!selection) {
      const title = document.createElement("div");
      title.className = "subpanel-title";
      title.textContent = "Selection";
      panel.append(title);
      panel.append(emptyText("No selection. Click a map tile, room, door, container, specimen, corpse, incident, or task to inspect it."));
      return panel;
    }

    panel.dataset.selectionKind = selection.kind;
    if (selection.id) {
      panel.dataset.selectionId = selection.id;
    }

    const heading = document.createElement("div");
    heading.className = "selection-inspector-heading";
    const title = document.createElement("div");
    title.className = "selection-inspector-title";
    title.append(textEl("strong", selectionLabel(selection)), chip(selectionKindLabel(selection)));
    const close = document.createElement("button");
    close.type = "button";
    close.className = "selection-inspector-close";
    close.textContent = "Close";
    close.title = "Clear the current map selection.";
    close.addEventListener("click", () => {
      setSelection(null);
      persist();
      render();
    });
    heading.append(title, close);
    panel.append(heading);

    const meta = document.createElement("div");
    meta.className = "selection-inspector-meta";
    meta.append(...selectionStatusChips(selection));
    panel.append(meta);

    const activeTab = currentSelectionInspectorTab();
    panel.dataset.selectionInspectorActiveTab = activeTab.id;
    panel.append(inspectorRowsEl(selectionCompactRows(selection), "No compact readout for this selection yet."));
    const alsoHere = selectionCompactAlsoHereEl(selection);
    if (alsoHere) {
      panel.append(alsoHere);
    }
    panel.append(selectionInspectorCompactControlsEl(selection, expanded));
    if (expanded) {
      panel.append(selectionInspectorExpandedEl(selection));
    }

    return panel;
  }

  function mapTileClickTarget({ roomId, door, objectEntry, incidentEntry, overlayEntry, plannedEntry, scientistHere, cell }) {
    const incidents = incidentEntry?.alerts || [];
    if (incidents.length) {
      const incident = [...incidents].sort((a, b) => incidentSeverityRank(b.severity) - incidentSeverityRank(a.severity) || a.createdAt - b.createdAt)[0];
      return { kind: "incident", id: incident.id };
    }
    if (scientistHere) {
      return { kind: "scientist" };
    }
    const targets = objectEntry?.targets || [];
    const synthesisTubeTarget = targets.find((candidate) => candidate.kind === "container" && candidate.id === SYNTHESIS_TUBE_ID);
    if (synthesisTubeTarget) {
      return synthesisTubeTarget;
    }
    const collectionStationTarget = targets.find((candidate) => candidate.kind === "collectionStation");
    if (collectionStationTarget) {
      return collectionStationTarget;
    }
    const hazardousSpill = targets.find((candidate) => {
      if (candidate.kind !== "itemStack") return false;
      const stack = ensurePhysicalItemStacks().find((entry) => entry.id === candidate.id);
      return stack?.form === "spill" && spillIsHazardous(stack);
    });
    if (hazardousSpill) return hazardousSpill;
    const priority = ["slime", "corpse", "container"];
    for (const kind of priority) {
      const target = targets.find((candidate) => candidate.kind === kind);
      if (target) {
        return target;
      }
    }
    if (door) {
      return { kind: "door", key: door.key, roomIds: door.roomIds };
    }
    for (const kind of ["fixture", "itemStack"]) {
      const target = targets.find((candidate) => candidate.kind === kind);
      if (target) {
        return target;
      }
    }
    if (overlayEntry?.target) {
      return overlayEntry.target;
    }
    if (plannedEntry?.task?.id) {
      return { kind: "task", id: plannedEntry.task.id };
    }
    if (roomId) {
      return { kind: "room", roomId };
    }
    return cell ? { kind: "tile", tile: cell } : null;
  }

  function mapTileInteractionTargets(context) {
    const primary = mapTileClickTarget(context);
    const incidents = [...(context.incidentEntry?.alerts || [])]
      .sort((a, b) => incidentSeverityRank(b.severity) - incidentSeverityRank(a.severity) || a.createdAt - b.createdAt)
      .map((incident) => ({ kind: "incident", id: incident.id }));
    return [
      primary,
      ...incidents,
      context.scientistHere ? { kind: "scientist" } : null,
      ...(context.objectEntry?.targets || []),
      context.door ? { kind: "door", key: context.door.key, roomIds: context.door.roomIds } : null,
      context.overlayEntry?.target || null,
      context.plannedEntry?.task?.id ? { kind: "task", id: context.plannedEntry.task.id } : null,
      context.roomId ? { kind: "room", roomId: context.roomId } : null,
      context.cell ? { kind: "tile", tile: context.cell } : null
    ].filter(Boolean);
  }

  function labMapAnchorAssignments(map) {
    const anchors = new Map();
    for (const room of Object.values(map.rooms || {})) {
      if (room?.anchor) {
        anchors.set(mapCellKey(room.anchor), room);
      }
    }
    return anchors;
  }

  function mapFullRevealActive() {
    return debugToolsEnabled();
  }

  function labMapBlueprintCellKeys(map) {
    const keys = new Set();
    const addKnown = (cell) => {
      if (mapCellInBounds(cell, map)) {
        keys.add(mapCellKey(cell));
      }
    };
    const addKnownWithWalls = (cell) => {
      addKnown(cell);
      for (let dy = -1; dy <= 1; dy += 1) {
        for (let dx = -1; dx <= 1; dx += 1) {
          addKnown(mapCellAtOffset(cell, dx, dy));
        }
      }
    };
    for (const roomId of Object.keys(map.rooms || {})) {
      for (const cell of labMapRoomCells(roomId, map)) {
        addKnownWithWalls(cell);
      }
    }
    for (const door of Object.values(map.doors || {})) {
      for (const cell of labMapDoorCells(door)) addKnownWithWalls(cell);
    }
    for (const entry of map.terrain?.constructedWalls || []) addKnownWithWalls(entry.cell);
    for (const entry of map.terrain?.constructedFloors || []) {
      if (entry.purpose === "roof") addKnown(entry.cell);
    }
    for (const connector of map.terrain?.verticalConnectors || []) {
      addKnownWithWalls(connector.lowerCell);
      addKnownWithWalls(connector.upperCell);
    }
    for (const [key] of plannedExcavationAssignments()) {
      const [x, y, z] = key.split(",").map((part) => Number(part));
      addKnownWithWalls({ x, y, z });
    }
    for (const [key] of draftExcavationAssignments()) {
      const [x, y, z] = key.split(",").map((part) => Number(part));
      addKnownWithWalls({ x, y, z });
    }
    return keys;
  }

  let scientistMapPerceptionCache = { signature: "", keys: new Set() };

  function perceptionLightLevelAtCell(candidate, map = ensureLabMap(), options = {}) {
    const cell = cleanMapCell(candidate);
    if (!cell) return 0;
    if (options.ensureLighting !== false) ensurePhysicalLightingCurrent(map);
    const environments = options.environments || ensureTileEnvironments(map);
    const direct = constructedWallAtCell(cell, map) ? null : environments[mapCellKey(cell)] || null;
    if (direct) return Number(direct.lightLevel) || 0;
    return Math.max(0, ...cardinalMapCells(cell)
      .map((neighbor) => (Number(environments[mapCellKey(neighbor)]?.lightLevel) || 0) * 0.85));
  }

  function scientistExactPerceptionAtCell(candidate, options = {}) {
    if (scientistIsDead()) return null;
    const cell = cleanMapCell(candidate);
    const origin = cleanMapCell(options.origin) || scientistMapCell();
    if (!cell || !origin || cell.z !== origin.z) return null;
    const sensory = options.sensory || normalizeSensoryState(state.scientist.sensory, "scientist");
    const distance = mapCellDistance(origin, cell);
    const lightLevel = perceptionLightLevelAtCell(cell, options.map || ensureLabMap(), {
      ensureLighting: options.lightingCurrent !== true,
      environments: options.environments
    });
    if (distance <= 1 && sensory.capabilities.contact) {
      return { channel: "contact", distance, lightLevel, lightBand: MapKnowledge.lightVisibilityBand(lightLevel).id };
    }
    if (!sensory.capabilities.vision || distance > MapKnowledge.visualRangeForLight(lightLevel)
      || !sensoryLineOfSight(origin, cell)) return null;
    return {
      channel: "vision",
      distance,
      lightLevel,
      lightBand: MapKnowledge.lightVisibilityBand(lightLevel).id
    };
  }

  function scientistPerceivesMapCell(candidate) {
    if (scientistIsDead()) return false;
    const cell = cleanMapCell(candidate);
    const origin = scientistMapCell();
    if (!cell || !origin || cell.z !== origin.z) return false;
    state.scientist.sensory = normalizeSensoryState(state.scientist.sensory, "scientist");
    const sensory = state.scientist.sensory;
    return Boolean(scientistExactPerceptionAtCell(cell, { sensory, origin }));
  }

  function scientistPerceivedMapCellKeys(map = ensureLabMap()) {
    if (scientistIsDead()) return new Set();
    state.scientist.sensory = normalizeSensoryState(state.scientist.sensory, "scientist");
    const sensory = state.scientist.sensory;
    const origin = scientistMapCell();
    if (!origin) return new Set();
    ensurePhysicalLightingCurrent(map);
    const environments = ensureTileEnvironments(map);
    const signature = [
      state.seed,
      mapCellKey(origin),
      map.width,
      map.height,
      Number(state.navigation?.topologyRevision) || 0,
      Number(state.navigation?.doorRevision) || 0,
      physicalLightingSignature,
      sensory.capabilities.vision ? "vision" : "contact"
    ].join(":");
    if (scientistMapPerceptionCache.signature === signature) {
      return scientistMapPerceptionCache.keys;
    }
    const keys = MapKnowledge.perceivedCellKeys({
      origin,
      width: map.width,
      height: map.height,
      radius: sensory.capabilities.vision
        ? Math.max(...MapKnowledge.LIGHT_VISIBILITY_BANDS.map((band) => band.range))
        : 1,
      distance: mapCellDistance,
      canSee: (from, to) => Boolean(scientistExactPerceptionAtCell(to, {
        sensory,
        origin: from,
        map,
        environments,
        lightingCurrent: true
      }))
    });
    scientistMapPerceptionCache = { signature, keys };
    return keys;
  }

  function rememberableMapObjectEntry(entry) {
    if (!entry) return null;
    const targets = (entry.targets || []).filter((target) =>
      ["fixture", "container", "collectionStation"].includes(target?.kind)
    );
    if (!targets.length) return null;
    const classNames = new Set();
    if (targets.some((target) => target.kind === "fixture")) classNames.add("fixture-object-cell");
    if (targets.some((target) => target.kind === "container")) {
      classNames.add("container-object-cell");
      classNames.add("blocking-object-cell");
    }
    if (targets.some((target) => target.kind === "collectionStation")) {
      classNames.add("collection-station-object-cell");
    }
    return {
      cell: cleanMapCell(entry.cell),
      symbols: [targets.some((target) => target.kind === "fixture") ? "F" : "C"],
      labels: targets.map((target) => target.label || titleCase(target.kind)),
      classNames,
      targets
    };
  }

  function mapObservationBuildContext(map) {
    const knownCellKeys = null;
    const excavatedKeys = labMapExcavatedCellKeys(map);
    const compartmentInference = inferLabCompartments(map);
    const envelopeContext = buildSurfaceEnvelopeContext(map);
    return {
      anchors: labMapAnchorAssignments(map),
      objects: labMapObjectAssignments(map, { debug: true }),
      excavatedKeys,
      envelopeContext,
      terrainContext: buildTerrainConnectivityContext(map, {
        fullReveal: true,
        knownCellKeys,
        excavatedKeys,
        compartmentInference
      })
    };
  }

  function mapCellObservationSnapshot(cell, map, context, objectEntry = null) {
    const roomId = labMapCellRoomId(cell, map);
    const hasFloor = labMapCellHasFloor(cell, map, context.excavatedKeys);
    const base = labMapCellBaseView(roomId, hasFloor, null, null, true, cell, map, context.envelopeContext);
    const terrainConnectivity = terrainConnectivityViewAtCell(cell, context.terrainContext);
    const door = labMapDoorAtCell(cell, map);
    const stateDoor = door ? doorFixtureState(door) || door : null;
    const semanticDoor = door ? {
      key: door.key,
      roomIds: [...door.roomIds],
      frameAxis: door.frameAxis,
      passageAxis: door.passageAxis,
      connectivity: terrainConnectivity.door,
      state: doorMapClassName(stateDoor).replace(/^door-/, ""),
      glyph: doorMapGlyph(stateDoor),
      spriteKey: `door.${doorMapClassName(stateDoor).replace(/^door-/, "")}`
    } : null;
    const semanticObject = objectEntry ? {
      symbols: [...(objectEntry.symbols || [])],
      labels: [...(objectEntry.labels || [])],
      tags: mapObjectSemanticTags(objectEntry.classNames),
      targets: [],
      blocking: Boolean(objectEntry.classNames?.has?.("blocking-object-cell")),
      spriteKey: labMapObjectSpriteKey(objectEntry)
    } : null;
    const anchorRoom = context.anchors.get(mapCellKey(cell));
    const anchor = anchorRoom ? { roomId: anchorRoom.roomId } : null;
    const visual = labMapCellVisualView({
      base,
      door: semanticDoor,
      object: semanticObject
    });
    return MapKnowledge.snapshotCellView({
      cell,
      roomId,
      base,
      terrainConnectivity,
      door: semanticDoor,
      object: semanticObject,
      anchor,
      visual
    });
  }

  function observeMapCellKeys(keys, options = {}) {
    const map = options.map || ensureLabMap();
    const observations = normalizeMapCellObservations(state.mapCellObservations);
    const context = options.context || mapObservationBuildContext(map);
    let changed = 0;
    for (const key of keys || []) {
      const [x, y, z] = String(key).split(",").map(Number);
      const cell = cleanMapCell({ x, y, z });
      if (!cell || !mapCellInBounds(cell, map)) continue;
      const previous = observations[key] || null;
      if (options.skipExisting && previous) continue;
      const objectEntry = rememberableMapObjectEntry(context.objects.get(key));
      const snapshot = mapCellObservationSnapshot(cell, map, context, objectEntry);
      if (!previous || JSON.stringify(previous.snapshot) !== JSON.stringify(snapshot)) changed += 1;
      observations[key] = MapKnowledge.normalizeObservation({
        cell,
        firstObservedAt: previous?.firstObservedAt ?? state.clock,
        lastObservedAt: options.observedAt ?? state.clock,
        source: options.source || "direct observation",
        snapshot
      });
    }
    state.mapCellObservations = observations;
    return changed;
  }

  function ensureMapCellObservations(map = ensureLabMap(), context = null) {
    state.mapCellObservations = normalizeMapCellObservations(state.mapCellObservations);
    if (!state.mapBlueprintMemorySeeded) {
      observeMapCellKeys(labMapBlueprintCellKeys(map), {
        map,
        context: context || undefined,
        skipExisting: true,
        observedAt: 0,
        source: "starter map"
      });
      state.mapBlueprintMemorySeeded = true;
    }
    return state.mapCellObservations;
  }

  function observeScientistMapCells(options = {}) {
    if (!options.force && mapFullRevealActive()) return 0;
    const map = ensureLabMap();
    const context = mapObservationBuildContext(map);
    state.mapCellObservations = normalizeMapCellObservations(state.mapCellObservations);
    return observeMapCellKeys(scientistPerceivedMapCellKeys(map), {
      map,
      context,
      observedAt: state.clock,
      source: options.source || "direct observation"
    });
  }

  function labMapKnownCellKeys(map, context = {}) {
    if (context.fullReveal || mapFullRevealActive()) {
      return null;
    }
    const keys = new Set(Object.keys(ensureMapCellObservations(map)));
    for (const [key] of plannedExcavationAssignments()) keys.add(key);
    for (const [key] of draftExcavationAssignments()) keys.add(key);
    return keys;
  }

  function labMapCellKnown(cell, map, knownCellKeys, excavatedKeys = null) {
    return knownCellKeys === null
      || knownCellKeys?.has?.(mapCellKey(cell))
      || labMapCellIsExcavated(cell, map, excavatedKeys);
  }

  function buildTerrainConnectivityContext(map, options = {}) {
    const byCell = (entries, cellFor = (entry) => entry?.cell || entry) => new Map(
      (entries || []).map((entry) => [mapCellKey(cellFor(entry)), entry])
    );
    const roomsByCell = new Map();
    for (const room of Object.values(map.rooms || {})) {
      for (const cell of room.cells || []) roomsByCell.set(mapCellKey(cell), room.roomId);
    }
    const connectorsByCell = new Map();
    for (const connector of map.terrain?.verticalConnectors || []) {
      const cells = connector.type === "ramp"
        ? [connector.lowerCell, connector.upperCell, ...(connector.footprintCells || []), ...(connector.upperCells || [])]
        : [connector.lowerCell, connector.upperCell];
      for (const cell of cells) {
        const key = mapCellKey(cell);
        if (!connectorsByCell.has(key)) connectorsByCell.set(key, []);
        if (!connectorsByCell.get(key).some((entry) => entry.id === connector.id)) connectorsByCell.get(key).push(connector);
      }
    }
    const doorsByCell = new Map();
    for (const door of Object.values(map.doors || {})) {
      for (const cell of labMapDoorCells(door)) doorsByCell.set(mapCellKey(cell), door);
    }
    return {
      map,
      geologySeed: state.seed,
      fullReveal: Boolean(options.fullReveal),
      knownCellKeys: options.knownCellKeys ?? null,
      excavatedKeys: options.excavatedKeys || labMapExcavatedCellKeys(map),
      surfaceGroundByCell: byCell(map.terrain?.surfaceGround),
      roomsByCell,
      compartmentsByCell: options.compartmentInference?.cellToCompartment || new Map(),
      constructedFloorsByCell: byCell(map.terrain?.constructedFloors),
      constructedWallsByCell: byCell(map.terrain?.constructedWalls),
      smoothedFloors: new Set((map.terrain?.smoothedFloors || []).map(mapCellKey)),
      smoothedWalls: new Set((map.terrain?.smoothedWalls || []).map(mapCellKey)),
      naturalDepositsByCell: byCell(map.terrain?.naturalDeposits),
      naturalDamageByCell: byCell(map.terrain?.naturalDamage),
      doorsByCell,
      connectorsByCell
    };
  }

  function terrainCellKnown(cell, context) {
    if (!mapCellInBounds(cell, context.map)) return false;
    return context.fullReveal
      || context.knownCellKeys === null
      || context.knownCellKeys.has(mapCellKey(cell))
      || context.excavatedKeys.has(mapCellKey(cell));
  }

  function terrainPhysicalCellDescriptor(cell, context) {
    const clean = cleanMapCell(cell);
    if (!clean || !mapCellInBounds(clean, context.map)) {
      return { known: false, kind: "mapBoundary", cell: clean };
    }
    const key = mapCellKey(clean);
    if (!terrainCellKnown(clean, context)) {
      return { known: false, kind: "unknown", cell: clean };
    }
    const door = context.doorsByCell.get(key) || null;
    const constructedWall = context.constructedWallsByCell.get(key) || null;
    const constructedFloor = context.constructedFloorsByCell.get(key) || null;
    const surfaceGround = context.surfaceGroundByCell.get(key) || null;
    const excavated = context.excavatedKeys.has(key);
    const roomId = context.roomsByCell.get(key) || "";
    const compartmentId = context.compartmentsByCell.get(key) || "";
    if (constructedWall) {
      return {
        known: true,
        kind: "constructedWall",
        cell: clean,
        roomId,
        compartmentId,
        door,
        materialId: constructedWall.materialId || "stoneBlocks",
        surfaceStyle: "constructed",
        conditionBand: structureConditionBand(constructedWall.condition).toLowerCase()
      };
    }
    if (!excavated && !surfaceGround && !constructedFloor && context.map.surfaceZ !== null && clean.z >= context.map.surfaceZ) {
      return { known: true, kind: "offsite", cell: clean, roomId: "", compartmentId: "", door: null, materialId: "", surfaceStyle: "boundary", conditionBand: "intact" };
    }
    if (!excavated && !surfaceGround && !constructedFloor) {
      const deposit = context.naturalDepositsByCell.get(key);
      const damage = context.naturalDamageByCell.get(key);
      const procedural = Geology.profileForCell(context.geologySeed, clean);
      return {
        known: true,
        kind: "naturalRock",
        cell: clean,
        roomId: "",
        compartmentId: "",
        door: null,
        materialId: normalizeMaterialId(deposit?.stoneId || procedural?.stratum.materialId || "stone"),
        depositId: context.fullReveal ? String(deposit?.oreId || procedural?.deposit?.materialId || "") : "",
        surfaceStyle: context.smoothedWalls.has(key) ? "smoothed" : "rough",
        conditionBand: structureConditionBand(damage?.condition ?? 100).toLowerCase()
      };
    }
    if (surfaceGround) {
      return {
        known: true,
        kind: "surface",
        cell: clean,
        roomId,
        compartmentId,
        door,
        materialId: constructedFloor?.materialId || surfaceGround.terrainId,
        terrainId: surfaceGround.terrainId,
        surfaceStyle: constructedFloor ? "constructed" : "natural",
        conditionBand: constructedFloor ? structureConditionBand(constructedFloor.condition).toLowerCase() : "intact"
      };
    }
    if (constructedFloor && constructedFloor.purpose === "roof") {
      return {
        known: true,
        kind: "roof",
        cell: clean,
        roomId,
        compartmentId,
        door,
        materialId: constructedFloor.materialId,
        surfaceStyle: "constructed",
        conditionBand: structureConditionBand(constructedFloor.condition).toLowerCase()
      };
    }
    const floorKind = constructedFloor
      ? "constructed"
      : context.smoothedFloors.has(key) ? "smoothedNatural" : "roughNatural";
    return {
      known: true,
      kind: "floor",
      cell: clean,
      roomId,
      compartmentId,
      door,
      materialId: constructedFloor?.materialId || "stone",
      surfaceStyle: floorKind,
      conditionBand: constructedFloor ? structureConditionBand(constructedFloor.condition).toLowerCase() : "intact"
    };
  }

  function terrainSurfaceSignature(cell) {
    return ["floor", "surface", "roof"].includes(cell?.kind) ? `${cell.kind}:${cell.surfaceStyle}:${cell.materialId}` : "";
  }

  function terrainRelationForLayer(center, neighbor, layer) {
    if (!neighbor?.known) return neighbor?.kind === "mapBoundary" ? "boundary" : "unknown";
    if (layer === "naturalRock") {
      if (neighbor.kind === "naturalRock") return "joined";
      if (neighbor.kind === "constructedWall") return "abutment";
      if (neighbor.door) return "portal";
      return "exposed";
    }
    if (layer === "constructedWall") {
      if (neighbor.kind === "constructedWall") {
        return neighbor.materialId === center.materialId ? "joined" : "abutment";
      }
      if (neighbor.kind === "naturalRock") return "abutment";
      if (neighbor.door) return "portal";
      return "exposed";
    }
    if (layer === "floor") {
      if (!["floor", "surface", "roof"].includes(neighbor.kind)) return neighbor.door ? "portal" : "exposed";
      return terrainSurfaceSignature(neighbor) === terrainSurfaceSignature(center) ? "joined" : "transition";
    }
    return "exposed";
  }

  function terrainLayerConnectivity(cell, center, layer, context) {
    return TerrainConnectivity.buildNeighborRelations(
      cell,
      (neighborCell) => terrainPhysicalCellDescriptor(neighborCell, context),
      (neighbor) => terrainRelationForLayer(center, neighbor, layer)
    );
  }

  function terrainBoundaryConnectivity(cell, center, field, context) {
    const ownership = field === "roomId" ? context.roomsByCell : context.compartmentsByCell;
    return TerrainConnectivity.buildNeighborRelations(
      cell,
      (neighborCell) => {
        if (!mapCellInBounds(neighborCell, context.map)) return { known: false, kind: "mapBoundary" };
        if (!terrainCellKnown(neighborCell, context)) return { known: false, kind: "unknown" };
        return { known: true, value: ownership.get(mapCellKey(neighborCell)) || "" };
      },
      (neighbor) => {
        if (!neighbor?.known) return neighbor?.kind === "mapBoundary" ? "boundary" : "unknown";
        return String(neighbor.value || "") === String(center[field] || "") ? "joined" : "boundary";
      }
    );
  }

  function terrainVariation(cell, layer, center, count = 8) {
    return TerrainConnectivity.variationIndex([
      state.seed,
      mapCellKey(cell),
      layer,
      center?.kind,
      center?.materialId,
      center?.surfaceStyle
    ], count);
  }

  function terrainDoorConnectivity(door, cell, context) {
    if (!door) return null;
    const supportMask = TerrainConnectivity.CARDINALS.reduce((mask, direction) => {
      const neighbor = terrainPhysicalCellDescriptor(mapCellAtOffset(cell, direction.dx, direction.dy), context);
      return ["naturalRock", "constructedWall"].includes(neighbor.kind) ? mask | direction.bit : mask;
    }, 0);
    const relations = Object.fromEntries(TerrainConnectivity.CARDINALS.map((direction) => {
      const neighbor = terrainPhysicalCellDescriptor(mapCellAtOffset(cell, direction.dx, direction.dy), context);
      if (!neighbor.known) return [direction.id, neighbor.kind === "mapBoundary" ? "boundary" : "unknown"];
      return [direction.id, ["naturalRock", "constructedWall"].includes(neighbor.kind) ? "abutment" : "exposed"];
    }));
    const frameAxis = TerrainConnectivity.cleanFrameAxis(door.frameAxis);
    const frameMask = frameAxis === "eastWest" ? 10 : 5;
    return {
      frameAxis,
      passageAxis: TerrainConnectivity.passageAxisForFrame(frameAxis),
      supportMask,
      frameSupportMask: supportMask & frameMask,
      passageMask: frameAxis === "eastWest" ? 5 : 10,
      edges: TerrainConnectivity.describeEdgeRelations(relations)
    };
  }

  function terrainCellHasSupport(cell, context) {
    const key = mapCellKey(cell);
    if (context.constructedFloorsByCell.has(key)) return true;
    if (context.surfaceGroundByCell.has(key)) return true;
    const below = mapCellAtOffset(cell, 0, 0, -1);
    const connectors = context.connectorsByCell.get(key) || [];
    if (connectors.some((entry) => sameMapCell(entry.lowerCell, below) && sameMapCell(entry.upperCell, cell))) {
      return true;
    }
    if (connectors.some((entry) => entry.type === "ramp" && sameMapCell(entry.upperCell, cell))) {
      return true;
    }
    return !context.excavatedKeys.has(mapCellKey(below)) && !context.surfaceGroundByCell.has(mapCellKey(below));
  }

  function terrainVerticalConnectivity(cell, center, context) {
    const connectors = context.connectorsByCell.get(mapCellKey(cell)) || [];
    const stairs = connectors.filter((entry) => entry.type !== "ramp");
    const stairUp = stairs.some((entry) => sameMapCell(entry.lowerCell, cell));
    const stairDown = stairs.some((entry) => sameMapCell(entry.upperCell, cell));
    const ramp = connectors.find((entry) => entry.type === "ramp" && TerrainConnectivity.rampSegment(entry, cell));
    const rampSegment = ramp ? TerrainConnectivity.rampSegment(ramp, cell) : null;
    const openBelow = ["floor", "surface", "roof"].includes(center.kind) && !terrainCellHasSupport(cell, context);
    const above = mapCellAtOffset(cell, 0, 0, 1);
    const openAbove = terrainCellKnown(above, context)
      && (context.excavatedKeys.has(mapCellKey(above)) || context.surfaceGroundByCell.has(mapCellKey(above)) || context.constructedFloorsByCell.has(mapCellKey(above)))
      && !terrainCellHasSupport(above, context);
    if (!stairUp && !stairDown && !rampSegment && !openBelow && !openAbove) return null;
    return {
      stairs: stairUp || stairDown ? {
        up: stairUp,
        down: stairDown,
        direction: stairUp && stairDown ? "both" : stairUp ? "up" : "down",
        connectorIds: stairs.map((entry) => entry.id)
      } : null,
      ramp: rampSegment ? {
        id: ramp.id,
        ...rampSegment,
        grade: ramp.grade,
        angleDegrees: ramp.angleDegrees,
        conditionBand: structureConditionBand(ramp.condition).toLowerCase()
      } : null,
      shaft: openBelow || openAbove ? { openBelow, openAbove } : null
    };
  }

  function terrainConnectivityViewAtCell(cell, context) {
    const center = terrainPhysicalCellDescriptor(cell, context);
    if (!center.known) return { version: 1, known: false };
    const layer = center.kind === "naturalRock"
      ? "naturalRock"
      : center.kind === "constructedWall" ? "constructedWall" : ["floor", "surface", "roof"].includes(center.kind) ? "floor" : "";
    const physicalLayer = layer ? {
      kind: center.kind,
      materialId: center.materialId,
      surfaceStyle: center.surfaceStyle,
      conditionBand: center.conditionBand,
      depositId: center.depositId || "",
      connectivity: terrainLayerConnectivity(cell, center, layer, context),
      variation: terrainVariation(cell, layer, center)
    } : null;
    return {
      version: 1,
      known: true,
      solid: center.kind === "naturalRock" ? physicalLayer : null,
      floor: ["floor", "surface", "roof"].includes(center.kind) ? physicalLayer : null,
      wall: center.kind === "constructedWall" ? physicalLayer : null,
      door: terrainDoorConnectivity(center.door, cell, context),
      vertical: terrainVerticalConnectivity(cell, center, context),
      fluid: null,
      boundaries: ["floor", "surface", "roof"].includes(center.kind) ? {
        room: terrainBoundaryConnectivity(cell, center, "roomId", context),
        compartment: terrainBoundaryConnectivity(cell, center, "compartmentId", context)
      } : { room: null, compartment: null }
    };
  }

  function surfaceGroundSpriteKey(cell, roomId, surfaceGround, constructedFloor, envelope, verticalDirection) {
    if (verticalDirection === "down") return "tile.surface.vertical.down";
    if (constructedFloor) {
      return roomId === SURFACE_LOADING_ROOM_ID
        ? "tile.surface.interior.loading.constructed"
        : "tile.surface.interior.constructed";
    }
    if (surfaceGround?.terrainId === "gravel") {
      const variation = Math.abs((Number(cell?.x) || 0) * 17 + (Number(cell?.y) || 0) * 31) % 19;
      if (variation === 0) return "tile.surface.outdoor.gravel.drainage";
      if (variation === 1) return "tile.surface.outdoor.gravel.weeds";
    }
    return `tile.surface.outdoor.${surfaceGround?.terrainId || "grass"}`;
  }

  function surfaceWallSpriteKey(cell, wall, map, envelopeContext) {
    const condition = structureConditionBand(wall.condition).toLowerCase();
    if (cell.z !== map.surfaceZ || wall.materialId !== "stoneBlocks") {
      return `tile.wall.constructed.${wall.materialId}.${condition}`;
    }
    const exterior = [[0, -1], [1, 0], [0, 1], [-1, 0]].some(([dx, dy]) => {
      const adjacent = mapCellAtOffset(cell, dx, dy);
      return Boolean(surfaceGroundAtCell(adjacent, map)
        && surfaceEnvelopeAtCell(adjacent, map, envelopeContext)?.openSky);
    });
    return `tile.wall.surface.${exterior ? "exterior" : "partition"}.${wall.materialId}.${condition}`;
  }

  function labMapCellBaseView(roomId, hasFloor = false, plannedEntry = null, draftEntry = null, known = true, cell = null, map = null, envelopeContext = null) {
    if (!known) {
      return {
        kind: "unknownDark",
        spriteKey: "tile.unknownDark"
      };
    }
    if (draftEntry) {
      return {
        kind: "draftExcavation",
        mode: draftEntry.mode || "mine",
        label: draftEntry.label || "Draft dig",
        valid: Boolean(draftEntry.valid),
        reason: draftEntry.reason || "",
        spriteKey: draftEntry.valid ? "tile.draftExcavation.valid" : "tile.draftExcavation.invalid"
      };
    }
    if (plannedEntry) {
      return {
        kind: "plannedExcavation",
        mode: plannedEntry.mode || "mine",
        priority: plannedEntry.priority || CONSTRUCTION_PRIORITY_DEFAULT,
        status: plannedEntry.status || "planned",
        blockedReason: plannedEntry.blockedReason || "",
        label: plannedEntry.label || "Planned dig",
        taskId: plannedEntry.task?.id || "",
        spriteKey: "tile.plannedExcavation"
      };
    }
    const constructedWall = cell && map ? constructedWallAtCell(cell, map) : null;
    const constructedFloor = cell && map ? constructedFloorAtCell(cell, map) : null;
    const surfaceGround = cell && map ? surfaceGroundAtCell(cell, map) : null;
    const envelope = cell && map ? surfaceEnvelopeAtCell(cell, map, envelopeContext) : null;
    const structuralFailure = cell && map ? structuralFailureAtCell(cell, map) : null;
    const verticalConnector = cell && map
      ? verticalConnectorAtEndpoint(cell, map)
      : null;
    const ramp = cell && map ? rampAtCell(cell, map) : null;
    const verticalDirection = verticalConnector
      ? verticalConnector.type === "ramp"
        ? sameMapCell(verticalConnector.lowerCell, cell) ? "rampUp" : "rampDown"
        : sameMapCell(verticalConnector.lowerCell, cell) ? "up" : "down"
      : ramp ? "ramp"
      : hasFloor && cell && map && !labMapCellHasSupport(cell, map) ? "shaft" : "";
    if (constructedWall) {
      return {
        kind: "constructedWall",
        materialId: constructedWall.materialId,
        condition: constructedWall.condition,
        state: structureConditionBand(constructedWall.condition).toLowerCase(),
        attackTransmission: constructedWall.condition > 0 && constructedWall.condition < STRUCTURE_BREACH_THRESHOLD,
        enclosure: envelope?.kind || "",
        supportStatus: structuralFailure?.status || "supported",
        spriteKey: surfaceWallSpriteKey(cell, constructedWall, map, envelopeContext)
      };
    }
    if (roomId) {
      const smoothed = Boolean(cell && (map?.terrain?.smoothedFloors || []).some((entry) => mapCellKey(entry) === mapCellKey(cell)));
      return {
        kind: "room",
        roomId,
        role: roomRole(roomId),
        smoothed,
        constructedFloor: constructedFloor?.materialId || "",
        surface: Boolean(surfaceGround),
        surfaceTerrainId: surfaceGround?.terrainId || "",
        enclosure: envelope?.kind || "",
        roofed: Boolean(envelope?.roofed),
        openSky: Boolean(envelope?.openSky),
        verticalDirection,
        ramp: ramp ? { id: ramp.id, grade: ramp.grade, length: ramp.length, width: ramp.width, direction: ramp.direction, angleDegrees: ramp.angleDegrees, condition: ramp.condition } : null,
        supportStatus: structuralFailure?.status || "supported",
        spriteKey: surfaceGround
          ? surfaceGroundSpriteKey(cell, roomId, surfaceGround, constructedFloor, envelope, verticalDirection)
          : constructedFloor ? `tile.room.${roomRole(roomId)}.constructedFloor.${constructedFloor.materialId}` : smoothed ? `tile.room.${roomRole(roomId)}.smoothed` : `tile.room.${roomRole(roomId)}`
      };
    }
    if (surfaceGround) {
      return {
        kind: "surface",
        terrainId: surfaceGround.terrainId,
        constructedFloor: constructedFloor?.materialId || "",
        enclosure: envelope?.kind || "outdoor",
        roofed: Boolean(envelope?.roofed),
        openSky: Boolean(envelope?.openSky),
        verticalDirection,
        supportStatus: structuralFailure?.status || "supported",
        spriteKey: surfaceGroundSpriteKey(cell, roomId, surfaceGround, constructedFloor, envelope, verticalDirection)
      };
    }
    if (constructedFloor?.purpose === "roof") {
      return {
        kind: "roof",
        materialId: constructedFloor.materialId,
        constructedFloor: constructedFloor.materialId,
        enclosure: "roof",
        roofed: false,
        openSky: true,
        verticalDirection,
        supportStatus: structuralFailure?.status || "supported",
        spriteKey: `tile.roof.${constructedFloor.materialId}.${structureConditionBand(constructedFloor.condition).toLowerCase()}`
      };
    }
    if (hasFloor) {
      const smoothed = Boolean(cell && (map?.terrain?.smoothedFloors || []).some((entry) => mapCellKey(entry) === mapCellKey(cell)));
      return {
        kind: "floor",
        smoothed,
        constructedFloor: constructedFloor?.materialId || "",
        verticalDirection,
        ramp: ramp ? { id: ramp.id, grade: ramp.grade, length: ramp.length, width: ramp.width, direction: ramp.direction, angleDegrees: ramp.angleDegrees, condition: ramp.condition } : null,
        supportStatus: structuralFailure?.status || "supported",
        spriteKey: constructedFloor ? `tile.floor.constructed.${constructedFloor.materialId}` : smoothed ? "tile.floor.smoothed" : "tile.floor.rough"
      };
    }
    if (cell && map && map.surfaceZ !== null && cell.z >= map.surfaceZ) {
      return { kind: "offsite", spriteKey: "tile.offsite" };
    }
    const smoothedWall = Boolean(cell && (map?.terrain?.smoothedWalls || []).some((entry) => mapCellKey(entry) === mapCellKey(cell)));
    const naturalCondition = cell && map ? naturalDamageAtCell(cell, map)?.condition ?? 100 : 100;
    return {
      kind: "solidEarth",
      smoothedWall,
      materialId: cell && map ? naturalWallMaterialId(cell, map) : "stone",
      condition: naturalCondition,
      state: structureConditionBand(naturalCondition).toLowerCase(),
      attackTransmission: naturalCondition > 0 && naturalCondition < STRUCTURE_BREACH_THRESHOLD,
      spriteKey: smoothedWall ? `tile.wall.smoothed.${structureConditionBand(naturalCondition).toLowerCase()}` : `tile.solidEarth.${structureConditionBand(naturalCondition).toLowerCase()}`
    };
  }

  function labMapObjectSpriteKey(objectEntry) {
    const targets = objectEntry?.targets || [];
    if (!objectEntry) {
      return "";
    }
    if ((objectEntry.symbols || []).length > 1 || targets.length > 1) {
      return "map.stack";
    }
    const target = targets[0];
    if (target?.kind === "slime") return "actor.slime";
    if (target?.kind === "corpse") return "corpse.remains";
    if (target?.kind === "container") return "object.container";
    return "object.unknown";
  }

  const MAP_OBJECT_SEMANTIC_TAG_BY_CLASS = Object.freeze({
    "fixture-object-cell": "fixture",
    "blocking-object-cell": "blocking",
    "fixture-access-cell": "interactionPort",
    "physical-item-stack-cell": "itemStack",
    "floor-stockpile-object-cell": "floorStored",
    "spill-object-cell": "spill",
    "container-object-cell": "container",
    "collection-station-object-cell": "collectionStation",
    "contained-object-cell": "contained",
    "living-object-cell": "living",
    "living-object-body-cell": "livingBodySegment",
    "corpse-object-cell": "corpse",
    "corpse-object-body-cell": "corpseBodySegment",
    "rubble-object-cell": "rubble"
  });
  const MAP_OBJECT_DOM_CLASS_BY_TAG = Object.freeze(Object.fromEntries(
    Object.entries(MAP_OBJECT_SEMANTIC_TAG_BY_CLASS).map(([className, tag]) => [tag, className])
  ));

  function mapObjectSemanticTags(classNames) {
    return [...new Set([...(classNames || [])].map((className) => MAP_OBJECT_SEMANTIC_TAG_BY_CLASS[className]).filter(Boolean))];
  }

  function mapObjectDomClasses(tags) {
    return [...new Set((tags || []).map((tag) => MAP_OBJECT_DOM_CLASS_BY_TAG[tag]).filter(Boolean))];
  }

  function mapOverlaySemanticStates(entry) {
    return [...new Set([...(entry?.classNames || [])].map((className) => {
      if (className === "map-overlay-debug-value") return "debugValue";
      if (className === "incident-stale") return "stale";
      if (className === "incident-acknowledged") return "acknowledged";
      if (className === "incident-stack-cell") return "stacked";
      return className.startsWith("map-overlay-") ? className.slice("map-overlay-".length) : "";
    }).filter(Boolean))];
  }

  function mapOverlayDomClasses(states) {
    return [...new Set((states || []).map((stateName) => {
      if (stateName === "debugValue") return "map-overlay-debug-value";
      if (stateName === "stale") return "incident-stale";
      if (stateName === "acknowledged") return "incident-acknowledged";
      if (stateName === "stacked") return "incident-stack-cell";
      return `map-overlay-${stateName}`;
    }))];
  }

  function labMapCellVisualView({ base, door, object, incident }) {
    if (object) {
      return {
        glyph: object.symbols.length > 1 ? String(object.symbols.length) : object.symbols[0],
        spriteKey: object.spriteKey,
        layer: "object"
      };
    }
    if (door) {
      return {
        glyph: door.glyph,
        spriteKey: door.spriteKey,
        layer: "door"
      };
    }
    if (base.verticalDirection) {
      return {
        glyph: base.verticalDirection === "up" ? "<" : base.verticalDirection === "down" ? ">"
          : base.verticalDirection === "rampUp" ? "^" : base.verticalDirection === "rampDown" ? "v"
            : base.verticalDirection === "ramp" ? "/" : "O",
        spriteKey: `tile.vertical.${base.verticalDirection}`,
        layer: "terrain"
      };
    }
    if (base.kind === "plannedExcavation") {
      return { glyph: ({ mine: "M", stairUp: "<", stairDown: ">", channelDown: "O", ramp: "/", smoothFloor: "F", smoothWall: "W", build: "B", deconstruct: "D", cancel: "X" }[base.mode] || "M"), spriteKey: base.spriteKey, layer: "construction" };
    }
    if (base.kind === "draftExcavation") {
      const glyph = ({ mine: "m", stairUp: "<", stairDown: ">", channelDown: "o", ramp: "/", smoothFloor: "f", smoothWall: "w", build: "b", deconstruct: "d", cancel: "x" }[base.mode] || "m");
      return { glyph: base.valid ? glyph : "?", spriteKey: base.spriteKey, layer: "construction" };
    }
    if (base.kind === "constructedWall") {
      return { glyph: "#", spriteKey: base.spriteKey, layer: "structure" };
    }
    if (incident) {
      return {
        glyph: incident.count > 1 ? `A${incident.count}` : "A",
        spriteKey: incident.count > 1 ? "marker.incident.stack" : "marker.incident",
        layer: "incident"
      };
    }
    return { glyph: "", spriteKey: base.spriteKey, layer: "base" };
  }

  function buildLabMapCellView({
    cell,
    map,
    anchorRoom,
    objectEntry,
    incidentEntry,
    routeEntry,
    plannedEntry,
    draftEntry,
    overlayEntry,
    selectedTarget,
    scientistCell,
    cursorCell,
    known,
    knowledge,
    remembered,
    excavatedKeys,
    terrainContext,
    envelopeContext
  }) {
    const memory = remembered?.snapshot || remembered || null;
    const cellKnowledge = knowledge || {
      state: known === false ? "unknown" : "current",
      observedAt: known === false ? null : state.clock,
      confidence: known === false ? 0 : 1,
      source: known === false ? "unexplored" : "direct observation",
      tier: known === false ? "unknown" : "current"
    };
    const currentKnowledge = ["current", "debug"].includes(cellKnowledge.state);
    const playerAuthored = Boolean(routeEntry || plannedEntry || draftEntry);
    const visible = currentKnowledge || Boolean(memory) || playerAuthored;
    const roomId = currentKnowledge ? labMapCellRoomId(cell, map) : String(memory?.roomId || "");
    const hasFloor = currentKnowledge
      ? labMapCellHasFloor(cell, map, excavatedKeys)
      : ["room", "floor", "surface", "roof"].includes(memory?.base?.kind);
    const door = currentKnowledge ? labMapDoorAtCell(cell, map) : null;
    const stateDoor = door ? doorFixtureState(door) || door : null;
    const scientistHere = currentKnowledge && sameMapCell(scientistCell, cell);
    const visibleObjectEntry = currentKnowledge ? objectEntry : null;
    const visibleIncidentEntry = currentKnowledge ? incidentEntry : null;
    const visibleRouteEntry = routeEntry || null;
    const visiblePlannedEntry = plannedEntry || null;
    const visibleDraftEntry = draftEntry || null;
    const visibleOverlayEntry = currentKnowledge
      || memory && (overlayEntry?.knowledge?.state === "stale" || overlayEntry?.scope === "roomObservation")
      ? overlayEntry
      : null;
    const interactionContext = {
      roomId: currentKnowledge ? roomId : "",
      door,
      objectEntry: visibleObjectEntry,
      incidentEntry: visibleIncidentEntry,
      overlayEntry: visibleOverlayEntry,
      plannedEntry: visiblePlannedEntry,
      scientistHere,
      cell
    };
    const clickTarget = visible ? mapTileClickTarget(interactionContext) : null;
    const interactionTargets = visible ? mapTileInteractionTargets(interactionContext) : [];
    const base = visiblePlannedEntry || visibleDraftEntry
      ? labMapCellBaseView("", false, visiblePlannedEntry, visibleDraftEntry, true, cell, map)
      : currentKnowledge
        ? labMapCellBaseView(roomId, hasFloor, null, null, true, cell, map, envelopeContext)
        : memory?.base || labMapCellBaseView("", false, null, null, false, cell, map);
    const terrainConnectivity = currentKnowledge
      ? terrainConnectivityViewAtCell(cell, terrainContext)
      : memory?.terrainConnectivity || { version: 1, known: false };
    const semanticDoor = currentKnowledge && door ? {
      key: door.key,
      roomIds: [...door.roomIds],
      frameAxis: door.frameAxis,
      passageAxis: door.passageAxis,
      connectivity: terrainConnectivity.door,
      state: doorMapClassName(stateDoor).replace(/^door-/, ""),
      glyph: doorMapGlyph(stateDoor),
      spriteKey: `door.${doorMapClassName(stateDoor).replace(/^door-/, "")}`
    } : memory?.door ? MapKnowledge.cloneJson(memory.door) : null;
    const semanticObject = currentKnowledge && visibleObjectEntry ? {
      symbols: [...(visibleObjectEntry.symbols || [])],
      labels: [...(visibleObjectEntry.labels || [])],
      tags: mapObjectSemanticTags(visibleObjectEntry.classNames),
      targets: [...(visibleObjectEntry.targets || [])],
      blocking: Boolean(visibleObjectEntry.classNames?.has?.("blocking-object-cell")),
      spriteKey: labMapObjectSpriteKey(visibleObjectEntry)
    } : memory?.object ? { ...MapKnowledge.cloneJson(memory.object), targets: [] } : null;
    const semanticIncident = visibleIncidentEntry ? {
      ids: (visibleIncidentEntry.alerts || []).map((incident) => incident.id),
      labels: (visibleIncidentEntry.alerts || []).map((incident) => incident.label),
      count: visibleIncidentEntry.alerts?.length || 0,
      highestSeverity: visibleIncidentEntry.highestSeverity,
      hasStale: Boolean(visibleIncidentEntry.hasStale),
      allAcknowledged: Boolean(visibleIncidentEntry.allAcknowledged)
    } : null;
    const semanticRoute = visibleRouteEntry ? {
      taskId: visibleRouteEntry.task?.id || "next",
      label: visibleRouteEntry.label || "",
      selected: Boolean(visibleRouteEntry.selected),
      connections: [...(visibleRouteEntry.marker?.connections || [])],
      start: Boolean(visibleRouteEntry.marker?.start),
      end: Boolean(visibleRouteEntry.marker?.end),
      vertical: [...(visibleRouteEntry.marker?.vertical || [])]
    } : null;
    const semanticOverlay = visibleOverlayEntry ? {
      id: visibleOverlayEntry.overlayId,
      label: visibleOverlayEntry.label || "",
      source: visibleOverlayEntry.source || "",
      value: visibleOverlayEntry.value ?? null,
      title: visibleOverlayEntry.title || "",
      states: mapOverlaySemanticStates(visibleOverlayEntry),
      knowledge: visibleOverlayEntry.knowledge || null,
      target: visibleOverlayEntry.target || null
    } : null;
    const anchor = currentKnowledge && anchorRoom
      ? { roomId: anchorRoom.roomId }
      : memory?.anchor ? { roomId: String(memory.anchor.roomId || "") } : null;
    const selected = visible && selectedTargetMatchesTile(selectedTarget, {
      cell,
      roomId: currentKnowledge ? roomId : "",
      door,
      objectEntry: visibleObjectEntry,
      incidentEntry: visibleIncidentEntry,
      overlayEntry: visibleOverlayEntry,
      scientistHere
    });
    const cursor = visible && sameMapCell(cursorCell, cell);
    const tooltipParts = currentKnowledge
      ? labMapCellTooltipParts(cell, map, visibleObjectEntry, visibleRouteEntry, visiblePlannedEntry, visibleDraftEntry, visibleIncidentEntry, visibleOverlayEntry, excavatedKeys, envelopeContext)
      : memory
        ? [
            `${cell.x}, ${cell.y}, Z ${cell.z}`,
            roomId ? `Remembered ${roomName(roomId)}` : `Remembered ${titleCase(base.kind || "terrain")}`,
            semanticDoor ? `Remembered ${semanticDoor.state || "door"} door` : "",
            ...(semanticObject?.labels || []).map((label) => `Remembered ${label}`),
            visibleOverlayEntry?.title || "",
            Number.isFinite(Number(cellKnowledge.observedAt)) ? `Last observed ${formatClock(cellKnowledge.observedAt)}` : ""
          ].filter(Boolean)
        : [`${cell.x}, ${cell.y}, Z ${cell.z}`, playerAuthored ? "player-authored plan" : "unexplored darkness"];
    if (cursor) {
      tooltipParts.push("Keyboard cursor");
    }
    if (scientistHere) {
      tooltipParts.push("Scientist");
    } else if (semanticObject?.labels?.length) {
      tooltipParts.push(semanticObject.labels.join("; "));
    }
    const markers = [];
    if (semanticDoor) markers.push("door");
    if (semanticRoute) markers.push(semanticRoute.selected ? "selectedRoute" : "route");
    if (semanticIncident) markers.push("incident");
    if (semanticOverlay) markers.push("overlay");
    if (selected) markers.push("selected");
    if (cursor) markers.push("cursor");
    if (scientistHere) markers.push("scientist");
    if (semanticObject) markers.push(semanticObject.blocking ? "blockingObject" : "object");
    const visual = scientistHere
      ? { glyph: "S", spriteKey: "actor.scientist", layer: "actor" }
      : !currentKnowledge && memory && !visiblePlannedEntry && !visibleDraftEntry
        ? (memory.visual?.layer === "roomAnchor" ? null : memory.visual) || labMapCellVisualView({ base, door: semanticDoor, object: semanticObject })
        : labMapCellVisualView({
            base,
            door: semanticDoor,
            object: semanticObject,
            incident: semanticIncident
          });

    return {
      key: mapCellKey(cell),
      cell,
      known: visible,
      knowledge: cellKnowledge,
      roomId,
      base,
      terrainConnectivity,
      door: semanticDoor,
      object: semanticObject,
      incident: semanticIncident,
      route: semanticRoute,
      planned: visiblePlannedEntry ? { taskId: visiblePlannedEntry.task?.id || "", label: visiblePlannedEntry.label || "Excavation" } : null,
      draft: visibleDraftEntry ? { label: visibleDraftEntry.label || "Draft dig", valid: Boolean(visibleDraftEntry.valid), reason: visibleDraftEntry.reason || "" } : null,
      overlay: semanticOverlay,
      anchor,
      scientist: scientistHere,
      selected,
      cursor,
      markers,
      visual,
      spriteKey: visual.spriteKey,
      spriteLayers: [base.spriteKey, semanticDoor?.spriteKey, semanticObject?.spriteKey, semanticOverlay ? `overlay.${semanticOverlay.id}` : "", visual.spriteKey]
        .filter(Boolean),
      tooltip: {
        parts: tooltipParts,
        text: labMapCellTooltipText(tooltipParts)
      },
      interactionTargets,
      target: clickTarget
    };
  }

  function labMapCellDomModel(cellView, scene = null) {
    const knowledgeState = MapVisualState.KNOWLEDGE_STATES.includes(cellView.knowledge?.state)
      ? cellView.knowledge.state
      : cellView.known === false ? "unknown" : "current";
    const classNames = ["lab-map-cell", `knowledge-${knowledgeState}`];
    const dataset = {
      mapX: String(cellView.cell.x),
      mapY: String(cellView.cell.y),
      mapZ: String(cellView.cell.z),
      mapKnowledge: knowledgeState
    };
    const effects = (cellView.effectIds || [])
      .map((effectId) => scene?.effects?.find((effect) => effect.id === effectId))
      .filter(Boolean);
    const statusCues = (cellView.entityIds || [])
      .flatMap((entityId) => {
        const entity = scene?.entities?.find((candidate) => candidate.id === entityId);
        return entity && mapCellKey(entity.anchorCell) === cellView.key ? entity.statusCues || [] : [];
      })
      .sort((left, right) =>
        MapVisualState.STATUS_SEVERITIES.indexOf(right.severity) - MapVisualState.STATUS_SEVERITIES.indexOf(left.severity)
        || left.id.localeCompare(right.id))
      .slice(0, 2);
    if (effects.length) {
      classNames.push("map-effect-cell");
      dataset.mapEffectKinds = [...new Set(effects.map((effect) => effect.kind))].join(" ");
      dataset.mapEffectCount = String(effects.reduce((total, effect) => total + effect.stackCount, 0));
      for (const effect of effects) {
        classNames.push(
          `map-effect-${overlayClassPart(effect.plane)}`,
          `map-effect-${overlayClassPart(effect.kind)}`,
          `map-effect-severity-${overlayClassPart(effect.severity || "routine")}`,
          `map-effect-state-${overlayClassPart(effect.state || "active")}`
        );
        if (effect.knowledge?.state === "uncertain") classNames.push("map-effect-uncertain");
        if (effect.knowledge?.state === "stale") classNames.push("map-effect-stale");
      }
    }
    if (statusCues.length) {
      classNames.push("map-status-cell");
      dataset.mapStatusCues = statusCues.map((cue) => cue.id).join(" ");
      dataset.mapStatusCount = String(statusCues.length);
      for (const cue of statusCues) {
        classNames.push(`map-status-${overlayClassPart(cue.id)}`, `map-status-severity-${overlayClassPart(cue.severity)}`);
      }
    }
    if (cellView.knowledge?.tier) classNames.push(`knowledge-tier-${cellView.knowledge.tier}`);
    if (["current", "debug"].includes(knowledgeState) && cellView.lighting?.band) {
      classNames.push(`lighting-${overlayClassPart(cellView.lighting.band)}`);
      dataset.mapLightingBand = cellView.lighting.band;
      dataset.mapLightingSpectrum = cellView.lighting.spectrum || "neutral";
    }
    if (cellView.atmosphere?.visible) {
      classNames.push("atmosphere-airborne", `atmosphere-airborne-${overlayClassPart(cellView.atmosphere.band)}`);
      dataset.mapAtmosphere = cellView.atmosphere.band;
    }
    if (cellView.base.kind === "room") {
      classNames.push("room-cell", `room-${cellView.base.role}`);
      if (cellView.base.surface) classNames.push("surface-cell", `surface-${cellView.base.surfaceTerrainId || "ground"}`, `enclosure-${cellView.base.enclosure || "interior"}`);
      if (cellView.base.verticalDirection) classNames.push("vertical-connector-cell", `vertical-${cellView.base.verticalDirection}-cell`);
      if (cellView.base.smoothed) classNames.push("smoothed-floor-cell");
      if (cellView.base.constructedFloor) classNames.push("constructed-floor-cell", `constructed-floor-${cellView.base.constructedFloor}`);
      if (cellView.base.supportStatus && cellView.base.supportStatus !== "supported") classNames.push(`structure-support-${cellView.base.supportStatus}`);
      dataset.mapRoom = cellView.base.roomId;
      if (cellView.base.surface) {
        dataset.mapSurface = cellView.base.surfaceTerrainId || "ground";
        dataset.mapEnclosure = cellView.base.enclosure || "interior";
      }
      if (cellView.base.ramp) dataset.mapRamp = cellView.base.ramp.id;
    } else if (cellView.base.kind === "floor") {
      classNames.push("floor-cell");
      if (cellView.base.verticalDirection) classNames.push("vertical-connector-cell", `vertical-${cellView.base.verticalDirection}-cell`);
      if (cellView.base.smoothed) classNames.push("smoothed-floor-cell");
      if (cellView.base.constructedFloor) classNames.push("constructed-floor-cell", `constructed-floor-${cellView.base.constructedFloor}`);
      if (cellView.base.supportStatus && cellView.base.supportStatus !== "supported") classNames.push(`structure-support-${cellView.base.supportStatus}`);
      dataset.mapFloor = "true";
      if (cellView.base.ramp) dataset.mapRamp = cellView.base.ramp.id;
    } else if (cellView.base.kind === "surface") {
      classNames.push("surface-cell", `surface-${cellView.base.terrainId || "ground"}`, `enclosure-${cellView.base.enclosure || "outdoor"}`);
      if (cellView.base.constructedFloor) classNames.push("constructed-floor-cell", `constructed-floor-${cellView.base.constructedFloor}`);
      if (cellView.base.verticalDirection) classNames.push("vertical-connector-cell", `vertical-${cellView.base.verticalDirection}-cell`);
      dataset.mapSurface = cellView.base.terrainId || "ground";
      dataset.mapEnclosure = cellView.base.enclosure || "outdoor";
    } else if (cellView.base.kind === "roof") {
      classNames.push("roof-cell", `roof-${cellView.base.materialId || "constructed"}`);
      if (cellView.base.verticalDirection) classNames.push("vertical-connector-cell", `vertical-${cellView.base.verticalDirection}-cell`);
      dataset.mapRoof = cellView.base.materialId || "constructed";
    } else if (cellView.base.kind === "offsite") {
      classNames.push("offsite-cell");
      dataset.mapOffsite = "true";
    } else if (cellView.base.kind === "constructedWall") {
      classNames.push("constructed-wall-cell", `constructed-wall-${cellView.base.materialId}`, `structure-${cellView.base.state}`);
      if (cellView.base.attackTransmission) classNames.push("attack-transmitting-breach");
      if (cellView.base.supportStatus && cellView.base.supportStatus !== "supported") classNames.push(`structure-support-${cellView.base.supportStatus}`);
      dataset.mapConstructedWall = cellView.base.materialId;
    } else if (cellView.base.kind === "unknownDark") {
      classNames.push("unknown-darkness-cell");
      dataset.mapUnknown = "true";
    } else if (cellView.base.kind === "draftExcavation") {
      classNames.push("draft-excavation-cell", cellView.base.valid ? "valid-draft-excavation-cell" : "invalid-draft-excavation-cell");
      dataset.mapDraftExcavation = "true";
      if (cellView.base.reason) {
        dataset.mapDraftReason = cellView.base.reason;
      }
    } else if (cellView.base.kind === "plannedExcavation") {
      classNames.push("planned-excavation-cell");
      dataset.mapExcavation = cellView.base.taskId || "pending";
      dataset.mapConstructionMode = cellView.base.mode;
      dataset.mapConstructionPriority = String(cellView.base.priority);
      if (cellView.base.blockedReason) {
        classNames.push("blocked-construction-cell");
        dataset.mapConstructionBlocked = cellView.base.blockedReason;
      }
    } else {
      classNames.push("solid-earth-cell");
      if (cellView.base.smoothedWall) classNames.push("smoothed-wall-cell");
      if (cellView.base.state && cellView.base.state !== "intact") classNames.push(`structure-${cellView.base.state}`);
      if (cellView.base.attackTransmission) classNames.push("attack-transmitting-breach");
    }
    if (cellView.door) {
      classNames.push("door-cell", `door-${cellView.door.state}`);
      dataset.mapDoor = cellView.door.key;
    }
    if (cellView.route) {
      classNames.push("queued-path-cell");
      if (cellView.route.selected) {
        classNames.push("selected-task-path-cell");
      }
      dataset.mapQueuedPath = cellView.route.taskId || "next";
    }
    if (cellView.incident) {
      classNames.push("incident-alert-cell", incidentSeverityClass(cellView.incident.highestSeverity));
      if (cellView.incident.hasStale) {
        classNames.push("incident-stale");
      }
      if (cellView.incident.allAcknowledged) {
        classNames.push("incident-acknowledged");
      }
      if (cellView.incident.count > 1) {
        classNames.push("incident-stack-cell");
      }
      dataset.mapIncident = cellView.incident.ids[0] || "active";
      dataset.mapIncidentCount = String(cellView.incident.count);
    }
    if (cellView.overlay) {
      classNames.push("map-overlay-cell", `map-overlay-${cellView.overlay.id}`, ...mapOverlayDomClasses(cellView.overlay.states));
      dataset.mapOverlay = cellView.overlay.id;
      if (cellView.overlay.label) {
        dataset.mapOverlayLabel = cellView.overlay.label;
      }
      if (cellView.overlay.source) {
        dataset.mapOverlaySource = cellView.overlay.source;
      }
      if (cellView.overlay.value !== null && cellView.overlay.value !== undefined) {
        dataset.mapOverlayValue = String(cellView.overlay.value);
      }
    }
    if (cellView.selected) {
      classNames.push("selected-map-cell");
    }
    if (cellView.cursor) {
      classNames.push("map-cursor-cell");
      dataset.mapCursor = "true";
    }
    if (cellView.target) {
      classNames.push("map-clickable-cell");
      dataset.mapTargetKind = cellView.target.kind;
      if (cellView.target.id) {
        dataset.mapTargetId = cellView.target.id;
      }
      if (cellView.target.roomId) {
        dataset.mapTargetRoom = cellView.target.roomId;
      }
      if (cellView.target.key) {
        dataset.mapTargetDoor = cellView.target.key;
      }
    }
    if (cellView.object?.targets?.length) {
      dataset.mapObjectSelectionKeys = [...new Set(cellView.object.targets.map(selectionKey).filter(Boolean))].join(" ");
    }
    if (cellView.scientist) {
      classNames.push("scientist-cell");
    } else if (cellView.object) {
      classNames.push("object-cell", ...mapObjectDomClasses(cellView.object.tags));
    }
    return {
      classNames,
      dataset,
      title: [
        cellView.tooltip.text,
        ...effects.map((effect) => effect.label),
        ...statusCues.map((cue) => cue.label)
      ].filter(Boolean).join("\n"),
      text: cellView.visual.glyph,
      effectMarkers: effects
        .filter((effect) => !["incident", "combatIncident"].includes(effect.kind))
        .map((effect) => ({
          kind: effect.kind,
          plane: effect.plane,
          severity: effect.severity,
          state: effect.state,
          glyph: effect.glyph || (effect.plane === "ground" ? "~" : effect.plane === "alert" ? "!" : "*"),
          stackCount: effect.stackCount,
          label: effect.label
        })),
      statusMarkers: statusCues.map((cue) => ({ ...cue })),
      clickTarget: cellView.target
    };
  }

  function labMapCellElement(cellView, scene = null, options = {}) {
    const domCell = labMapCellDomModel(cellView, scene);
    const tile = document.createElement("div");
    tile.className = domCell.classNames.join(" ");
    tile.title = domCell.title;
    const cellGlyph = document.createElement("span");
    cellGlyph.className = "map-cell-glyph";
    cellGlyph.textContent = domCell.text;
    tile.append(cellGlyph);
    for (const [key, value] of Object.entries(domCell.dataset)) {
      tile.dataset[key] = value;
    }
    for (const marker of domCell.effectMarkers) {
      const effectMarker = document.createElement("span");
      effectMarker.className = [
        "map-cell-effect-marker",
        `map-cell-effect-${overlayClassPart(marker.plane)}`,
        `map-cell-effect-${overlayClassPart(marker.kind)}`,
        `map-cell-effect-severity-${overlayClassPart(marker.severity || "routine")}`
      ].join(" ");
      effectMarker.textContent = marker.stackCount > 1 ? `${marker.glyph}${marker.stackCount}` : marker.glyph;
      effectMarker.title = marker.label;
      effectMarker.setAttribute("aria-hidden", "true");
      tile.append(effectMarker);
    }
    for (const [markerIndex, marker] of domCell.statusMarkers.entries()) {
      const statusMarker = document.createElement("span");
      statusMarker.className = `map-cell-status-marker map-cell-status-${overlayClassPart(marker.severity)}`;
      statusMarker.textContent = marker.glyph;
      statusMarker.title = marker.label;
      statusMarker.dataset.statusIndex = String(markerIndex);
      statusMarker.setAttribute("aria-hidden", "true");
      tile.append(statusMarker);
    }
    if (options.interactive !== false) {
      tile.addEventListener("click", () => {
        if (suppressNextMapClick) {
          suppressNextMapClick = false;
          return;
        }
        if (handleConstructionMapCellClick(cellView)) return;
        if (domCell.clickTarget) {
          focusMapTarget(domCell.clickTarget, {
            keepWorkspace: true,
            source: "map",
            resetInspectorTab: true,
            resetInspectorExpanded: true,
            resetCommandMenu: true
          });
        }
      });
    }
    return { tile, model: domCell };
  }

  function removeMapRendererParityFixture() {
    activeMapParityFixtureRoot?.remove();
    activeMapParityFixtureRoot = null;
  }

  async function mountMapRendererParityFixture(fixtureId) {
    removeMapRendererParityFixture();
    const parity = window.HelixMapRendererParity;
    if (!parity) throw new Error("Renderer parity fixtures are not loaded.");
    await spriteAssetLoader.loadAll();
    await document.fonts?.ready;
    const fixture = parity.createFixture(fixtureId);
    const { scene, presentation } = fixture;
    const root = document.createElement("section");
    root.className = "map-parity-fixture-root";
    root.dataset.mapParityFixture = fixture.id;
    root.dataset.fixtureVersion = String(fixture.version);
    root.setAttribute("aria-label", `Renderer parity fixture: ${fixture.title}`);
    const heading = document.createElement("header");
    heading.className = "map-parity-fixture-header";
    heading.append(
      textEl("strong", fixture.title),
      textEl("span", `Fixture ${fixture.version} · ${scene.viewport.width}×${scene.viewport.height} · Z ${scene.viewport.z} · ${presentation.tilePx}px`)
    );
    const pair = document.createElement("div");
    pair.className = "map-parity-pair";
    const accessibleSummary = `Map fixture ${fixture.title}. Z ${scene.viewport.z}. ${scene.interactionIndex.length} interactive cells. Selection ${scene.selection.key || "none"}.`;

    const domSurface = document.createElement("section");
    domSurface.className = "map-parity-surface lab-map-panel";
    domSurface.dataset.parityRenderer = "dom";
    domSurface.dataset.mapContrast = presentation.highContrast ? "high" : "standard";
    domSurface.dataset.mapEffectIntensity = presentation.effectIntensity;
    domSurface.dataset.mapVisualMode = presentation.glyphMode ? "glyphs" : "sprites";
    domSurface.style.setProperty("--map-marker-scale", String(presentation.markerScale));
    domSurface.append(textEl("strong", "DOM glyph renderer"));
    const domGrid = document.createElement("div");
    domGrid.className = "lab-map-grid map-parity-grid";
    domGrid.setAttribute("role", "img");
    domGrid.setAttribute("aria-label", accessibleSummary);
    domGrid.style.setProperty("--map-tile-size", `${presentation.tilePx}px`);
    domGrid.style.gridTemplateColumns = `repeat(${scene.viewport.width}, var(--map-tile-size))`;
    const domEntries = [];
    for (const cell of scene.cells.filter((entry) => MapVisualState.cellInBounds(entry.cell, scene.viewport))) {
      const rendered = labMapCellElement(cell, scene, { interactive: false });
      domEntries.push({ key: cell.key, model: rendered.model });
      domGrid.append(rendered.tile);
    }
    domSurface.append(domGrid);

    const canvasSurface = document.createElement("section");
    canvasSurface.className = "map-parity-surface lab-map-panel";
    canvasSurface.dataset.parityRenderer = "canvas";
    canvasSurface.dataset.mapContrast = presentation.highContrast ? "high" : "standard";
    canvasSurface.dataset.mapEffectIntensity = presentation.effectIntensity;
    canvasSurface.dataset.mapVisualMode = presentation.glyphMode ? "glyphs" : "sprites";
    canvasSurface.style.setProperty("--map-marker-scale", String(presentation.markerScale));
    canvasSurface.append(textEl("strong", "Canvas map renderer"));
    const canvasHost = document.createElement("div");
    canvasHost.className = "lab-map-canvas-host map-parity-canvas-host";
    canvasHost.setAttribute("role", "img");
    canvasHost.setAttribute("aria-label", accessibleSummary);
    const canvas = document.createElement("canvas");
    canvas.className = "lab-map-canvas";
    canvas.dataset.canvasMap = "true";
    canvas.dataset.canvasFrameCount = "1";
    const width = scene.viewport.width * presentation.tilePx + 12;
    const height = scene.viewport.height * presentation.tilePx + 12;
    canvas.width = width;
    canvas.height = height;
    canvas.style.width = `${width}px`;
    canvas.style.height = `${height}px`;
    const context = canvas.getContext("2d", { alpha: false });
    context.fillStyle = presentation.highContrast ? "#000000" : "#090a08";
    context.fillRect(0, 0, width, height);
    const canvasCounts = CanvasMapRenderer.renderScene(context, scene, {
      ...presentation,
      origin: { x: 6, y: 6 },
      assetLoader: spriteAssetLoader,
      presentationTime: scene.clock,
      speed: 1,
      paused: true,
      timelineMode: "paused"
    });
    canvas.dataset.canvasCellsDrawn = String(canvasCounts.cellsDrawn);
    canvas.dataset.canvasEntitiesDrawn = String(canvasCounts.entitiesDrawn);
    canvasHost.append(canvas);
    canvasSurface.append(canvasHost);
    pair.append(domSurface, canvasSurface);
    root.append(heading, pair);
    document.body.append(root);
    activeMapParityFixtureRoot = root;

    const report = parity.semanticReport(fixture, domEntries);
    report.accessibility = {
      dom: domGrid.getAttribute("aria-label"),
      canvas: canvasHost.getAttribute("aria-label"),
      matches: domGrid.getAttribute("aria-label") === canvasHost.getAttribute("aria-label")
    };
    if (!report.accessibility.matches) report.errors.push("Renderer accessibility summaries differ.");
    report.canvas = {
      cellsDrawn: canvasCounts.cellsDrawn,
      entitiesDrawn: canvasCounts.entitiesDrawn,
      effectsDrawn: canvasCounts.drawPlanStats?.visibleEffects || 0,
      spritesDrawn: canvasCounts.spritesDrawn,
      spriteFallbacks: canvasCounts.spriteFallbacks,
      renderPassCounts: canvasCounts.renderPassCounts
    };
    return report;
  }

  function mapSceneEnvironmentAtCell(cell, roomId, known, options = {}) {
    if (!known) {
      return { knowledge: { state: "unknown", observedAt: null, confidence: 0, source: "unknown terrain" }, values: null, bands: null };
    }
    const environment = options.environments?.[mapCellKey(cell)] || null;
    if (!environment) {
      return { knowledge: { state: options.debug ? "debug" : "current", observedAt: state.clock, confidence: 1, source: "solid terrain" }, values: null, bands: null };
    }
    const room = roomById(roomId);
    const directlyObserved = options.debug || options.current;
    if (directlyObserved) {
      const contamination = clamp(airborneLoadTotal(environment.airborne), 0, 100);
      const values = options.debug ? {
          temperatureC: environment.temperatureC,
          lightLevel: environment.lightLevel,
          humidityPercent: environment.humidity,
          manaDensityThaumsM3: environment.manaDensity,
          airborne: { ...environment.airborne },
          chemicalTraces: { ...environment.chemicalTraces }
        } : null;
      const bands = {
        temperature: roomAttributeBand("temperature", environment.temperatureC).label,
        light: roomAttributeBand("light", environment.lightLevel).label,
        humidity: roomAttributeBand("humidity", environment.humidity).label,
        ambientMana: roomAttributeBand("ambientMana", environment.manaDensity).label,
        contamination: roomAttributeBand("contamination", contamination).label
      };
      const airborneBand = contamination >= 55 ? "dense" : contamination >= 30 ? "haze" : contamination >= 8 ? "trace" : "clear";
      const atmosphere = {
        kind: "airborne",
        band: airborneBand,
        visible: airborneBand === "haze" || airborneBand === "dense",
        identityKnown: Boolean(options.debug)
      };
      return {
        knowledge: {
          state: options.debug ? "debug" : "current",
          observedAt: state.clock,
          confidence: 1,
          source: options.debug ? "debug" : "direct observation"
        },
        values,
        bands,
        atmosphere
      };
    }
    const observation = normalizeRoomObservation(room?.observation || state.roomObservations?.[roomId]);
    if (!observation) {
      return { knowledge: { state: "unknown", observedAt: null, confidence: 0, source: "no observation" }, values: null, bands: null };
    }
    return {
      knowledge: {
        state: "stale",
        observedAt: observation.observedAt,
        confidence: roomObservationReliabilityScore(room, observation) / 100,
        source: "room observation"
      },
      values: null,
      bands: {
        exposure: observation.exposureBand,
        contamination: observation.contaminationBand,
        ...(observation.environmentBands || {})
      },
      atmosphere: null
    };
  }

  function mapSceneLightingAtCell(cell, knowledge, map = ensureLabMap(), environments = null, solid = false, envelopeContext = null) {
    if (!["current", "debug"].includes(knowledge?.state)) {
      return {
        band: knowledge?.state === "stale" ? "remembered" : "unknown",
        intensity: knowledge?.state === "stale" ? 0.32 : 0,
        spectrum: "neutral"
      };
    }
    const envelope = surfaceEnvelopeAtCell(cell, map, envelopeContext);
    let level = solid
      ? Math.max(0, ...cardinalMapCells(cell)
        .map((neighbor) => (Number(environments?.[mapCellKey(neighbor)]?.lightLevel) || 0) * 0.85))
      : Number(environments?.[mapCellKey(cell)]?.lightLevel) || 0;
    if (envelope.openSky) level = Math.max(level, surfaceDaylightIntensity(state.clock));
    const band = MapKnowledge.lightVisibilityBand(level);
    return {
      band: band.id,
      intensity: clamp(level / 100, 0, 1),
      visualRangeTiles: band.range,
      spectrum: level > 0 && envelope.openSky ? "daylight" : level > 0 ? "warm" : "neutral"
    };
  }

  function mapEffectIntensityBand(amount) {
    const value = Math.max(0, Number(amount) || 0);
    if (value <= 0.5) return "trace";
    if (value <= 1) return "low";
    if (value <= 3) return "medium";
    if (value <= 8) return "high";
    return "extreme";
  }

  function spillEffectDamageTags(stack) {
    const tags = new Set();
    for (const tag of normalizeResidueTags(stack?.tags)) {
      const damageId = normalizeDamageTypeId(tag);
      if (DAMAGE_TYPE_BY_ID[damageId]) tags.add(damageId);
    }
    if (spillIsHazardous(stack) && !tags.size) tags.add("toxic");
    return [...tags];
  }

  function mapSceneSpillEffectSeeds(map, options = {}) {
    const effects = [];
    for (const stack of ensurePhysicalItemStacks()) {
      if (stack.form !== "spill" || !stack.cell || stack.containerId || stack.fixtureId || stack.carriedBy
        || stack.quantity <= TILE_ENVIRONMENT_EPSILON) continue;
      const knowledge = mapSceneKnowledgeForRoom(stack.roomId, { ...options, map, cell: stack.cell });
      if (!["current", "debug"].includes(knowledge.state)) continue;
      const hazardous = spillIsHazardous(stack);
      effects.push({
        id: `spill:${stack.id}`,
        kind: hazardous ? "hazardousSpill" : "spill",
        sourceId: stack.id,
        cells: [stack.cell],
        knowledge,
        severity: hazardous ? "serious" : "routine",
        state: "persistent",
        plane: "ground",
        intensityBand: mapEffectIntensityBand(stack.quantity),
        damageTags: spillEffectDamageTags(stack),
        glyph: "~",
        visualKey: hazardous ? "effect.spill.hazardous" : "effect.spill.residue",
        label: `${physicalStackLabel(stack)} spill`
      });
    }
    return effects;
  }

  function mapSceneStructuralEffectSeeds(map, options = {}) {
    const effects = [];
    for (const failure of map.terrain?.structuralFailures || []) {
      const knowledge = mapSceneKnowledgeForRoom(labMapCellRoomId(failure.cell, map), {
        ...options,
        map,
        cell: failure.cell
      });
      if (!["current", "debug"].includes(knowledge.state)) continue;
      const severity = failure.status === "collapsing" ? "critical"
        : failure.status === "failing" ? "serious"
          : "warning";
      effects.push({
        id: `structural-failure:${failure.key}`,
        kind: "structuralFailure",
        sourceId: failure.key,
        cells: [failure.cell],
        knowledge,
        severity,
        state: failure.status,
        plane: "world",
        intensityBand: failure.status === "collapsing" ? "extreme" : failure.status === "failing" ? "high" : "medium",
        damageTags: ["physical"],
        timing: { startAt: failure.detectedAt, activeAt: failure.detectedAt, endAt: failure.collapseAt },
        glyph: "^",
        visualKey: `effect.structure.${failure.status}`,
        label: `${titleCase(failure.kind.replace(/([A-Z])/g, " $1"))} ${failure.status}`
      });
    }
    return effects;
  }

  function mapScenePendingActionEffectSeeds() {
    const pending = state.combat?.pendingActions?.scientist;
    const action = combatActionDef(pending?.actionId);
    const cell = scientistMapCell();
    if (!pending || !action || !cell) return [];
    const damageTags = (action.damageTypes || []).map((entry) => normalizeDamageTypeId(entry)).filter((entry) => DAMAGE_TYPE_BY_ID[entry]);
    const kind = damageTags.includes("electrical") ? "electricity"
      : damageTags.includes("heat") ? "fire"
        : damageTags.some((tag) => ["arcane", "radiant", "shadow", "force"].includes(tag)) ? "magic"
          : "combatAction";
    return [{
      id: `action:scientist:${pending.actionId}`,
      kind,
      sourceId: "scientist",
      cells: [cell],
      knowledge: { state: "current", observedAt: state.clock, confidence: 1, source: "self" },
      severity: "advisory",
      state: state.clock < pending.releaseAt ? "charging" : "active",
      plane: "world",
      intensityBand: "high",
      damageTags,
      timing: { startAt: pending.startedAt, activeAt: pending.releaseAt, endAt: pending.channelEndsAt },
      glyph: "*",
      visualKey: `effect.${kind}.active`,
      label: `${action.label} ${state.clock < pending.releaseAt ? "charging" : "active"}`
    }];
  }

  function mapSceneTaskEffectSeeds() {
    const queue = scientistQueueTasks();
    const selected = currentSelection();
    const nextTask = queue[0] || null;
    const candidates = queue.flatMap((task) => {
      const status = taskStatusInfo(task);
      const selectedTask = selected?.kind === "task" && selected.id === task.id;
      const urgent = Boolean(task.data?.combatPriority);
      if (!selectedTask && task.id !== nextTask?.id && status.id !== "blocked" && !urgent) return [];
      const cell = taskTargetCell(task);
      if (!cell) return [];
      return [{
        task,
        cell,
        status,
        selected: selectedTask,
        urgent,
        priority: urgent ? 5 : status.id === "blocked" ? 4 : selectedTask ? 3 : status.id === "active" ? 2 : 1
      }];
    });
    const byCell = new Map();
    for (const entry of candidates) {
      const key = mapCellKey(entry.cell);
      if (!byCell.has(key)) byCell.set(key, []);
      byCell.get(key).push(entry);
    }
    return [...byCell.entries()].map(([key, entries]) => {
      entries.sort((left, right) => right.priority - left.priority || left.task.createdAt - right.task.createdAt || left.task.id.localeCompare(right.task.id));
      const primary = entries[0];
      const severity = primary.urgent ? "serious" : primary.status.id === "blocked" ? "warning" : "advisory";
      return {
        id: `task-marker:${key}`,
        kind: "taskMarker",
        sourceId: primary.task.id,
        cells: [primary.cell],
        knowledge: { state: "current", observedAt: state.clock, confidence: 1, source: "player task" },
        severity,
        state: primary.urgent ? "urgent" : primary.status.id,
        plane: "alert",
        intensityBand: primary.urgent || primary.status.id === "blocked" ? "high" : "medium",
        stackCount: entries.length,
        glyph: primary.urgent ? "!" : primary.status.id === "blocked" ? "×" : "T",
        visualKey: `effect.task.${primary.urgent ? "urgent" : primary.status.id}`,
        target: { kind: "task", id: primary.task.id },
        relatedTargets: entries.slice(1).map((entry) => ({ kind: "task", id: entry.task.id })),
        label: entries.length > 1 ? `${primary.task.label} and ${entries.length - 1} more task${entries.length === 2 ? "" : "s"}` : primary.task.label
      };
    });
  }

  function mapSceneIncidentEffectSeeds(visibleIncidents) {
    const effects = [];
    for (const entry of visibleIncidents.values()) {
      const incidents = [...(entry.alerts || [])]
        .sort((left, right) => incidentSeverityRank(right.severity) - incidentSeverityRank(left.severity)
          || finiteTime(left.createdAt, 0) - finiteTime(right.createdAt, 0)
          || left.id.localeCompare(right.id));
      const incident = incidents[0];
      if (!incident) continue;
      const cell = incidentCell(incident.roomId, incident.cell);
      if (!cell) continue;
      const uncertain = incidents.some((candidate) => candidate.perceptionPrecision && candidate.perceptionPrecision !== "exact");
      const stale = incidents.every((candidate) => candidate.status === "stale");
      const uncertaintyRadius = uncertain
        ? Math.max(1, ...incidents.map((candidate) => Number(candidate.uncertaintyRadius) || 0))
        : 0;
      effects.push({
        id: `incident-stack:${mapCellKey(cell)}`,
        kind: incident.type === "combat" ? "combatIncident" : "incident",
        sourceId: incident.sourceId,
        cells: [cell],
        knowledge: {
          state: uncertain ? "uncertain" : stale ? "stale" : "current",
          observedAt: Math.max(...incidents.map((candidate) => finiteTime(candidate.updatedAt ?? candidate.createdAt, state.clock))),
          confidence: uncertain ? 1 / (1 + uncertaintyRadius) : stale ? 0.6 : 1,
          source: uncertain ? incident.perceptionChannel || "uncertain detection" : "incident record"
        },
        uncertaintyRadius,
        stackCount: incidents.length,
        severity: incident.severity,
        state: stale ? "stale" : incident.status,
        plane: "alert",
        intensityBand: ["serious", "critical"].includes(incident.severity) ? "high" : "medium",
        glyph: incident.type === "combat" ? "!" : "A",
        visualKey: `effect.incident.${incident.type}.${incident.severity}`,
        target: { kind: "incident", id: incident.id },
        relatedTargets: incidents.slice(1).map((candidate) => ({ kind: "incident", id: candidate.id })),
        label: incidents.length > 1 ? `${incident.label} and ${incidents.length - 1} more alert${incidents.length === 2 ? "" : "s"}` : incident.label
      });
    }
    return effects;
  }

  function mapSceneFeedbackEffectSeeds(map, options = {}) {
    const effects = [];
    const feedbackEvents = Array.isArray(options.feedbackEvents)
      ? options.feedbackEvents
      : mapFeedbackSnapshot();
    for (const event of feedbackEvents) {
      const visibleCells = event.cells.filter((cell) => {
        const knowledge = mapSceneKnowledgeForRoom(labMapCellRoomId(cell, map), {
          ...options,
          map,
          cell
        });
        return ["current", "debug"].includes(knowledge.state);
      });
      if (!visibleCells.length) continue;
      effects.push({
        id: event.id,
        kind: event.kind,
        sourceId: event.coalesceKey,
        cells: visibleCells,
        knowledge: { state: options.debug ? "debug" : "current", observedAt: state.clock, confidence: 1, source: "direct feedback" },
        severity: event.severity,
        state: "transient",
        plane: "world",
        intensityBand: event.intensityBand,
        damageTags: event.damageTags,
        stackCount: event.stackCount,
        glyph: "",
        visualKey: "",
        label: event.label,
        feedback: {
          startedAtMs: event.startedAtMs,
          durationMs: event.durationMs,
          direction: event.direction,
          coalescedCount: event.stackCount
        }
      });
    }
    return effects;
  }

  function mapSceneEffectSeeds(visibleIncidents, options = {}) {
    const map = options.map || ensureLabMap();
    return [
      ...mapSceneSpillEffectSeeds(map, options),
      ...mapSceneStructuralEffectSeeds(map, options),
      ...mapScenePendingActionEffectSeeds(),
      ...mapSceneTaskEffectSeeds(),
      ...mapSceneFeedbackEffectSeeds(map, options),
      ...mapSceneIncidentEffectSeeds(visibleIncidents)
    ];
  }

  function mapSceneOverlaySeeds(overlayAssignments) {
    const overlays = [];
    for (const [key, entry] of overlayAssignments.entries()) {
      const [x, y, z] = key.split(",").map(Number);
      overlays.push({
        id: `overlay:${entry.overlayId}:${key}`,
        kind: entry.overlayId,
        cells: [{ x, y, z }],
        knowledge: entry.knowledge || { state: entry.source === "debug" ? "debug" : "current", observedAt: state.clock, confidence: 1, source: entry.source || "overlay" },
        visualKey: `overlay.${entry.overlayId}`,
        value: entry.value ?? null,
        label: entry.label || "",
        target: entry.target || null
      });
    }
    return overlays;
  }

  function buildLabMapView(map = ensureLabMap()) {
    const sceneBuildStartedAt = performance.now();
    // Preserve feedback that was live when this frame began even when a busy
    // scene build takes longer than a short effect's display duration.
    const feedbackEvents = mapFeedbackSnapshot();
    const overlay = currentMapOverlayDef();
    const scientistCell = scientistMapCell();
    const fullReveal = mapFullRevealActive() || overlay.id === "debug";
    const perceivedCellKeys = fullReveal ? null : scientistPerceivedMapCellKeys(map);
    const observations = fullReveal ? {} : ensureMapCellObservations(map);
    const objectAssignments = labMapObjectAssignments(map, {
      debug: fullReveal,
      perceivedCellKeys
    });
    const incidentAssignments = labMapIncidentAssignments(map);
    const route = selectedOrNextScientistTaskRoute(map);
    const plannedExcavations = plannedExcavationAssignments();
    const draftExcavations = draftExcavationAssignments();
    const selectedTarget = selectedMapTarget();
    const visibleIncidents = visibleIncidentAssignments(map, incidentAssignments, selectedTarget, overlay.id);
    const resourceFocus = currentResourceOverlayFocusDef();
    const overlayAssignments = labMapOverlayAssignments(overlay.id, map, {
      incidentAssignments: visibleIncidents,
      plannedExcavations,
      route,
      resourceFocus,
      perceivedCellKeys,
      observations,
      debug: fullReveal
    });
    const knowledgeFilteredOverlays = new Map([...overlayAssignments.entries()].filter(([key]) =>
      fullReveal
      || perceivedCellKeys.has(key)
      || overlayAssignments.get(key)?.knowledge?.state === "stale" && observations[key]
      || overlayAssignments.get(key)?.scope === "roomObservation" && observations[key]
      || ["movement", "construction"].includes(overlay.id)
    ));
    const cursorCell = mapCursorCell(map);
    ensureMapCameraIncludesCell(cursorCell);
    const viewport = mapViewportForUi(map);
    const sceneBounds = MapVisualState.overscanBounds(viewport, map, 1);
    const anchors = labMapAnchorAssignments(map);
    const knownCellKeys = fullReveal ? null : perceivedCellKeys;
    const excavatedKeys = labMapExcavatedCellKeys(map);
    const connectivityExcavatedKeys = fullReveal
      ? excavatedKeys
      : new Set([...excavatedKeys].filter((key) => perceivedCellKeys.has(key)));
    const compartmentInference = inferLabCompartments(map);
    const envelopeContext = buildSurfaceEnvelopeContext(map);
    const terrainContext = buildTerrainConnectivityContext(map, {
      fullReveal,
      knownCellKeys,
      excavatedKeys: connectivityExcavatedKeys,
      compartmentInference
    });
    const sceneEnvironments = ensureTileEnvironments(map);
    const sceneCells = [];

    for (let y = sceneBounds.y; y < sceneBounds.y + sceneBounds.height; y += 1) {
      for (let x = sceneBounds.x; x < sceneBounds.x + sceneBounds.width; x += 1) {
        const cell = { x, y, z: viewport.z };
        const key = mapCellKey(cell);
        const current = fullReveal || perceivedCellKeys.has(key);
        const observation = observations[key] || null;
        const knowledge = MapKnowledge.knowledgeForObservation(observation, state.clock, {
          debug: fullReveal,
          current,
          source: current ? "direct observation" : undefined
        });
        const known = current || Boolean(observation) || plannedExcavations.has(key) || draftExcavations.has(key) || route.keys.has(key);
        const routeEntry = route.keys.has(key)
          ? { ...route, marker: route.markers.get(key) || null }
          : null;
        const cellView = buildLabMapCellView({
          cell,
          map,
          anchorRoom: anchors.get(key),
          objectEntry: objectAssignments.get(key),
          incidentEntry: visibleIncidents.get(key),
          routeEntry,
          plannedEntry: plannedExcavations.get(key),
          draftEntry: draftExcavations.get(key),
          overlayEntry: knowledgeFilteredOverlays.get(key),
          selectedTarget,
          scientistCell,
          cursorCell,
          known,
          knowledge,
          remembered: observation,
          excavatedKeys,
          terrainContext,
          envelopeContext
        });
        cellView.compartmentId = compartmentInference.cellToCompartment.get(key) || "";
        cellView.environment = mapSceneEnvironmentAtCell(cell, cellView.roomId, known, {
          map,
          debug: fullReveal,
          current,
          environments: sceneEnvironments
        });
        cellView.lighting = mapSceneLightingAtCell(
          cell,
          knowledge,
          map,
          sceneEnvironments,
          cellView.base?.kind === "constructedWall",
          envelopeContext
        );
        cellView.atmosphere = current || fullReveal ? cellView.environment?.atmosphere || null : null;
        sceneCells.push(cellView);
      }
    }

    const scene = MapVisualState.buildScene({
      clock: state.clock,
      timeline: animationTimelineSnapshot(),
      perspective: { kind: fullReveal ? "debug" : "player", observerId: "scientist" },
      viewport,
      queryBounds: sceneBounds,
      mapSize: {
        width: map.width,
        height: map.height,
        tileSizeM: map.tileSizeM,
        layerHeightM: map.layerHeightM
      },
      revisions: {
        topology: Number(state.navigation?.topologyRevision) || 0,
        fixtures: Number(state.navigation?.fixtureRevision) || 0,
        doors: Number(state.navigation?.doorRevision) || 0,
        access: Number(state.navigation?.accessRevision) || 0,
        simulationClock: state.clock
      },
      cells: sceneCells,
      entities: labMapSceneEntitySeeds(map, objectAssignments, {
        debug: fullReveal,
        perceivedCellKeys
      }),
      effects: mapSceneEffectSeeds(visibleIncidents, {
        map,
        debug: fullReveal,
        perceivedCellKeys,
        feedbackEvents
      }),
      overlays: mapSceneOverlaySeeds(knowledgeFilteredOverlays),
      selection: { target: selectedTarget }
    });
    MapRenderOrder.orderSceneInteractions(scene);
    const cells = MapVisualState.cellsWithinBounds(scene.cells, viewport);

    const mapView = {
      width: viewport.width,
      height: viewport.height,
      mapWidth: map.width,
      mapHeight: map.height,
      tileSizeM: map.tileSizeM,
      layerHeightM: map.layerHeightM,
      viewport,
      zoom: {
        index: viewport.zoomIndex,
        tilePx: viewport.tilePx,
        label: `${viewport.tilePx}px tiles`,
        canZoomIn: viewport.zoomIndex < LAB_MAP_ZOOM_LEVELS.length - 1,
        canZoomOut: viewport.zoomIndex > minimumMapZoomIndex()
      },
      fullReveal,
      headerMeta: `${map.width} x ${map.height} m grid; ${labMapLayerLabel(viewport.z, map)}; viewing ${viewport.width} x ${viewport.height}; 1 tile = ${formatDecimal(map.tileSizeM, 0)} m; layer = ${formatDecimal(map.layerHeightM, 0)} m`,
      cursor: cursorCell,
      cursorTarget: mapCursorTarget(scene),
      construction: normalizeConstructionState(state.construction, state),
      mode: ensureUiState().mode,
      overlay,
      resourceFocus,
      overlayMenuOpen: Boolean(ensureUiState().overlayMenuOpen),
      keyboardHelpOpen: ensureUiState().keyboardHelpOpen,
      compartments: compartmentInference.compartments.map((compartment) => ({
        id: compartment.id,
        kind: compartment.kind,
        status: compartment.status,
        cells: compartment.cells.map((cell) => ({ ...cell })),
        bounds: { ...compartment.bounds },
        roomIds: [...compartment.roomIds],
        connectionIds: [...compartment.connectionIds],
        portals: compartment.portals.map((portal) => ({ ...portal, cell: { ...portal.cell }, compartmentIds: [...portal.compartmentIds] }))
      })),
      compartmentConnectors: compartmentInference.connectors.map((connector) => ({
        ...connector,
        cell: { ...connector.cell },
        compartmentIds: [...connector.compartmentIds]
      })),
      scene,
      cells,
      legendItems: mapOverlayLegendItems(overlay.id)
    };
    recordPerformanceSample(simulationPerformance.mapScene, performance.now() - sceneBuildStartedAt);
    return mapView;
  }

  function focusMapTarget(target, options = {}) {
    const normalized = normalizeMapTarget(target);
    if (!normalized) {
      return false;
    }
    if (options.keepWorkspace) {
      setSelection(normalized, { source: options.source || target?.source || "map" });
      if (options.resetInspectorTab) {
        ensureUiState().selectionInspectorTab = DEFAULT_SELECTION_INSPECTOR_TAB;
      }
      if (options.resetInspectorExpanded) {
        ensureUiState().selectionInspectorExpanded = false;
      }
      if (options.resetCommandMenu) {
        const ui = ensureUiState();
        ui.commandMenuOpen = false;
        if (ui.mode === UI_MODE_COMMAND) {
          ui.mode = UI_MODE_NAVIGATION;
        }
      }
      setActiveWorkspaceTab("map");
      persist();
      renderMapSelectionInteraction();
      return true;
    }
    setSelectedMapTarget(normalized);
    if (normalized.kind === "tile") {
      setActiveWorkspaceTab("map");
      persist();
      render();
      return true;
    }
    if (normalized.kind === "scientist") {
      setActiveWorkspaceTab("map");
      persist();
      render();
      requestAnimationFrame(() => {
        focusRoom(scientistRoomId(), options);
      });
      return true;
    }
    if (normalized.kind === "room") {
      setActiveWorkspaceTab("map");
      persist();
      render();
      requestAnimationFrame(() => focusRoom(normalized.roomId, options));
      return true;
    }
    if (normalized.kind === "door") {
      setActiveWorkspaceTab("map");
      persist();
      render();
      requestAnimationFrame(() => focusDoor(normalized.key, options));
      return true;
    }
    if (normalized.kind === "container") {
      setActiveWorkspaceTab("containers");
      persist();
      render();
      requestAnimationFrame(() => focusContainer(normalized.id, options));
      return true;
    }
    if (normalized.kind === "slime") {
      focusSlime(normalized.id, options);
      return true;
    }
    if (normalized.kind === "corpse") {
      focusCorpse(normalized.id, options);
      return true;
    }
    if (normalized.kind === "incident") {
      setActiveWorkspaceTab("map");
      persist();
      render();
      requestAnimationFrame(() => {
        focusEntityCard(elementByDataset("incidentAlert", normalized.id), options);
      });
      return true;
    }
    if (normalized.kind === "task") {
      setActiveWorkspaceTab("map");
      persist();
      render();
      requestAnimationFrame(() => {
        focusEntityCard(elementByDataset("taskRow", normalized.id), options);
      });
      return true;
    }
    return false;
  }

  function keyboardModeLabel(mode) {
    return mode === UI_MODE_COMMAND ? "Command mode" : "Navigation mode";
  }

  function mapAssistiveDescription(mapView) {
    const cursor = cleanMapCell(mapView?.cursor);
    if (!cursor) return "Map cursor unavailable.";
    const cellView = mapView.cells.find((cell) => mapCellKey(cell.cell) === mapCellKey(cursor));
    const domModel = cellView ? labMapCellDomModel(cellView, mapView.scene) : null;
    const target = mapView.cursorTarget ? selectionLabel(mapView.cursorTarget) : "nothing selectable";
    const detail = domModel?.title || cellView?.tooltip?.text || "No known map detail.";
    return `Map cursor ${cursor.x}, ${cursor.y}, ${cursor.z}. ${target}. ${detail}`;
  }

  function mapAssistiveStatusEl(mapView) {
    const status = document.createElement("div");
    status.id = "mapAssistiveStatus";
    status.className = "screen-reader-only";
    status.dataset.mapAssistiveStatus = "true";
    status.setAttribute("role", "status");
    status.setAttribute("aria-live", "polite");
    status.setAttribute("aria-atomic", "true");
    status.textContent = mapAssistiveDescription(mapView);
    return status;
  }

  function keyboardStatusEl(mapView) {
    const row = document.createElement("div");
    row.className = "keyboard-status-row";
    row.dataset.keyboardMode = mapView.mode;
    const cursorTarget = mapView.cursorTarget ? selectionLabel(mapView.cursorTarget) : "nothing";
    const cursorText = mapView.cursor
      ? `Cursor ${mapView.cursor.x},${mapView.cursor.y},${mapView.cursor.z} - ${cursorTarget}`
      : "Cursor unavailable";
    const menuPath = normalizeKeyboardMenuPath(ensureUiState().keyboardMenuPath);
    const menuHint = menuPath
      ? `Key path ${keyboardMenuDef(menuPath).key}: ${keyboardMenuOptionsText(menuPath)}.`
      : currentMapRendererMode() === MAP_RENDERER_CANVAS
        ? "WASD/middle-drag pan camera; wheel or +/- zoom; click or Enter selects; hover inspects; arrows move cursor; [/] change layer; O cycles overlay; T/I/C/P/R/G open menus; ? help."
        : "WASD/middle-drag pan camera; arrows move cursor; [/] change layer; +/- zoom; Enter selects; O cycles overlay; B opens Black Market; T/I/C/P/R/G open menus; ? help.";
    if (accessAreaEditing()) row.append(chip(`Access area: ${activeAccessArea().name} · ${ensureAccessControl().editor.brush}`));
    else if (roomDesignationModeActive()) row.append(chip("Room designation mode"));
    else if (constructionWorkModeActive()) row.append(chip(`${constructionModeLabel(constructionActiveMode())} mode · priority ${state.construction.priority}`));
    row.append(
      chip(keyboardModeLabel(mapView.mode)),
      textEl("span", cursorText),
      textEl("span", mapView.mode === UI_MODE_COMMAND ? "1-9 choose commands; Esc cancels." : menuHint)
    );
    return row;
  }

  function mapAccessibilitySelect(labelText, preferenceKey, options, value) {
    const label = document.createElement("label");
    const text = textEl("span", labelText);
    const select = document.createElement("select");
    select.dataset.mapAccessibilityPreference = preferenceKey;
    select.setAttribute("aria-label", labelText);
    for (const [optionValue, optionLabel] of options) {
      const option = document.createElement("option");
      option.value = String(optionValue);
      option.textContent = optionLabel;
      select.append(option);
    }
    select.value = String(value);
    select.addEventListener("change", () => {
      mapAccessibilityPanelOpen = Boolean(select.closest("details")?.open);
      setMapAccessibilityPreference(preferenceKey, select.value);
    });
    label.append(text, select);
    return label;
  }

  function setMapAccessibilityPreference(preferenceKey, value) {
    const next = { ...normalizeUiPreferences(uiPreferences) };
    if (preferenceKey === "mapMinimumTilePx") next[preferenceKey] = Number(value);
    else if (preferenceKey === "mapMarkerScale") next[preferenceKey] = Number(value);
    else next[preferenceKey] = value;
    uiPreferences = normalizeUiPreferences(next);
    persistUiPreferences();
    applyAccessibilityDocumentPreferences();
    if (preferenceKey === "mapRendererMode") {
      mapRendererFallbackNotice = "";
      setMapRendererMode(uiPreferences.mapRendererMode);
      return;
    }
    if (!state?.started) return;
    const ui = ensureUiState();
    const minimumZoomIndex = minimumMapZoomIndex();
    if (ui.mapZoomIndex < minimumZoomIndex) {
      setMapZoom(minimumZoomIndex - ui.mapZoomIndex);
      return;
    }
    renderMapInteraction();
  }

